c["npc:abercrombie"] = "e51b93"
P.scopedClips["npc:abercrombie"] = {scope="overview-body",sourceHash="5125f8",hash="e51b93",name="Аберкромбі",summary="Аберкромбі здається немічним, дивакуватим відлюдником, що живе в напіврозваленій халупі на заході Сутінколісся, біля Цвинтаря Воронячого Пагорба. Видаючи себе за безневинного самітника, якого мучать жахи лісу, він охоче просить співчутливих мандрівників зібрати для нього дивні реагенти й припаси.",section="Захований у гнилих тінях біля Цвинтаря Воронячого Пагорба, Аберкромбі має жалюгідний вигляд. Він видає себе за старого, який лише намагається пережити жахи Сутінколісся, і просить мандрівників збігати в Даркшир по дрібниці — припаси, трави й нитки. Тим, хто не знає історії краю, він здається ще однією нещасною душею, покинутою напризволяще, коли край занепав.",sectionIndex=1}
c["npc:agathelos-the-raging"] = "3da065"
P.scopedClips["npc:agathelos-the-raging"] = {scope="overview-body",sourceHash="27081f",hash="3da065",name="Аґателос Лютий",summary="Аґателос Лютий — велетенський броньований вепр, замкнений у колючих тунелях Рейзорфен Краула. Шипогриви Мертвої Голови виростили його як живу облогову машину й утілення свого давнього бога, і його довели до лютого, неприродного шалу. Завдяки самій своїй масі й силі він — один із найнебезпечніших звірів, що ховаються під південними Пустками.",section="Шипогриви шанують усіх свиней як нащадків свого покровителя й праотця — бога Аґамаґґана. Для них вепри надзвичайного розміру й витривалості — пряме благословення від полеглого бога. Звір завбільшки з Аґателоса — а він удвічі вищий за громоящера з Пусток — має для племен Рейзорфен величезне духовне й обрядове значення.",sectionIndex=1}
c["npc:aku-mai"] = "1b36ae"
P.scopedClips["npc:aku-mai"] = {scope="overview-body",sourceHash="fdbeb5",hash="1b36ae",name="Аку'май",summary="Аку'май — потворна триголова гідра, що живе в затонулих руїнах Чорноглибинних Печер на Зорамському Узмор'ї. Просякнуту первісною тінню й обрану Древніми Богами, цю звірюку шанують як провісницю загибелі світу. Культ Молота Присмерку доглядає її в затопленому лігві, приносячи живі жертви, щоб угамувати її вічний голод.",section="Задовго до того, як культисти заволоділи затонулим храмом під морем, Аку'май наводила жах на узбережжя Ашенвалю, наче жива пошесть на Зорамському Узмор'ї. Створіння глибоких вод і темніших сил, ця велетенська гідра несе у своїх трьох ненажерливих головах частку давньої злоби Древніх Богів. Аку'май — не звичайний мешканець припливів, а давній жах, що чатує в затоплених руїнах відтоді, як упав храм нічних ельфів на честь Елуни, і отруює води злобою, просякнутою Порожнечею.",sectionIndex=1}
c["npc:alanndarian-nightsong"] = "3c99ca"
P.scopedClips["npc:alanndarian-nightsong"] = {scope="overview-body",sourceHash="5033bc",hash="3c99ca",name="Аланндаріан Найтсонг",summary="Аланндаріан Найтсонг — нічна ельфійка з Обердайна на Темному Узбережжі, яка присвятила себе догляду за знедоленими звірами краю. Разом із мандрівниками вона шукає ліки від пошестей, що вражають місцевих тварин, зокрема довгоступів і лісових створінь, осквернених темними силами.",section="Аланндаріан Найтсонг, що живе в приморському поселенні Обердайн, пильнує крихку природну рівновагу Темного Узбережжя. Таємнича скверна просочується в ґрунт і води, і створіння давніх лісів почали хворіти й ставати неприродно агресивними. Аланндаріан — охоронниця й дослідниця природи, що шукає дієвих засобів полегшити їхні страждання й повернути їм природну силу.",sectionIndex=1}
c["npc:althea-ebonlocke"] = "c01f65"
P.scopedClips["npc:althea-ebonlocke"] = {scope="overview-body",sourceHash="0e40f7",hash="c01f65",name="Алтея Ебонлок",summary="Командир Алтея Ебонлок очолює Нічну Варту — знесилену міську сторожу, що захищає Даркшир від жахів Сутінколісся. Родичка мера Елло Ебонлока, вона тримає оборону відрізаного краю, який покинуло регулярне військо Стормвінда. Вона організовує патрулі, доручає шукачам пригод винищувати місцевих потвор і дбає, щоб місто вистояло під безупинними нападами чудовиськ.",section="Поки її родич, мер Елло Ебонлок, порядкує цивільними справами в ратуші, командир Алтея керує тонкою лінією оборони Даркшира. Коли Стормвінд так і не прислав королівських військ, щоб захистити Сутінколісся від повзучих жахів, містяни створили Нічну Варту. Під незмінно твердою рукою Алтеї ці добровольці патрулюють оповиті туманом дороги, не даючи скелетам-нежиті, лютим вовкам і павукам прорватися до міста.",sectionIndex=1}
c["npc:anastasia-hartwell"] = "6d6e32"
P.scopedClips["npc:anastasia-hartwell"] = {scope="overview-body",sourceHash="d575c5",hash="6d6e32",name="Анастасія Гартвелл",summary="Анастасія Гартвелл — відома наставниця магів із Відступників, що живе в Магічному Кварталі Андерсіті. Вона допомагає молодим і досвідченішим заклиначам опановувати чародійне мистецтво й керує важливими магічними дослідженнями та виправами по всьому Лордерона й поза ним.",section="У темних, відлунних покоях Магічного Кварталу Андерсіті Анастасія Гартвелл навчає магів Відступників і Орди спрямовувати чародійну енергію. Хоч королівство Лордерон лежить у руїнах, колишні люди-чародії, як-от Анастасія, зберегли свої вчені традиції й після смерті. Вона наполягає, що магія вимагає суворої дисципліни, і застерігає кожного зустрічного мандрівника: необачні закляття швидко поглинуть невмілого.",sectionIndex=1}
c["npc:apothecary-johaan"] = "38edda"
P.scopedClips["npc:apothecary-johaan"] = {scope="overview-body",sourceHash="d1851d",hash="38edda",name="Аптекар Йогаан",summary="Аптекар Йогаан — алхімік і дослідник Королівського Аптекарського Товариства в Бріллі. За дорученням свого ордену та Леді Сильвани він проводить смертельні досліди над місцевою флорою та фауною, розробляючи нову чуму Відступників.",section="Відкрито працюючи в поселенні Відступників Брілл у Галявинах Тірісфалю, Аптекар Йогаан утілює наукові амбіції новоствореного Королівського Аптекарського Товариства. Як і його колеги по всьому Лордерону, Йогаан діє за прямим наказом — створювати біологічну й алхімічну зброю, здатну убезпечити хистке майбутнє Відступників і від живих, і від Погибелі.",sectionIndex=1}
c["npc:apothecary-renferrel"] = "da3102"
P.scopedClips["npc:apothecary-renferrel"] = {scope="overview-body",sourceHash="f7159c",hash="da3102",name="Аптекар Ренферрел",summary="Аптекар Ренферрел — знаний член Королівського Аптекарського Товариства, що працює в Гробниці в Срібноліссі. Йому доручено просувати алхімічні справи Відступників, і він керує широкими польовими дослідженнями осквернених звірів краю та загроз нежиті. Мандрівники Срібноліссям часто допомагають йому збирати неспокійні інгредієнти й розслідувати небезпечні рештки Погибелі.",section="Ренферрел, що працює в Гробниці, — один із головних польових дослідників Королівського Аптекарського Товариства в Срібноліссі. Поки в Андерсіті містяться великі лабораторії й найвищий провід товариства, Ренферрел виконує практичну, брудну роботу: здобуває місцеві біологічні зразки, вдосконалює могутні зілля й вивчає похмуру природу західного прикордоння Лордерона.",sectionIndex=1}
c["npc:aramis-hammerhand"] = "e2a479"
P.scopedClips["npc:aramis-hammerhand"] = {scope="overview-body",sourceHash="b233ea",hash="e2a479",name="Араміс Гаммергенд",summary="Араміс Гаммергенд — святий воїн з-поміж нежиті, що перебуває в оскверненій каплиці Похоронного Подзвону. Як наставник паладинів Відступників він навчає щойно воскреслих мерців, що прагнуть відновити свій зв'язок зі Святим Світлом. Іти цим шляхом у нежитті потребує величезної дисципліни: володіння такою променистою силою завдає їхній зотлілій плоті нестерпного болю.",section="Стоячи в похмурих стінах каплиці Похоронного Подзвону, Араміс Гаммергенд — виняток серед нещодавно пробуджених Відступників. За життя чимало громадян Лордерона відгукнулися на поклик Срібної Длані — і загинули, коли Погибель прокотилася північчю. Араміс пережив падіння лише для того, щоб повстати нежиттю, та він вирішив не зрікатися бойових і духовних настанов свого колишнього існування. Тепер він наставляє інших, хто відмовляється зректися своєї відданості.",sectionIndex=1}
c["npc:arcanist-doan"] = "ce579f"
P.scopedClips["npc:arcanist-doan"] = {scope="overview-body",sourceHash="5dd8aa",hash="ce579f",name="Арканіст Доан",summary="Арканіст Доан — майстер-маг із людей, що мешкає в Атенеумі, у крилі Бібліотеки Багряного Монастиря. Колись він був соратником Срібної Длані й допомагав викувати легендарний Ешбрінгер, а нині служить Багряному Хрестовому Походу як один із його найнебезпечніших знавців таємної магії й охоронець ключових архівів походу.",section="Ще до того, як Багряний Хрестовий Похід замкнувся в собі й ударився у фанатизм, арканіст Доан ходив серед Лицарів Срібної Длані. Під час Третьої війни він зустрівся в Саутшорі з верховним лордом Александросом Моґрейном та іншими засновниками. Коли Моґрейн показав темний кристал, відібраний в орка-чорнокнижника ще в Другій війні, Доан помітив його неприродну здатність поглинати святу енергію. Поєднавши своє знання таємної магії зі святою магією соратників, Доан допоміг очистити кристал Порожнечі й обернути його на сяйливе світло — серце зброї, відомої як Ешбрінгер.",sectionIndex=1}
c["npc:arugal"] = "e8344f"
P.scopedClips["npc:arugal"] = {scope="overview-body",sourceHash="48c8c2",hash="e8344f",name="Аруґал",summary="Архімаг Аруґал — колишній чарівник Даларана й Ґілнеаса, що випустив диких воргенів на Лордерон. Охоплений божевіллям і горем, він тепер править із висот Фортеці Шадовфенг, вважаючи лютих звірів своїми любими дітьми й погрожуючи всьому Срібноліссю.",section="До падіння Лордерона Аруґал був членом Кірін-Тору, хоча деякі колеги, як-от Далар Донвівер, зневажливо вважали його шарлатаном, чия слабка магія трималася здебільшого на зачарованих дрібничках. Коли під час Третьої війни Погибель прокотилася північчю, Аруґал шукав зброю, достатньо могутню, щоб стримати навалу. Спираючись на езотеричні дослідження покійного даларанського мага Ура, Аруґал прорвав завісу між світами й викликав воргенів у світ смертних. Ненажерливі звірі, як і задумувалося, розтерзали легіони нежиті, але їхню дику лютість не вдалося стримати, і їхній звірячий голод швидко обернувся проти невинних смертних.",sectionIndex=1}
c["npc:asterion"] = "b3125f"
P.scopedClips["npc:asterion"] = {scope="overview-body",sourceHash="e74d12",hash="b3125f",name="Астеріон",summary="Астеріон — давній дух із Високородних, прикутий до руїн Башал'Арану на Темному Узбережжі. Десять тисячоліть тому він був довіреною правою рукою правителя Атрікуса Нарассіна, але за загадкових обставин його ув'язнили в магічній печатці з місячного каменю, що тримала його і за життя, і після смерті. Сьогодні його примара досі прикута до зруйнованої святині, оточена демонічними звірами, і мріє про звільнення.",section="До того як Великий Розкол зруйнував давній Калімдор, Башал'Аран і Амет'Аран були містами-сестрами, які благословила сама королева Азшара. Азшара призначила Атрікуса Нарассіна правити двома поселеннями, а Астеріон був його правою рукою. Шанований і за бойову вправність, і за володіння таємною магією, Астеріон жив серед мешканців Башал'Арану й часто подорожував між містами-сестрами, дбаючи про потреби їхніх громадян.",sectionIndex=1}
c["npc:athridas-bearmantle"] = "b62dc4"
P.scopedClips["npc:athridas-bearmantle"] = {scope="overview-body",sourceHash="c5f08e",hash="b62dc4",name="Атрідас Бермантл",summary="Атрідас Бермантл — друїд нічних ельфів, що мешкає в Доланаарі серед гілля Тельдрассила. Йому доручено берегти місцеве поселення, тож він посилає молодих шукачів пригод розслідувати скверну, що насувається на тутешню живність і сусідніх фурболгів-Вузлошкірів.",section="Атрідас Бермантл у Доланаарі — перша лінія оборони для нічних ельфів, що виходять із Тінедолу. Поки гілля новорослого Світового Дерева Тельдрассила виказує неприродні ознаки занепаду й неспокою, Атрідас невтомно керує місцевою розвідкою й захищає мирне містечко від довколишніх загроз.",sectionIndex=1}
c["npc:auntie-bernice-stonefield"] = "2f2722"
P.scopedClips["npc:auntie-bernice-stonefield"] = {scope="overview-body",sourceHash="7581b5",hash="2f2722",name="\"Тітонька\" Берніс Стоунфілд",summary="«Тітонька» Берніс Стоунфілд — старша в родині Стоунфілдів, що живе на їхній садибі в південно-центральній частині Лісу Елвінн. Вона овдовіла, коли її чоловік загинув у військових походах королівства, і на всю долину славиться своїми пирогами зі свинячою грудинкою. Її можна знайти біля фермерського будинку разом із Ма Стоунфілд: вона пильно стежить за околицею і глибоко не довіряє суперникам-Маклурам.",section="Як і багато простих людей королівства Стормвінд, Берніс сповна заплатила за нескінченну війну. Втративши чоловіка у військових походах, вона доживає вік на родинній садибі серед рідні й допомагає матріархині Ма Стоунфілд у щоденних справах ферми. Попри втрату, вона годує родину й тримає господарство на ходу, а її пироги зі свинячою грудинкою знають по всій окрузі.",sectionIndex=1}
c["npc:baine-bloodhoof"] = "ad1228"
P.scopedClips["npc:baine-bloodhoof"] = {scope="overview-body",sourceHash="5d1b6c",hash="ad1228",name="Бейн Бладгуф",summary="Бейн Бладгуф — син Верховного Вождя Кайрна Бладгуфа й чинний захисник Села Бладгуф у Малгорі. Поки його батько править племенами з високих плато Тандер Блафу, Бейн безпосередньо керує місцевою обороною: розслідує промислове визискування, що насувається, і боронить край від здичавілих хижаків. Він — важлива ланка між юними тауренськими хоробрими та прадавньою мудрістю свого клану.",section="Народжений від Кайрна й покійної Тамаали, Бейн провів юність у мандрах зі своїм кочовим народом, перш ніж той здобув багаті луки Малгору. Його ранні роки позначила повсякчасна загроза від кланів кентаврів. Невдовзі після Третьої війни бойовий загін кентаврів під проводом Хіраґґа захопив юного Бейна, і Кайрн поринув у скорботне заціпеніння, яке ледь не знищило щойно засновані поселення. Лише завдяки відвазі захисника Рекссара Бейна визволили з полону. Той порятунок повернув Кайрнові дух, і таурени змогли стати поруч з Ордою Тралла проти загарбників із Кул Тірасу й закріпитися на континенті.",sectionIndex=1}
c["npc:balthule-shadowstrike"] = "2d9acd"
P.scopedClips["npc:balthule-shadowstrike"] = {scope="overview-body",sourceHash="7263d8",hash="2d9acd",name="Балтул Шедовстрайк",summary="Балтул Шедовстрайк — розвідник нічних ельфів, що несе службу на півночі Темного Узбережжя поблизу Вежі Альталакса. Як передовий агент Делґрена Очищувача, він стежить за зловісними культистами й темними чаклунами, що засіли в давніх ельфійських руїнах. Шукачів пригод, що мандрують північним узбережжям, часто посилають до нього, щоб допомогти розкрити й зірвати темні ритуали у вежі.",section="Причаївшись у нетрях трохи на захід від Вежі Альталакса, Балтул Шедовстрайк несе самотню й небезпечну варту. Північ Темного Узбережжя повна неспокійних духів і затінених руїн, але те, що коїться довкола вежі, — особливо гостра загроза. Балтул діє за вказівками Делґрена Очищувача, стежачи за пересуваннями темних чаклунів, що прокралися до давніх решток Високородних.",sectionIndex=1}
c["npc:baron-aquanis"] = "55e440"
P.scopedClips["npc:baron-aquanis"] = {scope="overview-body",sourceHash="8993c4",hash="55e440",name="Барон Аквеніс",summary="Барон Аквеніс — могутній водяний елементаль затоплених Руїн Місячної Святині в Чорноглибинних Печерах, де влаштував собі лігво Молот Присмерку. Він здіймається з глибини, коли хтось потривожить Глибинний Камінь у руїнах. Шамани Земляного Кільця давно вважають його оскверненою стихійною силою і підозрюють, що за цим стоїть культ.",section="Глибинний Камінь лежить у затоплених залах Руїн Місячної Святині, просто під носом у культистів Молота Присмерку, які тепер займають руїни. Усередині каменю — глибинне ядро, пристрій, що, коли його правильно прочитати, розповідає історію всієї стихійної діяльності довкола. Дже'ню Санкреа із Земляного Кільця посилає шукачів пригод з Орди здобути ядро, і потривожений камінь викликає Барона Аквеніса з глибин.",sectionIndex=1}
c["npc:baron-silverlaine"] = "e3d4c7"
P.scopedClips["npc:baron-silverlaine"] = {scope="overview-body",sourceHash="0a9f7b",hash="e3d4c7",name="Барон Сільверлейн",summary="Барон Сільверлейн був законним людським володарем фортеці, колись відомої як Фортеця Сільверлейн, що височіє над Селом Пайрвуд. Коли Архімаг Аруґал випустив лютих воргенів на цей край, барона й усю його челядь нещадно вирізали. Тепер його змучений дух блукає зруйнованою бенкетною залою, прикутий нежиттям до захисту того самого лігва, що стало його гробницею.",section="Доки тінь вовкоподібних звірів не огорнула південні пагорби Срібнолісся, Барон Сільверлейн правив гордим шляхетським маєтком. Його фортеця давала безпеку й нагляд довколишнім ґілнеаським землям. Цей мир розбився, коли Архімаг Аруґал, шукаючи зброю проти Погибелі, що лютувала довкола, випустив у край викликаних воргенів. Диких потвор не вдалося приборкати: вони штурмом узяли твердиню, здолали варту й порубали барона разом з усією його родиною.",sectionIndex=1}
c["npc:baros-alexston"] = "26682f"
P.scopedClips["npc:baros-alexston"] = {scope="overview-body",sourceHash="ddb188",hash="26682f",name="Барос Алекстон",summary="Барос Алекстон — Головний Архітектор Стормвінда, що працює в Ратуші над Соборною Площею. Колишній член Гільдії Каменярів, що допомагав відбудовувати столицю після Першої війни, він обрав офіційну посаду замість того, щоб піти за своїм давнім другом Едвіном Венкліфом у відкритий бунт.",section="Барос виріс на Хуторі Алекстона серед пологих луків Вестфолу. Коли він був юнаком, злодії напали на родинну садибу й підпалили її, тож його батько мусив поспіхом поховати найцінніші родинні реліквії по всьому обійстю, перш ніж утекти. Згодом Барос подався до столиці й вступив до Гільдії Каменярів, роками віддаючи виснажливу працю поряд із головою гільдії Едвіном Венкліфом, щоб підняти Стормвінд із попелу Першої війни.",sectionIndex=1}
c["npc:bazil-thredd"] = "fe1d9a"
P.scopedClips["npc:bazil-thredd"] = {scope="overview-body",sourceHash="7b50b7",hash="fe1d9a",name="Базіл Тредд",summary="Базіл Тредд — лейтенант і найдовіреніший помічник Едвіна Венкліфа, ув'язнений у В'язниці Стормвінда від часів бунту каменярів, під час якого загинула королева Тіффін. Тепер в'язниця повстала, і Тредд очолює бунтівних в'язнів Братства Дефіас зі свого східного блоку камер.",section="Коли знать Стормвінда відмовилася заплатити Гільдії Каменярів за відбудову міста, Едвін Венкліф відкинув урядові поступки й підняв відкритий бунт. Базіл Тредд стояв поруч із Венкліфом як його головний лейтенант і найдовіреніший помічник. Під час запеклих сутичок, що спалахнули слідом і забрали життя королеви Тіффін Рінн, Тредда схопила міська варта. Поки Венкліф і вцілілі каменярі тікали до Вестфолу, щоб заснувати Братство Дефіас, Тредда кинули в глибини В'язниці Стормвінда.",sectionIndex=1}
c["npc:bazzalan"] = "bb0972"
P.scopedClips["npc:bazzalan"] = {scope="overview-body",sourceHash="a32bba",hash="bb0972",name="Баззалан",summary="Баззалан — зловісний сатир-розбійник, що ховається у вулканічних глибинах Провалля Лютого Вогню. Разом із Джерґошем Призивачем він керує темними справами культу Пекучого Клинка просто під столицею Орди — Оргріммаром.",section="Поки Тралл працює над тим, щоб збудувати оркам нову домівку в Дуротарі, давнє зло знайшло собі лігво в нього під ногами. Баззалан, хитрий сатир-розбійник, уклав союз із культом Пекучого Клинка у звивистих лавових печерах Провалля Лютого Вогню. Прудкий і смертоносний із двома клинками, він — один із головних польових командирів культу.",sectionIndex=1}
c["npc:bethor-iceshard"] = "e2ea9a"
P.scopedClips["npc:bethor-iceshard"] = {scope="overview-body",sourceHash="17c940",hash="e2ea9a",name="Бетор Айсшард",summary="Бетор Айсшард — могутній маг із Відступників, що перебуває в Магічному Кварталі Андерсіті. Він очолює знавців чародійної й тіньової магії в Храмі Проклятих і має чималу владу в державі Сильвани. За його крижаною вдачею ховається минуле, сплетене зі старими друзями, яких розлучила Погибель.",section="У Храмі Проклятих Бетор Айсшард наглядає за знавцями чародійних мистецтв і тіньової магії Андерсіті. Шанований і страшний своїм розумом та крижаною рішучістю, Бетор має досить політичної й магічної ваги, щоб напряму віддавати накази провінційним магістратам по всьому Лордерона. Він посилає агентів Відступників здобувати цінні гримуари, розслідувати чародійні аномалії й знищувати ворожі сили, що загрожують владі Андерсіті.",sectionIndex=1}
c["npc:billy-maclure"] = "2fb34e"
P.scopedClips["npc:billy-maclure"] = {scope="overview-body",sourceHash="9979d9",hash="2fb34e",name="Біллі Маклур",summary="Біллі Маклур — бешкетний хлопчисько з людей, що живе на Виноградниках Маклюрів у Лісі Елвінн. Опинившись посеред запеклої ворожнечі між своєю родиною та сусідами Стоунфілдами, Біллі своїми дрібними витівками часто завдає клопоту обом фермам. Його слабкість до свіжої випічки робить його легкою здобиччю для підкупу, коли пустощі заходять надто далеко.",section="Біллі Маклура зазвичай можна застати, коли він тиняється біля клуні на Виноградниках Маклюрів, неподалік від фермера Джерарда Тіллера. Вирісши серед нескінченних рядів виноградної лози, Біллі здебільшого ухиляється від хатньої роботи й носиться сільськими луками центрального Лісу Елвінн. Як і вся його рідня, він добре знає про давню ворожнечу між Маклюрами та Стоунфілдами, та для Біллі ця чвара — радше гра в витівки й дрібні крадіжки, ніж серйозний конфлікт.",sectionIndex=1}
c["npc:blind-hunter"] = "895738"
P.scopedClips["npc:blind-hunter"] = {scope="overview-body",sourceHash="7f105d",hash="895738",name="Сліпий Мисливець",summary="Сліпий Мисливець — невловимий кажан-альбінос, що гніздиться глибоко в Рейзорфен Краулі. На відміну від звичайних кажанів, що тримаються біля входів до печер, це рідкісне створіння полює в безсонячних глибинах редуту шипогривів.",section="Рейзорфен Краул пронизаний звивистими терновиками й темними підземними печерами. Звичайні кажани Краула гніздяться ближче до поверхні, куди просочується тьмяне світло ззовні, а Сліпий Мисливець цілком пристосувався до найвіддаленіших, найтемніших закутків гущавини. Його бліда шкура альбіноса й каламутний погляд, найімовірніше, — наслідок поколінь, проведених цілком без сонячного світла.",sectionIndex=1}
c["npc:blind-mary"] = "c8b189"
P.scopedClips["npc:blind-mary"] = {scope="overview-body",sourceHash="563402",hash="c8b189",name="Сліпа Мері",summary="Сліпа Мері — змучена банші, що блукає покинутою, зруйнованою хатою на південний схід від Даркшира в Сутінколіссі. Колись вона була марнославною й вродливою смертною жінкою, але насильницька смерть і перетворення довели її до того, що з горя вона скалічила себе.",section="Доки тінь не лягла на Сутінколісся, Мері знали як ефектну жінку, що неабияк пишалася своєю вродою й рідко розлучалася з улюбленим дзеркальцем. Коли нежить заполонила край, Мері загинула разом із багатьма сусідами. Та, на відміну від тих, хто знайшов спокій у землі, її дух лишився серед живих — безтілесною банші, приреченою блукати світом смертних у моторошній, напівпрозорій подобі.",sectionIndex=1}
c["npc:bloodmage-thalnos"] = "24ebaa"
P.scopedClips["npc:bloodmage-thalnos"] = {scope="overview-body",sourceHash="756cfc",hash="24ebaa",name="Маг Крові Талнос",summary="Маг крові Талнос — маг-кістяк, що блукає в крилі Кладовища Багряного Монастиря. Колись він був катом-дізнавачем Багряного Хрестового Походу, але й сам піддався чумі нежиття, з якою так фанатично боровся, — і все ж досі тримається в глибині їхніх святих земель.",section="У ревних лавах Багряного Хрестового Походу Талнос зажив темної слави своїми жорстокими тортурами, які чинив під приводом очищення новобранців від зарази. Та попри фанатичну відданість викоріненню зла, маг-садист зрештою сам піддався чумі нежиття. Його не очистили й не знищили назавжди: він повстав зсохлим кістяком, що досі чіпляється за свою вогняну магію й майстерність у таємних мистецтвах.",sectionIndex=1}
c["npc:bolvar-fordragon"] = "6abf9b"
P.scopedClips["npc:bolvar-fordragon"] = {scope="overview-body",sourceHash="b43617",hash="6abf9b",name="Болвар Фордрагон",summary="Верховний Лорд Болвар Фордрагон — регент Стормвінда й верховний командувач його збройних сил після загадкового зникнення короля Варіана Рінна. Стоячи поруч із юним королем Андуїном Рінном у Фортеці Стормвінда, він намагається втримати королівство докупи серед дедалі гірших внутрішніх негараздів. Хоч Болвар — людина незламної честі, його військові рішення часто спрямовує й гальмує королівська радниця Леді Катрана Престор.",section="Коли король Варіан зник дорогою на мирні перемовини на Острові Терамор, Стормвінд поринув у політичний хаос. Десятирічного принца Андуїна коронували, щоб зберегти тяглість влади, але справжнє правління перейшло до Верховного Лорда Болвара Фордрагона як регента. Болвар — шанований паладин, відданий короні, та тягар на ньому величезний. Військо Стормвінда розпорошене по Вестфолу, Редріджу й Сутінколіссю. А на додачу Болвар часто прислухається до Леді Катрани Престор, чиї зневажливі поради раз у раз не дають йому послати королівські війська до віддалених містечок.",sectionIndex=1}
c["npc:brewmaster-drohn"] = "0f3b03"
P.scopedClips["npc:brewmaster-drohn"] = {scope="overview-body",sourceHash="9606bb",hash="0f3b03",name="Майстер Броварства Дрон",summary="Майстер Броварства Дрон — орк-бровар, що живе на пагорбі над гамірним портом Раджет. Мистецтва екзотичного бродіння він навчився завдяки зв'язкам із легендарним мандрівним пандареном Ченем Бурештофом і тепер варить міцні напої на посушливому прикордонні Пусток. Шукачі пригод, що натрапляють на покинуті барильця по всьому Калімдору, часто опиняються саме на його ґанку.",section="Над гоблінськими доками Раджета живе Майстер Броварства Дрон — орк, що присвятив себе не простому бою, а науці броварства. Він тримає Ґуральню Дрона у своєму домі на схилі пагорба й мирно працює в нейтральному прихистку, створеному Ґазлоу та картелем Стімвідл. Більшість орків задовольняється грубим ґроґом чи простою горілкою, а Дрон працює з рідкісними інгредієнтами, тонким балансом смаків і техніками, яких серед його родичів майже ніхто не знає.",sectionIndex=1}
c["npc:brine"] = "b34c71"
P.scopedClips["npc:brine"] = {scope="overview-body",sourceHash="ff68ea",hash="b34c71",name="Брайн",summary="Брайн — орчиха-шаманка, що живе серед посушливих пагорбів Кряжа Чорного Терну на півдні Пусток. Знавчиня духів води, вона веде учнів-шаманів духовним шляхом до єднання з припливами, щоб ті здобули свій Тотем Води.",section="Брайн живе на продуваному вітрами пагорбі в північній частині Кряжа Чорного Терну, далеко від гамірних торгових застав Пусток. Попри сухі савани довкола, вона присвятила життя пізнанню плинної й мінливої стихії води. Шаманів з усієї Орди посилають по її мудрість, щойно вони опанують землю й вогонь, бо вода вимагає терпіння й широкого погляду, які мало хто розуміє так глибоко, як вона.",sectionIndex=1}
c["npc:bruegal-ironknuckle"] = "04b1a8"
P.scopedClips["npc:bruegal-ironknuckle"] = {scope="overview-body",sourceHash="1461ca",hash="04b1a8",name="Бруеґал Айроннакл",summary="Бруеґал Айроннакл — сумнозвісний дворф-в'язень у В'язниці Стормвінда. На відміну від дрібних злочинців і бунтівного наброду, що заповнюють камери, він — грізний кулачний боєць, і його присутність у глибині коридорів означає безпосередню небезпеку для кожного, хто намагається навести лад.",section="Коли у В'язниці Стормвінда спалахнув відкритий бунт, чимало найнебезпечніших головорізів міста захопили підземні блоки камер. Серед них — Бруеґал Айроннакл, особливо небезпечний в'язень-дворф, відомий своєю жорстокою силою в бійці. Замість сидіти в одній камері, він никає розтрощеними бунтом коридорами, готовий розквасити пику кожному, хто спробує придушити заколот.",sectionIndex=1}
c["npc:cairne-bloodhoof"] = "9bdb0f"
P.scopedClips["npc:cairne-bloodhoof"] = {scope="overview-body",sourceHash="cfeb54",hash="9bdb0f",name="Кайрн Бладгуф",summary="Кайрн Бладгуф — поважний Верховний Вождь об'єднаних тауренських племен і правитель Тандер Блафу. Величезний воїн неосяжної мудрості, він зв'язав долю тауренів з Ордою Тралла після того, як орки допомогли його народові уникнути винищення від рук кентаврів.",section="Поколіннями таурени жили мандрівними кочовиками по Пустках, і дикі кентаври-грабіжники без упину полювали на них, штовхаючи до загибелі. Коли Тралл зі своїми орками прибув на береги Калімдору, Кайрн розгледів у них рідкісну шляхетність. Тралл запропонував військовий захист і провів зневірену валку Кайрна через рівнини до безпечного Малгору в обмін на дорогу до Оракула на Піку Кам'яного Кігтя. Оселившись на високих плато Тандер Блафу, Кайрн нарешті заснував постійний, єдиний дім для всіх тауренських племен.",sectionIndex=1}
c["npc:calor"] = "0bfc34"
P.scopedClips["npc:calor"] = {scope="overview-body",sourceHash="319fc7",hash="0bfc34",name="Калор",summary="Калор — відданий мешканець Даркшира, що допомагає Нічній Варті та родині Каревінів захищати Сутінколісся. Діючи за вказівками Джонатана Каревіна, він організовує полювання на лютих воргенів, які нишпорять похмурими лісами. Шукачі пригод, що прагнуть відігнати ненажерливих звірів, часто отримують завдання саме від нього.",section="Калор живе в обложеному Даркширі й тісно співпрацює з Джонатаном Каревіном, одним із чільних захисників міста. Серед нескінченного мороку й повзучих жахів Сутінколісся Калор віддає себе справі родини Каревінів: знищити надприродні жахіття, що підступають до околиць міста, доки ті не вирізали решту мешканців.",sectionIndex=1}
c["npc:canaga-earthcaller"] = "2ca9a3"
P.scopedClips["npc:canaga-earthcaller"] = {scope="overview-body",sourceHash="559d78",hash="2ca9a3",name="Канаґа Ерткаллер",summary="Канаґа Ерткаллер — троль-шаман із племені Темного Списа, що стоїть у випаленій сонцем Долині Випробувань. Він навчає шаманів-новачків Орди спілкуватися з духами землі й здобувати перші стихійні тотеми. Окрім настанов в обрядах, він пильнує за пораненими розвідниками та загрозами, що виникають поблизу Лігва.",section="На червоних кручах Долини Випробувань Канаґа Ерткаллер є одним із найперших духовних провідників для тролів Темного Списа та орків, що стають на шлях шамана. Поки багато наставників дбають лише про бойову готовність, Канаґа вчить новачків утихомирити розум і прислухатися до гуркоту самого Калімдору, готуючи земляну сапту, потрібну для спілкування з духами.",sectionIndex=1}
c["npc:captain-grayson"] = "ac5f6a"
P.scopedClips["npc:captain-grayson"] = {scope="overview-body",sourceHash="5119b3",hash="ac5f6a",name="Капітан Ґрейсон",summary="Капітан Ґрейсон — неспокійний дух піратського капітана, що чатує біля Маяка Вестфолу. Сам загинувши, коли його корабель розбився об темне узбережжя, він тепер стереже маяк, щоб інших мореплавців не спіткала його доля.",section="За життя Ґрейсон водив корабель небезпечними південними морями Східних Королівств. Його плавання жорстоко обірвалося біля зубчастих мілин Вестфолу тієї ночі, коли вогонь маяка згас. Викинутий на скелі, Ґрейсон загинув разом зі своїм кораблем — і прокинувся привидом, прикутим до узбережжя.",sectionIndex=1}
c["npc:captain-greenskin"] = "30c52a"
P.scopedClips["npc:captain-greenskin"] = {scope="overview-body",sourceHash="015378",hash="30c52a",name="Капітан Ґрінскін",summary="Капітан Ґрінскін — елітний гоблін-пірат, що наглядає за будівництвом і командою величезного броненосця Едвіна Венкліфа. Захований глибоко в підземній бухті Мертвих Копалень, він командує піратами, яких найняло Братство Дефіас. Його мета — підготувати бойовий корабель до походу на Стормвінд.",section="Походжаючи головною палубою велетенського броненосця, що його будують у бухті Мертвих Копалень, капітан Ґрінскін уособлює морську силу змови Дефіас. Досвідчений гоблін-мореплавець, який раніше орудував із Буті Бей, Ґрінскін увійшов до найближчого кола Едвіна Венкліфа, щоб перетворити підземну печеру на сухий док для бойового корабля.",sectionIndex=1}
c["npc:captain-stoutfist"] = "f61713"
P.scopedClips["npc:captain-stoutfist"] = {scope="overview-body",sourceHash="65311a",hash="f61713",name="Капітан Стаутфіст",summary="Капітан Стаутфіст — дворфійський офіцер, що відповідає за оборону Гавані Менетіл у Багнокраї. Клан Драконячої Пащі дедалі зухваліше висувається зі своїх болотяних твердинь, тож Стаутфіст керує обороною й контрнаступами, щоб важливий порт Альянсу не впав.",section="Гавань Менетіл — головний глибоководний порт, що поєднує Айронфордж і Стормвінд із болотистими низинами Багнокраю й морем за ними. Як комендант міста, Капітан Стаутфіст несе важкий тягар: він мусить уберегти доки, мирних мешканців і гарнізон від довколишніх загроз. Болота славляться своїми небезпеками, але найбільша загроза для поселення — організований наступ орків-ренегатів.",sectionIndex=1}
c["npc:carendin-halgar"] = "fa0614"
P.scopedClips["npc:carendin-halgar"] = {scope="overview-body",sourceHash="ecd0b5",hash="fa0614",name="Карендін Галґар",summary="Карендін Галґар — відомий наставник чорнокнижників із Відступників, що мешкає в Магічному Кварталі Андерсіті. Гострий на язик і сумнозвісно нетерплячий, він наглядає за вишколом молодих знавців темних мистецтв. Він навчає чорнокнижників підкоряти могутніх демонічних істот із Викривленого Нижнього Світу, зокрема обрядів, що зв'язують блукачів Порожнечі й сукубів.",section="У смердючому присмерку Магічного Кварталу Андерсіті Карендін Галґар навчає тих, хто заглиблюється у Викривлений Нижній Світ. Він вимагає зосередженості й послуху і майже не терпить невдач, вагань чи слабкості. Під його пильним оком чорнокнижники переходять від простих заклинань до небезпечного мистецтва прикликання й маніпуляції душами, що лише утверджує безжальний підхід Відступників до служби демонів.",sectionIndex=1}
c["npc:charlga-razorflank"] = "ed421c"
P.scopedClips["npc:charlga-razorflank"] = {scope="overview-body",sourceHash="430ec0",hash="ed421c",name="Чарлґа Рейзорфленк",summary="Чарлґа Рейзорфленк, широко відома як Стара з Краула, — люта й хитра геомантка-ватажок, що панує над Рейзорфен Краулом. Під її проводом шипогриви Рейзорфен безжальною експансією вигнали тауренів із південних Пусток, стверджуючи, що борються в ім'я свого полеглого бога Аґамаґґана.",section="Серед заплутаних велетенських терновиків Рейзорфен Краула править Чарлґа Рейзорфленк. Її народ шанує її як майстриню геомантії, чия експериментальна магія не має рівних серед шипогривів, і Чарлґа згуртувала своїх свавільних родичів у єдину смертоносну загрозу. Вона підкорила первісну землю й велетенські колючки, що проросли з решток напівбога Аґамаґґана, перетворивши лабіринт Краула на неприступну фортецю.",sectionIndex=1}
c["npc:chief-engineer-hinderweir-vii"] = "87fafd"
P.scopedClips["npc:chief-engineer-hinderweir-vii"] = {scope="overview-body",sourceHash="381452",hash="87fafd",name="Головний Інженер Гіндервір VII",summary="Головний Інженер Гіндервір VII — досвідчений дворф-інженер, що несе службу на вершині Каменетесної Греблі в Лох Модані. Йому доручено утримувати й обороняти цю монументальну інженерну споруду: він наглядає за її делікатними механізмами й пильнує, щоб не сталося диверсії. Кожен, хто з ним заговорить, швидко дізнається, що цілості великої греблі загрожує серйозна небезпека.",section="Каменетесна Гребля — одне з найвищих досягнень дворфійського каменярства й інженерії: вона стримує величезні води Лоху. На Головному Інженерові Гіндервірі VII лежить величезна відповідальність за її споруду й робочі механізми. Влаштувавшись на гребені греблі, він стежить за водотоками, шлюзами й вразливими місцями конструкції, оберігаючи їх від стихії та місцевих небезпек.",sectionIndex=1}
c["npc:chief-hawkwind"] = "6e2e8d"
P.scopedClips["npc:chief-hawkwind"] = {scope="overview-body",sourceHash="ed10a9",hash="6e2e8d",name="Вождь Гоквінд",summary="Вождь Гоквінд — племінний ватажок Табору Нарачі, місця випробувань, що сховалося на Плато Червоної Хмари в Малгорі. Він наставляє молодь Шу'хало й веде новачків-шукачів пригод через традиційні обряди посвяти. Під його пильним оком юні сміливці вчаться смирення, поваги до землі та сили, потрібної, щоб захищати свій народ.",section="Стоячи в серці Табору Нарачі, Вождь Гоквінд несе урочистий обов'язок — готувати нове покоління тауренів до великого світу. Плато Червоної Хмари править за затишний прихисток, де мисливці, шамани, друїди й воїни-початківці проходять прадавні Обряди Земної Матері. Гоквінд наглядає за цими звичаями й дбає, щоб кожен юнак пізнав обов'язок і витривалість, перш ніж ступити за безпечні межі плато.",sectionIndex=1}
c["npc:clerk-daltry"] = "776961"
P.scopedClips["npc:clerk-daltry"] = {scope="overview-body",sourceHash="3cf937",hash="776961",name="Писар Долтрі",summary="Писар Долтрі — міський архіваріус у Ратуші Даркшира в Сутінколіссі. Оточений книгами обліку й реєстрами, він допомагає розкривати минуле містечка й розшукувати давні записи, хоч його архів і доволі занедбаний та застарілий.",section="Поки Даркшир бореться з навалою звірів, жахами нежиті й надприродним мороком, буденні міські справи лягають на плечі Писаря Долтрі. Працюючи в Ратуші Даркшира разом із Лордом Елло Ебонлоком і місцевою радою, Долтрі веде історичні книги міста, реєстри майна й переписи. У краї, розколотому лихом, його записи — одна з небагатьох уцілілих ниток, що тягнуться до часів, коли Велике Селище ще не поринув у тінь.",sectionIndex=1}
c["npc:cliffwatcher-longhorn"] = "6c48e3"
P.scopedClips["npc:cliffwatcher-longhorn"] = {scope="overview-body",sourceHash="7bec53",hash="6c48e3",name="Скельний Вартовий Лонггорн",summary="Скельний Вартовий Лонггорн — незворушний тауренський ватажок, що несе варту високо на Заставі Вільного Вітру в Тисячі Голок. Йому доручено оберігати відрізану від світу заставу Орди: він організовує оборону від кентаврів Ґалак, що підступають, і стежить за підозрілими інтригами племені Ґрімтотем.",section="Застава Вільного Вітру, що височіє на кам'яних шпилях Тисячі Голок, виживає завдяки пильним очам і твердій руці. Скельний Вартовий Лонггорн щодня дбає про безпеку цього хиткого поселення. Унизу, на дні каньйону, і на сусідніх гребенях збираються ворожі сили, тож саме Лонггорн зводить докупи донесення розвідників і керує обороною.",sectionIndex=1}
c["npc:coleman-farthing"] = "42a365"
P.scopedClips["npc:coleman-farthing"] = {scope="overview-body",sourceHash="bb7bfc",hash="42a365",name="Коулмен Фартінґ",summary="Коулмен Фартінґ — озлоблений уцілілий з-поміж Відступників, що мешкає в Таверні «Шибеничний Кінець» у Бріллі. За життя він працював на заможну династію Аґамандів на їхніх великих борошняних млинах у північному Тірісфалі. Умовлений лишитися й боронити маєток від Погибелі, він загинув разом із товаришами-робітниками, а тепер присвячує своє нежиття помсті колишнім господарям.",section="До Третьої війни Коулмен Фартінґ чесно заробляв на життя робітником на Млинах Аґаманда — найбільшому млинарському й сільському господарстві Галявин Тірісфалю. Коли Погибель ринула на Лордерон, аристократична родина Аґамандів відмовилася тікати зі своїх цінних земель. Натомість вони закликали челядь і робітників узятися за зброю разом із ними, обіцяючи, що хутори вдасться втримати проти орди нежиті. Коулмен і його товариші лишилися, повіривши господарям, — і це рішення коштувало життя кожному з них.",sectionIndex=1}
c["npc:collin-mauren"] = "f55c2a"
P.scopedClips["npc:collin-mauren"] = {scope="overview-body",sourceHash="e1098a",hash="f55c2a",name="Коллін Маурен",summary="Коллін Маурен — людина-маг, що живе в Кварталі магів Стормвінда. Учений-дослідник і творець заклинань, він експериментує з екзотичними природними реагентами, щоб вигадувати незвичні прикладні чари. Серед іншого він допомагає своєму знайомому, гномові-інженерові й досліднику Ґаксиму Растфіззлу, особливими чародійними сувоями.",section="Оселившись у гомінкому Кварталі магів Стормвінда, Коллін Маурен присвячує дні тихішим, практичнішим застосуванням магії. Замість гонитви за сирою силою стихій він створює чародійні формули, що розв'язують конкретні щоденні задачі. Коллін часто звертається до природних аномалій і сирих складників, зібраних по всьому Азероту, вплітаючи їхні властивості в робочі магічні сувої та реагенти для друзів і мандрівників.",sectionIndex=1}
c["npc:commander-springvale"] = "68075d"
P.scopedClips["npc:commander-springvale"] = {scope="overview-body",sourceHash="494c6a",hash="68075d",name="Командир Спрінґвейл",summary="Командир Спрінґвейл колись був відданим паладином і очільником збройної варти Барона Сільверлейна у Фортеці Шадовфенг. Він загинув разом зі своїми вояками під час різанини, яку влаштували дикі воргени, викликані Архімагом Аруґалом, і тепер його мстивий дух блукає залами замку. Навіть після смерті його привид люто стереже фортецю й прагне помститися за свого полеглого пана.",section="До загибелі Фортеці Шадовфенг Командир Спрінґвейл був шляхетним паладином, відданим Святому Світлу, і присяжним захисником Барона Сільверлейна. Очолюючи гарнізон у Срібноліссі, він відповідав за безпеку фортеці в тривожні дні після того, як Лордерон упав під натиском Погибелі.",sectionIndex=1}
c["npc:cookie"] = "4c55ea"
P.scopedClips["npc:cookie"] = {scope="overview-body",sourceHash="1a6a7c",hash="4c55ea",name="Печивко",summary="Печивко — елітний мурлок, корабельний кок на броненосці, захованому глибоко в Мертвих Копальнях. Незвичний новобранець Братства Дефіас, він доглядає казани команди під пильним оком капітана Ґрінскіна та Едвіна Венкліфа. Це єдиний цілком необов'язковий бос у підземному сухому доці.",section="Під палубами височенного броненосця в Бухті Айронклад куховарить не людина-розвідник і не гоблін-інженер, а самотній мурлок, якого звуть просто Печивко. Як він здобув цю посаду, лишається таємницею, яку знає лише сам Едвін Венкліф. Хай які сумніви має решта команди щодо мурлока, що порядкує їхнім пайком, пірати рідко можуть перебирати, а в підземному світі Мунбрука їжа — то їжа.",sectionIndex=1}
c["npc:corithras-moonrage"] = "8d1a26"
P.scopedClips["npc:corithras-moonrage"] = {scope="overview-body",sourceHash="dd4036",hash="8d1a26",name="Корітрас Мунрейдж",summary="Корітрас Мунрейдж — учений нічних ельфів і давач завдань у селищі Доланаар на Тельдрассилі. Він допомагає новоприбулим шукачам пригод збагнути природу великого Світового Дерева й доручає їм дбати про його священні місячні колодязі. Його уроки розкривають і духовну вагу Тельдрассила, і дедалі важчий тягар, що лягає на калдореїв.",section="Корітрас Мунрейдж мешкає в тінистому поселенні Доланаар і наставляє мандрівників, що залишають захищені межі Тінедолу. Коли молоді калдореї вирушають у ширше гілля Тельдрассила, Корітрас дбає, щоб вони розуміли історію своєї нової домівки. Він навчає, що вижити в цю мінливу добу можна лише пильністю та шаною до природного ладу.",sectionIndex=1}
c["npc:dalar-dawnweaver"] = "a27adc"
P.scopedClips["npc:dalar-dawnweaver"] = {scope="overview-body",sourceHash="dbf08f",hash="a27adc",name="Далар Донвівер",summary="Далар Донвівер — колишній архімаг Даларана, що нині служить Відступникам у Гробниці в Срібноліссі. Загинувши, коли Погибель знищувала місто магів, і згодом звільнившись з-під влади Короля-Ліча, він спрямовує свій магічний розум на розбір загроз краю. Із тіні гробниці він керує зусиллями, щоб з'ясувати, що досі робить у краї Даларан, і виправити наслідки божевілля Архімага Аруґала.",section="За життя Далар Донвівер мав високий ранг у Кірін-Торі й ходив залами Фіолетової Цитаделі, коли Даларан був вершиною таємної майстерності. Його смертне життя обірвалося, коли Погибель сплюндрувала місто, щоб розчистити шлях для виклику Архімонда. Піднятий як бездумний раб Короля-Ліча, Далар вирвався на волю разом із Леді Сильваною Віндраннер, коли хватка Погибелі ослабла. Нині, у Гробниці, він зберігає гострий розум архімага, цілком спрямований на захист королівства Відступників.",sectionIndex=1}
c["npc:daphne-stilwell"] = "552540"
P.scopedClips["npc:daphne-stilwell"] = {scope="overview-body",sourceHash="f2b672",hash="552540",name="Дафна Стілвелл",summary="Дафна Стілвелл доглядає відлюдний сад на прибережних кручах Вестфолу над Лонгшором. Разом із чоловіком Джорданом вона втекла від смути на півночі й переселилася на південь, де тихо допомагає Церкві Святого Світла й боронить свій дім від сусідніх розбійників.",section="На урвищах на захід від Мунбрука й виходу з Мертвих Копалень Дафна Стілвелл веде відлюдне господарство з яблуневим садом. Знизу, з Лонгшору, чи згори, з грифонових маршрутів на південь до Долини Стренглторну, маленька ферма здається тихою й непримітною. Та тримати господарство в нинішньому Вестфолі — аж ніяк не безпечно. Попри розбійників, що підступають, і мародерів, що никають довкола, Дафна сумлінно доглядає дерева й пильнує свій відлюдний клаптик землі.",sectionIndex=1}
c["npc:darsok-swiftdagger"] = "dfa9be"
P.scopedClips["npc:darsok-swiftdagger"] = {scope="overview-body",sourceHash="cba460",hash="dfa9be",name="Дарсок Свіфтдаґґер",summary="Дарсок Свіфтдаґґер — орк-воїн і розвідник, що несе службу на Перехресті в самому серці Пусток. Відомий лютою ненавистю до гарпій, він посилає шукачів пригод з Орди на північ, до Сухих Пагорбів, щоб зламати пташиний матріархат, який допікає мандрівникам і поселенням. Він підтримує зв'язки по всіх рівнинах і є довіреною особою Знахаря Джин'Зіла в Малака'джині.",section="Серед гамору Перехрестя Дарсок Свіфтдаґґер пильно стежить за загрозами, що виповзають із північних чагарників. Торговий шлях, який з'єднує Дуротар, Малгор і північні краї, постійно в облозі — не лише від грабіжників і кентаврів, а й від злагоджених повітряних мисливців. Свій гнів Дарсок спрямовує на гарпій Відьмокрилих, чиї гнізда в Сухих Пагорбах на північний захід від Забутих ставків прямо загрожують північним караванам.",sectionIndex=1}
c["npc:deathguard-dillinger"] = "0b5ea9"
P.scopedClips["npc:deathguard-dillinger"] = {scope="overview-body",sourceHash="5fa035",hash="0b5ea9",name="Вартовий Смерті Діллінджер",summary="Вартовий Смерті Діллінджер — вартівник Відступників у Бріллі, у Галявинах Тірісфалю. Пильнуючи околиці містечка, він скеровує новоприбулих мерців до потрібних служб і доручає новобранцям тримати на відстані рештки Погибелі.",section="Як член Варти Смерті Відступників, Діллінджер стоїть біля входу до Брілла — водночас захисник передової й провідник для подорожніх, що приходять із Похоронного Подзвону. Він підказує дорогу до корчми, ратуші й місцевих наставників, допомагаючи щойно пробудженим мерцям зорієнтуватися в новій дійсності під владою Темної Леді.",sectionIndex=1}
c["npc:delgren-the-purifier"] = "ffabff"
P.scopedClips["npc:delgren-the-purifier"] = {scope="overview-body",sourceHash="3a2c8d",hash="ffabff",name="Делґрен Очищувач",summary="Делґрен Очищувач — паладин-людина, що несе службу на Пості Маестри на північній околиці Ашенвалю. Разом із соратниками Балтулом Шедовстрайком і Фіро Айронгендом він допомагає нічним ельфам очищати прикордоння від демонічної та тіньової магії, а насамперед протистоїть зловісному Культу Темного Берега.",section="Паладини-люди — рідкісні гості в глибині прадавніх лісів Калімдору, але Делґрен Очищувач прибув сюди з певною місією. Пов'язаний зі Срібним світанком, він вирушив на захід разом із загоном святих воїнів, сповнених рішучості допомогти новим союзникам Альянсу — нічним ельфам — у боротьбі з недобитим злом: демонами та рештками нежиті, що лишилися після Третьої війни. Отаборившись біля межі Темного Узбережжя й Ашенвалю, він пильно стежить за мандрівниками, які прямують на південь з Обердайна.",sectionIndex=1}
c["npc:denalan"] = "48937b"
P.scopedClips["npc:denalan"] = {scope="overview-body",sourceHash="d1a145",hash="48937b",name="Деналан",summary="Деналан — досвідчений травник і ботанік нічних ельфів, що порається на тихій ділянці біля східного берега Озера Ал'Амет. Під простим навісом він присвячує дні вивченню рослинного світу острова й пошуку ботанічних ліків від дивної скверни, що вражає Тельдрассил. Він часто залучає молодих шукачів пригод збирати зразки, вивчати розлючених деревляників і випробовувати зачаровані ґрунти.",section="Поки багато калдореїв зосереджені на військовій пильності чи високих друїдських обрядах, Деналан обрав терпляче, скрупульозне ремесло травника. На тихому східному березі Озера Ал'Амет він облаштував скромний дослідницький табір: полотняний навіс, прості польові знаряддя й охайні ряди грядок у ящиках. Замість ховатися у величних курганах Дарнасуса він воліє лишатися ближче до землі й напряму вивчати незвичну флору, що проросла після насадження нового Світового Дерева.",sectionIndex=1}
c["npc:dendrite-starblaze"] = "ecd4c3"
P.scopedClips["npc:dendrite-starblaze"] = {scope="overview-body",sourceHash="1cb3cf",hash="ecd4c3",name="Дендрит Старблейз",summary="Дендрит Старблейз — друїд нічних ельфів, що живе у священному селищі Нічний Притулок у Місячному Гаю. На службі Кола Кенарія він став важливим наставником і провідником для молодих друїдів — і нічних ельфів, і тауренів. Через нього новачків кличуть до священного гаю, щоб опанувати важливі обряди, як-от очищення від отрут і єднання з подобами природи.",section="Дендрит Старблейз, що оселився в Нічному Притулку, уособлює безсторонній, незмінний дух Кола Кенарія. Коли молоді друїди вчаться налаштовувати дух на закляття «Телепорт: Місячний Гай», Дендрит одним із перших вітає їх по прибутті. Він поєднує давню калдорейську традицію з новим шляхом тауренів і під гіллям священного прихистку вважає рідними всіх, хто чує поклик дикої природи.",sectionIndex=1}
c["npc:devrak"] = "750510"
P.scopedClips["npc:devrak"] = {scope="overview-body",sourceHash="7c1597",hash="750510",name="Деврак",summary="Деврак — орк, господар вітрокрилів на Перехресті в Пустках. Він — головний повітряний вузол центрального Калімдору: наглядає за мережею віверн Орди, які переносять припаси й гінців між Дуротаром, Малгором і прикордонними заставами. Він також дбає, щоб важливі вантажі, як-от дичина й вичинені шкури, без перешкод діставалися столиць Орди.",section="На перетині головних торгових шляхів Калімдору Деврак доглядає віверн, завдяки яким Орда залишається єдиною попри величезні відстані. Перехрестя лежить відкрите під пекучим сонцем, вразливе і для шипогривів, і для кентаврів, і для розвідників Альянсу, тож швидке сполучення повітрям незамінне. Деврак обслуговує і бувалих мандрівників, і недосвідчених гінців, підбираючи їм навчених вітрокрилів, здатних перетнути савану й дістатися гірських висот Малгору чи кам'яних каньйонів Дуротара.",sectionIndex=1}
c["npc:dextren-ward"] = "c70e61"
P.scopedClips["npc:dextren-ward"] = {scope="overview-body",sourceHash="00cfd8",hash="c70e61",name="Декстрен Ворд",summary="Декстрен Ворд — сумнозвісний злочинець і грабіжник могил, ув'язнений у В'язниці Стормвінда. До арешту він наживався, викопуючи тіла на Цвинтарі Воронячого Пагорба в Сутінколіссі й постачаючи їх некромантові Морбенту Фелу. Тепер, опинившись у вирі кривавого бунту у в'язниці, він досі засуджений на смерть міською радою Даркшира.",section="Перш ніж опинитися в кайданах під вулицями Стормвінда, Декстрен Ворд вів похмуру й прибуткову справу в оповитих туманом лісах Сутінколісся. Цвинтар Воронячого Пагорба вже й так був місцем скорботи й наростаючого жаху, але Ворд ставився до тамтешніх поховань як до власного кар'єру. Він полював не лише на дрібнички й родинні реліквії, залишені з мерцями, — Ворд торгував плоттю, розкопуючи свіжі могили, щоб постачати місцевих темних чаклунів.",sectionIndex=1}
c["npc:dirania-silvershine"] = "90d555"
P.scopedClips["npc:dirania-silvershine"] = {scope="overview-body",sourceHash="594c61",hash="90d555",name="Діранія Сілвершайн",summary="Діранія Сілвершайн — нічна ельфійка, мешканка Тінедолу на Тельдрассилі. Глибоко віддана й спостережлива, вона наглядає за тихим гаєм і пильнує свого товариша Іверрона, коли його нерозважливі витівки доводять до біди.",section="Діранія стоїть серед тихого гілля Тінедолу — відлюдної долини, де молоді нічні ельфи починають службу Калімдору й Альянсу. Поки чимало мешканців курганів і святилищ дбають про високі духовні обов'язки, Діранія пам'ятає про тих, хто поруч, і помічає тихі небезпеки, що ворушаться навіть у серці Тельдрассила.",sectionIndex=1}
c["npc:dorn-plainstalker"] = "4c22e3"
P.scopedClips["npc:dorn-plainstalker"] = {scope="overview-body",sourceHash="a9d0a3",hash="4c22e3",name="Дорн Плейнстокер",summary="Дорн Плейнстокер — самотній тауренський старійшина, що живе в Обвітреному Закутку над каньйонами Тисячі Голок. Він наглядає за давніми випробуваннями-посвятами й кидає виклик шукачам пригод Орди, щоб ті довели свою вдачу й стійкість. Випробуваннями віри, витривалості, сили та знань він перевіряє, чи гідні мандрівники служити Земній Матері та своєму народові.",section="Дорн Плейнстокер живе осторонь від метушні Застави Вільного Вітру — у неглибокій печері високо на гребенях каньйону, в Обвітреному Закутку. Щоб дістатися його гірського сховку, треба довго петляти прямовисними північними скелями над височенними столовими горами внизу. З цього тихого місця Дорн береже давні звичаї та судить тих, хто шукає настанов у суворих південних пустищах.",sectionIndex=1}
c["npc:duthorian-rall"] = "972b0d"
P.scopedClips["npc:duthorian-rall"] = {scope="overview-body",sourceHash="3590b0",hash="972b0d",name="Дуторіан Ралл",summary="Дуторіан Ралл — шанований лицар-людина Срібної Длані, що служить у Соборі Світла в Стормвінді. Знаний як один із найвпливовіших паладинів Альянсу, він наглядає за навчанням і духовними випробуваннями молодих святих воїнів. Він веде новобранців крізь урочисті обітниці милосердя, звитяги й відданості, щоб вони захищали Азерот від Погибелі й прихованих загроз усередині королівства.",section="Стоячи в склепінчастому трансепті Собору Світла, Дуторіан Ралл уособлює шановані традиції Лицарів Срібної Длані. Королівство похитують внутрішні чвари й зникнення короля Варіана Рінна, тож на Дуторіанові лежить важливий обов'язок — прищеплювати новим посвяченим праведну дисципліну. Шановані паладини з різних куточків, зокрема Брат Вільгельм у Нортширі та Брандур Айронгаммер в Айронфорджі, спрямовують до нього перспективних новобранців, щоб ті розпочали свої священні випробування.",sectionIndex=1}
c["npc:edwin-vancleef"] = "7a5738"
P.scopedClips["npc:edwin-vancleef"] = {scope="overview-body",sourceHash="421706",hash="7a5738",name="Едвін Венкліф",summary="Едвін Венкліф — блискучий голова Гільдії Каменярів, що відбудував Стормвінд після Другої війни. Коли Дім Вельмож ошукав його з оплатою, він очолив жорстокий бунт робітників і заснував розбійницьке Братство Дефіас. З глибин Мертвих Копалень у Вестфолі він прагне помститися королівству, яке сам допоміг відродити.",section="Після спустошень Першої війни саме Едвіна Венкліфа обрали очолити Гільдію Каменярів у величезній справі — відбудові Стормвінда. Неперевершений майстер та ідеаліст, Венкліф керував спорудженням величних мурів і височенних соборів столиці, а також наглядав за будівництвом Замку Незерґард, що стеріг Темний Портал. Крім хисту зодчого, Венкліф був напрочуд небезпечним агентом: скрадатися, плести підступи й орудувати клинком його навчив друг дитинства — Матіас Шоу.",sectionIndex=1}
c["npc:eitrigg"] = "741c7c"
P.scopedClips["npc:eitrigg"] = {scope="overview-body",sourceHash="992033",hash="741c7c",name="Ейтріґґ",summary="Ейтріґґ — бувалий ветеран Першої та Другої воєн, що стоїть поруч із Вождем Траллом як шанований радник в Оргріммарі. Колись він був одним із найвищих воєначальників клану Блекрок, але розчарувався в давній, демонічній Орді й жив у вигнанні, аж поки незвичайна дружба з людиною-паладином не змінила його долю. Нині він допомагає вести Нову Орду назад до її витоків — честі й шаманства.",section="Ейтріґґ народився на Дренорі в клані Блекрок і колись був одним із головних воєначальників Вождя Блекганда — поряд з Оргрімом Думхаммером і Вароком Саурфангом. Коли Думхаммер очолив Орду, Ейтріґґ лишився довіреним командиром і наглядав за полоненою вбивцею-напіворкинею Ґароною. Спершу він відкинув її викриття про Ґул'дана й демонічну скверну Ради Тіней, та жахливі битви й остаточна поразка Орди в Другій війні змусили його поглянути в очі темній правді. Збридивши тим, як маніпулювали його народом, Ейтріґґ полишив розпорошені рештки Орди й подався в добровільне вигнання, шукаючи лише самотності в диких краях Лордерона.",sectionIndex=1}
c["npc:electrocutioner-6000"] = "37b7e4"
P.scopedClips["npc:electrocutioner-6000"] = {scope="overview-body",sourceHash="aafc47",hash="37b7e4",name="Електрокутор 6000",summary="Електрокутор 6000 — смертоносний, надзаряджений павукоподібний танк, що обороняє Стартовий відсік в опромінених залах Гномреґана. Ним керує горезвісний гном-прокажений лейтенант Том «Шкварчоштан» Кренкл, і ця машина втілює безрозсудне прагнення Мехінженера Термаплаґа перетворити струм високої напруги на зброю.",section="Мехінженер Термаплаґ ніколи не славився ретельними випробуваннями на безпеку. Гнаний манією величі й поспіхом, він раз у раз кидає неперевірені бойові машини просто з креслярської дошки в бій. Електрокутор 6000 став його першою спробою приборкати сирий електричний струм як наступальну систему на броньованому павукоподібному шасі. Замість налагодити смертельні стрибки напруги в лабораторії, Термаплаґ одразу послав машину стерегти верхні яруси Стартового відсіку Гномреґана.",sectionIndex=1}
c["npc:elling-trias"] = "47c89b"
P.scopedClips["npc:elling-trias"] = {scope="overview-body",sourceHash="07f45f",hash="47c89b",name="Еллінг Тріас",summary="Еллінг Тріас тримає крамничку «Сири Тріаса» в гомінкому Торговому Кварталі Стормвінда. Він видає себе за веселого й завзятого торговця сирами, але потай є одним із найобізнаніших посередників у торгівлі відомостями в королівстві. За сирними головками й привітними балачками Тріас тримає вухо при землі, і його слух сягає через континенти.",section="Для випадкового покупця, що прогулюється Торговим Кварталом, Еллінг Тріас — просто майстер, відданий добірним сирам, який веде крамницю разом із дружиною Елейн і сином Беном. Він завзято розхвалює сирні головки й привітно балакає з містянами. Та обізнані люди знають: «Сири Тріаса» — одне з найнадійніших прикриттів у Стормвінді. Невпинний гомін міської торгівлі ідеально приховує агентів, придворних і шукачів пригод, яким треба перекинутися тихим словом, не привертаючи уваги міської варти.",sectionIndex=1}
c["npc:executor-arren"] = "aae39e"
P.scopedClips["npc:executor-arren"] = {scope="overview-body",sourceHash="686ca5",hash="aae39e",name="Екзекутор Аррен",summary="Екзекутор Аррен — високопоставлений офіцер Відступників в Похоронному Подзвоні. Він наглядає за безпосередньою обороною й зміцненням поселення, поки щойно пробуджені мерці виходять зі своїх могил. Аррен керує місцевою кампанією проти безтямних зомбі Погибелі, здичавілих звірів і фанатиків Багряного Хрестового Походу, що насуваються.",section="Непохитно стоячи одразу біля каплиці в Похоронному Подзвоні, Екзекутор Аррен — головний військовий голос молодих Відступників на землях їхнього пробудження. Поки доглядачі в склепах виводять щойно воскреслих мерців із заціпеніння, Аррен спрямовує їхню увагу назовні — на виживання. Під прапором Королеви Сильвани Віндраннер він організовує місцеві операції, щоб вимести безтямних зомбі, які загрожують межам села, і закріпити безпечну землю в тіні падіння Лордерона.",sectionIndex=1}
c["npc:executor-zygand"] = "dd6e66"
P.scopedClips["npc:executor-zygand"] = {scope="overview-body",sourceHash="91c1d2",hash="dd6e66",name="Екзекутор Зиґанд",summary="Екзекутор Зиґанд — старший командир Відступників в ратуші Брілла, що керує оборонними й військовими операціями по центральних Галявинах Тірісфалю. Підпорядкований безпосередньо верховному командуванню Андерсіті, він координує зачистку сил Багряного Хрестового Походу, що тиснуть на землі Відступників.",section="З адміністративного серця Брілла Екзекутор Зиґанд координує оборону краю для Відступників після їхнього пробудження в Похоронному Подзвоні. Безпосередній начальник таких місцевих офіцерів, як Екзекутор Аррен, і польових вартівників, як Вартова Смерті Ліннея, Зиґанд зводить докупи донесення розвідки й висилає здібних новобранців боронити кордони Лордерона від зазіхань.",sectionIndex=1}
c["npc:fandral-staghelm"] = "cedca7"
P.scopedClips["npc:fandral-staghelm"] = {scope="overview-body",sourceHash="ea3923",hash="cedca7",name="Фандрал Стаґгелм",summary="Архідруїд Фандрал Стаґгелм очолює друїдів Кола Кенарія з Ценаріонського Анклаву в Дарнасусі. Прийшовши до влади після того, як Малфуріон Стормрейдж зник у Смарагдовому Сні, він став головним поборником насадження нового Світового Дерева — Тельдрассила. Гордий, різкий і невгамовно честолюбний, Фандрал обстоює рішуче відродження калдореїв, що раз у раз зіштовхує його з Верховною Жрицею Тірандою Віспервінд.",section="Після Третьої війни й жертви Нордрассила на Горі Гіджал нічні ельфи втратили безсмертя та своє священне святилище. Поки Малфуріон Стормрейдж закликав до терпіння й застерігав від марнославства, Фандрал обстоював зухвалий задум — виростити нове Світове Дерево біля узбережжя Калімдору. Коли ж Малфуріон упав у кому в Смарагдовому Сні, Фандрал перехопив ініціативу й повів друїдів вирощувати Тельдрассил. У велетенському дереві він бачив пам'ятник витривалості калдореїв і засіб повернути втрачену велич — навіть попри те, що Аспекти драконів демонстративно відмовили несхваленому задуму в благословенні.",sectionIndex=1}
c["npc:farthing"] = "85a2b0"
P.scopedClips["npc:farthing"] = {scope="overview-body",sourceHash="e14f3a",hash="85a2b0",name="Фартінґ",summary="Єпископ Фартінґ — людина-священнослужитель, що служить у Соборі Світла в Стормвінді. Відвідувачам і вірянам він постає відданим слугою Святого Світла, що наставляє парафіян і спрямовує допомогу до знесилених поселень по всьому королівству.",section="У тихих мармурових залах Собору Світла Єпископ Фартінґ — одна з чільних постатей, що дбають про духовні потреби Стормвінда. Разом з Архієпископом Бенедиктусом і зібраним духовенством він радить мандрівникам, допомагає тим, хто опановує святі мистецтва, і виконує громадські та пастирські обов'язки Церкви Святого Світла.",sectionIndex=1}
c["npc:fenrus-the-devourer"] = "745b9c"
P.scopedClips["npc:fenrus-the-devourer"] = {scope="overview-body",sourceHash="117ab1",hash="745b9c",name="Фенрус Пожирач",summary="Фенрус Пожирач — величезний ворг, що никає у верхньому святилищі Фортеці Шадовфенг. Архімаг Аруґал тримає цього ненажерливого звіра як особистого улюбленця й охоронця, і звір роздувся від неприродної магії. Кожен, хто наважиться вдертися до особистого кабінету архімага, мусить зійтися з цим диким жахіттям і господарем, що за ним наглядає.",section="Глибоко у Фортеці Шадовфенг, просто біля особистих покоїв Архімага Аруґала, чатує жахливий ворг, відомий як Фенрус Пожирач. На відміну від вовкоподібних воргенів, що никають мурами, Фенрус — справжній ворг, роздутий до велетенських розмірів. Никаючи між полицями, сувоями й таємними приладами в приватному кабінеті Аруґала, звір править і за улюбленця, і за лютого вартового, що не підпускає жодного загарбника, який полює на голову божевільного мага.",sectionIndex=1}
c["npc:first-mate-fitzsimmons"] = "e1db91"
P.scopedClips["npc:first-mate-fitzsimmons"] = {scope="overview-body",sourceHash="8cb1d8",hash="e1db91",name="Перший Помічник Фіцсіммонс",summary="Перший Помічник Фіцсіммонс — обдертий, смердючий моряк, що днями п'є біля Таверни «Глибока Вода» в Гавані Менетіл. Колись він був першим помічником на «Володарці Хвиль» із Третього флоту Кул Тіраса, а тепер — єдиний відомий живий свідок загибелі флоту в Другій війні. Переслідуваний спогадами про ту трагедію, він шукає сміливців, готових вийти проти неспокійних духів його потонулих товаришів.",section="Перший Помічник Фіцсіммонс, що вилежується біля Таверни «Глибока Вода» у вологому солоному повітрі Гавані Менетіл, — людина, яку легко не помітити, а то й узагалі обійти десятою дорогою, зважаючи на його немитий сморід. Для більшості відвідувачів він лише ще один зламаний старий морський вовк, що топить спогади в чарці. Та хто сяде поруч і вислухає, почує моторошні оповіді про гордий флот, знищений вогнем і пазурами.",sectionIndex=1}
c["npc:foreman-oslow"] = "3fd774"
P.scopedClips["npc:foreman-oslow"] = {scope="overview-body",sourceHash="4bfc5a",hash="3fd774",name="Бригадир Ослоу",summary="Бригадир Ослоу — знесилений головний будівничий Лейкшира, якому доручили відновити зруйнований міст через Озеро Незрушне в серці Гір Редріджу. Під обстрілом катапульт орків Блекрок і нападами гнолів відбудова застрягла: вантажі загублено, а знаряддя пішло на дно. Ослоу покладається на мандрівних шукачів пригод, щоб повернути своє спорядження й роздобути матеріали, аби Лейкшир знову відкрив свій життєво важливий торговий шлях.",section="Стоячи біля потрощеної кладки зруйнованого мосту, Бригадир Ослоу веде важку боротьбу. Міст — життєва артерія Лейкшира: він перетинає Озеро Незрушне й з'єднує західні дороги до Елвінна зі східними берегами. Орки Блекрок, що спускаються з круч Кам'яної Варти, вдарили по переправі, щоб паралізувати постачання й пересування військ, і поселення опинилося розколотим і вразливим.",sectionIndex=1}
c["npc:furen-longbeard"] = "a86fb6"
P.scopedClips["npc:furen-longbeard"] = {scope="overview-body",sourceHash="200c8a",hash="a86fb6",name="Фурен Лонґбірд",summary="Фурен Лонґбірд — дворф, майстер-бронник, що працює в гомінкому Дворфійському Кварталі Стормвінда. Учень славетного коваля Ґріманда Елмора, він спеціалізується на важкому захисному спорядженні й міцних кольчугах для досвідчених захисників Альянсу. Воїни з усього королівства шукають його знань у металургії, щоб викувати особливі бойові обладунки.",section="Фурен Лонґбірд займається своїм ремеслом далеко від великих горнів Айронфорджа — він оселився серед бруківки й кіптяви Дворфійського Кварталу Стормвінда. Як і багато його родичів, Фурен приніс на південь традиційну дворфійську металургію, щоб підтримати відбудову й оборону королівства. Працюючи серед палаючих горнів і дзвінких ковадел, він підтримує міцні зв'язки з іншими майстрами міста й не лише.",sectionIndex=1}
c["npc:gakin-the-darkbinder"] = "864258"
P.scopedClips["npc:gakin-the-darkbinder"] = {scope="overview-body",sourceHash="6252c8",hash="864258",name="Ґакін Зв'язувач Темряви",summary="Ґакін Зв'язувач Темряви — майстер-чорнокнижник, що таємно діє глибоко під таверною «Зарізане Ягня» в Кварталі магів Стормвінда. Він навчає охочих чаклунів Альянсу темних мистецтв, випробовуючи їхню рішучість, перш ніж допустити до обрядів виклику й підкорення потойбічних демонів.",section="Маги Стормвінда відкрито практикують у своїх височенних святилищах, а от адептам тіні й скверни доводиться жити там, куди не сягають цікаві очі. Під шинком таверни «Зарізане Ягня» сховано вогкий льох, схожий на склеп, із колами виклику й похмурими фоліантами. Ґакін — осердя цього таємного кола: він дбає, щоб молоді чорнокнижники навчилися дисципліни й стриманості, перш ніж випускати жахіття, яких не зможуть контролювати.",sectionIndex=1}
c["npc:gan-rul-bloodeye"] = "d3518b"
P.scopedClips["npc:gan-rul-bloodeye"] = {scope="overview-body",sourceHash="429e13",hash="d3518b",name="Ґан'рул Бладай",summary="Ґан'рул Бладай — досвідчений орк-наставник чорнокнижників, що мешкає глибоко в темній печері Тіньової Розколини в Оргріммарі. Подалі від пильних очей міста нагорі він посвячує чорнокнижників Орди в темніші демонічні обряди. Під його проводом новачки вчаться підкоряти своїй волі потойбічних істот, як-от блукачів Порожнечі та сукубів.",section="Вождь Тралл терпить чорнокнижників у Новій Орді, та їхнім темним мистецтвам не місце під відкритим сонцем Дуротару. Ґан'рул Бладай живе в Тіньовій Розколині — підземному прихистку під Оргріммаром, де ткачі тіней, розбійники й заклиначі скверни можуть навчатися без перешкод. Звідси, зі свого підземного гнізда, Ґан'рул навчає тих, хто лише починає опановувати магію скверни.",sectionIndex=1}
c["npc:gann-stonespire"] = "47cbdf"
P.scopedClips["npc:gann-stonespire"] = {scope="overview-body",sourceHash="262fa6",hash="47cbdf",name="Ґанн Стоунспайр",summary="Ґанн Стоунспайр — скривджений таурен-кочівник, що блукає дорогами південних Пусток поблизу Бель Модана. Дворфи-копачі вигнали його плем'я з прадавніх мисливських угідь, і тепер він шукає відплати проти розкопок, що наступають на його землю.",section="Перш ніж з Айронфорджа прибула дворфійська експедиція й заклала фортецю Бель Модан, довколишня земля була прадавньою територією та мисливськими угіддями племені Ґанна Стоунспайра. Дворфи-рудокопи прогнали корінних тауренів з їхньої землі кайлами, рушницями й важкими машинами, відкинувши всі мирні пропозиції. Тепер Ґанн отаборився при запорошеній дорозі на півдні Пусток і не збирається мовчки зректися своєї спадщини: він скликає мандрівників, щоб дати відсіч копачам.",sectionIndex=1}
c["npc:gaxim-rustfizzle"] = "d5f37f"
P.scopedClips["npc:gaxim-rustfizzle"] = {scope="overview-body",sourceHash="09603a",hash="d5f37f",name="Ґаксим Растфіззл",summary="Ґаксим Растфіззл — честолюбний гном-учений і майстер, що несе службу в невеликому таборі Альянсу на Стежці Павутинника в Горах Кам'яного Кігтя. Представник Просвітленої Асамблеї Таємнознавства, Алхімії й Інженерії, він прагне довести скептичним нічним ельфам, що досконала механіка й алхімія можуть зберегти їхні лісові володіння. Його наукова допитливість не поступається запеклій ворожнечі з руйнівними роботами Венчурної Компанії.",section="Нічні ельфи здавна покладаються на давнє друїдство й магію природи, а Ґаксим Растфіззл прибув на скелясті перевали Гір Кам'яного Кігтя, щоб показати зовсім інший погляд. Представляючи Просвітлену Асамблею Таємнознавства, Алхімії й Інженерії, він щиро вірить, що розраховані механізми й хімічні рішення можуть захищати й відновлювати дику природу Калімдору не гірше за молитви до Елуни. Отаборившись поруч із вартовою Каелою Шедовспір на Стежці Павутинника, він невтомно переконує своїх високих, відлюдних союзників у користі інженерії для природи.",sectionIndex=1}
c["npc:gazrog"] = "0b1b0d"
P.scopedClips["npc:gazrog"] = {scope="overview-body",sourceHash="e68e71",hash="0b1b0d",name="Ґазроґ",summary="Ґазроґ — орк-воїн, що несе службу на Перехресті в серці Пусток. Йому доручено дбати про постачання й безпеку на небезпечних дорогах савани, тож він наймає вправних мандрівників з Орди, щоб упоратися з місцевими загрозами й розшукати зниклі патрулі.",section="Перехрестя — життєво важливий вузол для всіх шляхів Орди через Калімдор, але його відокремленість робить шляхи постачання вразливими і для грабіжників, і для звірів. Ґазроґ стоїть на варті разом із захисниками поселення, дбаючи, щоб вантажі, гроші й гінці діставалися місця призначення. Підтримувати лад у безкраїх нетрях можна лише за постійної пильності, тож Ґазроґ дуже покладається на мандрівних шукачів пригод, які розв'язують кризи, що назрівають за частоколом застави.",sectionIndex=1}
c["npc:gelbin-mekkatorque"] = "13a047"
P.scopedClips["npc:gelbin-mekkatorque"] = {scope="overview-body",sourceHash="db5de5",hash="13a047",name="Ґелбін Меккаторк",summary="Ґелбін Меккаторк — Великий Тінкер гномів, що нині живе у вигнанні в Містечку Майстрів в Айронфорджі. Цей далекоглядний інженер, автор механоступа й Глибинного трамвая, несе тепер тяжкий тягар падіння Гномреґана й очолює зусилля, щоб повернути прадавню домівку свого народу.",section="Провід у гномів здобувають розумом і заслугами, а не родоводом, і Ґелбін Меккаторк став Великим Тінкером завдяки чистому винахідницькому генію. Випускник Університету Ґіршафт, він здійснив переворот у пересуванні, створивши перший робочий механоступ. За десятиліття винаходів Меккаторк сконструював гіроматичний мікрорегулятор і автоматичних роботів-ремонтників, а разом із дворфами Бронзбірдами розробив їхні грізні облогові машини. Коли після Другої війни Стормвінду знадобилося швидке сполучення з Айронфорджем, Король Маґні Бронзбірд звернувся до Меккаторка, і той власноруч розробив креслення й наглядав за будівництвом підземного Глибинного трамвая.",sectionIndex=1}
c["npc:gelihast"] = "42939b"
P.scopedClips["npc:gelihast"] = {scope="overview-body",sourceHash="3e2e31",hash="42939b",name="Ґелігаст",summary="Ґелігаст — лютий мурлок-ватажок із двома клинками, що живе в Ставку Аск'ар у Чорноглибинних Печерах. Приваблений темним шепотом Древніх Богів, він прорубав собі шлях до затонулих руїн храму, а згодом здобув неохочу повагу культистів Молота Присмерку.",section="Більшість мурлоків тримається прибережних мілин, але Ґелігаст відчув темний, зловісний поклик Древніх Богів глибоко під Ашенвалем. Гнаний цим первісним шепотом, він силоміць пробився до затонулого храму Чорноглибинних Печер. Коли культисти Молота Присмерку спробували заступити йому дорогу, він власноруч порубав своїми двома мечами майже дюжину з них.",sectionIndex=1}
c["npc:ghamoo-ra-classic"] = "c52fa4"
P.scopedClips["npc:ghamoo-ra-classic"] = {scope="overview-body",sourceHash="ce2c46",hash="c52fa4",name="Ґаму-Ра",summary="Ґаму-Ра — давній велетень, морська черепаха, що живе в Ставку Аск'ар у Чорноглибинних Печерах. Колись мирний мешканець затонулого храму Елуни, він потрапив до рук культу Молота Присмерку, який закатував його й довів до божевілля, щоб зробити лютим охоронцем.",section="До осквернення Чорноглибинних Печер Ґаму-Ра був одним з останніх мирних природних мешканців затоплених руїн храму нічних ельфів, присвяченого Елуні. Коли нігілістичний культ Молота Присмерку захопив святилище, культисти вирвали давнього звіра з його тихого життя й замкнули в неволі. Його не вбили — роками його систематично мучили, і він зазнавав і душевних, і тілесних катувань від рук культистів.",sectionIndex=1}
c["npc:gilnid"] = "3abc18"
P.scopedClips["npc:gilnid"] = {scope="overview-body",sourceHash="4fe0e2",hash="3abc18",name="Ґілнід",summary="Ґілнід на прізвисько Плавильник — гоблін, головний інженер, що керує горнами в глибинах Мертвих Копалень. Він наглядає, як сиру руду переплавляють на чистий метал і боєприпаси для потаємного броненосця Едвіна Венкліфа. Без його вогняного ремесла Братство Дефіас не мало б важких гармат для нападу на Стормвінд.",section="Глибоко в Мертвих Копальнях Братство Дефіас покладається на промислову майстерність, щоб кувати зброю. Ґілнід — головний плавильник Венкліфа: він командує цілим невеликим військом гоблінів-робітників, майстрів і ковалів у центральній ливарні. Вищий за більшість родичів, він безжально жене команду крізь дим і шлак, вигукує накази й не дає перепочинку, аби сира залізна руда ставала важкою обшивкою та смертоносними снарядами.",sectionIndex=1}
c["npc:glorin-steelbrow"] = "b4ee3c"
P.scopedClips["npc:glorin-steelbrow"] = {scope="overview-body",sourceHash="fe1e50",hash="b4ee3c",name="Ґлорін Стілброу",summary="Ґлорін Стілброу — дворф-агент, якого можна застати за кухлем у Таверні «Глибока Вода» в Гавані Менетіл. Як соратник Єпископа Фартінґа із Собору Світла в Стормвінді, він допомагає шукачам пригод розслідувати загибель Третього Флоту й повертати священні реліквії та матеріали, розкидані узбережжям Багнокраю. Завдяки йому похмурі хащі Сутінколісся пов'язані просто з затонулими кораблями на півночі.",section="Єпископ Фартінґ із Собору Світла в Стормвінді допомагає людям Сутінколісся боротися з повзучими жахами, але має зв'язки й далеко на півночі, у Гавані Менетіл. Ґлорін Стілброу, що сидить у гомінкій Таверні «Глибока Вода», — очі й руки Фартінґа на узбережжі. Він допомагає й підказує дорогу мандрівникам, яких відіслали на північ шукати священні метали й забуті реліквії, і стає важливим містком між бідами південного лісу та затонулими уламками Багнокраю.",sectionIndex=1}
c["npc:gornek"] = "7332fd"
P.scopedClips["npc:gornek"] = {scope="overview-body",sourceHash="c7c15f",hash="7332fd",name="Ґорнек",summary="Ґорнек — орк-наглядач у Долині Випробувань у Дуротарі. Саме він першим приймає нових орків і тролів Темного Списа, які готуються довести свою цінність Новій Орді.",section="Стоячи в самому серці Долини Випробувань, Ґорнек — перше випробування дисципліни для майбутніх воїнів, розвідників і чаклунів Орди. За наказом Вождя Тралла кожен юнак і кожен новоприбулий має заслужити своє місце завзяттям і наполегливістю, а не правом народження. Ґорнек оцінює тих, хто ступає в долину, читає їхні супровідні накази й скеровує до наставників по всьому табору. Чи приніс посвячуваний зашифровану писульку, гліфічний пергамент чи просту табличку — саме Ґорнек приймає його вірчі знаки й ставить на суворий шлях виживання.",sectionIndex=1}
c["npc:grelin-whitebeard"] = "9c9d1d"
P.scopedClips["npc:grelin-whitebeard"] = {scope="overview-body",sourceHash="2ee122",hash="9c9d1d",name="Ґрелін Вайтбірд",summary="Ґрелін Вайтбірд — дворфський розвідник, якого королівським наказом відрядили до Долини Холодного Хребта оцінити загрозу від тролів Морозогривів. Він працює з відлюдного табору разом із недолугим учнем і покладається на молодих шукачів пригод, щоб стримувати тролів, поки увагу Айронфорджа цілком поглинула навала трогів.",section="Ґреліна Вайтбірда та його брата Сеніра відрядили до Долини Холодного Хребта за прямим наказом Сенату Айронфорджа й самого Короля Маґні Бронзбірда. Завдання було чітке: оцінити й усунути загрозу від тутешніх тролів Морозогривів. Та оскільки регулярне військо Айронфорджа загрузло в боротьбі з трогами по всьому Дун Мороґу, братам дали геть мало засобів. Ґрелінові довелося розбити табір серед засніжених пагорбів і покладатися на місцевих добровольців та новачків, що проходили повз, аби виконати всю потрібну роботу.",sectionIndex=1}
c["npc:grif-wildheart"] = "76221b"
P.scopedClips["npc:grif-wildheart"] = {scope="overview-body",sourceHash="7d3df9",hash="76221b",name="Ґріф Вайлдгарт",summary="Ґріф Вайлдгарт — досвідчений дворфський наставник мисливців, що стоїть біля Ґуральні Тандербрю в Хараносі. Серед місцевих горян він славиться глибоким зв'язком із дикою природою і навчає молодих стрільців вистежувати здобич, влучно стріляти й приборкувати звірів. Для юних мисливців, що виходять із Долини Холодного Хребта, Ґріф — важлива ланка між першим пострілом з рушниці та вірним звіром поруч.",section="Поки більшість дворфів Айронфорджа віддають перевагу вогняному теплу кузні чи розміреному дзенькоту кайл, Ґріф Вайлдгарт цілком присвятив своє життя морозній глушині Дун Мороґу. Місцеві горяни напівжартома кажуть, що він надто багато часу проводить із чотирилапими, але ніхто не заперечує його майстерності в дикій природі. Роками вистежуючи здобич на засніжених хребтах пліч-о-пліч із бувалими мисливськими супутниками, Ґріф досконало пізнав хижаків, які блукають тутешніми скелями.",sectionIndex=1}
c["npc:gryan-stoutmantle"] = "e6dd0e"
P.scopedClips["npc:gryan-stoutmantle"] = {scope="overview-body",sourceHash="9663fc",hash="e6dd0e",name="Ґраян Стаутмантл",summary="Ґраян Стаутмантл — паладин Срібної Длані й командир Народного ополчення, що діє із Сентінел Гілла у Вестфолі. Уродженець Вестфолу, він повернувся зі спустошеного північного королівства Лордерон, щоб захистити рідний край, коли корона Стормвінда кинула його на поталу розбійникам.",section="Ґраян Стаутмантл почав службу далеко від тихих нив південного Азероту. Юнаком він подався на північ, до Лордерону, склав обітниці Лицаря Срібної Длані й пережив жахи Третьої війни — навіть став свідком трагічної зачистки Стратгольма принцом Артасом Менетілом. Коли до нього дійшла звістка, що рідний Вестфол поринає в беззаконня, заполонений організованими розбійниками й покинутий короною, Ґраян залишив північні фронти. Він проміняв поля великих битв на оборону чесних фермерів, присягнувшись, що його дім не впаде так, як упала північ.",sectionIndex=1}
c["npc:guard-thomas"] = "1fd7ca"
P.scopedClips["npc:guard-thomas"] = {scope="overview-body",sourceHash="0db2b7",hash="1fd7ca",name="Вартовий Томас",summary="Вартовий Томас — відданий солдат армії Стормвінда, що стоїть біля мосту на захід від Лісозаготівельного Табору Східної Долини. Відрізаний на східному порубіжжі Лісу Елвінн, він керує обороною місцевих поселенців від хижої звірини та мурлоків, що насуваються.",section="Поки увага королівства здебільшого звернена всередину, до столиці, або на захід, до Вестфолу, Вартовий Томас тримає один із найтихіших, але найхиткіших постів у Лісі Елвінн. Стоячи біля кам'яного мосту через річку в бік Лісозаготівельного Табору Східної Долини, Томас — тонка лінія оборони між простими лісорубами та войовничими створіннями, що блукають лісом. Оскільки військо Стормвінда розтягнуте до краю, вартовим на кшталт Томаса доводиться чимало покладатися на перехожих шукачів пригод, щоб підтримувати лад і передавати донесення до центрального командування.",sectionIndex=1}
c["npc:gunther-arcanus"] = "b438ac"
P.scopedClips["npc:gunther-arcanus"] = {scope="overview-body",sourceHash="67e6e1",hash="b438ac",name="Ґунтер Арканус",summary="Ґунтер Арканус — надзвичайно могутній некромант, що живе на відлюдному острові посеред Озера Світлої Води. Убитий під час Третьої війни й воскреслий нежиттю, він зумів цілком самотужки розірвати ментальну хватку Короля-Ліча. Довго вважаючи себе єдиним мерцем із вільною волею, він боронив свій притулок від усіх чужинців, аж поки його не знайшли Відступники.",section="До падіння Лордерона Ґунтер був перспективним учнем Кірін-Тору в Даларані. Разом із близькими друзями Бетором Айсшардом і Тулом Рейвенкловом він вивчав таємні мистецтва й потай заглиблювався в некромантію попри сувору заборону Кірін-Тору на темну магію. На пам'ять про своє братерство троє друзів колись сплели свої учнівські жезли в єдину реліквію.",sectionIndex=1}
c["npc:gwennyth-bly-leggonde"] = "80d4a4"
P.scopedClips["npc:gwennyth-bly-leggonde"] = {scope="overview-body",sourceHash="c66fdc",hash="80d4a4",name="Ґвенніт Блай'Леґґонд",summary="Ґвенніт Блай'Леґґонд — нічна ельфійка з приморського порту Обердайн. Живучи на туманному Темному Узбережжі, вона стежить за припливами й посилає мандрівників дослідити дивні рештки, які викидає на берег. Її непокоять загадкові морські створіння й велетенські черепахи, чиї туші почали всіювати північні пляжі.",section="Ґвенніт Блай'Леґґонд живе в Обердайні, гамірному приморському прихистку Темного Узбережжя. Поки багато хто в містечку переймається лісом чи судноплавством через Приховане Море, Ґвенніт не зводить очей з узбережжя. Останнім часом припливи стали похмурими: вони викидають на берег рештки велетенських морських створінь. Щоб зрозуміти, що діється у водах біля берега, вона покладається на охочих шукачів пригод, які прочісують піски, збирають зразки кісток і приносять відповіді.",sectionIndex=1}
c["npc:hamhock"] = "bd02cf"
P.scopedClips["npc:hamhock"] = {scope="overview-body",sourceHash="e61524",hash="bd02cf",name="Окіст",summary="Окіст — велетенський двоголовий огр, ув'язнений у глибинах В'язниці Стормвінда. Замкнений під столицею разом із загартованими бунтарями Дефіас і головорізами, він — особливо жорстокий і несподіваний в'язень серед тюремного бунту.",section="В'язницю Стормвінда збудували для дрібних злодіїв, убивць і політичних бунтарів, тож височенний двоголовий огр серед камер — вражаюче видовище. Коли в'язні повстали й захопили в'язницю, Окіст закріпився посеред хаосу й розчавлює кожного, хто необачно вдереться до його блоку.",sectionIndex=1}
c["npc:herod"] = "4742b0"
P.scopedClips["npc:herod"] = {scope="overview-body",sourceHash="cee43e",hash="4742b0",name="Герод",summary="Герод — уславлений чемпіон і берсерк Багряного Хрестового Походу, що командує Збройнею Багряного Монастиря. Відомий лютою бойовою майстерністю й непохитним запалом, він навчає новобранців жорстокого ближнього бою, без якого не вести святої війни. Його смерті прагнуть і незгодні з орденом люди Альянсу, і правителі Орди в Андерсіті, щоб підірвати військову силу Хрестового Походу.",section="В укріплених залах Збройні Багряного Монастиря Герод уособлює бойову агресію Хрестового Походу. На відміну від чародіїв і паладинів, що черпають святу магію в Соборі, Герод покладається на грубу, кровожерну фізичну силу. Закутий у кольчугу, з величезною дворучною сокирою, він особисто муштрує загони багряних новобранців, прищеплюючи їм шалену відданість винищенню всіх, хто не підтримує їхньої фанатичної справи.",sectionIndex=1}
c["npc:high-executor-darthalia"] = "4a754b"
P.scopedClips["npc:high-executor-darthalia"] = {scope="overview-body",sourceHash="789d3f",hash="4a754b",name="Верховний Екзекутор Дарталія",summary="Верховний Екзекутор Дарталія — високопоставлена воєначальниця Відступників, що несе службу в Таррен Міллі в Передгір'ї Гілсбреда. Діючи з прямого доручення Леді Сильвани Віндраннер і Варіматраса, вона керує операціями Відступників проти людської твердині Саутшор і місцевих розбійників Синдикату. Її провід — запорука безпеки південного флангу Орди в Лордероні.",section="Верховний Екзекутор Дарталія, що діє з Таррен Мілла, — оперативна командувачка сил Відступників по всьому Передгір'ю Гілсбреда. Її головна стратегічна мета — зупинити поширення людського опору, стримувати сили Альянсу в Саутшорі й вистежувати свавільних розбійників Синдикату, що заполонили околиці. Кожен наступ на південь Гілсбреда йде просто через її командування.",sectionIndex=1}
c["npc:high-executor-hadrec"] = "342d1c"
P.scopedClips["npc:high-executor-hadrec"] = {scope="overview-body",sourceHash="ab064e",hash="342d1c",name="Верховний Екзекутор Гадрек",summary="Верховний Екзекутор Гадрек — військовий командир гарнізону Відступників у Гробниці в Срібноліссі. З цієї центральної крипти він керує обороною від загроз краю, зокрема від гнилошкірих гнолів, і розслідує зникнення розвідників по всьому краю. Він — головний офіцер, що спрямовує дії Орди по всьому Срібноліссю.",section="Верховний Екзекутор Гадрек, що несе службу в похмурій Гробниці, керує військовими діями Відступників по всьому Срібноліссю. Галявини Тірісфалю надійно тримають сили Темної Леді, а Срібнолісся досі сповнене небезпек: довкола ворожі маги Даларана, дикі воргени й гноли, що наступають. На Гадрекові лежить похмура відповідальність — зміцнювати землі Відступників і придушувати все, що кидає виклик владі Андерсіті на південь від столиці.",sectionIndex=1}
c["npc:high-inquisitor-fairbanks"] = "b007c2"
P.scopedClips["npc:high-inquisitor-fairbanks"] = {scope="overview-body",sourceHash="7c942b",hash="b007c2",name="Верховний Інквізитор Фербенкс",summary="Верховний інквізитор Фербенкс колись був шанованим жерцем Лицарів Срібної Длані й довіреним радником верховного лорда Александроса Моґрейна. Він був видатним духовним провідником серед уцілілих захисників Лордерону, але його доля сплелася з темним падінням Багряного Хрестового Походу.",section="До падіння Лордерону Фербенкс був поважним священнослужителем серед Лицарів Срібної Длані. Коли верховний лорд Александрос Моґрейн скликав доленосну зустріч у корчмі Саутшора, Фербенкс стояв поруч і допомагав спрямувати святу силу в загадковий кристал, що згодом став серцем легендарного Ешбрінгера. Коли принц Артас розпустив орден паладинів, Фербенкс вирушив із Моґрейном до Айронфорджа й став свідком того, як Король Маґні Бронзбірд викував великий клинок для боротьби з Погибеллю.",sectionIndex=1}
c["npc:high-priestess-laurena"] = "5fead2"
P.scopedClips["npc:high-priestess-laurena"] = {scope="overview-body",sourceHash="f1d294",hash="5fead2",name="Верховна Жриця Лаурена",summary="Верховна Жриця Лаурена — шанована наставниця жерців-людей, що служить за великим вівтарем Собору Світла в Стормвінді. Утікши як біженка з охопленого руйнацією Лордерону під час Третьої війни, нині вона навчає молодих жерців Альянсу духовної відданості й захисних чарів.",section="Перш ніж посісти місце у височенних залах Собору Світла, Лаурена жила в північному королівстві Лордерон. Коли під час Третьої війни Погибель прокотилася тим краєм, вона й уся її родина мали щастя вижити й утекти на південь, до Стормвінда, як переселенці. Попри безмежне горе й хаос, що зруйнували її батьківщину, Лаурена лишилася непохитною у вірі й зрештою стала Верховною Жрицею на службі Церкви Святого Світла.",sectionIndex=1}
c["npc:houndmaster-loksey"] = "de2cab"
P.scopedClips["npc:houndmaster-loksey"] = {scope="overview-body",sourceHash="955980",hash="de2cab",name="Псар Локсі",summary="Псар Локсі — офіцер, якому доручено розводити й муштрувати грізних бойових псів Багряного Хрестового Походу. Він порядкує псарнями у Збройні Багряного Монастиря й посилає зграї собак полювати на нежить, непроханих гостей і уявних єретиків. Завдяки його нещадній дисципліні звірі Монастиря зажили лихої слави по всіх Галявинах Тірісфалю.",section="За неприступними мурами Багряного Монастиря Псар Локсі керує вишколом лютих собак-слідопитів і бойових псів. Багряний Хрестовий Похід покладається на цих вишколених собак: вони винюхують заражені чумою трупи, викривають прихованих лазутчиків і наздоганяють утікачів від гніву фанатиків. Локсі має необмежену владу над псарнею Збройні й дбає, щоб його вихованці будь-якої миті були готові роздерти непроханих гостей на шматки.",sectionIndex=1}
c["npc:illiyana"] = "0c7002"
P.scopedClips["npc:illiyana"] = {scope="overview-body",sourceHash="420ead",hash="0c7002",name="Ілліяна",summary="Ілліяна — давня дріада, що оберігає ліси південно-західного Ашенвалю від прадавньої скверни. Блукаючи біля Святилища Аессіни, вона скликає героїв Альянсу, щоб дати відсіч лютим сатирам, які нівечать давні гаї. Її пильність — свідчення нерозривного зв'язку між дочками Кенарія та дикими лісами нічних ельфів.",section="Як і всі дріади, Ілліяна — одна з дочок напівбога Кенарія. Мирна, але затято віддана захисту дикої природи, вона обходить ліси південно-західного Ашенвалю. Тепер, коли темні сили заворушилися, а ліси потерпають від повзучої скверни, Ілліяна стереже священні реліквії та гаї, оберігаючи первісну святість природи.",sectionIndex=1}
c["npc:interrogator-vishas"] = "9b3700"
P.scopedClips["npc:interrogator-vishas"] = {scope="overview-body",sourceHash="9df3de",hash="9b3700",name="Дізнавач Вішас",summary="Дізнавач Джеймс Вішас — майстер катувань Багряного Хрестового Походу, що служить у глибині крила Кладовища Багряного Монастиря. Відомий своїм верескливим голосом і неприхованою жорстокістю, він зі збоченою насолодою ламає полонених і випробовує межі смертної плоті. Мало хто з тих, хто потрапляє до його катівні, виходить звідти з цілим розумом чи тілом.",section="У темних склепах і на цвинтарі Багряного Монастиря дізнавач Вішас «опікується» полоненими ворогами Хрестового Походу. Поки фанатики назовні марширують у сяйливих обладунках під стягами чистоти, Вішас уособлює похмуру правду, що стоїть за їхнім походом: неприборканий садизм, прикритий праведним релігійним гнівом. Допит для нього — не просто справа розвідки, а улюблене ремесло: він смакує муки полонених Відступників, захоплених прислужників Погибелі й будь-яких живих мандрівників, яких на своє лихо затаврували єретиками.",sectionIndex=1}
c["npc:islen-waterseer"] = "4d6525"
P.scopedClips["npc:islen-waterseer"] = {scope="overview-body",sourceHash="6fca89",hash="4d6525",name="Іслен Вотерсір",summary="Іслен Вотерсір — шанована тауренка-шаманка, що живе біля тихої рибальської хатини на Сходах Тідуса, звідки видно східне море Пусток. Вона в глибокому єднанні з духами води й проводить учнів крізь випробування, потрібні, щоб злагодитися з цією стихією. Шамани-початківці з усієї Орди шукають її мудрості, щоб здобути Тотем Води.",section="Далеко від гамірного Перехрестя й таборів Пусток Іслен Вотерсір живе на скелястому узбережжі, відомому як Сходи Тідуса. Тут, де посушливі рівнини розбиваються об Велике Море, присутність духів води відчутна всюди й первісно сильна. Іслен не живе в гримучих залах чи гамірних містах — вона обрала цю тиху заставу й присвячує дні тому, щоб слухати припливи й допомагати шаманам, які прагнуть єднання з плинною стихією.",sectionIndex=1}
c["npc:iverron"] = "35c9d1"
P.scopedClips["npc:iverron"] = {scope="overview-body",sourceHash="3f999f",hash="35c9d1",name="Іверрон",summary="Іверрон — молодий нічний ельф, якого можна знайти в Тінедолі, захищеному стартовому гіллі Тельдрассила. Уражений отрутою дедалі неспокійніших павуків лісу, він своєю бідою рано попереджає про скверну, що росте в Світовому Дереві.",section="Блукаючи тихими кронами Тінедолу, Іверрон наразився на павуків Вебвуда, що гніздяться в долині. Отруйний укус швидко звалив молодого ельфа, і він лишився безпорадним, не здатним сам повернутися в безпечне місце. Його стан виказує раптову агресію, що охоплює створіння, які колись мирно ділили з ельфами цей гай.",sectionIndex=1}
c["npc:jaina-proudmoore"] = "d5a5fb"
P.scopedClips["npc:jaina-proudmoore"] = {scope="overview-body",sourceHash="495224",hash="d5a5fb",name="Джайна Праудмур",summary="Леді Джайна Праудмур — правителька Острова Терамор і наймогутніша з живих чародійок-людей. Колись найкраща учениця Кірін-Тору в Даларані, вона повела вцілілих мешканців Лордерону через Велике море й тепер намагається зберегти крихкий мир між Альянсом і Новою Ордою.",section="Донька великого адмірала Дейліна Праудмура з Кул Тірасу, Джайна ще змалку виявила неабиякий хист до таємної магії й навчалася в Даларані під проводом архімага Антонідаса. Під час Третьої війни вона разом із принцом Артасом Менетілом розслідувала загадкову Чуму Нежиття і на власні очі бачила трагічне падіння Лордерону. Прислухавшись до застережень Пророка Медіва, вона зібрала вцілілих людей і відплила на захід, до забутого континенту Калімдор. Там її загони уклали небачений союз з Ордою Тралла й нічними ельфами, і разом вони на вершині Гори Гіджал розбили Архімонда й зірвали вторгнення Палаючого Легіону.",sectionIndex=1}
c["npc:je-neu-sancrea"] = "78ffaf"
P.scopedClips["npc:je-neu-sancrea"] = {scope="overview-body",sourceHash="69bfa0",hash="78ffaf",name="Дже'ню Санкреа",summary="Дже'ню Санкреа — троль із Темного Спису й член Земляного Кільця, що несе службу на Заставі Зорам'гар на узбережжі Ашенвалю. Відчуваючи темні збурення глибоко під берегом, він посилає шукачів пригод з Орди розслідувати скверну, що вразила давній затонулий храм Чорноглибинних Печер.",section="Більшість членів Земляного Кільця дбає про гармонію стихій по всьому Калімдору, а Дже'ню Санкреа пильнує відлюдне й небезпечне Зорамське Узмор'я. Із Застави Зорам'гар він спостерігає за темними поштовхами й неприродними припливами біля зруйнованого храму Чорноглибинних Печер. Хоч його пов'язують шаманські обов'язки перед колом, міцна вірність племені Темного Спису й Орді Тралла змушує його працювати лише з героями Орди.",sectionIndex=1}
c["npc:jergosh-the-invoker"] = "5fde6a"
P.scopedClips["npc:jergosh-the-invoker"] = {scope="overview-body",sourceHash="25a0d7",hash="5fde6a",name="Джерґош Призивач",summary="Джерґош Призивач — віроломний орк-чорнокнижник, що ховається глибоко в Проваллі Лютого Вогню під Оргріммаром. Як один із вищих ватажків культистів Пекучого Клинка, він практикує демонічні мистецтва просто під носом у Вождя й плете змову проти Орди.",section="Поки Тралл невтомно веде орків шляхом честі й шаманізму, Джерґош відкинув ці ідеали заради сирої демонічної сили. Сховавшись у підземному лабіринті Провалля Лютого Вогню під Оргріммаром, він зібрав прихильників у Пекучий Клинок — підступну секту, пов'язану з рештками Ради Тіней. Діючи в тіні просто під столицею Орди, Джерґош намагається зруйнувати все, на чому стоїть нова Орда.",sectionIndex=1}
c["npc:jern-hornhelm"] = "4f2b6d"
P.scopedClips["npc:jern-hornhelm"] = {scope="overview-body",sourceHash="eccab0",hash="4f2b6d",name="Джерн Горнгелм",summary="Джерн Горнгелм — дворф-рудокоп із Ліги Дослідників, що несе службу в містечку Телсамар. Він налагоджує важливе постачання й зв'язок між поселенням, Айронфорджем і місцем археологічних розкопок у глибині Лох Модану. Шукачі пригод часто допомагають йому перевозити гірниче спорядження й звіти про поступ робіт по всьому краю.",section="Джерн Горнгелм, що працює в затишному містечку Телсамар, відіграє ключову роль у постачанні дворфійських робіт по всьому Лох Модану. Поки дворфійські вчені й польові загони вирушають у нетрі, щоб відкопати минуле своїх предків, надійне постачання лишається конче потрібним. Джерн дбає, щоб важливі ресурси, інструменти й звістки безпечно діставалися діючих розкопок.",sectionIndex=1}
c["npc:jitters"] = "8bc7c6"
P.scopedClips["npc:jitters"] = {scope="overview-body",sourceHash="2eceeb",hash="8bc7c6",name="Тремтій",summary="Тремтій — тремтливий чоловік-відлюдник, що ховається серед руїн Воронячого Пагорба на заході Сутінколісся. Охоплений постійною параноєю й страхом, він сам-один виживає на небезпечному західному краю лісу, сподіваючись на допомогу перехожих шукачів пригод і стежачи за тінями, що підступають.",section="Тремтія можна знайти серед напіврозвалених хат Воронячого Пагорба: він живе в постійному жаху перед хижаками, що никають західними стежками Сутінколісся. Він покладається на перехожих шукачів пригод, щоб роздобути бодай якусь їжу, і гарячково стежить за тінями, що підступають. Своє прізвисько він отримав давно — за полохливі манери й дивовижне чуття, що допомагає вчасно відскочити від раптової небезпеки, — та його нестямна параноя народилася з власної зустрічі з неймовірними жахами.",sectionIndex=1}
c["npc:jonathan-carevin"] = "496a59"
P.scopedClips["npc:jonathan-carevin"] = {scope="overview-body",sourceHash="41bb57",hash="496a59",name="Джонатан Каревін",summary="Джонатан Каревін — рішучий мисливець-людина з Даркшира, що присвятив себе викоріненню темряви, яка гнітить Сутінколісся. На відміну від Нічної Варти, що лише обороняється, він і його родина самі полюють на нежить, воргенів і будь-які єретичні загрози, що чаяться під темними кронами.",section="Даркшир покладається на Нічну Варту, яка патрулює дороги й охороняє містечко, але Джонатан Каревін переконаний, що самої лише оборони замало. Разом із родиною та союзниками на кшталт Калора Джонатан переходить у наступ. Він полює на нечестивих потвор, що блукають Сутінколіссям, і веде власний хрестовий похід, щоб із ласки Світла очистити край від усіх демонів, нежиті й єретиків.",sectionIndex=1}
c["npc:jordan-stilwell"] = "481134"
P.scopedClips["npc:jordan-stilwell"] = {scope="overview-body",sourceHash="b879ae",hash="481134",name="Джордан Стілвелл",summary="Джордан Стілвелл — вправний зброяр-людина, що працює біля засніженої Брами Айронфорджа в Дун Мороґу. Хоча спершу йому судилося стати паладином Святого Світла, він пішов батьковим ремеслом і став майстром, чиї вироби служать паладинам по всьому Альянсу. Найбільше він відомий тим, що викував Кулак Верігана на честь свого давнього друга Боша Верігана.",section="Від Джордана Стілвелла чекали, що він складе святі обітниці й стане паладином Церкви Святого Світла, але зрештою він обрав шлях горна. Він пішов батьковими слідами й узяв до рук батьків зачарований ковальський молот. Своє ремесло Джордан відточував під наглядом дворфа-коваля Бейлора Стоунгенда. Хоч він і відмовився від мантії помазаного святого воїна, Джордан лишається глибоко відданим Світлу й присвячує свою надзвичайну майстерність спорядженню поборників, що б'ються в його ім'я.",sectionIndex=1}
c["npc:kadrak"] = "417c4e"
P.scopedClips["npc:kadrak"] = {scope="overview-body",sourceHash="728f0d",hash="417c4e",name="Кадрак",summary="Кадрак — досвідчений орк-командир, що несе службу на Валу Мор'шан на кордоні Пусток і Ашенвалю. Йому доручено стерегти північне прикордоння, і він керує потоком донесень і підкріплень у спірний ліс. Для шукачів пригод з Орди, що прямують за межі посушливих рівнин, Кадрак — брама до війни з нічними ельфами, яка не вщухає.",section="Стоячи на укріплених дерев'яних барикадах Валу Мор'шан, Кадрак пильнує головний шлях, що з'єднує Пустки з Ашенвалем. Цей кордон — хиткий рубіж: на півдні лежать випалені сонцем рівнини, які захопила Орда, а на півночі здіймаються прадавні ліси, що їх люто стережуть нічні ельфи. Кадрак дбає, щоб оборонне кільце не прорвали ні Вартові, ні ворожі лісові створіння.",sectionIndex=1}
c["npc:kaela-shadowspear"] = "08c174"
P.scopedClips["npc:kaela-shadowspear"] = {scope="overview-body",sourceHash="9472f3",hash="08c174",name="Каела Шедовспір",summary="Каела Шедовспір — вартова нічних ельфів, що несе службу на південний захід від Кручі Вітрорізу в Горах Кам'яного Кігтя. Зі своєї невеликої застави вона разом з іншими вартовими стежить за дедалі гострішою напругою й безладом у дикому краї. Вона покладається на відважних мандрівників, щоб розвідувати небезпечні місця й нести допомогу пораненим захисникам землі.",section="Каела Шедовспір, що стоїть трохи на південний захід від промислового спустошення Кручі Вітрорізу, пильно стежить за довколишніми перевалами. Гори Кам'яного Кігтя сповнені небезпек: Орда наступає, а гоблінські промисли виснажують природні багатства краю. Разом із гномом Ґаксимом Растфіззлом Каела — важлива передова ланка зв'язку нічних ельфів, що відстежує загрози, які просуваються вглиб земель предків.",sectionIndex=1}
c["npc:kam-deepfury"] = "41de2b"
P.scopedClips["npc:kam-deepfury"] = {scope="overview-body",sourceHash="adbb91",hash="41de2b",name="Кам Діпф'юрі",summary="Кам Діпф'юрі — сумнозвісний диверсант із дворфів Темного Заліза, ув'язнений у глибинах В'язниці Стормвінда. На відміну від більшості в'язнів, він не має жодного стосунку до Братства Дефіас: його схопили за влаштування нищівного вибуху на Мосту Тандол далеко на півночі.",section="В'язниця переповнена озлобленими каменярами й бунтарями Дефіас, але Кам Діпф'юрі стоїть осторонь. Підступного й жорстокого дворфа Темного Заліза схопили й привезли до Стормвінда після того, як він задумав операцію, що паралізувала важливі північні шляхи. Його замкнено глибоко в тюремних камерах, далеко від родичів під Горою Блекрок, але до Альянсу він такий самий ворожий, як і будь-який бунтар, що ділить із ним коридори.",sectionIndex=1}
c["npc:lady-anacondra"] = "ef3b4b"
P.scopedClips["npc:lady-anacondra"] = {scope="overview-body",sourceHash="c65e0d",hash="ef3b4b",name="Леді Анакондра",summary="Леді Анакондра — одна з Володарів іклів, що очолюють Друїдів Ікла в Печерах Стогонів. Колись вона була послушницею з нічних ельфів на ім'я Скарлетліф і першою зголосилася допомогти Наралексові в його сміливому задумі зцілити Пустки. Коли єднання її наставника зі Смарагдовим Сном обернулося жахіттям, її розум зламався, а відданість переродилася в отруйне прагнення побачити Калімдор, заполонений зміями.",section="Ще до того як узяти собі зміїне ім'я, Леді Анакондра звалася Скарлетліф. Коли старший друїд Наралекс задумав через Смарагдовий Сон дістатися підземних джерел Пусток, вона першою зголосилася йому допомагати. Та палка відданість її й згубила. Коли розумом Наралекса заволоділи темні видіння, жахіття просочилося зі світу снів і заразило його учнів: Скарлетліф утратила розум, а її мрійливе захоплення обернулося холодною, плазуючою одержимістю.",sectionIndex=1}
c["npc:lady-sarevess"] = "a4682a"
P.scopedClips["npc:lady-sarevess"] = {scope="overview-body",sourceHash="46ee45",hash="a4682a",name="Леді Саревесс",summary="Леді Саревесс — спотворена нага-чаклунка, що живе в затоплених руїнах Чорноглибинних Печер і віддається темному чаклунству.",section="У Ставку Аск'ар леді Саревесс проводить свої ритуали в затопленому гроті зруйнованого храму. Украй спотворена чарівниця, вона віддається темній магії, тоді як культисти Молота Присмерку, що теж нишпорять затонулим храмом, правлять свої служби глибше в печері.",sectionIndex=1}
c["npc:laurna-morninglight"] = "136761"
P.scopedClips["npc:laurna-morninglight"] = {scope="overview-body",sourceHash="f2f804",hash="136761",name="Лаурна Морнінґлайт",summary="Лаурна Морнінґлайт — наставниця жерців нічних ельфів, що мешкає в тихому поселенні Доланаар на Тельдрассилі. Віддана Сестринству Елуни, вона веде послушників-початківців, що приходять із Тінедолу, через духовні обряди й цілющі дари Богині Місяця. Її наука готує молодих жерців нічних ельфів до загроз, що насуваються на гілля Світового Дерева.",section="Серед гілля Доланаара Лаурна Морнінґлайт — одна з головних наставниць молодих жерців, що пройшли перші обряди в Тінедолі. Коли нові посвячені виходять у ширші простори Тельдрассила, вона вчить їх поглиблювати єднання з Елуною, урівноважуючи світло зцілення з оборонними обрядами, без яких не вижити в дедалі ворожіших хащах.",sectionIndex=1}
c["npc:lieutenant-farren-orinelle"] = "51ea02"
P.scopedClips["npc:lieutenant-farren-orinelle"] = {scope="overview-body",sourceHash="44ee36",hash="51ea02",name="Лейтенант Фаррен Орінелль",summary="Лейтенант Фаррен Орінелль — офіцер армії Стормвінда, що нині несе службу в корчмі Саутшора в Передгір'ї Гілсбреда. Глибоко незадоволений своїм прикордонним призначенням, він здебільшого пиячить, перекладаючи свої обов'язки на мандрівників. Його головне військове доручення — розібратися з мурлоками, що наступають на узбережжі, і цю морочливу справу він охоче доручає іншим, сподіваючись вибити собі переведення назад на південь.",section="Лейтенант Фаррен Орінелль не обирав Саутшор. Посланий далеко від Стормвінда, лейтенант вважає вологі спірні береги Гілсбреда жалюгідним пониженням порівняно з цивілізованими вигодами столиці. Замість патрулювати поля чи узгоджувати оборону зі своїм командиром, Маршалом Редпатом, Орінелль практично оселився в корчмі Саутшора. Дні він проводить, дуючись, пиячачи й мріючи про офіційний наказ про переведення, що поверне його на південь.",sectionIndex=1}
c["npc:lord-cobrahn"] = "6aa190"
P.scopedClips["npc:lord-cobrahn"] = {scope="overview-body",sourceHash="57ddbf",hash="6aa190",name="Лорд Кобран",summary="Лорд Кобран, колись друїд із нічних ельфів на ім'я Джарлаксла, — один зі спотворених Друїдів Ікла, що чатують у глибинах Печер Стогонів. Колись він славився в Колі Кенарія майстерністю перевтілення, але піддався жахіттю, що заразило печерні джерела. Тепер, назвавшись на честь своєї нової смертоносної подоби, Кобран командує виводками девіантних змій і боронить спотворений лабіринт.",section="Перш ніж узяти собі прізвисько Лорд Кобран, Джарлаксла був шанованим членом Кола Кенарія, і друїди славили його за надзвичайну вправність у перевтіленні на звірів. Коли Наралекс спустився в Печери Стогонів під Пустками, сподіваючись дістатися підземних джерел і повернути посушливим пустищам буяння життя, Джарлаксла пішов із ним. Та коли єднання Наралекса зі Смарагдовим Сном переродилося в зловісне жахіття, розум Джарлаксли зламався разом із розумом його побратимів.",sectionIndex=1}
c["npc:lord-ello-ebonlocke"] = "0240c1"
P.scopedClips["npc:lord-ello-ebonlocke"] = {scope="overview-body",sourceHash="893f16",hash="0240c1",name="Лорд Елло Ебонлок",summary="Лорд Елло Ебонлок — мер Даркшира й голова його ради, що засідає в Ратуші Даркшира. Оточений темрявою та повзучими жахами, він щодня бореться за порядок і захищає обложених містян, хоча зі Стормвінда допомоги майже не надходить.",section="Сидячи в сутінках Ратуші Даркшира, Лорд Елло Ебонлок несе важкий тягар правління поселенням на межі загибелі. Колись Даркшир був частиною квітучого сільського краю, відомого як Велике Селище, а тепер його огорнула вічна тінь і обложили ненажерливі гулі, скелети-потвори та дикі звірі. Елло очолює Раду Даркшира й попри безнадійні обставини намагається підтримувати рештки цивілізованого життя, поки Стормвінд заплющує очі на їхню біду.",sectionIndex=1}
c["npc:lord-pythas"] = "35a0a6"
P.scopedClips["npc:lord-pythas"] = {scope="overview-body",sourceHash="f26433",hash="35a0a6",name="Лорд Пайтас",summary="Лорд Пайтас, колись воїн із нічних ельфів на ім'я Арін, — один із чотирьох спотворених ватажків Друїдів Ікла в Печерах Стогонів. Він був другом дитинства й присяжним охоронцем верховного друїда Наралекса, але став жертвою жахіття, що отруїло підземну оазу. Тепер він обертає і бойову міць, і спотворену зміїну магію проти кожного, хто намагається дістатися до його сплячого володаря.",section="Перш ніж узяти собі ім'я Пайтас, цей нічний ельф звався Арін. Досвідчений воїн і вірний товариш Наралекса з дитячих років, він був особистим охоронцем верховного друїда, коли експедиція вирушила в сухі пустища Пусток. Прагнучи краще служити сміливій мрії Наралекса — повернути посушливому краю буяння життя, — Арін узявся вивчати друїдство й виявився надзвичайно здібним учнем. Та тілесна дисципліна й бойова звитяга не вберегли його від підступної порчі, що чатувала глибоко в підземних розколинах.",sectionIndex=1}
c["npc:lord-serpentis"] = "8ef286"
P.scopedClips["npc:lord-serpentis"] = {scope="overview-body",sourceHash="362613",hash="8ef286",name="Лорд Серпентіс",summary="Лорд Серпентіс — спотворений друїд із нічних ельфів, один із чотирьох ватажків свавільних Друїдів Ікла в Печерах Стогонів. Колись могутній і шанований друїд в ордені Наралекса, він збожеволів, коли сон Наралекса обернувся жахіттям у підземних джерелах. Тепер він допомагає керувати сектою зміїних поклонників глибоко в печерах, де спить зіпсований Наралекс.",section="До того як темрява поглинула печерні джерела, Серпентіс був могутнім і шанованим друїдом — членом шляхетного ордену на чолі з Наралексом, який сподівався за допомогою печерних джерел і Смарагдового Сну зцілити Пустки. Та коли видіння Наралекса обернулося згубним жахіттям, Серпентіс опинився серед тих друїдів, чий розум поглинуло божевілля, що тоді зароджувалося.",sectionIndex=1}
c["npc:lorgus-jett"] = "3b01d6"
P.scopedClips["npc:lorgus-jett"] = {scope="overview-body",sourceHash="2f147e",hash="3b01d6",name="Лорґус Джетт",summary="Лорґус Джетт — людина, член культу Молота Присмерку, що діє в затоплених коридорах Чорноглибинних Печер. Блукаючи Руїнами Місячної Святині, він слугує безжальним командиром культу, відданого Древнім Богам. Ватажки Орди визначили його однією з головних цілей, щоб зупинити поширення культу на узбережжі Ашенвалю.",section="Багато членів Молота Присмерку, що діють у Чорноглибинних Печерах, — орки чи таурени, але Лорґус Джетт вирізняється тим, що він людина, яка опинилася в глибинах давніх руїн нічних ельфів. Блукаючи будь-де між верхніми Руїнами Місячної Святині й печерними тунелями за лігвом мурлока-осквернителя Ґелігаста, Джетт керує темними ритуалами культу та його кривавими задумами.",sectionIndex=1}
c["npc:madame-eva"] = "5ea0a2"
P.scopedClips["npc:madame-eva"] = {scope="overview-body",sourceHash="186bb8",hash="5ea0a2",name="Мадам Єва",summary="Мадам Єва — шанована ворожка й матріарх, що живе в Даркширі, посеред темного лісу Сутінколісся. Вона володіє давнім містичним мистецтвом віщування й ворожіння на картах і часто першою з містян відчуває неприродні збурення в лісі. Мандрівники нерідко шукають її, щоб розгадати похмурі таємниці чи роздобути чародійні обереги від темряви, що підкрадається.",section="Тихо живучи серед мороку Даркшира, Мадам Єва ворожить на картах і проводить давні народні обряди, на які багато хто в соборі Стормвінда дивився б із підозрою. У покинутому краї, де лютують дикі звірі, нежить і ще темніші жахи, її моторошні прозріння терплять і шукають — і зневірені містяни, і заїжджі шукачі пригод.",sectionIndex=1}
c["npc:magatha-grimtotem"] = "27bace"
P.scopedClips["npc:magatha-grimtotem"] = {scope="overview-body",sourceHash="7fd9b2",hash="27bace",name="Маґата Ґрімтотем",summary="Маґата Ґрімтотем — матріарх племені Ґрімтотем і Стара Відьма Тандер Блафа. Грізна шаманка й політична інтриганка, вона живе на Узвишші Старійшин і раз у раз кидає виклик баченню Кайрна Бладгуфа щодо майбутнього тауренського народу.",section="Маґата здобула абсолютну владу над Ґрімтотемами через шлюб за домовленістю, після якого її чоловік раптово загинув, зірвавшись зі скелі. Зі своїм почтом і охоронцями вона править з Узвишшя Старійшин як незаперечна політична й духовна провідниця свого відлюдного племені. На відміну від Кайрна Бладгуфа, Маґата проповідує панування тауренів і вважає інші смертні раси зайдами в Калімдорі, яких слід знищити чи відкинути геть.",sectionIndex=1}
c["npc:maggran-earthbinder"] = "09b892"
P.scopedClips["npc:maggran-earthbinder"] = {scope="overview-body",sourceHash="ac9440",hash="09b892",name="Маґґран Ертбайндер",summary="Маґґран Ертбайндер — сивий таурен-ветеран, якого Верховний Вождь Кайрн Бладгуф призначив очолити табір Орди в Притулку Сонячної Скелі. Загартований життям, сповненим жорстоких боїв, він керує обороною скелястих долин Гір Кам'яного Кігтя від ненажерливих звірів і агресивних зграй гарпій. Хоч він утомився від незліченних битв, він лишається непохитним охоронцем поселення.",section="Маґґрана Ертбайндера послав у Гори Кам'яного Кігтя сам Верховний Вождь Кайрн Бладгуф. Ветеран незліченних сутичок і кривавих походів, Маґґран визнає, що вік і насильство зробили його серце жорстким, позбавивши природної лагідності, властивої його народові. Притулок Сонячної Скелі мав стати і заставою під його твердою рукою, і місцем перепочинку, де теплі вітри й гірське сонце могли б заспокоїти його втомлений боями дух.",sectionIndex=1}
c["npc:magistrate-sevren"] = "a34948"
P.scopedClips["npc:magistrate-sevren"] = {scope="overview-body",sourceHash="34426f",hash="a34948",name="Магістрат Севрен",summary="Магістрат Севрен — головний управитель поселення Брілл у Галявинах Тірісфалю. Стоячи в ратуші, він організовує ранню оборону Відступників й скеровує прибулих звитяжців зміцнювати землі довкола Андерсіті.",section="З ратуші Брілла Магістрат Севрен координує цивільну владу й стратегічні зусилля на землях одразу на північ від Андерсіті. Коли нові Відступники виходять у Галявини Тірісфалю, Севрен оцінює місцеві негаразди й висилає шукачів пригод відновлювати лад, убезпечувати зруйноване господарство та придушувати невідступні загрози, що чаяться в довколишніх пагорбах.",sectionIndex=1}
c["npc:magistrate-solomon"] = "189ba9"
P.scopedClips["npc:magistrate-solomon"] = {scope="overview-body",sourceHash="bbf2dd",hash="189ba9",name="Магістрат Соломон",summary="Магістрат Соломон — обраний правитель і головний магістрат Лейкшира, що вершить місцеві справи з ратуші. Обложений орками Блекрок і невгамовними кланами гнолів, він днями гарячково благає про воєнну допомогу байдужий і зайнятий іншим Стормвінд.",section="Магістрат Соломон править Лейкширом у найтемнішу годину його новітньої історії. Мирне поселення над озером оточене ворогами: пагорбами довкола никають гноли Редріджу й гноли Тіньової Шкури, а з півночі організованими загонами спускаються орки Блекрок. Соломон разом із Маршалом Маррісом підтримує лад і збирає оборону, але місцева варта й ополчення Лейкшира вже на межі сил.",sectionIndex=1}
c["npc:magni-bronzebeard"] = "b3e15f"
P.scopedClips["npc:magni-bronzebeard"] = {scope="overview-body",sourceHash="854931",hash="b3e15f",name="Маґні Бронзбірд",summary="Маґні Бронзбірд — Володар Айронфорджа, тан клану Бронзбірдів і правитель Каз Модану. Неперевершений коваль і бувалий полководець Другої війни, він веде своє гірське королівство крізь горе й політичну напругу, водночас підтримуючи дворфську археологію по всьому Азероту.",section="Найстарший із трьох братів, Маґні змалку добре усвідомлював тягар, що чекав на нього під горою. Коли під час Другої війни вторглася Орда, він утримав Айронфордж за його неприступною брамою, а щойно облогу було знято, вийшов і присягнув Каз Моданом Альянсу Лордерону. У мирні роки, що настали потім, Маґні прийняв у місто гномських союзників після падіння Гномреґану, давши прихисток під горою Великому Тінкеру Ґелбіну Меккаторку та його біженцям. Щоб об'єднати роз'єднані південне й північне королівства, Маґні попросив Меккаторка створити нечуване підземне диво — Глибинний трамвай, що сполучив Айронфордж просто зі Стормвіндом.",sectionIndex=1}
c["npc:makaba-flathoof"] = "7febce"
P.scopedClips["npc:makaba-flathoof"] = {scope="overview-body",sourceHash="cac618",hash="7febce",name="Макаба Флетгуф",summary="Макаба Флетгуф — таурен, що вцілів у Таборі Апараже в Горах Кам'яного Кігтя. Ставши свідком спустошення своєї домівки й народу від рук клану Ґрімтотем, він шукає відважних героїв Орди, щоб помститися нападникам і вберегти свою родину.",section="Макаба Флетгуф уособлює трагічну ціну внутрішніх чвар серед тауренів. Його домівка, Табір Апараже в Горах Кам'яного Кігтя, стала жертвою безжального раптового нападу клану Ґрімтотем. Поки багато тауренів прагнуть миру й єдності під проводом Кайрна Бладгуфа, віроломні Ґрімтотеми раз у раз сіють розбрат і насильство, лишаючи таких, як Макаба, без домівки й у жалобі.",sectionIndex=1}
c["npc:malfurion-stormrage"] = "3097a0"
P.scopedClips["npc:malfurion-stormrage"] = {scope="overview-body",sourceHash="1432a6",hash="3097a0",name="Малфуріон Стормрейдж",summary="Малфуріон Стормрейдж — перший смертний друїд і шанований провідник нічних ельфів, що веде їх пліч-о-пліч із Верховною Жрицею Тірандою Віспервінд. Він уславився тим, що здолав Палаючий Легіон і у Війні Прадавніх, і в Третій війні, тож його вшановують як Шан'до — «шанованого вчителя». Нині ж його дух загубився у Смарагдовому Сні, тіло лежить у глибокому заціпенінні, і калдореї лишилися без його живих настанов.",section="Десять тисяч років тому, ще до того, як Великий Розкол розтрощив прадавній Калімдор, Малфуріон навчався в напівбога Кенарія. Поки королева Азшара та її каста Високородних небезпечно заглиблювалися в чародійну міць Колодязя Вічності, Малфуріон звернувся до первісних сил природи й став першим смертним друїдом Азерота. Його підозри щодо Високородних, на лихо, справдилися: безрозсудне чаклунство Азшари прорвало завісу між світами й прикликало до Азерота Саргераса та Палаючий Легіон. Так спалахнула нищівна Війна Прадавніх.",sectionIndex=1}
c["npc:mangletooth"] = "01ae45"
P.scopedClips["npc:mangletooth"] = {scope="overview-body",sourceHash="84223f",hash="01ae45",name="Понівечозуб",summary="Понівечозуб — ув'язнений шипогрив із Гостроманів, якого Орда тримає в полоні в Таборі Тауражо. Чекаючи на страту, він виміняє стратегічні відомості про своїх суперників і давні перекази про Аґамаґґана на послуги тих шукачів пригод, які готові виконати його волю.",section="Понівечозуб — полонений шипогрив із Гостроманів, якого таурени-мисливці та орки-вартові тримають у клітці в Таборі Тауражо в очікуванні страти. Він не змирився зі смертю, а намагається маніпулювати своїми наглядачами й шукачами пригод з Орди, щоб ті розправилися з ворогами його племені: сподівається, що хитрість доведе його цінність або допоможе вибратися на волю.",sectionIndex=1}
c["npc:marshal-dughan"] = "7675c0"
P.scopedClips["npc:marshal-dughan"] = {scope="overview-body",sourceHash="3bf33d",hash="7675c0",name="Маршал Дуґан",summary="Маршал Дуґан — командир загону армії Стормвінда, розквартированого в Ґолдширі. Йому доручено захищати серце Лісу Елвінн, та його місцевий гарнізон розтягнутий до краю перед дедалі більшими вторгненнями кобольдів, гнолів і розбійників. Щоб убезпечити містечко на перехресті й навколишні ферми, він чимало покладається на вільних шукачів пригод.",section="Маршал Дуґан, що стоїть на видноті в Ґолдширі біля корчми «Лев'яча Гордість», несе важкий тягар: тримати Ліс Елвінн у безпеці, поки військові сили Стормвінда зайняті деінде. Навколишні ліси неухильно занепадають: копальні кишать поганню, гноли збираються на берегах річок, а розбійники дошкуляють мандрівникам на Королівському шляху. Маючи замало піхотинців під прямим командуванням, Дуґан організовує місцеву оборону, спрямовуючи новобранців зміцнювати застави й розвідувати спірні землі.",sectionIndex=1}
c["npc:marshal-marris"] = "36f28d"
P.scopedClips["npc:marshal-marris"] = {scope="overview-body",sourceHash="5bab89",hash="36f28d",name="Маршал Марріс",summary="Маршал Марріс — знесилений офіцер, що командує міською вартою Лейкшира. Стоячи біля міського мосту, він керує обороною проти величезного вторгнення орків Блекрок, які насуваються з висот Гір Редріджу. Армії Стормвінда тут немає, тож він покладається на заїжджих шукачів пригод, щоб стримати наступ орди.",section="Лейкшир на межі загибелі: на заході — гноли, на сході — страхітлива воєнна міць клану Блекрок. Маршал Марріс тримає лінію варти біля головного мосту міста, але його запаси вичерпано, а солдати розпорошені до неможливого. Королівство Стормвінд не дає підкріплень, тож саме на Маррісі лежить важкий тягар — не дати грубій силі розчавити містечко.",sectionIndex=1}
c["npc:marshal-mcbride"] = "ce9bae"
P.scopedClips["npc:marshal-mcbride"] = {scope="overview-body",sourceHash="ae6415",hash="ce9bae",name="Маршал Макбрайд",summary="Маршал Дуглас Макбрайд — командир гарнізону Стормвінда при Абатстві Нортшира. Йому доручено оборону Долини Нортширу, і він кидає новоприбулих рекрутів проти навали кобольдів, що загрожує місцевим фермам і шахтам. Для новачків, які починають службу королівству Стормвінд, він — головна військова влада.",section="Маршал Дуглас Макбрайд стоїть просто біля Абатства Нортшира й уособлює пряму владу армії Стормвінда в цій тихій долині. Саме абатство — острівець віри й знань, але неспокій, що шириться королівством, розтягнув військові гарнізони до краю. Макбрайд мусить берегти мир і забезпечувати долину харчами та ресурсами, маючи лише жменьку присяжних вартових і потік зелених рекрутів, які приходять навчатися в майстрів абатства.",sectionIndex=1}
c["npc:master-apothecary-faranell"] = "228998"
P.scopedClips["npc:master-apothecary-faranell"] = {scope="overview-body",sourceHash="4b0de0",hash="228998",name="Головний Аптекар Фаранелл",summary="Головний Аптекар Фаранелл — очільник Королівського Аптекарського Товариства, що працює в глибинах Апотекаріуму в Андерсіті. За життя шанований учений Даларана, у нежитті він керує пошуками нищівної Нової Чуми, яка має знищити і Погибель, і живих.",section="До Третьої війни Фаранелл був шанованим алхіміком, що десятиліттями навчався поруч із ученими магами Даларана. Свої смертні дні він присвятив пошукам ліків, засобів і зілль, що поліпшували б здоров'я смертних. Коли чума Погибелі забрала його життя і він повстав як Відступник із вільною волею, колишня наукова цікавість обернулася на жорстокість. Зберігши енциклопедичний розум, він проміняв цілющі мазі на згубні реагенти й швидко став одним із найцінніших дослідників Королеви Сильвани Віндраннер у надрах занепалої столиці Лордерона.",sectionIndex=1}
c["npc:master-gadrin"] = "41ff3f"
P.scopedClips["npc:master-gadrin"] = {scope="overview-body",sourceHash="e94b44",hash="41ff3f",name="Майстер Ґадрін",summary="Майстер Ґадрін — старий троль із джунглів і шанований знахар племені Темного Списа, що нині живе в Селі Сен'джин. Колись він разом із відступником-знахарем Залазаном навчав жерців і магів племені, а тепер очолює зусилля, щоб допомогти своєму вигнаному народові й зняти темне прокляття з їхнього вкраденого дому на Островах Відлуння.",section="Задовго до того, як Темний Спис прибув на Калімдор, Майстер Ґадрін був знахарем свого племені на прадавніх островах Південних Морів, де керував містичним навчанням цілих поколінь тролів Темного Списа.",sectionIndex=1}
c["npc:mathias-shaw"] = "eaee27"
P.scopedClips["npc:mathias-shaw"] = {scope="overview-body",sourceHash="d7b874",hash="eaee27",name="Матіас Шоу",summary="Майстер Матіас Шоу — очільник SI:7, таємної розвідувальної служби Королівства Стормвінд. Діючи з тіней Старого Міста, він керує шпигунами й розвідниками, щоб захистити королівство і від внутрішніх змов, і від зовнішніх жахіть.",section="Матіас Шоу — головний шпигун і вбивця Стормвінда. Зі скромного штабу SI:7, захованого за казармами в Старому Місті, Шоу керує таємною мережею, що охоплює Східні Королівства й не тільки. Прагматичний, розважливий і безмежно відданий дому Ріннів, він дотримується переконання, що безпека Стормвінда так само залежить від невидимих кинджалів і викрадених листів, як і від блискучих обладунків та палацових гарнізонів.",sectionIndex=1}
c["npc:mathrengyl-bearwalker"] = "127a30"
P.scopedClips["npc:mathrengyl-bearwalker"] = {scope="overview-body",sourceHash="9f5189",hash="127a30",name="Матренґіл Берволкер",summary="Матренґіл Берволкер — досвідчений наставник друїдів і шанований старійшина Кола Кенарія, що живе в Ценаріонському Анклаві Дарнасуса. Колись він був безпосереднім помічником Архідруїда Фандрала Стаґгелма, а нині веде молодих друїдів Альянсу крізь духовні випробування, обряди перевтілення й доручення по всьому Калімдору.",section="Серед зелених крон Ценаріонського Анклаву в Дарнасусі Матренґіл Берволкер вважається одним із наймудріших і найврівноваженіших друїдів Тельдрассила. Він — головний провідник для недосвідчених друїдів Альянсу: стежить за їхнім єднанням із Місячним Гаєм і перевіряє, чи готові вони опанувати первісні звірині подоби. Замолоду Матренґіл і сам пройшов крізь виснажливе, приголомшливе єднання з Великим Духом Ведмедя, тож добре розуміє вагу цих обрядів. Він особисто велить новачкам випробувати силу свого духу в поєдинку зі священним місячником Лунакло, перш ніж вони ступлять на шлях Друїда Пазура.",sectionIndex=1}
c["npc:mebok-mizzyrix"] = "983903"
P.scopedClips["npc:mebok-mizzyrix"] = {scope="overview-body",sourceHash="cd8510",hash="983903",name="Мебок Міззірікс",summary="Мебок Міззірікс — заповзятливий гоблін-ділок, що живе в портовому містечку Раджет. Завжди готовий перетворити дивовижні дикі інгредієнти на прибуток, він наймає мандрівних шукачів пригод збирати незвичайні рослини й тварин по всіх Пустках і далі. Найславетніший його задум — комерційний напій для поліпшення розуму з рогів рапторів.",section="Мебок Міззірікс, що веде справи в гамірному нейтральному порту Раджет, утілює класичний дух картелю Стімвідл — невтомне вміння скористатися будь-якою нагодою. Раджет обслуговує моряків, піратів і торговців усіх мастей, а Мебок пильно придивляється до дикої природи Калімдору. Замість добувати звичайну руду чи торгувати буденним полотном, він шукає рідкісні біологічні дивовижі, з яких, на його думку, можна виготовити дуже прибуткові зілля й товари.",sectionIndex=1}
c["npc:melor-stonehoof"] = "0683e0"
P.scopedClips["npc:melor-stonehoof"] = {scope="overview-body",sourceHash="0e6d9d",hash="0683e0",name="Мелор Стоунгуф",summary="Мелор Стоунгуф — бувалий тауренський мисливець, що несе службу на Узвишші Мисливців у Тандер Блафі. Як наставник у мисливському мистецтві, він перевіряє, як мисливці Орди вміють вистежувати здобич і чи вистачає їм мужності, посилаючи їх за найнебезпечнішими хижаками Пусток і Тисячі Голок.",section="Зі свого місця на вітряних просторах Узвишшя Мисливців Мелор Стоунгуф досвідченим оком оглядає рівнини внизу. Для тауренів полювання священне: воно переплетене з виживанням, духовною рівновагою й шаною до найбільших хижаків природи. Мелор дбає, щоб ті, хто носить лук і клинок в ім'я Орди, розуміли цю рівновагу, і посилає здібних слідопитів відточувати майстерність у випробуваннях із легендарними звірами.",sectionIndex=1}
c["npc:menara-voidrender"] = "712a36"
P.scopedClips["npc:menara-voidrender"] = {scope="overview-body",sourceHash="b06f99",hash="712a36",name="Менара Войдрендер",summary="Менара Войдрендер — чорнокнижниця-людина, що живе в гоблінському порту Раджет. Вона наставляє честолюбних адептів темних мистецтв і з Альянсу, і з Орди, ділячись глибокими знаннями про артефакти для зв'язування демонів і таємне ремесло. Відлюдне життя на Калімдорі тримає її далеко від пильного ока правовірної влади.",section="Більшість чорнокнижників у Східних Королівствах практикують у вогких підвалах чи відлюдних бойнях під рідними містами, але Менара Войдрендер обрала нейтральний гоблінський порт Раджет у Пустках. Далеко від прискіпливого ока Кірін-Тору, варти Стормвінда чи наглядачів Оргріммара, вона вільно віддається своїм окультним студіям у всіх на виду. Готовність працювати з будь-яким здібним учнем, незалежно від фракції, робить її рідкісною спільною точкою для адептів темних мистецтв.",sectionIndex=1}
c["npc:miner-johnson"] = "c4d616"
P.scopedClips["npc:miner-johnson"] = {scope="overview-body",sourceHash="7b9858",hash="c4d616",name="Шахтар Джонсон",summary="Шахтар Джонсон — невловимий бувалий гірник Братства Дефіас, що працює глибоко в Мертвих Копальнях. Сховавшись у бічній ніші поруч зі звичайними робітниками, цей небезпечний рудошукач наглядає за розкопками попереду важких машин, що стоять глибше під землею. Він блукає підземними тунелями без жодного ладу, тож шукачі пригод лише зрідка натрапляють на нього.",section="Поки сотні робітників довбають підземні жили Мертвих Копалень, постачаючи потаємну фортецю Едвіна Венкліфа, Шахтар Джонсон помітно вирізняється серед них грізною вдачею. Він причаївся в затіненій ніші ліворуч, перед незграбними потрощувачами Щоглової Кімнати, і значно міцніший та зліший за звичайних робітників. З'являється він непередбачувано, тож для дослідників тунелів Дефіас Джонсон став легендарною здобиччю.",sectionIndex=1}
c["npc:morin-cloudstalker"] = "60e07e"
P.scopedClips["npc:morin-cloudstalker"] = {scope="overview-body",sourceHash="8bcfbf",hash="60e07e",name="Морін Клаудсталкер",summary="Морін Клаудсталкер — тауренський розвідник, що вартує на дорозі, яка веде на схід від Села Бладгуф до Пусток у Малгорі. Пильнуючи рівнини, він стежить за місцевими торговими шляхами й розслідує загрози, що насуваються на тауренських мандрівників.",section="Ставши край ґрунтової дороги, що в'ється на схід до Пусток, Морін Клаудсталкер водночас розвідник і охоронець для подорожніх Малгору. Трав'янисті рівнини тут зазвичай мирні, але відкриття торгових шляхів і зрушення кордонів привабили пройдисвітів і розбійників небезпечно близько до серця тауренської батьківщини.",sectionIndex=1}
c["npc:motega-firemane"] = "6a93e1"
P.scopedClips["npc:motega-firemane"] = {scope="overview-body",sourceHash="2b3825",hash="6a93e1",name="Мотеґа Фаєрмейн",summary="Мотеґа Фаєрмейн — тауренський учений із Застави Білого Рубежу в Тисячі Голок. Він присвятив себе описуванню небезпечних звірів каньйону, проте його дослідження раз у раз перериває мстивий дух вітряного змія та безрозсудні пригоди його юного помічника.",section="Через чотири роки після Третьої війни Мотеґа Фаєрмейн вирушив на південь, у Тисячу Голок, щоб спостерігати й описувати незвичних звірів, які виживають серед височенних столових гір. Разом зі своїм юним помічником Пао'кою Свіфтмаунтіном — чий надміру дбайливий батько неохоче відпустив сина з Малгору — Мотеґа розбив табір поряд із Канаті Ґрейклаудом на Заставі Білого Рубежу. Він прийшов сюди заради тихих спостережень за природою, але суворі небезпеки на дні каньйону раз у раз вимагають від нього радше бойового підходу до виживання.",sectionIndex=1}
c["npc:mr-smite"] = "157262"
P.scopedClips["npc:mr-smite"] = {scope="overview-body",sourceHash="4ce3bd",hash="157262",name="Пан Кара",summary="Пан Кара — могутній таурен, старший помічник на флагмані Братства Дефіас глибоко в Мертвих Копальнях. Вправний майстер зброї на службі в капітана Ґрінскіна, він із нещадною дисципліною стереже підступи до потаємного броненосця з боку доків. Кожен, хто стане проти нього, муситиме протистояти його змінному арсеналу й нищівній силі.",section="Пан Кара стереже доки Бухти Айронклад і служить старшим помічником гобліна, капітана Ґрінскіна. Братство Дефіас складається здебільшого зі знедолених людей і союзних гоблінів-майстрів, тож Кара тут — разюча дивина: велетенський, загартований у боях таурен, далеко від рівнин Калімдору. Йому доручено тримати в суворому порядку галасливу піратську команду, і він стежить, щоб оснащення таємного броненосця Едвіна Венкліфа йшло без перешкод.",sectionIndex=1}
c["npc:mull-thunderhorn"] = "1c0dd0"
P.scopedClips["npc:mull-thunderhorn"] = {scope="overview-body",sourceHash="147d3b",hash="1c0dd0",name="Малл Тандергорн",summary="Малл Тандергорн — тауренський старійшина, що мешкає в Селі Бладгуф у Малгорі. Глибоко відданий Земній Матері та рівновазі землі, він наглядає за священними водяними криницями, розкиданими по рівнинах. Коли чужинці-визискувачі загрожують життєдайним водам краю, Малл проводить молодих тауренів через обряди очищення прабатьківських джерел.",section="Стоячи на варті в Селі Бладгуф, Малл Тандергорн несе на собі тягар духовного добробуту Малгору. Кочові племена зібралися під рукою Верховного Вождя Кайрна Бладгуфа, щоб звести собі постійну домівку, та їхні землі вже в облозі жадібності й нерозважливого загарбання. Малл — духовна опора для молодих сміливців, що виходять із Табору Нарачі; він кличе їх берегти життєво важливі скарби предків.",sectionIndex=1}
c["npc:mutanus-the-devourer"] = "52d3c1"
P.scopedClips["npc:mutanus-the-devourer"] = {scope="overview-body",sourceHash="08162d",hash="52d3c1",name="Мутанус Пожирач",summary="Мутанус Пожирач — жахливий блідий мурлок, що постав просто зі Смарагдового Жахіття. Він чатує в найтемніших закутках розуму сплячого друїда Наралекса й виринає, щоб пожерти кожного, хто намагається зламати владу Жахіття над Печерами Стогонів. Убити цю спотворену потвору — останній крок до того, щоб звільнити Наралекса з його болісного сну.",section="Коли друїд із нічних ельфів Наралекс дістався підземних джерел під Пустками, він хотів повернути життя посушливим пустищам, поєднавши їх зі Смарагдовим Сном. Натомість у його думки вдерлася прадавня порча, відома як Смарагдове Жахіття. Ув'язнений у болісному видінні, Наралекс побачив, як його потаємні страхи набувають плоті. Порча вчепилася в дивну, первісну відразу в душі друїда — його глибоко вкорінений жах перед мурлоками — і роздула її до велетенського хижака-альбіноса.",sectionIndex=1}
c["npc:naralex"] = "848b7f"
P.scopedClips["npc:naralex"] = {scope="overview-body",sourceHash="519ad2",hash="848b7f",name="Наралекс",summary="Наралекс — друїд із нічних ельфів, який прагнув силами Смарагдового Сну перетворити спраглі Пустки на пишний ліс. Натомість його сон поглинуло темне жахіття, що спотворило Печери Стогонів під землею й обернуло його послідовників на отруйних потвор.",section="Задовго до Великого Розколу випалені сонцем рівнини Пусток були буйним лісом. Вважаючи цю втрату трагедією, Наралекс вирушив із Дарнасуса на південь разом із гуртом відданих учнів, щоб здолати посуху. Глибоко під саваною він відкрив хитромудру мережу підземних джерел і бурхливих гейзерів і назвав її Печерами Стогонів — через виття вітру й пари, що стогнали в скелі. Він вірив, що коли зануриться в глибокий транс і спрямує чисту енергію Смарагдового Сну в ці підземні води, життєдайна течія дійде до поверхні, і вся пустка розквітне.",sectionIndex=1}
c["npc:oggleflint"] = "2e5ffd"
P.scopedClips["npc:oggleflint"] = {scope="overview-body",sourceHash="9cc654",hash="2e5ffd",name="Оґґлфлінт",summary="Оґґлфлінт — ватажок племені трогів, що живе у вулканічних глибинах Провалля Лютого Вогню просто під Оргріммаром. Колись володар усієї підземної печери, він і його родичі були відтиснуті до верхніх тунелів культистами Пекучого Клинка, що прийшли сюди. Тепер він окопався біля входу, керує своєю дикою зграєю й становить безпосередню загрозу для столиці Орди нагорі.",section="Доки культисти тіні не проникли в провалля під Оргріммаром, Оґґлфлінт і його троги безроздільно панували у вогняних підземних тунелях. Жорстокі й ревниві до своєї території, вони вирізали собі примітивне володіння серед розпеченого каміння. Хоч троги майже не знають цивілізації, Оґґлфлінт тримав над зграєю цілковиту владу самою лише грубою силою.",sectionIndex=1}
c["npc:old-serra-kis"] = "31fb05"
P.scopedClips["npc:old-serra-kis"] = {scope="overview-body",sourceHash="a9eb21",hash="31fb05",name="Старий Серра'кіс",summary="Старий Серра'кіс — давній велетенський трешадон, що живе в затоплених підземних водах Чорноглибинних Печер. Культисти Молота Присмерку, що вторглися сюди, винищили на харч більшість водних мешканців храму, але полювання на цього велетенського звіра виявилося смертельно небезпечним.",section="Коли культисти Молота Присмерку спустилися до затонулих Руїн Місячної Святині, вони перебили місцевих підводних звірів собі на поживу. Та під Святилищем Місячної Святині одна первісна істота не захотіла ставати здобиччю. Старий Серра'кіс, найбільший трешадон затонулого храму, швидко розправлявся з кожним культистом, що мав зухвалість націлити на нього спис. Зрештою мисливці відступилися, і давній хижак лишився у своїх водяних володіннях сам.",sectionIndex=1}
c["npc:onyxia"] = "3df129"
P.scopedClips["npc:onyxia"] = {scope="overview-body",sourceHash="3a556d",hash="3df129",name="Оніксія",summary="Оніксія — матір виводку чорних драконів і підступна донька Детвінга. Причаївшись у своєму драконячому лігві в Багні Пилоброду, вона доглядає свій зростаючий виводок і разом зі своєю зловісною зграєю прагне панувати над світами смертних."}
c["npc:orgnil-soulscar"] = "ed9640"
P.scopedClips["npc:orgnil-soulscar"] = {scope="overview-body",sourceHash="85f4c3",hash="ed9640",name="Орґніл Соулскар",summary="Орґніл Соулскар — орк-слідчий, що стоїть на Гострому Пагорбі в центральному Дуротарі. Він виконує роль неофіційного охоронця порядку, узгоджуючи оборону й розвідку проти внутрішніх загроз молодій державі. Найбільше його непокоїть тінь, яку кидає на каньйони Дуротару культ Палаючого Клинка.",section="На Гострому Пагорбі Орґніл Соулскар узяв на себе похмурий обов'язок вистежувати підривну діяльність і підступні загрози по всьому Дуротару. Поки патрулі бійців дивляться назовні — на плацдарми Альянсу та загони кентаврів-нападників, — Орґніл зосереджений на гнилі, що визріває зсередини. Він збирає донесення розвідників з усього краю, складаючи докупи докази обрядового скверніння та потаємних зібрань.",sectionIndex=1}
c["npc:orgrim-doomhammer"] = "1cd2c3"
P.scopedClips["npc:orgrim-doomhammer"] = {scope="overview-body",sourceHash="ef4ecf",hash="1cd2c3",name="Оргрім Думхаммер",summary="Оргрім Думхаммер був верховним Вождем Старої Орди впродовж усієї Другої війни; його пам'ятають як одного з найвидатніших орочих воїнів в історії. Він загинув, визволяючи табори ув'язнення в Аратійському нагір'ї, але його спадщина живе у столиці Оргріммар і в Траллі, який успадкував його могутній бойовий молот і чорні латні обладунки.",section="Спершу Оргрім був правою рукою Блекгенда з клану Блекрок. Він відмовився від демонічної крові, яку пропонував Ґул'дан, хоча й ховав свої сумніви за запеклою вірністю. Наприкінці Першої війни, з огидою спостерігаючи за підступністю Ради Тіней і вбивством свого друга дитинства Дуротана, Оргрім убив Блекгенда в чесному поєдинку. Ставши Вождем, він нещадно винищив чорнокнижників Ґул'дана й повів Орду через Східні Королівства в Другій війні. Грізний стратег, що поставив людські королівства на межу загибелі, він усе ж зазнав поразки й потрапив у полон під Шпилем Блекрок, коли зрада Ґул'дана розколола його військо.",sectionIndex=1}
c["npc:overlord-ramtusk"] = "1acf57"
P.scopedClips["npc:overlord-ramtusk"] = {scope="overview-body",sourceHash="cf22b0",hash="1acf57",name="Володар Рамтаск",summary="Володар Рамтаск — загартований командир військових сил племені Мертвої Голови глибоко в Рейзорфен Краулі. Шкура цього величезного старого воїна-шипогрива всіяна шрамами за десятиліття жорстоких сутичок по всіх Пустках. Його смерть ламає бойовий хребет захисників Краула.",section="Володар Рамтаск пережив десятиліття на одному з найкривавіших прикордонь Калімдору. Його товсту, мов дублена, шкуру перетинають глибокі шрами, здобуті в сутичках із загонами кентаврів, дикими гарпіями, орками-загарбниками й стійкими тауренськими воїнами. Похилий вік сповільнює багатьох бійців, але досвідчене чуття й фізична витривалість Рамтаска лише загартувалися, тож він керує постійним гарнізоном Рейзорфен Краула з непохитною владою.",sectionIndex=1}
c["npc:ozzie-togglevolt"] = "c4fb9e"
P.scopedClips["npc:ozzie-togglevolt"] = {scope="overview-body",sourceHash="9ce9c0",hash="c4fb9e",name="Оззі Тоґлвольт",summary="Оззі Тоґлвольт — гном-інженер, що пережив падіння Гномреґана, а тепер працює в засніженому селищі Харанос у Дун Мороґу. Переслідуваний трагедією, що спіткала його народ, він разом зі своїм напарником Раззлом Спрайспрокетом шукає ліки для опромінених гномів-прокажених.",section="Оззі Тоґлвольт був серед підземних див Гномреґана, коли сталася катастрофа. Коли отруйні викиди пустили коридорами, щоб зупинити навалу трогів, Оззі стояв поруч зі своїм товаришем-гномом Ґноарном. Раптовий радіоактивний викид ударив просто в Ґноарна й назавжди змінив його на очах в Оззі. Хоч Оззі вибрався на поверхню живим і дістався прихистку в Дун Мороґу, жахливий спогад про ту катастрофу так і не покинув його.",sectionIndex=1}
c["npc:pelturas-whitemoon"] = "8dea4f"
P.scopedClips["npc:pelturas-whitemoon"] = {scope="overview-body",sourceHash="db47a0",hash="8dea4f",name="Пелтурас Вайтмун",summary="Пелтурас Вайтмун — нічний ельф з Астранаару, батько маленької Релари, яку вразила страшна хвороба скверни. Відчайдушно прагнучи врятувати доньку, він разом із місцевим травником Орендилом Броудліфом та героями Альянсу збирає священні ліки в навколишніх нетрях. Пошуки зцілення для Релари ведуть шукачів пригод до найдавніших священних гаїв і руїн Ашенвалю.",section="Пелтурас Вайтмун живе серед спокійного віття Астранаару тихим життям, звичним для лісових калдореїв, і часто ходить зі своєю маленькою донькою Реларою збирати мерехтливі місячні камені біля Озера Впалого Неба. Та коли Релара тяжко захворіла на загадкову недугу, його тихий світ обернувся відчаєм. Астранаар оточений ворогами з багатьох боків, але для Пелтураса ніщо в цьому великому лісі не важить більше, ніж порятунок дитини.",sectionIndex=1}
c["npc:priestess-alathea"] = "0a7f20"
P.scopedClips["npc:priestess-alathea"] = {scope="overview-body",sourceHash="303638",hash="0a7f20",name="Жриця Алатея",summary="Жриця Алатея — наставниця жерців серед нічних ельфів, що служить у тихих залах Храму Місяця в Дарнасусі. Віддана Місячній Богині, вона навчає послушників священних мистецтв і особливих благословень, якими Елуна обдаровує свій народ. Її наука допомагає нічним ельфам налаштувати розум на захисні молитви й небесну магію.",section="Під високими срібними склепіннями найвеличнішого святилища Дарнасуса Жриця Алатея служить Сестринству Елуни як наставниця й духовна провідниця. Коли молоді нічні ельфи виростають із тихого затінку Тінедолу, їх скеровують до Храму Місяця, щоб поглибити їхній завіт із Богинею. Алатея — серед жриць, готових передати священне знання тим, хто присвячує життя зціленню, захисту й божественному світлу.",sectionIndex=1}
c["npc:raene-wolfrunner"] = "a4893c"
P.scopedClips["npc:raene-wolfrunner"] = {scope="overview-body",sourceHash="d1c84c",hash="a4893c",name="Рейн Вульфраннер",summary="Рейн Вульфраннер — досвідчена офіцерка Вартових і мисливиця, що несе службу в самому серці Астранаару в Ашенвалі. Разом із вірними супутниками — вовком і шаблезубою кішкою — вона керує обороною лісу від Орди та осквернених племен фурболгів. Для героїв Альянсу, що захищають священну дикину, вона — надійна опора.",section="Рейн Вульфраннер пильно стоїть на варті в Астранаарі разом зі своєю вірною шаблезубою кішкою Коррою та вовком Даґрі. Як офіцерка Вартових, вона наглядає за патрулями по всьому Ашенвалю й координує розвідку далеко за його межами, посилаючи розвідниць на кшталт Каели Шедовспір у сусідні краї, як-от Гори Кам'яного Кігтя. Відданість Рейн давнім лісам безмежна: вона заявила, що радше сама вийде проти неповоротких загонів Орди, ніж дивитиметься, як вони безкарно рубають і палять священні дерева.",sectionIndex=1}
c["npc:rejold-barleybrew"] = "13bd76"
P.scopedClips["npc:rejold-barleybrew"] = {scope="overview-body",sourceHash="06b2b6",hash="13bd76",name="Реджолд Барліброю",summary="Реджолд Барліброю — майстер-пивовар із дворфів, що оселився в прибережному Селі Брюнолл на заході Дун Мороґу. Відданий удосконаленню міцних гірських напоїв, він раз у раз залучає мандрівників збирати місцеві інгредієнти й випробовувати його потужні рецепти по всій засніженій долині.",section="У Дун Мороґу пивоваріння — не просто ремесло, а справжнє мистецтво, яке визначає характер краю. Реджолд Барліброю втілює цю традицію в Селі Брюнолл, що притулилося біля замерзлого озера на річці Крижаного Потоку. Замість задовольнятися звичайним шинковим пійлом, Реджолд невпинно вдосконалює свої купажі, шукаючи рідкісний хміль, гірські мінерали та чисту талу воду, щоб варити стаути, здатні зігріти найміцніших дворфських воїнів.",sectionIndex=1}
c["npc:rethiel-the-greenwarden"] = "f9b999"
P.scopedClips["npc:rethiel-the-greenwarden"] = {scope="overview-body",sourceHash="f0c0df",hash="f9b999",name="Ретіель Зеленовартовий",summary="Ретіель Зеленовартовий — прадавній розумний болотяний звір, що живе в Зеленому Поясі в Багнокраї. Він тонко відчуває природну рівновагу боліт, оберігає цю землю й закликає мандрівників винищувати загрози, що порушують її злагоду.",section="Ретіель, що височіє серед вологих хащів Зеленого Поясу, — велетенське створіння з моху, торфу й первісної рослинної плоті. Багато болотяних звірів тиняються драговинами як безтямні хижаки, а Ретіель має рідкісну свідому тяму й журливий голос. Для нього болота — не просто каламутна місцевість, а живий світ, який нині стогне під тягарем зайд-хижаків і порчі.",sectionIndex=1}
c["npc:rhahk-zor"] = "2b04f9"
P.scopedClips["npc:rhahk-zor"] = {scope="overview-body",sourceHash="b3c45b",hash="2b04f9",name="Рагк'Зор",summary="Рагк'Зор — кремезний огр, головний наглядач у Мертвих Копальнях. Він стежить за підземним будівництвом Едвіна Венкліфа й тримає робітників та гірників Дефіас у покорі грубою силою й важкою рукою.",section="Глибоко під пологими пагорбами Вестфолу Братство Дефіас перетворило покинуті золоті копальні Мунбрука на підземну фортецю. Таке розлоге будівництво потребує суворої дисципліни, і цю роль виконує огр Рагк'Зор. Призначений головним наглядачем, він керує бригадами копачів і робітниками, підганяючи їх прокладати тунелі й утілювати таємні задуми Венкліфа.",sectionIndex=1}
c["npc:rorian-the-dayseeker"] = "f7f4cd"
P.scopedClips["npc:rorian-the-dayseeker"] = {scope="overview-body",sourceHash="d45a0a",hash="f7f4cd",name="Роріан Деньошукач",summary="Роріан Деньошукач — шанований старійшина небороджених у Селі Тендаль на Острові Зефрас. Він наглядає за посвятою юних новаків, коли ті відкривають своє покликання, дорослішають і налаштовуються на природні стихії рідного краю. Під його пильним проводом новачки опановують основи виживання, традицій і служіння громаді.",section="У спокійному затишку Села Тендаль на Острові Зефрас Роріан Деньошукач — один із головних наставників юних небороджених. Шанований за досвід і спокійну мудрість, Роріан скеровує молодь на важливому шляху до дорослості. Саме під його наглядом новаки проходять традиційний обряд посвяти, що засвідчує їхню готовність боронити й підтримувати рідний острів.",sectionIndex=1}
c["npc:scarlet-commander-mograine"] = "17a23e"
P.scopedClips["npc:scarlet-commander-mograine"] = {scope="overview-body",sourceHash="6b792a",hash="17a23e",name="Багряний Командир Моґрейн",summary="Багряний командир Моґрейн — воєначальник гарнізону в Соборі Багряного Монастиря. Ревний паладин Багряного Хрестового Походу, він боронить каплицю разом із Верховною інквізиторкою Вайтмейн. І Орда, і Альянс полюють на нього, щоб приборкати фанатиків, які загрожують Галявинам Тірісфалю й сусіднім землям.",section="У величній Каплиці Хрестоносця, в самому серці Багряного Монастиря, Багряний командир Моґрейн очолює постійний гарнізон Багряного Хрестового Походу. Він володіє святою силою паладина з лютою відданістю й покладається на відплату, божественні щити та приголомшливі удари, щоб розтрощити кожного, кого Похід вважає зіпсованим чи нечистим.",sectionIndex=1}
c["npc:senani-thunderheart"] = "88d2e4"
P.scopedClips["npc:senani-thunderheart"] = {scope="overview-body",sourceHash="72227e",hash="88d2e4",name="Сенані Тандергарт",summary="Сенані Тандергарт — тауренка-мисливиця із Застави Розщепленого Дерева в Ашенвалі, трохи на північ від Пусток. Служачи Орді, вона випробовує мандрівників, кидаючи їм виклик вистежити лютих хижаків давнього лісу. Її випробування дають мисливцям змогу довести свою майстерність і водночас прорідити смертоносних звірів, що нишпорять поблизу земель Орди.",section="Сенані Тандергарт, що отаборилася на Заставі Розщепленого Дерева, уособлює мисливські традиції тауренів серед затінених гаїв Ашенвалю. Далеко від відкритих рівнин Малгору вона посилає шукачів пригод з Орди випробувати свої навички слідопитів і бійців на найгрізніших хижаках лісу. Полювання для неї — і почесне випробування, і необхідний ритуал виживання в дикому, спірному краї.",sectionIndex=1}
c["npc:senir-whitebeard"] = "d598e2"
P.scopedClips["npc:senir-whitebeard"] = {scope="overview-body",sourceHash="90d624",hash="d598e2",name="Сенір Вайтбірдий",summary="Сенір Вайтбірдий — дворфський сановник і польовий агент, що стоїть біля Ґуральні Тандербрю в Хараносі. Як особливий посланець Сенату Айронфорджа, він має стежити за загрозами, що дедалі тісніше оточують Дун Мороґ. Його головне завдання — оцінити наступ тролів Морозогривів і доповідати про їхні пересування безпосередньо дворфському проводу.",section="Поки більшість мандрівників приходять до Хараноса заради гамірної корчми й славетного стауту, Сенір Вайтбірдий тут у службових справах. Його, представника, присланого самим Сенатом Айронфорджа, присутність показує, наскільки серйозно у високих залах ставляться до розхитування Дун Мороґу. Він — важлива ланка між місцевими розвідниками, що зустрічають небезпеку на засніженому порубіжжі, і законодавцями, які сперечаються про політику за кам'яною брамою міста.",sectionIndex=1}
c["npc:shadow-priest-allister"] = "554f5e"
P.scopedClips["npc:shadow-priest-allister"] = {scope="overview-body",sourceHash="83ecf9",hash="554f5e",name="Жрець Тіні Аллістер",summary="Жрець Тіні Аллістер — жрець-Відступник, що несе службу в Гробниці в Срібноліссі. Він керує розвідкою й тактичними діями в краї, організовуючи стеження за чарівниками Даларана й захист кордонів Лордерона для Темної Леді.",section="Жрець Тіні Аллістер, що діє з Гробниці, керує розвідкою Відступників по всьому Срібноліссю. З цього поселення-крипти він стежить за загрозами поблизу — від людей-ренегатів і навал звірів до таємних задумів, що розгортаються біля мерехтливого купола Даларана.",sectionIndex=1}
c["npc:shadow-priest-sarvis"] = "3f0512"
P.scopedClips["npc:shadow-priest-sarvis"] = {scope="overview-body",sourceHash="25263e",hash="3f0512",name="Жрець Тіні Сарвіс",summary="Жрець Тіні Сарвіс стоїть у зруйнованій каплиці Похоронного Подзвону — один із головних провідників щойно пробуджених Відступників. Він знайомить свіжих мерців з їхньою похмурою дійсністю, посилаючи їх винищувати безтямну нежить і збирати відомості про місцеві загрози. Під прапором Леді Сильвани Сарвіс невтомно ліпить із розгублених мерців дисциплінованих слуг Відступників.",section="У тінистій каплиці Похоронного Подзвону Жрець Тіні Сарвіс чекає на тих, хто щойно вигрібся з могили. Пробудження душі Відступника — струс і жах: багато хто одразу втрачає розум у безтямному шалі чи відчаї. Сарвіс — опора, що дає мету щойно воскреслим. Він доручає новобранцям добивати шкутильгаючі безтямні трупи, які блукають цвинтарем, і посилає їх убезпечувати межі Похоронного Подзвону від Погибелі, що насувається.",sectionIndex=1}
c["npc:shael-dryn"] = "6c0fb2"
P.scopedClips["npc:shael-dryn"] = {scope="overview-body",sourceHash="d9c035",hash="6c0fb2",name="Шаель'дрін",summary="Шаель'дрін — допитлива дріада, що живе біля Місячного Колодязя Чистоти, на схід від Озера Ірисів в Ашенвалі. Вона — важлива помічниця розвідників нічних ельфів, які досліджують скверну в лісі. Саме вона допомагає вартовим Астранаару очищувальними реліквіями в боротьбі з демонічними й згубними силами, що ширяться дикими землями.",section="Шаель'дрін живе біля Місячного Колодязя Чистоти й разом із вартовими нічних ельфів стереже східні підступи до лісу. Коли серед місцевих звірів проступає скверна або осквернені реліквії загрожують гармонії краю, її глибоке чуття природи допомагає провести шукачів пригод через усі кроки, потрібні для відновлення духовної рівноваги.",sectionIndex=1}
c["npc:shenthul"] = "047eec"
P.scopedClips["npc:shenthul"] = {scope="overview-body",sourceHash="a1ab33",hash="047eec",name="Шентул",summary="Шентул — троль із джунглів, наставник розбійників у тінистих підземних закутках Тіньової Розколини в Оргріммарі. Як агент Розтрощеної Руки, він керує розвідувальними операціями по всьому Калімдору й посвячує молодих розбійників у таємні лави гільдії.",section="Шентул, що ховається в каламутних глибинах Тіньової Розколини, — один із найкращих наставників розбійників Орди. Поки воїни й шамани нагорі відкрито крокують червоним пилом Дуротару, Шентул навчає тих, хто віддає перевагу скритності, засідкам і підступу. Під його проводом новачки опановують необхідні польові навички й смертоносні мистецтва та вчаться діяти серед безжальної політики й суворої дикої природи Калімдору.",sectionIndex=1}
c["npc:sneed"] = "d85bf2"
P.scopedClips["npc:sneed"] = {scope="overview-body",sourceHash="3e8306",hash="d85bf2",name="Снід",summary="Снід — гоблін, старший лісоруб Братства Дефіас, що працює глибоко в Мертвих Копальнях. З лісопильні, відомої як Щоглова Кімната, він керує важким потрощувачем власної конструкції й обробляє деревину для таємного броненосця Едвіна Венкліфа.",section="Ядро Братства Дефіас — знедолені людські каменярі та прості робітники, але для будівництва броненосця потрібні фахівці особливих ремесел. Едвін Венкліф завербував Сніда саме заради його інженерних знань і безжальної гоблінської діловитості. У Щогловій Кімнаті, при підземній залізниці, Снід наглядає, як швидко валять, ріжуть і обтесують дерево для каркаса колосального броненосця Венкліфа.",sectionIndex=1}
c["npc:sneed-s-shredder"] = "98cb09"
P.scopedClips["npc:sneed-s-shredder"] = {scope="overview-body",sourceHash="cc7f8d",hash="98cb09",name="Потрощувач Сніда",summary="Потрощувач Сніда — грізна механічна лісозаготівельна машина глибоко в Мертвих Копальнях. Нею керує гоблін-наглядач Снід, і вона водночас служить важким промисловим механізмом для корабелів Едвіна Венкліфа та жахливим вартовим на підступах.",section="У ливарні Мертвих Копалень, де заправляють гобліни, механічні потрощувачі мають подвійне призначення: вони обробляють величезну кількість деревини для потаємного броненосця Едвіна Венкліфа й водночас слугують броньованими таранами проти непроханих гостей. Снід, наглядач лісопильні, сам керує цим переробленим механічним чудовиськом, перетворивши велетенську циркулярну пилку на знаряддя оборони.",sectionIndex=1}
c["npc:sprite-jumpsprocket"] = "97ade2"
P.scopedClips["npc:sprite-jumpsprocket"] = {scope="overview-body",sourceHash="7f11e1",hash="97ade2",name="Спрайт Джампспрокет",summary="Спрайт Джампспрокет — гномка, учениця інженера, що нині живе в гамірному Дворфійському Кварталі Стормвінда. Як і багато гномів, що шукали прихистку після падіння Гномреґану, вона займається технічним ремеслом і винахідництвом разом зі своїми колегами-майстрами. Її присутність свідчить про квітучу громаду дворфійських і гномських майстрів, що забезпечують столицю шестернями, пристроями й механічними знаннями.",section="На закіптюжених вулицях і в гомінких майстернях Дворфійського Кварталу гноми й дворфи працюють пліч-о-пліч, кують метал і конструюють хитромудрі пристрої. Спрайт Джампспрокет — учениця інженера в цьому жвавому осередку. Освоївшись у столиці королівства, учні-майстри на кшталт Спрайт відточують ремесло під наглядом досвідчених наставників, вкладаючи свій винахідливий розум у повсякденні механізми й технічні дива Альянсу.",sectionIndex=1}
c["npc:sputtervalve"] = "581e5b"
P.scopedClips["npc:sputtervalve"] = {scope="overview-body",sourceHash="002cc1",hash="581e5b",name="Спаттервалв",summary="Спаттервалв — знервований гоблін-інженер, що працює в портовому містечку Раджет. Служачи Спілці Винахідників під керівництвом директора Ріддлвокса, він відповідає за розробку подрібнювачів у краї і працює під тиском нещадних корпоративних строків. Щоб зберегти посаду, він часто наймає шукачів пригод для промислового шпигунства проти суперниці — Венчурної Компанії.",section="Спаттервалв, що працює в Раджеті, звітує директорові Ріддлвоксу зі Спілки Винахідників. Отримавши доручення розробляти подрібнювачі, він швидко з'ясував, що встигати за сучасною механізацією — жорстока праця. Під тиском запеклої конкуренції та невблаганного строку Спаттервалв опинився майже без власних робочих зразків. Замість визнати поразку перед Спілкою, він вдався до класичного гоблінського рішення: вкрасти кращі креслення в тих, хто збудував їх першим.",sectionIndex=1}
c["npc:sten-stoutarm"] = "5faf8e"
P.scopedClips["npc:sten-stoutarm"] = {scope="overview-body",sourceHash="6a84d0",hash="5faf8e",name="Стен Стаутарм",summary="Стен Стаутарм — практичний дворфський постачальник і кур'єр, що стоїть біля Анвілмара в Долині Холодного Хребта. Він відповідає за спорядження новобранців і місцеву пошту, дбаючи, щоб молоді горяни лишалися в теплі, ситими й поінформованими попри суворі гірські умови.",section="Стен Стаутарм стоїть майже в самому серці Долини Холодного Хребта — одне з перших привітних облич, яке дворфські та гномські новобранці бачать, вийшовши з корчми Анвілмара. Поки долина відрізана зимовими хуртовинами й оточена небезпеками, Стен бере на себе клопіт спорядити зелених учнів міцним одягом, перш ніж вони замерзнуть або непідготовленими заблукають у заметах.",sectionIndex=1}
c["npc:strahad-farsan"] = "68a534"
P.scopedClips["npc:strahad-farsan"] = {scope="overview-body",sourceHash="784bc5",hash="68a534",name="Страгад Фарсан",summary="Страгад Фарсан — майстер-чорнокнижник із людей, що живе у відлюдній кам'яній вежі над Раджетом у Пустках. Знаний по обидва боки фронту, він діє поза звичною політикою Альянсу й Орди, навчаючи честолюбних заклиначів небезпечного мистецтва зв'язування вищих демонів. Адепти магії скверни і зі Стормвінда, і з Оргріммара, і з Андерсіті шукають його суворого наставництва.",section="Вежа Страгада Фарсана, що стоїть на кручах над гоблінським портом Раджет, височіє осторонь гамірних торгових доків унизу. Нейтральність Раджета дає Страгадові свободу проводити небезпечні демонічні виклики далеко від цікавих очей магістратів Альянсу чи шаманів Орди. В оточенні своїх послідовників він вивчає глибші таємниці Викривленого Нижнього Світу у відносній самоті, не зважаючи на дріб'язкові чвари за землю.",sectionIndex=1}
c["npc:sven-yorgen"] = "57f4c6"
P.scopedClips["npc:sven-yorgen"] = {scope="overview-body",sourceHash="7aaadf",hash="57f4c6",name="Свен Йорґен",summary="Свен Йорґен — фермер у жалобі, що отаборився на Притихлому Березі на півночі Сутінколісся разом зі своїм товаришем Ларсом. Переживши жорстоку різанину своєї родини на Хуторі Йорґенів, Свен живе невідступним прагненням дізнатися, хто зруйнував його дім, і помститися.",section="Свен народився ще до Першої війни й пам'ятає часи, коли край ще не огорнула пітьма після падіння Медіва. Роками він обробляв землю на Хуторі Йорґенів на півдні Сутінколісся разом із дружиною й дітьми. Те тихе життя обірвалося раптовим насильством: коли Свена не було вдома, на хутір налетіли загадкові Темні Вершники, вирізали його родину й перетворили ферму на цвинтар.",sectionIndex=1}
c["npc:sylvanas-windrunner"] = "5f9505"
P.scopedClips["npc:sylvanas-windrunner"] = {scope="overview-body",sourceHash="daff7e",hash="5f9505",name="Сильвана Віндраннер",summary="Леді Сильвана Віндраннер — Королева Баньші й верховна володарка Відступників, що править в Андерсіті під руїнами Лордерона. Колись відважна Генерал-Рейнджер Сілвермуну, вона загинула від руки Артаса Менетіла й була піднята ним у нежиття, а згодом вирвалася з-під влади Короля-Ліча. Нині, уклавши союз з Ордою Тралла заради спільного виживання, вона затято прагне забезпечити майбутнє своїй нежиті з вільною волею й помститися Погибелі.",section="За життя Леді Сильвана була славетною Генерал-Рейнджером Сілвермуну й керувала обороною Кель'Таласу під час Третьої війни. Коли принц Артас Менетіл повів Погибель у королівство високих ельфів, щоб дістатися Сонячного Колодязя, Сильвана запекло билася, щоб затримати його наступ. Розлючений її опором, Артас убив її, але не дав їй спокійної смерті. Він вирвав її душу з тіла й перетворив на мстиву баньші, змусивши служити Погибелі й допомагати в різанині власного народу.",sectionIndex=1}
c["npc:tallonkai-swiftroot"] = "7ce1f6"
P.scopedClips["npc:tallonkai-swiftroot"] = {scope="overview-body",sourceHash="374d35",hash="7ce1f6",name="Таллонкай Свіфтрут",summary="Таллонкай Свіфтрут — нічний ельф, мешканець Доланаара на Тельдрассилі. Стурбований скверною, що зароджується й отруює велике гілля, він залучає молодих шукачів пригод повертати зачаровані реліквії та стримувати нечисті сили, що мучать ліс.",section="Живучи в кронах Доланаара, Таллонкай Свіфтрут пильно стежить за довколишніми лісами. Як і багатьох нічних ельфів під гіллям новорослого Світового Дерева, його тривожить неприродне збурення живності та лиховісні тіні, що збираються на околицях поселень.",sectionIndex=1}
c["npc:taragaman-the-hungerer"] = "ff0a81"
P.scopedClips["npc:taragaman-the-hungerer"] = {scope="overview-body",sourceHash="8adf73",hash="ff0a81",name="Тараґаман Голодний",summary="Тараґаман Голодний — кремезний вартовий скверни, що чатує в розпечених печерах Провалля Лютого Вогню під Оргріммаром. Хоч його повсюдно бояться як демонічного володаря, що стоїть за культом Пекучого Клинка, його присутність у вогняних глибинах служить темнішій, підступнішій меті. Орда прагне його знищити, щоб позбутися демонічної скверни, що отруює нутрощі міста.",section="Никаючи між озерами магми в Проваллі Лютого Вогню, Тараґаман Голодний становить пряму й жахливу загрозу безпеці Оргріммара. Багатьом розвідникам і молодим воїнам, яких посилають у темне провалля, цей демонічний вартовий скверни видається головним ватажком культистів Пекучого Клинка, що пекельною силою підкоряє слабодухих і оскверняє підземні ходи під фортецею Тралла.",sectionIndex=1}
c["npc:targorr-the-dread"] = "b93728"
P.scopedClips["npc:targorr-the-dread"] = {scope="overview-body",sourceHash="12c33c",hash="b93728",name="Тарґорр Жахливий",summary="Тарґорр Жахливий — сумнозвісний кат з орків Блекрок, ув'язнений глибоко у В'язниці Стормвінда. Відомий жорстокими катуваннями полонених солдатів Стормвінда, він уникнув страти, яку безкінечно відкладали через бюрократичну недолугість і корупцію. Коли під проводом Братства Дефіас у В'язниці спалахнув бунт, Тарґорр вирвався на волю й пристав до бунтівних каторжників.",section="До полону Тарґорр Жахливий був головним катом клану Блекрок під командою воєначальника Ґат'Ілзоґґа. Діючи з захоплених руїн у Редріджі, він вирізнявся жорстокістю навіть за кривавими мірками Темної Орди. Вартові й ополченці Стормвінда, що боронили прикордоння, зазнавали від його рук страшних мук і повільної смерті, і його ім'я стало одним із найненависніших у королівстві.",sectionIndex=1}
c["npc:tavernkeep-smitts"] = "51f988"
P.scopedClips["npc:tavernkeep-smitts"] = {scope="overview-body",sourceHash="cb0a6b",hash="51f988",name="Шинкар Смітс",summary="Шинкар Смітс — господар Таверни «Багряний Крук» у Даркширі. Він тримає заклад у самому серці громадського життя Сутінколісся й знає геть усі міські плітки та нерозкриті місцеві трагедії. Довга пам'ять і гостре око роблять його безцінним співрозмовником для кожного, хто розслідує темну історію краю.",section="За шинквасом Таверни «Багряний Крук» Шинкар Смітс пропонує тепло вогнища й випивку втомленим мандрівникам, місцевим містянам і знервованим вартовим Нічної Варти, що щодня ризикують життям у Сутінколіссі. Як одне з найдавніших знайомих облич у місті, Смітс чує кожну чутку, що просочується крізь морок. Поки інші містяни ховаються за зачиненими віконницями, Смітс тверезо й уважно придивляється до кожного, хто переступає його поріг, — помічає дивну поведінку, квапливі від'їзди й химерних відвідувачів.",sectionIndex=1}
c["npc:telf-joolam"] = "d1ae50"
P.scopedClips["npc:telf-joolam"] = {scope="overview-body",sourceHash="78eeff",hash="d1ae50",name="Телф Джулам",summary="Телф Джулам — троль-шаман із джунглів, із племені Темного Списа, що наглядає за Святинею Приспаного Полум'я. Він проводить посвячуваних Орди крізь випробування, потрібні, щоб спілкуватися з мінливою стихією вогню й керувати нею.",section="Серед скель над порубіжжям Телф Джулам доглядає Святиню Приспаного Полум'я. На відміну від спокійної певності землі чи терплячої глибини води, духи вогню вимагають гострої дисципліни й непохитної зосередженості. Телф виступає розпорядником випробувань: він готує молодих шаманів довести свою гідність диким жаринам, перш ніж ті їх поглинуть.",sectionIndex=1}
c["npc:terenthis"] = "f728e5"
P.scopedClips["npc:terenthis"] = {scope="overview-body",sourceHash="676fa2",hash="f728e5",name="Терентіс",summary="Терентіс — друїд нічних ельфів, що несе службу в приморському поселенні Обердайн. Представник Кола Кенарія, він розслідує тривожну скверну, що шириться Темним Узбережжям і Тельдрассилом. Він залучає здібних мандрівників, щоб оцінити загрози на узбережжі й допомогти місцевим союзникам, яких оточили осквернені звірі.",section="Терентіс, якого Коло Кенарія прислало до Обердайна, стежить за поширенням Моху Скверни та інших згубних сил, що просочуються з Тельдрассилу на Темне Узбережжя. Нічні ельфи з великою тривогою дивляться на цю повзучу пошесть, боячись, що дика рівновага північного Калімдору може цілком розвалитися, якщо її не стримати. Терентіс намагається з'ясувати першопричини гниття й знайти спосіб зупинити його, перш ніж воно поглине ліси.",sectionIndex=1}
c["npc:theocritus"] = "639a37"
P.scopedClips["npc:theocritus"] = {scope="overview-body",sourceHash="57db6e",hash="639a37",name="Теокрітус",summary="Архімаг Теокрітус — дивакуватий чародій з людей, що живе на вершині Вежі Азори на сході Лісу Елвінн. Колись пов'язаний із Кірін-Тором Даларану, нині він живе незалежно, в оточенні слуг і магічних пристроїв для прозирання. Зі свого високого святилища Теокрітус спрямовує свої таємні таланти на нагляд за королівством і боротьбу зі своїм темним суперником — магом-відступником Морґантом.",section="Колись член престижного Кірін-Тору Даларану, Архімаг Теокрітус вирішив заснувати незалежну твердиню далеко на півдні, у королівстві Стормвінд. Він оселився у примітній Вежі Азори біля східної дороги на Редрідж. Теокрітус відомий дивацькими звичками та вигідним способом життя: він тримає численну челядь, зокрема багатьох слуг-гномів і власного кравця Морлі Еберлейна. Хоч він і тримається осторонь буденних клопотів місцевих селян, його присутність — важливий магічний щит східного Елвінну.",sectionIndex=1}
c["npc:thotar"] = "530f65"
P.scopedClips["npc:thotar"] = {scope="overview-body",sourceHash="3f384d",hash="530f65",name="Тотар",summary="Тотар — бувалий орк, наставник мисливців у поселенні Гострий Пагорб у Дуротарі. Він навчає майбутніх розвідників і стрільців Орди прадавніх традицій вистежування, стрільби з лука та єднання з дикими звірами. Молодим оркам і тролям, що роблять перші кроки за межами Долини Випробувань, він дає основоположні обряди, потрібні, щоб опанувати сувору звірину Калімдору.",section="В укріпленому осередку Гострого Пагорба Тотар служить бувалим наставником для стрільців Орди. Поки новобранці опановують найперші основи в Долині Випробувань, саме Тотарові випадає вести мисливців, коли ті зустрічають суворішу хижу глушину Дуротару. Спираючись на традиції, передані крізь незліченні покоління орків, він навчає не лише влучності, а й глибшої поваги, потрібної, щоб жити поруч із найсмертоноснішими створіннями Калімдору й керувати ними.",sectionIndex=1}
c["npc:thrall"] = "50cd9d"
P.scopedClips["npc:thrall"] = {scope="overview-body",sourceHash="ea8c58",hash="50cd9d",name="Тралл",summary="Тралл — Вождь Орди й володар Дуротару, що править із Долини Мудрості в Оргріммарі. Колись раб людей, вихований для гладіаторських боїв на арені, він розбив кайдани свого народу, заново відкрив його давні шаманські традиції й повів його через Велике Море, щоб збудувати нову батьківщину.",section="Народжений як Ґо'ел, син вождя клану Морозного Вовка Дуротана й Драки, Тралл осиротів ще немовлям, коли вбивці Ґул'дана вбили його батьків. Його знайшов людський командувач Еделас Блекмур, який назвав його Траллом, що означає «раб», і виховав у Твердині Дурнгольд як бійця арени, навчивши людської тактики. З допомогою названої сестри Тарети Фокстон Тралл зрештою втік від своїх кривдників. Під проводом вигнанця з клану Морозного Вовка Дрек'Тара він відкинув демонічну скверну, опанував стихійних духів і став першим із нового покоління орочих шаманів.",sectionIndex=1}
c["npc:thyn-tel-bladeweaver"] = "4239cd"
P.scopedClips["npc:thyn-tel-bladeweaver"] = {scope="overview-body",sourceHash="1d0306",hash="4239cd",name="Тин'тел Блейдвівер",summary="Тин'тел Блейдвівер — вартова нічних ельфів, що несе службу на Терасі Воїна в Дарнасусі. Її глибоко непокоїть зникнення жриці Велінде Старсонг, тож вона посилає надійних шукачів пригод з Альянсу шукати її сліди. Своїми розпитуваннями вона намагається розплутати таємницю Коси Елуни.",section="Тин'тел Блейдвівер, що з Тераси Воїна пильнує Дарнасус, представляє військову силу калдореїв. Коли жриця Велінде Старсонг таємниче зникла, не лишивши жодної звістки, Тин'тел не дала сліду охолонути. Відчуваючи, що тут замішані грізні сили, вона сама взялася наймати шукачів пригод, готових переглянути особисті речі жриці й з'ясувати, куди привела її дорога.",sectionIndex=1}
c["npc:tirion-fordring"] = "d05869"
P.scopedClips["npc:tirion-fordring"] = {scope="overview-body",sourceHash="0146ab",hash="d05869",name="Тіріон Фордрінг",summary="Тіріон Фордрінг — легендарний паладин і колишній володар Фортеці Марденгольд, що нині тихо живе у вигнанні у Східних Чумних землях. Один із перших п'яти паладинів, посвячених у Лицарі Срібної Длані, він утратив титул і землі, бо дотримав слова честі, даного ворогові-оркові. Зі своєї скромної хатини над Річкою Тондроріл він спостерігає за трагедією, що розгортається в Лордероні, і тривожиться за сина.",section="Ще до загибелі Лордерону Тіріон Фордрінг славився як один із найкращих лицарів королівства. Під час Другої війни архієпископ Алонсус Фаол обрав його разом з Утером Світлоносцем, Туральйоном, Саїданом Датроганом і Ґавінрадом Грізним, щоб заснувати Орден Лицарів Срібної Длані. Озброєний латами, святою відданістю й Книгою Відплати, Тіріон водив воїнів у жорстокі бої зі Старою Ордою, зокрема в кривавій облозі Шпиля Блекрок. Його шанували як непохитний взірець Святого Світла.",sectionIndex=1}
c["npc:tiza-battleforge"] = "e7a6ad"
P.scopedClips["npc:tiza-battleforge"] = {scope="overview-body",sourceHash="430bfd",hash="e7a6ad",name="Тіза Баттлфордж",summary="Тіза Баттлфордж — досвідчена дворфійська паладинка з Лицарів Срібної Длані, що служить у Залі Таїнств в Айронфорджі. Вона славиться непохитною відданістю й проникливістю та веде молодих дворфійських паладинів шляхом чесноти, милосердя й самопожертви. Через вивчення священних текстів і випробування в поході вона перевіряє, чи справді новачки готові прийняти дар Світла — воскресіння.",section="У тихих покоях Зали Таїнств в Айронфорджі Тіза Баттлфордж — одна з найшанованіших дворфійських паладинок Лицарів Срібної Длані. Новачків з усього Альянсу посилають до неї наставники — Брандур Айронгаммер в Айронфорджі, Азар Стронгхаммер у Дун Мороґу та Лорд Ґрейсон Шедовбрейкер у Стормвінді, — щоб поглибити їхню духовну освіту. Тіза певна, що Святе Світло вимагає більшого, ніж бойова вправність: смиренного служіння, співчуття й непохитної стійкості перед темрявою Погибелі, що насувається, та іншими загрозами.",sectionIndex=1}
c["npc:tonga-runetotem"] = "e63a29"
P.scopedClips["npc:tonga-runetotem"] = {scope="overview-body",sourceHash="9aa498",hash="e63a29",name="Тонга Рунтотем",summary="Тонга Рунтотем — обізнаний таурен-друїд, що стоїть біля корчми на Перехресті в Пустках. Його прислали з Тандер Блафа розслідувати неприродну скверну, яка просочується в нечисленні оази краю й отруює місцевих звірів. Своїми дослідженнями він прагне простежити духовне збурення до самого джерела, поки крихка рівновага природи остаточно не зруйнувалася.",section="Серед пилу й гамірної торгівлі Перехрестя Тонга Рунтотем тихо несе свою варту. Його прислали з високих плато Малгору старійшини Тандер Блафа, і він глибоко розуміє посушливу савану. Там, де інші бачать лише голі чагарники й хижих звірів, він читає тонкі ознаки здоров'я землі. Останнім часом ці ознаки різко погіршилися, і він наймає здібних мандрівників, щоб дослідити саме серце життя савани — її відокремлені оази.",sectionIndex=1}
c["npc:turak-runetotem"] = "b38bc5"
P.scopedClips["npc:turak-runetotem"] = {scope="overview-body",sourceHash="055811",hash="b38bc5",name="Турак Рунтотем",summary="Турак Рунтотем — шанований тауренський наставник друїдів, що живе в Залі Старійшин на Узвишші Старійшин у Тандер Блафі. Як довірений помічник Верховного Друїда Гамуула Рунтотема, він веде молодих тауренів священними шляхами природи й рівноваги. Під його проводом юні друїди проходять перші випробування, щоб єднатися з духами й опанувати звірині подоби.",section="У спокійних стінах Зали Старійшин Турак Рунтотем — один із провідних наставників друїдів в Орді. Відомий глибоким терпінням і врівноваженою вдачею, він допомагає Верховному Друїду Гамуулу Рунтотему відроджувати серед тауренів давні друїдські мистецтва. Турак дбає, щоб кожен молодий друїд шанував волю Земної Матері, і вчить, що фізична сила завжди мусить спиратися на духовну шану й гармонію з природою.",sectionIndex=1}
c["npc:twilight-lord-kelris"] = "dce71a"
P.scopedClips["npc:twilight-lord-kelris"] = {scope="overview-body",sourceHash="3947e3",hash="dce71a",name="Сутінковий Володар Келріс",summary="Сутінковий Володар Келріс — орк-чорнокнижник і високий ватажок культу Молота Присмерку, що діє глибоко в Чорноглибинних Печерах. Зі свого місця у Святилищі Місячної Святині він керує темними ритуалами й доглядає первісну гідру Аку'май, прагнучи принести у світ царство космічного хаосу.",section="Сутінковий Володар Келріс керує культистами Молота Присмерку, які захопили затонулі руїни Чорноглибинних Печер. Роками Келріс вислизав з-під пильного ока Дарнасуса, ухилявся від Срібного світанку й здобув похмуру славу: щойно десь на Калімдорі заворушувалося давнє зло, підозра падала на Келріса. Цей орк не служить ні воєначальникам, ні кланам — він цілком віддав себе Древнім Богам, прагнучи зруйнувати цивілізацію смертних і повернути Азерот до стану цілковитого первісного хаосу.",sectionIndex=1}
c["npc:tyrande-whisperwind"] = "b85a86"
P.scopedClips["npc:tyrande-whisperwind"] = {scope="overview-body",sourceHash="fe5734",hash="b85a86",name="Тіранда Віспервінд",summary="Тіранда Віспервінд — Верховна Жриця Елуни й найвища провідниця нічних ельфів. Разом зі своїм коханим, Архідруїдом Малфуріоном Стормрейджем, вона провела свій народ крізь нищівну Війну Прадавніх і десять тисячоліть Довгої Варти. Нині вона править зі священних віт Тельдрассила, очолює Сестринство Елуни й командує військом Вартових, що боронять священну дику природу Калімдору.",section="Тіранда народилася в давньому місті Сурамар і зростала разом із братами-близнюками Малфуріоном та Ілліданом Стормрейджами. Брати обрали друїдство й чародійство, а Тіранда вступила до сестринства Елуни послушницею. Коли під час Війни Прадавніх демонічний Палаючий Легіон уперше вдерся в Азерот, смертельно поранена Верховна Жриця Деджана обрала Тіранду своєю наступницею. Благословенна прямою ласкою Місячної Богині, Тіранда перетворила Сестринство на сяйливу бойову силу, що володіла і божественним зціленням, і палючим місячним гнівом, і вберегла свій народ на краю цілковитої загибелі.",sectionIndex=1}
c["npc:varimathras"] = "c65435"
P.scopedClips["npc:varimathras"] = {scope="overview-body",sourceHash="3810c0",hash="c65435",name="Варіматрас",summary="Варіматрас — жахолорд з раси натрезимів, головний поплічник і військовий радник Леді Сильвани Віндраннер. Зазнавши поразки в громадянській війні за Лордерон, він був змушений присягнути на вірність Королеві Баньші й тепер стоїть по праву руку від неї в Королівському Кварталі Андерсіті.",section="До Третьої війни Варіматрас та інші жахолорди працювали безпосередньо під началом Кіл'джедена, щоб зламати дух Нер'жула й перекувати його на Короля-Ліча. Разом зі своїми братами Детероком і Балназзаром він наглядав за Погибеллю в Лордероні, поки Архімонд вторгався в Калімдор. Коли Легіон зазнав поразки біля Гори Гіджал, тріумвірат лишався в руїнах Столиці Лордерона, нічого не знаючи про загибель свого господаря, аж поки принц Артас не повернувся й не змусив їх сховатися.",sectionIndex=1}
c["npc:verdan-the-everliving"] = "28b92e"
P.scopedClips["npc:verdan-the-everliving"] = {scope="overview-body",sourceHash="c130a6",hash="28b92e",name="Вердан Вічноживий",summary="Вердан Вічноживий — велетенський болотяний звір, що чатує глибоко в зелених тунелях Печер Стогонів. Колись він мирно оберігав підземні джерела й рослини, але його спотворило жахіття наяву, що струменіло від сплячого друїда Наралекса. Тепер Вердан служить зіпсованим Друїдам Ікла й люто нападає на всіх, хто забреде в його вологі нори.",section="Задовго до того, як Наралекс прийшов сюди, щоб дістатися природних джерел Пусток, Вердан постав із буйного листя, мулу й вологи, що наповнювали печери. Його вважають споконвічним духом-охоронцем підземної оази: це був прадавній лагідний елементаль, що доглядав підземні рослини.",sectionIndex=1}
c["npc:verner-osgood"] = "4476e2"
P.scopedClips["npc:verner-osgood"] = {scope="overview-body",sourceHash="5cf679",hash="4476e2",name="Вернер Осґуд",summary="Вернер Осґуд — коваль Лейкшира, що працює просто біля міської кузні. Розриваючись між замовленнями місцевих жителів і нищівними вимогами військових Стормвінда, він невтомно працює, щоб коні були підковані, а захисники — озброєні, попри безупинні набіги гнолів.",section="Стоячи біля горна в центрі Лейкшира, Вернер Осґуд уособлює надірвану ремісничу основу Гір Редріджу. Його справа — найпростіше спорядження, як-от підкови для місцевих коней, та його запаси раз у раз забирають, щоб кувати зброю й обладунки для Вартових Стормвінда. Королівство розтягує свої кордони, місцевим гарнізонам бракує припасів, тож незалежні ковалі на кшталт Вернера змушені нести на своїх плечах тягар забезпечення оборони краю.",sectionIndex=1}
c["npc:viktori-prism-antras"] = "f05e24"
P.scopedClips["npc:viktori-prism-antras"] = {scope="overview-body",sourceHash="47bdc4",hash="f05e24",name="Вікторі Призм'Антрас",summary="Вікторі Призм'Антрас — дивакуватий звіздар, що живе в маленькій хатині на схилі над Даркширом. Поки місто довкола поринає в страх і чекання нових жахів, Вікторі всією душею віддається будівництву телескопа, щоб ясно бачити небо. Аби втілити свою мрію, він покладається на відважних мандрівників, які добувають складні деталі за гномськими кресленнями.",section="Оселившись на схилі одразу за сідалом грифонів, Вікторі Призм'Антрас цілими днями вдивляється вдалину з мороку Сутінколісся. Серед набігів нежиті, ненажерливих павуків і повзучих тіней його пристрасть лежить далеко за задушливими кронами. Він мріє збудувати чудовий оптичний телескоп, який чітко наблизить зорі й подарує тиху втечу від страху, що поглинає містечко.",sectionIndex=1}
c["npc:viscous-fallout"] = "5b841f"
P.scopedClips["npc:viscous-fallout"] = {scope="overview-body",sourceHash="c2d821",hash="5b841f",name="В'язкий Осад",summary="В'язкий Осад — осквернений водяний елементаль, що блукає опроміненими коридорами Гномреґана. Колись чистий дух, що жив у прозорих підземних водах міста, він перетворився на отруйну потвору через згубний радіоактивний викид, який влаштував Мехінженер Термаплаґ.",section="До падіння Гномреґана столиця гномів покладалася на складні, витончені водні системи й чисті підземні водоносні шари, які живили й рухали її механічні дива. У цих чистих водах мирно жив самотній водяний елементаль. Коли за підступною порадою Мехінженера Термаплаґа відкрили радіаційні клапани, щоб знищити трогів-загарбників, хімічне зараження просочилося глибоко в міські резервуари, затиснуло елементаля в пастку й зіпсувало саму його суть.",sectionIndex=1}
c["npc:vol-jin"] = "6139e2"
P.scopedClips["npc:vol-jin"] = {scope="overview-body",sourceHash="7b0a24",hash="6139e2",name="Вол'джин",summary="Вол'джин — вождь тролів Темного Списа і майстерний мисливець тіней. Мешкаючи у Фортеці Ґроммаш поруч із Вождем Траллом, він є довіреним радником Орди й водночас працює над тим, щоб забезпечити своєму вигнаному народові постійний дім у Дуротарі.",section="Вол'джин очолив плем'я Темного Списа після трагічної смерті свого батька Сен'джина на прадавньому острівному домі племені. Коли мурлоки, що поклонялися морській відьмі, та людські війська ледь не знищили відлюдне плем'я, втрутилися орки Тралла, і між двома народами зав'язався міцний зв'язок. Залишивши руїни своїх островів, Вол'джин присягнув своїми тролями Новій Орді й повів їх через Велике Море на Калімдор.",sectionIndex=1}
c["npc:warden-thelwater"] = "b4a65f"
P.scopedClips["npc:warden-thelwater"] = {scope="overview-body",sourceHash="1d7721",hash="b4a65f",name="Наглядач Телвотер",summary="Наглядач Телвотер — обложений начальник В'язниці, підземного каземату суворого режиму в Стормвінді. Заскочений зненацька, коли серед в'язнів Дефіас спалахнув жорстокий бунт, він тепер відчайдушно наймає вправних шукачів пригод, щоб придушити заколот, доки чутки не дісталися міста нагорі.",section="Захована під каналами Стормвінда, В'язниця тримає найнебезпечніших покидьків королівства, дрібних злодіїв і політичних змовників. Наглядачеві Телвотеру доручили тримати їх під надійним замком, але організований бунт застав вартових цілком зненацька. В'язні подолали охорону й захопили камери, і Телвотер опинився забарикадованим біля самого входу, ледве стримуючи збройний заколот просто під вулицями столиці.",sectionIndex=1}
c["npc:william-pestle"] = "c8351b"
P.scopedClips["npc:william-pestle"] = {scope="overview-body",sourceHash="163da4",hash="c8351b",name="Вільям Пестл",summary="Вільям Пестл — алхімік з людей, що зупинився в корчмі «Лев'яча Гордість» у Ґолдширі. Разом із братом Морґаном він тримає аптеку в Торговому Кварталі Стормвінда. Він часто наймає мандрівних шукачів пригод збирати дивні реагенти — свічки кобольдів, водорості мурлоків і трави.",section="Поки його брат Морґан Пестл стоїть за прилавком аптеки Пестлів у Торговому Кварталі Стормвінда, Вільям працює з корчми «Лев'яча Гордість» у Ґолдширі. Перебування в Лісі Елвінн дозволяє йому тісно співпрацювати з місцевими збирачами й добувати сировину, якої повсякчас потребують міські крамниці. Він регулярно відправляє вантажі до столиці, щоб мешканці Стормвінда мали сталий доступ до цілющих мазей, настоянок і порошків.",sectionIndex=1}
c["npc:wizbang-cranktoggle"] = "e58780"
P.scopedClips["npc:wizbang-cranktoggle"] = {scope="overview-body",sourceHash="d3e8bc",hash="e58780",name="Візбанґ Кранктоґґл",summary="Візбанґ Кранктоґґл — ексцентричний гном-інженер, що живе на верхньому поверсі корчми в Обердайні. Попри те, що він далеко від повних зубчастих коліс залів Гномреґана чи Айронфорджа, він спрямував свою механічну винахідливість на встановлення й обслуговування автоматичних пристроїв зв'язку — дзижчалок — по всьому дикому Темному Узбережжю.",section="Нічні ельфи Обердайна воліють жити в злагоді з природою й триматися давніх звичаїв, а Візбанґ Кранктоґґл уособлює допитливу, майструвальну присутність Альянсу. Влаштувавшись на горішньому поверсі корчми Обердайна серед інструментів і запчастин, Візбанґ мало зважає на урочисті друїдські традиції Калімдору й зосереджується на практичних механічних задачах.",sectionIndex=1}
c["npc:yaw-sharpmane"] = "3b79db"
P.scopedClips["npc:yaw-sharpmane"] = {scope="overview-body",sourceHash="38daea",hash="3b79db",name="Яв Шарпмейн",summary="Яв Шарпмейн — досвідчений тауренський наставник мисливців у Селі Бладгуф у Малгорі. Він веде молодих мисливців, що виходять із Табору Нарачі, й допомагає їм опанувати диких звірів прабатьківських рівнин.",section="Серед наметів і вогнищ Села Бладгуф Яв Шарпмейн служить Шу'хало як наставник у влучній стрільбі, вистежуванні та виживанні. Молодих мисливців, які довели свою вправність на Плато Червоної Хмари, посилають до Ява відточувати ремесло, щойно вони ступають на широкі рівнини Малгору.",sectionIndex=1}
c["subzone:addle-s-stead"] = "5f603b"
P.scopedClips["subzone:addle-s-stead"] = {scope="overview-body",sourceHash="98d145",hash="5f603b",name="Хутір Аддла",summary="Хутір Аддла — покинута садиба на південному заході Сутінколісся, що тихо лежить у лісовому мороці на південь від Воронячого Пагорба. Перші господарі давно втекли, а хутір став потаємним плацдармом Братства Дефіас.",section="Як і багато забутих садиб, розкиданих Сутінколіссям, Хутір Аддла занепав, коли край огорнули темрява й руїна. Проте порожнім він не лишився: його прибрало до рук Братство Дефіас. Агенти патрулюють околиці, причаюються в напіврозваленій хаті й ховають припаси в стодолі, користуючись тінистим прикриттям південно-західного Сутінколісся, щоб не потрапити на очі ні Нічній Варті, ні владі Стормвінда.",sectionIndex=1}
c["subzone:agama-gor"] = "99b1bd"
P.scopedClips["subzone:agama-gor"] = {scope="overview-body",sourceHash="78b644",hash="99b1bd",name="Аґама'ґор",summary="Аґама'ґор — велике стійбище шипогривів Щетиноспинів на півдні Пусток, трохи на північ від дороги, що веде від Табору Тауражо на захід до Малгору. Це постійна скалка в боці сусідньої застави Орди: тут кишать ворожі шипогриви, які затято тримаються за свою сувору землю.",section="Аґама'ґор, що розкинувся на курних рівнинах південних Пусток, — укріплене поселення агресивного племені шипогривів Щетиноспинів. Шипогриви, що живуть небезпечно близько від Табору Тауражо, звели тут густу мережу терновиків, хиж і грубих тотемів. Їхня численність становить пряму загрозу для мандрівників між Пустками й трав'янистими пагорбами Малгору, тож розвідники й мисливці Орди ведуть проти них безупинну війну, щоб їх стримати.",sectionIndex=1}
c["subzone:agamand-family-crypt"] = "e23d1e"
P.scopedClips["subzone:agamand-family-crypt"] = {scope="overview-body",sourceHash="51ae02",hash="e23d1e",name="Родинний Склеп Аґамандів",summary="Родинний Склеп Аґамандів, схований у пагорбах одразу на північ від Млинів Аґаманда, — давнє місце спочинку однієї з найзаможніших фермерських династій Тірісфалю. Тепер його захопила Погибель під проводом Капітана Дарґола: гробниці розкрито, а сплячих предків піднято безтямними страхіттями.",section="До Третьої війни родина Аґамандів володіла великими маєтками по північних Галявинах Тірісфалю й ховала своїх предків у цьому мавзолеї на схилі пагорба. Коли Чума принесла королівству руїну, склеп потрапив у лабети Капітана Дарґола, агента Погибелі. Замість дати заможному роду спочивати з миром, Дарґол темною некромантією пробудив поховані скелети й мстиві привиди, перетворивши священне поховання на войовничий плацдарм Погибелі просто на краю земель Відступників.",sectionIndex=1}
c["subzone:agamand-mills"] = "56bfb9"
P.scopedClips["subzone:agamand-mills"] = {scope="overview-body",sourceHash="d5d598",hash="56bfb9",name="Млини Аґаманда",summary="Млини Аґаманда — розлогий комплекс ферм і вітряків на північних висотах Галявин Тірісфалю. Колись гордий маєток заможної династії Аґамандів, він занепав і став найбільшою твердинею Погибелі в краї.",section="Століття тому заможні дворяни-переселенці зі Строму заснували маєток Аґамандів і збудували розгалужену мережу млинів по північному Тірісфалю. Коли спалахнула Третя війна й Погибель прокотилася Лордероном, патріарх Ґреґор Аґаманд відмовився тікати: він укріпив садибу й переконав челядь і робітників стати на бій. Їхні припаси й кам'яні стіни могли б вистояти, та наймолодший син, Девлін Аґаманд, зрадив свою кров. Девлін перебив вартових маєтку й упустив ходячих мерців до спалень. Підкошені зсередини, решта захисників були винищені, а родина поповнила безтямні лави нежиті.",sectionIndex=1}
c["subzone:aldrassil"] = "18111c"
P.scopedClips["subzone:aldrassil"] = {scope="overview-body",sourceHash="5dbacd",hash="18111c",name="Алдрассил",summary="Алдрассил — велетенське дерево-оселя й поселення в серці Тінедолу на північному сході Тельдрассила. Головний прихисток і місце навчання молодих калдореїв; у його вирізьблених порожнинах знайшли притулок наставники, крамарі та місцеве керівництво.",section="Здіймаючись над відлюдною долиною Тінедолу, Алдрассил — водночас прихисток і громадський осередок для молодих нічних ельфів, що роблять перші кроки у світі. Усередині й довкола велетенського стовбура цього прадавнього дерева в'ються пандуси, що ведуть повз наставників класів і ремісників до високого сідала, звідки Тенарон Стормґріп наглядає за безпекою гаю. Поки Світове Дерево Тельдрассил тягнеться через увесь обрій, Алдрассил дає безпечну, надійну крону, де новачки опановують своє мистецтво, перш ніж спуститися в неспокійні хащі Калімдору.",sectionIndex=1}
c["subzone:alexston-farmstead"] = "b91db8"
P.scopedClips["subzone:alexston-farmstead"] = {scope="overview-body",sourceHash="a2aa28",hash="b91db8",name="Хутір Алекстона",summary="Хутір Алекстона — занедбана ферма у Вестфолі, що заросла бур'янами й де никають зіпсовані Вартові Урожаю. Колись тут минуло дитинство міського архітектора Стормвінда Бароса Алекстона, а тепер хутір лежить у руїні, як і більшість житниці довкола.",section="Хутір Алекстона, що стоїть серед сухих рівнин Вестфолу, — ще одне похмуре свідчення занедбаності королівства. Як і сусідні садиби, ферму покинули господарі, коли краєм прокотився розбій. Нині поля заросли, а механічні Вартові Урожаю, яких лишили доглядати посіви, вийшли з-під контролю й люто нападають на кожного, хто наближається до спустілої хати.",sectionIndex=1}
c["subzone:algaz-station"] = "fdea6d"
P.scopedClips["subzone:algaz-station"] = {scope="overview-body",sourceHash="920289",hash="fdea6d",name="Станція Алґаз",summary="Станція Алґаз — дворфійська військова застава на північному заході Лох Модану, просто на південь від укріпленого перевалу Дун Алґаз. Її гарнізон горян стереже підступи до північних тунелів, охороняє мандрівників і пильнує прикордоння в бік Багнокраю.",section="Станція Алґаз, що стоїть трохи на схід від Перевалу Північної Брами й на південь від Дун Алґаза, — важливий стратегічний дозорний пункт королівства Айронфорджа. Загін дворфійських горян несе тут постійну варту, тримаючи відкритою важливу дорогу між Лох Моданом і північними низинами для торгівлі й пересування військ. Зважаючи на часті загрози з довколишніх пагорбів — від мандрівних звірів до трогів, що наступають, — застава дає втомленим мандрівникам перепочинок, змогу полагодити спорядження й військову підтримку, перш ніж вони вирушать гірськими тунелями.",sectionIndex=1}
c["subzone:alterac-mountains"] = "b4f1fc"
P.scopedClips["subzone:alterac-mountains"] = {scope="overview-body",sourceHash="a9a4f5",hash="b4f1fc",name="Гори Альтерак",summary="Гори Альтерак — порізаний, засніжений хребет, що здіймається просто над пологими пасовищами Гілсбреда. Колись серце гордого людського королівства, тепер на їхніх схилах — зруйновані поселення, розбійницькі угруповання й небезпечна дика місцина, де мандрівники рідко ходять без охорони.",section="Задовго до того, як пагорби поринули в хаос, це нагір'я було суверенним королівством Альтерак — одним із семи королівств, що постали з давнього Аратора. Ця спадщина розбилася під час Другої війни, коли король Ейден Перенольд уклав таємну угоду зі Старою Ордою, дозволивши оркам пройти крізь гори в обмін на безпеку свого королівства. Альянс Лордерона викрив зраду й скинув Перенольда, залишивши край розколотим воєнним станом і суперечками за землю.",sectionIndex=1}
c["subzone:alther-s-mill"] = "f0f573"
P.scopedClips["subzone:alther-s-mill"] = {scope="overview-body",sourceHash="6704f0",hash="f0f573",name="Млин Альтера",summary="Млин Альтера — зруйнована лісопильня серед скелястих пагорбів на північний схід від Лейкшира в Горах Редріджу. Колись важливе джерело обробленої деревини для місцевих будівничих, покинуте обійстя стало притулком для диких стерв'ятників і хижаків. Для шукачів пригод, що прямують на схід до Кам'яної Варти, напіврозвалені будівлі — похмурий орієнтир, що позначає межу безпечних прикордонних земель.",section="Доки край не став здобиччю хижаків і орочих набігів, Млин Альтера вирував торгівлею деревиною, з якої будували Лейкшир і навколишні поселення. Тиха галявина на північний схід від Озера Незрушного давала зручний доступ до гірських лісів. Коли смута в Королівстві Стормвінд наростала, а клан Блекрок насунув із висот Кам'яної Варти, місцеві мельники покинули лісопильню, і сухі дерев'яні будівлі разом із колесом почали гнити.",sectionIndex=1}
c["subzone:amberstill-ranch"] = "f8b328"
P.scopedClips["subzone:amberstill-ranch"] = {scope="overview-body",sourceHash="26b941",hash="f8b328",name="Ранчо Амберстілл",summary="Ранчо Амберстілл — тиха дворфська садиба при засніженій дорозі на Лох Модан, просто на північ від Кар'єру Гол'Болар. Це головне місце, де розводять і тренують славетних гірських баранів Айронфорджа. Шукачі пригод навідуються сюди, щоб придбати витривалого дворфського скакуна, навчитися верхової їзди або допомогти родині захистити худобу від місцевих хижаків.",section="Притулившись до скель Дун Мороґу, Ранчо Амберстілл славиться на весь Каз Модан найвитривалішими гірськими баранами Східних Королівств. Родина Амберстіллів порядкує в стайнях і загонах, навчаючи цих твердоногих тварин долати підступні снігові перевали й круті альпійські урвища. Окрім постачання їздових скакунів і свійської худоби, родині часто доводиться відбиватися від дикої звірини пагорбів — особливо від вендіго, яких приваблює запах свіжої отари.",sectionIndex=1}
c["subzone:ameth-aran"] = "f00676"
P.scopedClips["subzone:ameth-aran"] = {scope="overview-body",sourceHash="de5ea0",hash="f00676",name="Амет'Аран",summary="Амет'Аран — давні руїни на півдні Темного Узбережжя, колись квітуче місто, де Високородні королеви Азшари віддавалися таємному чаклунству. Коли Великий Розкол зруйнував давній світ, місто впало разом із ним. Сьогодні його поламаними колонадами блукають мстиві привиди ельфів, що загинули тут.",section="До Великого Розколу Амет'Аран і його місто-сестра Башал'Аран були двома осередками влади Високородних на давньому узбережжі. Тішачись прихильністю королеви Азшари, місто славилося гамірними базарами й витонченими святилищами Елуни, хоча його знать присвятила себе нестримним таємним експериментам. Містом здалеку, з Вежі Альталакса, правив чаклун Атрікус Нарассін, і воно процвітало, доки катастрофічний обвал Колодязя Вічності не розірвав Імперію калдореїв на шматки.",sectionIndex=1}
c["subzone:angerfang-encampment"] = "cc1601"
P.scopedClips["subzone:angerfang-encampment"] = {scope="overview-body",sourceHash="c4ef6a",hash="cc1601",name="Табір Анґерфанґ",summary="Табір Анґерфанґ — головна твердиня клану Драконячої Пащі в центрі Багнокраю. Ці орки-ренегати на чолі з Вождем Нек'рошем Скаллкрашером використовують розлогий табір як плацдарм, щоб загрожувати сусіднім дворфійським поселенням і плести задуми знищення Гавані Менетіл.",section="Табір Анґерфанґ, що розкинувся в багнюці центрального Багнокраю, — укріплене серце влади Драконячої Пащі в цьому краї. На відміну від розпорошених загонів, що никають болотами, тут є добре захищені барикади, сторожові вежі й грізне військо воїнів, кісткових вартових і темних чаклунів, вірних старим звичаям. Звідси Драконяча Паща простягає свою військову силу на всі болота, нападає на мандрівників на дорогах і загрожує довколишнім дворфійським розкопкам, як-от Місцю Розкопок Велґара.",sectionIndex=1}
c["subzone:anvilmar"] = "bae145"
P.scopedClips["subzone:anvilmar"] = {scope="overview-body",sourceHash="6e2f0d",hash="bae145",name="Анвілмар",summary="Анвілмар — укріплена дворфська застава в засніжених глибинах Долини Холодного Хребта в Дун Мороґу. Збудована довкола величезної кам'яної кузні, вона є головним тренувальним майданчиком і місцем збору молодих дворфів Бронзбірдів та гномських біженців, що починають свої пригоди.",section="Схований серед північних скель Долини Холодного Хребта, Анвілмар стоїть як незмінний символ дворфської стійкості. Над цим міцним кам'яним комплексом панує ревуча центральна кузня, а всередині знайшли місце наставники класів, торговці припасами та бувалі горяни, які муштрують новобранців, перш ніж відіслати їх у ширше королівство. Хоч поселення й сховане за високими заметами, воно постійно насторожі проти ворожих тролів Морозогривів та лютих диких звірів, що нишпорять замерзлою долиною.",sectionIndex=1}
c["subzone:apothecarium"] = "02fa61"
P.scopedClips["subzone:apothecarium"] = {scope="overview-body",sourceHash="143fc0",hash="02fa61",name="Апотекаріум",summary="Апотекаріум — південно-західний квартал Андерсіті й осідок Королівського Аптекарського Товариства. У його смердючих лабораторіях алхіміки-Відступники невтомно працюють під проводом Головного Аптекаря Фаранелла, створюючи згубні чуми, отрути й штучно виведені жахіття. Це похмуре серце біологічних досліджень Андерсіті, без якого не обійтися в боротьбі Леді Сильвани проти живих і Погибелі.",section="Апотекаріум займає південно-західну терасу підземної столиці — це лабіринт булькотливих чанів, секційних столів і їдких хімічних випарів. Під проводом Головного Аптекаря Фаранелла Королівське Аптекарське Товариство використовує цей квартал, щоб глибше пізнати смертність і тлін. Тут алхіміки й хірурги експериментують із пересадкою тканин, розтинами живих і складанням могутніх гидот. Їхня найголовніша мета, визначена Леді Сильваною Віндраннер, — створити нову чуму, здатну знищити і Погибель, і рештки людей у Лордероні.",sectionIndex=1}
c["subzone:astranaar"] = "8cac9c"
P.scopedClips["subzone:astranaar"] = {scope="overview-body",sourceHash="8c57a1",hash="8cac9c",name="Астранаар",summary="Астранаар — головне поселення нічних ельфів у центральному Ашенвалі, збудоване на острові посеред спокійного озера, яке перетинає давня лісова дорога. Це серце діяльності Альянсу в краї: тут мандрівники знаходять надійний притулок від ворожих фурболгів, сатирів та Орди.",section="Астранаар, що стоїть на острові посеред лісового озера, — найбільше поселення нічних ельфів в Ашенвалі. З берегом його з'єднують дерев'яні кладки над водою, а в місті живуть вартові, жерці й ремісники, які пильнують ліси. Окрім звичних вигод — корчми, крамарів і вправного шкірника, — на його високих помостах є приборкувач гіпогрифів, з яким можна полетіти до далеких застав Калімдору.",sectionIndex=1}
c["subzone:auberdine"] = "066b50"
P.scopedClips["subzone:auberdine"] = {scope="overview-body",sourceHash="9b0ecc",hash="066b50",name="Обердайн",summary="Обердайн — приморське портове містечко нічних ельфів на похмурих берегах Темного Узбережжя, головна морська брама Альянсу до північного Калімдору. Сховане під хмарним небом і порослими соснами кручами, воно з'єднує острівну домівку на Тельдрассилі зі Східними Королівствами й слугує осередком влади серед дикого краю, що наступає.",section="Обердайн, що лежить на березі Прихованого Моря, — єдине велике поселення, яке встояло на нинішньому Темному Узбережжі. На відміну від відлюдних міст у кронах Тельдрассилу, Обердайн дивиться назовні: це найжвавіший порт Альянсу на півночі. Звідси регулярно ходять кораблі до Гавані Менетіл у Східних Королівствах, а місцеві пороми курсують до Селища Рут'теран біля коріння Світового Дерева. Завдяки торгівлі в Обердайні панує розмаїтіший дух, ніж у традиційних ельфійських анклавах: гості бачать ліхтарі над брукованими вулицями, вивіски дарнаською й всезагальною мовами та заморських купців, серед них дворфів і гномів, що походжають між низькими дерев'яними будинками з арками.",sectionIndex=1}
c["subzone:azurelode-mine"] = "149a4f"
P.scopedClips["subzone:azurelode-mine"] = {scope="overview-body",sourceHash="04e416",hash="149a4f",name="Шахта Лазурової Жили",summary="Шахта Лазурової Жили — діюча залізна копальня Альянсу в південно-західних пагорбах Передгір'я Гілсбреда. Її охороняє ополчення Саутшора, а працюють тут люди-робітники; надійний видобуток руди живить воєнні зусилля місцевих людей проти Відступників Таррен Мілла.",section="Шахта Лазурової Жили, що лежить на південний захід від відкритих полів і трохи на захід від Саутшора, здавна видобуває багатства з рудних кряжів уздовж узбережжя. До того як запечатали Стіну Ґреймейна, ці пагорби вважалися частиною земель Ґілнеаса. Сьогодні люди-рудокопи працюють глибоко під землею під пильним оком Наглядача Бондса, добуваючи залізо, щоб кувати зброю й обладунки для захисників Альянсу, які тримають край проти Андерсіті.",sectionIndex=1}
c["subzone:bael-dun-digsite"] = "bae24e"
P.scopedClips["subzone:bael-dun-digsite"] = {scope="overview-body",sourceHash="b6134f",hash="bae24e",name="Розкопки Бел'дуну",summary="Розкопки Бел'дуну — дворфійська копальня, вирубана глибоко в горах уздовж західного краю Малгору. Закладена загоном Шукача Хазґорма з Бель Модану, вона в очах місцевих тауренів — пряме осквернення прабатьківської землі й образа Земній Матері.",section="Розкопки Бел'дуну, що примостилися на гірських схилах західного Малгору, — найпівденніший форпост експедиції дворфійської Ліги Дослідників, яка базується в Бель Модані в південних Пустках. Не зважаючи ні на кордони, ні на духовні традиції щойно осілих племен, дворфійські шукачі прибули з кирками, лопатами й вибуховим порохом, аби видобути стародавні реліквії титанів, поховані під рівнинами.",sectionIndex=1}
c["subzone:bael-dun-keep"] = "4f6de2"
P.scopedClips["subzone:bael-dun-keep"] = {scope="overview-body",sourceHash="a50fc4",hash="4f6de2",name="Фортеця Бел'дун",summary="Фортеця Бел'дун — грізне дворфійське укріплення над розкопками Бель Модан на півдні Пусток. Під командуванням Генерала Твінбрейда ця фортеця тримає суперечливу присутність Альянсу в краї і втягує його в запеклий конфлікт із довколишніми землями Орди.",section="Фортеця Бел'дун, збудована за кресленнями дворфійського архітектора Гаґґіса Боутмердера, — укріплене військове серце присутності Айронфорджа на півдні Пусток. Височіючи над широкими траншеями розкопок Бель Модана, вона захищає шукачів і археологів, які розшукують давні артефакти титанів. Гарнізон, добре озброєний залізом і гарматами, пильно стереже дворфійські шляхи постачання й демонструє військову силу Альянсу в самому серці Калімдору.",sectionIndex=1}
c["subzone:bael-modan"] = "25dac3"
P.scopedClips["subzone:bael-modan"] = {scope="overview-body",sourceHash="bf6c25",hash="25dac3",name="Бель Модан",summary="Бель Модан — укріплена дворфійська застава й місце археологічних розкопок на півдні Пусток. Її заснували дворфи-копачі, що шукають давні реліквії Титанів, і ця добре озброєна споруда розпалила запеклий конфлікт, вигнавши корінних тауренів Стоунспайр.",section="Бель Модан — це укріплена Фортеця Бел'дун, ряд велетенських облогових гармат, майданчики для гірокоптерів і глибокий відкритий котлован. Дворфи-шукачі прибули на Калімдор, переконані, що під червоною землею похована давня споруда Титанів. Проте їхні вибухові роботи прорвалися просто крізь священну землю тауренів Стоунспайр. Замість домовлятися, дворфійська експедиція прогнала Стоунспайрів з прадавніх земель рушничним вогнем і вибухівкою, і вцілілі одноплемінники розсіялися, сповнені жаги помсти.",sectionIndex=1}
c["subzone:balnir-farmstead"] = "156a92"
P.scopedClips["subzone:balnir-farmstead"] = {scope="overview-body",sourceHash="cb54ca",hash="156a92",name="Хутір Балнірів",summary="Хутір Балнірів — занедбаний маєток у східних Галявинах Тірісфалю, на північний схід від Руїн Лордерона. Колись славний розведенням знаменитих білих коней, яких любила королівська родина Лордерона, тепер він лежить у руїнах, заполонений блукаючою Погибеллю. Сьогодні маєток — сумний пам'ятник ранньому життю принца Артаса Менетіла й місце, де той здобув свого скакуна-нежить.",section="Поколіннями родина Балнірів розводила легендарних білих жеребців Лордерона на своїй садибі серед хвилястих пагорбів Тірісфалю. Хлопчиком принц Артас Менетіл часто навідувався на ферму, тікаючи від придворного життя, і заприятелював із молодим Джарімом Балніром. Саме тут Артас допоміг прийняти лоша, яке назвав Інвінсіблом. Через роки, коли трагічний нещасний випадок під час верхової їзди обірвав життя скакуна, Інвінсібла на особисте прохання Артаса поховали в землі хутора.",sectionIndex=1}
c["subzone:ban-ethil-barrow-den"] = "f645a1"
P.scopedClips["subzone:ban-ethil-barrow-den"] = {scope="overview-body",sourceHash="2b3d1d",hash="f645a1",name="Курганне Лігво Бан'етіл",summary="Курганне Лігво Бан'етіл — священне підземне святилище, видовбане в корінні Тельдрассила. Створене як місце спочинку для сплячих Друїдів Кігтя, печерний комплекс нещодавно поринув у хаос. Зіпсуті фурболги племені Вузлошкірів заполонили його зали, перетворивши місце мирного сну на небезпечне лігво божевілля.",section="Курганні лігва — священні покої спочинку, де друїди нічних ельфів сплять, посилаючи свій дух у Смарагдовий Сон. Курганне Лігво Бан'етіл було призначене саме для Друїдів Кігтя, що єднаються з природою. Поділене на верхні й нижні підземні покої, лігво колись бриніло тихою задумою й глибокою магією медитації. Та недуга, що охопила живність Тельдрассила, не оминула й фурболгів-Вузлошкірів: вони вдерлися до комплексу й перетворили його видовбані зали на укріплене кубло.",sectionIndex=1}
c["subzone:ban-ethil-hollow"] = "8f0ca1"
P.scopedClips["subzone:ban-ethil-hollow"] = {scope="overview-body",sourceHash="3cd1b7",hash="8f0ca1",name="Лощина Бан'етіл",summary="Лощина Бан'етіл — скелястий яр, що врізається в ліс одразу на південь від головної дороги між Доланааром і Дарнасусом. Вона стала небезпечним прихистком для зіпсутих, агресивних фурболгів, які постійно загрожують подорожнім. У глибині яру ховається вхід до Курганного Лігва Бан'етіл.",section="Лощина Бан'етіл, що лежить осторонь шляху між Доланааром і Дарнасусом, — різке нагадування, що гілля Тельдрассила не зовсім безпечне. Фурболги, збожеволілі від дивної недуги, яка мучить Світове Дерево, знайшли притулок по всьому скелястому спуску. Вони часто чатують біля стежки, вичікуючи необачних гінців і мандрівних вартових, щоб напасти із засідки. У глибині яру — поріг Курганного Лігва Бан'етіл, де сплячі друїди й давні тунелі потерпають від навали знавіснілих звірів іззовні.",sectionIndex=1}
c["subzone:bandarion-keep"] = "a0fa56"
P.scopedClips["subzone:bandarion-keep"] = {scope="overview-body",sourceHash="82be31",hash="a0fa56",name="Фортеця Бандаріон",summary="Фортеця Бандаріон — укріплений редут, пов'язаний із Вартою Тіра, у західних закутках Галявин Тірісфалю біля Шепітливого Лісу. Названа на честь Ґарека Бандаріона, застава править за відособлений оплот серед загроз, що не зникають уздовж лісового прикордоння. Її захисники мають справу з усім — від ворожих прибережних мурлоків до мандрівних фанатиків і неврівноваженої нежиті.",section="Фортеця Бандаріон біля відлюдного Шепітливого Лісу в західних Галявинах Тірісфалю — самотній вартовий Відступників. Названа на честь Ґарека Бандаріона, ця твердиня тісно пов'язана з Вартою Тіра. Інтенданти на кшталт Джоріна Кроджа старанно постачають гарнізон попри віддалене й важке становище далеко від людних дворів Андерсіті.",sectionIndex=1}
c["subzone:baradin-bay"] = "4d965e"
P.scopedClips["subzone:baradin-bay"] = {scope="overview-body",sourceHash="fe98ce",hash="4d965e",name="Затока Барадін",summary="Затока Барадін — розлога водойма між берегами Каз Модану, Багнокраю, Аратійського нагір'я та південного Лордерону. Під час Другої війни її пильно патрулював могутній флот Кул Тіраса, а нині в її водах ховаються підступні рифи, затонулі бойові кораблі й ворожі морські хижаки.",section="Затока Барадін, яку обрамлюють береги Дун Мороґа на півдні та Лордерону на півночі, — важливий морський шлях, що з'єднує гавані Східних Королівств. Її опорою є жваві порти — Гавань Менетіл у Багнокраї та Саутшор у Передгір'ї Гілсбреда. Та плавати цими водами небезпечно: мілкі піщані коси, зубчасті мілини й небезпечні мешканці — мурлоки, кроколіски й глибоководні акули — повсякчас загрожують і морякам, і мандрівникам.",sectionIndex=1}
c["subzone:bashal-aran"] = "22d600"
P.scopedClips["subzone:bashal-aran"] = {scope="overview-body",sourceHash="458eb1",hash="22d600",name="Башал'Аран",summary="Башал'Аран — давні руїни Високородних на півночі Темного Узбережжя, трохи на схід від Обердайна. До Великого Розколу це було квітуче місто-сестра Амет'Арану, а тепер тут кишать демонічні сатири й грелли, що живляться залишками таємної магії, а самотній ельфійський привид досі ув'язнений давнім прокляттям.",section="До того як десять тисяч років тому Великий Розкол зламав давній Калімдор, королева Азшара оселила улюблених підданих із Високородних у містах-близнюках Башал'Аран і Амет'Аран. Під владою могутнього мага Атрікуса Нарассіна міста славилися розкішними ринками й храмами на честь Елуни. Коли Колодязь Вічності обвалилося, катаклізм спустошив обидва поселення. З причин, загублених у часі, Атрікус скористався своєю таємною майстерністю, щоб ув'язнити власного заступника, мага Астеріона, у печатці з місячного каменю в Башал'Арані. Навіть після смерті тіла привид Астеріона лишився прикутим до зруйнованої святині.",sectionIndex=1}
c["subzone:bathran-s-haunt"] = "1a3c8c"
P.scopedClips["subzone:bathran-s-haunt"] = {scope="overview-body",sourceHash="77cab2",hash="1a3c8c",name="Притулок Батрана",summary="Притулок Батрана — давні руїни калдореїв на північному заході Ашенвалю, на схід від Зорамського Узмор'я. Нещодавно це місце захопили травники Відступників зі своєю охороною: вони збирають тутешні рослини для алхімічних досліджень, і довколишній ліс поволі в'яне.",section="На північ від Руїн Ордил'Аран серед густого ашенвальського листя стоять напівзруйновані колони нічних ельфів. Колись тиха пам'ятка калдореїв опинилася в тіні Відступників. Серед мармурових уламків нишпорять травники-нежить та їхні охоронці, що влаштували тут грубу лабораторію просто неба. Сама їхня присутність отруює давню землю: трава гниє й буріє, яскраві квіти в'януть, а гаєм розповзається неприродний тлін, поки вони методично збирають рідкісні лісові інгредієнти для своїх дослідів.",sectionIndex=1}
c["subzone:beggar-s-haunt"] = "ee0faa"
P.scopedClips["subzone:beggar-s-haunt"] = {scope="overview-body",sourceHash="3d5e68",hash="ee0faa",name="Притон Жебрака",summary="Притон Жебрака — покинута розвідувальна вежа Стормвінда на схилі пагорба на північному сході Сутінколісся, біля гірської дороги до Перевалу Мертвого Вітру. Колись її звели, щоб стерегти східні кордони королівства, а тепер вона стала заставою лазутчиків-Відступників глибоко на землях Альянсу.",section="Притон Жебрака, що височіє над туманними пагорбами на схід від Маєтку Містмантл, колись був діяльним спостережним постом, де Вартові Стормвінда стерегли східні підступи до королівства. Коли Велике Селище поринув у морок нинішнього Сутінколісся, а королівські патрулі відійшли до Даркшира, кам'яну вежу покинули на поталу негоді. Нині її вигідне розташування служить куди зловіснішій меті: агенти Відступників, серед них члени Королівського Аптекарського Товариства та скрадачі смерті, проводять у зруйнованій твердині досліди й стежать за краєм просто під носом в Альянсу.",sectionIndex=1}
c["subzone:beren-s-peril"] = "5be58f"
P.scopedClips["subzone:beren-s-peril"] = {scope="overview-body",sourceHash="69feb9",hash="5be58f",name="Лихо Берена",summary="Лихо Берена — відлюдна гірська печера серед скелястих пагорбів на південний захід від Амбермілла в Срібноліссі. Це вкорінений редут мерців-ренегатів, вірних Погибелі, що служать некромантові Тулу Рейвенклову й плетуть змову проти сусідніх Відступників.",section="Лихо Берена, що сховалося високо в скелях на південний захід від Амбермілла, — це затінена печера й звивиста гірська стежка, приховані від головної дороги. Після спустошень Третьої війни мерці Погибелі, що не підкорилися Відступникам, під командуванням некроманта-ренегата Тула Рейвенклова укріпили цей анклав. Замість схилитися перед Темною Леді чи відступити на північ, слуги Рейвенклова — регенти, вартові й наймити — таємно збиралися тут, щоб підготувати напад на базу Відступників у Гробниці. Розвідники Відступників викрили їх, і тиха скеля перетворилася на поле бою для загонів Орди, посланих знищити загрозу, перш ніж напад відбудеться.",sectionIndex=1}
c["subzone:blackthorn-ridge"] = "39a220"
P.scopedClips["subzone:blackthorn-ridge"] = {scope="overview-body",sourceHash="8f4d4e",hash="39a220",name="Кряж Чорного Терну",summary="Кряж Чорного Терну — порізана, задушена терновиками долина в південній частині Пусток, просто на північ від Рейзорфен Краула. Тут кишать агресивні шипогриви Гостромани, що стережуть свої колючі поселення. Високо на кряжі стоїть табір орчихи-шаманки Брайн, яка оберігає надзвичайно чисте озерце гірської води.",section="Кряж Чорного Терну, що лежить поблизу велетенських наростів Рейзорфен Краула, заріс густими хащами величезних гострих колючок. Шипогриви Гостромани вважають ці землі прадавньою територією і використовують природні загорожі, щоб влаштовувати засідки на чужинців і готувати вилазки в південні Пустки. Попри постійну небезпеку, мандрівники шукають кряж заради відлюдної орчихи-шаманки Брайн: її табір стоїть над джерелом, відомим на весь Калімдор дивовижною прозорістю й духовною чистотою.",sectionIndex=1}
c["subzone:blackwolf-river"] = "a20132"
P.scopedClips["subzone:blackwolf-river"] = {scope="overview-body",sourceHash="ef4470",hash="a20132",name="Річка Чорного Вовка",summary="Річка Чорного Вовка витікає з Озера Скельної Заводі й збігає крізь Кручу Вітрорізу в Горах Кам'яного Кігтя. Колись це був чистий гірський потік, а тепер його води геть отруєні хижацькими вирубками та промисловими роботами Венчурної Компанії.",section="Спускаючись з Озера Скельної Заводі, Річка Чорного Вовка перетинає улоговину Кручі Вітрорізу. Вона мала б бути незайманою гірською притокою, але натомість узяла на себе весь тягар неприборканого гоблінського підприємництва. Поки Венчурна Компанія розчищає навколишні ліси важкими машинами й циркулярними пилами, мул, мастило та відходи лісозаготівлі невпинно стікають у течію. Сплюндрована річка — яскравий приклад торговельного грабунку, що загрожує дикій природі Кам'яного Кігтя.",sectionIndex=1}
c["subzone:blackwood-den"] = "f848d3"
P.scopedClips["subzone:blackwood-den"] = {scope="overview-body",sourceHash="2b2b46",hash="f848d3",name="Лігво Чорнолісся",summary="Лігво Чорнолісся — осквернене стійбище фурболгів на півдні Темного Узбережжя, біля кордону з Ашенвалем. Колись мирна оселя, печера й табори довкола неї поринули в божевілля разом з усім племенем Чорнолісся. Самотній розвідник нічних ельфів на ім'я Волкор опинився в пастці в печері й чекає допомоги з Обердайна.",section="Лігво Чорнолісся, що лежить біля південного кордону, де Темне Узбережжя сходиться з Ашенвалем, — це звивиста мережа грубих таборів і кам'яниста печера. Фурболги Чорнолісся, що живуть тут, піддалися скверні, яка охопила край, і стали люто ворожими до чужинців. Глибоко в печері нічний ельф Волкор досі в облозі агресивного племені й у смертельній небезпеці, і йому конче потрібна допомога розвідників і мандрівників, посланих з Обердайна.",sectionIndex=1}
c["subzone:bladefist-bay"] = "31c406"
P.scopedClips["subzone:bladefist-bay"] = {scope="overview-body",sourceHash="f44bd6",hash="31c406",name="Затока Блейдфіст",summary="Затока Блейдфіст — суворий відтинок узбережжя на сході Дуротару, одразу за брамою Оргріммара. Названа на честь Карґата Блейдфіста, затока служить природною гаванню, зверненою до Великого Моря, у тіні скелястих круч і сусідніх південних берегів Азшари.",section="Простягшись уздовж північно-східного краю Дуротару, Затока Блейдфіст відкривається просто в неосяжні води Великого Моря. Затиснута скелястими урвищами й підступним прибоєм, вона є головним морським порогом столиці Орди — Оргріммара. Припливи раз у раз викидають на берег плавник, океанське сміття та уламки, тож серед місцевих затока має славу природного збірника морського непотребу. Просто на північ, через воду, височіють прадавні червоні скелі й руїни Азшари, роблячи затоку важливим морським кордоном Дуротару.",sectionIndex=1}
c["subzone:bloodhoof-village"] = "6f727a"
P.scopedClips["subzone:bloodhoof-village"] = {scope="overview-body",sourceHash="1a6781",hash="6f727a",name="Село Бладгуф",summary="Село Бладгуф — центральне тауренське поселення на берегах Озера Кам'яного Бика в Малгорі. Назване на честь племені Бладгуф, воно стає першим великим осередком для молодих мисливців і сміливців, що прямують із Табору Нарачі до Тандер Блафа. Під проводом Бейна Бладгуфа село узгоджує місцеву оборону, торгівлю й традиційні обряди по всіх рівнинах.",section="Розташоване довкола прозорих вод Озера Кам'яного Бика, Село Бладгуф — жвавий осередок торгівлі, ремесла й обрядів у центрі Малгору. Молоді таурени, що пройшли випробування в Таборі Нарачі, приходять сюди відточити вміння, перш ніж рушити далі, до великих плато Тандер Блафа. Село також відоме по всьому Калімдору своїми майстрами-барабанниками й терплячими заводчиками, що приручають диких кодо для подорожей.",sectionIndex=1}
c["subzone:bloodtooth-camp"] = "59930e"
P.scopedClips["subzone:bloodtooth-camp"] = {scope="overview-body",sourceHash="6abc6d",hash="59930e",name="Табір Кривавого Ікла",summary="Табір Кривавого Ікла — стійбище ворожих осквернених фурболгів у центральному Ашенвалі, трохи на захід від Річки Фалфаррен. Під проводом вождя Рана Бладтуса ці колись мирні створіння піддалися темному божевіллю й нападають на кожного, хто наближається. Табір — одна з головних цілей розвідників Альянсу, які очищають довколишні ліси.",section="Табір Кривавого Ікла, що сховався на південний захід від південного місячного колодязя й на захід від Річки Фалфаррен, — суворе нагадування про занепад, який охоплює Ашенваль. Фурболги, що живуть тут, колись були пов'язані зі священною дикою природою Калімдору, але затяжна духовна скверна поглинула їхнє плем'я. Під командою Рана Бладтуса вони з шаленою ворожістю стережуть своє примітивне поселення, кидаючись і на мандрівників, і на нічних ельфів, що боронять ліс.",sectionIndex=1}
c["subzone:bough-shadow"] = "84f46e"
P.scopedClips["subzone:bough-shadow"] = {scope="overview-body",sourceHash="edf199",hash="84f46e",name="Тінь Віття",summary="Тінь Віття — відлюдний гай у далекому північно-східному куточку Ашенвалю, на схід від Лісової Пісні. Його серце — велетенське Велике Дерево, що вкоренилося над давнім порталом, який веде просто до Смарагдового Сну.",section="У Тіні Віття росте одне з рідкісних Великих Дерев, виплеканих із живця Світового Дерева, Нордрассілу. Давно посаджене друїдами, що йшли за Фандралом Стаґгелмом, воно запускає коріння глибоко в землю довкола природного переходу до Смарагдового Сну. Сьогодні цей тихий, але величний гай пильно охороняє рід зелених драконів. Смарагдові дракони, як-от Фантім і Скрадач снів, кружляють над кронами, а патрулі драконородів-емеральдонів та оракули невідступно стережуть вихористий зелений портал біля підніжжя дерева, завертаючи кожного смертного, хто наближається без запрошення.",sectionIndex=1}
c["subzone:boulder-lode-mine"] = "7366c6"
P.scopedClips["subzone:boulder-lode-mine"] = {scope="overview-body",sourceHash="f086a7",hash="7366c6",name="Шахта Кам'яної Жили",summary="Шахта Кам'яної Жили — хижацька розробка, врізана в пагорби північно-східних Пусток. Хоча орківські прапори й сторожові вежі свідчать, що першою це місце облаштувала Орда, нині ним твердо заволоділа й орудує безжальна Венчурна Компанія.",section="Обвітрені орківські споруди біля входу до Шахти Кам'яної Жили вказують на те, що колись цією ділянкою володіла або навіть заснувала її Орда. Проте сьогодні тут кишать наглядачі й костоломи Венчурної Компанії, що працюють під орудою Боса Копперплаґа. Гоблінський синдикат нещадно розорює каньйон, не зважаючи ні на місцеву природу, ні на своїх робітників, — його цікавлять лише цінні мінерали, дорогоцінне каміння й промислові машини.",sectionIndex=1}
c["subzone:boulderslide-cavern"] = "205204"
P.scopedClips["subzone:boulderslide-cavern"] = {scope="overview-body",sourceHash="38b2db",hash="205204",name="Печера Кам'яного Зсуву",summary="Печера Кам'яного Зсуву — підземний лабіринт нір у найглибшому кінці Яру Кам'яного Зсуву в Горах Кам'яного Кігтя. Тут головне лігвище й копальня місцевих кобольдів Кам'яного Зсуву, які одержимо риють тунелі в пошуках сяйливих мінералів.",section="Кобольди Кам'яного Зсуву глибоко вгризлися в скелі Кам'яного Кігтя й зробили Печеру Кам'яного Зсуву своєю твердинею. На відміну від звичайних печерних шкідників, що шукають лише сховку, ці кобольди гарячково видобувають резоніт — рідкісний сяйливий пурпуровий кристал, вкраплений по всій породі. Кристали пульсують залишками земної магії, і через це істоти шаленіють, люто обороняючи свої розкопки від кожного прибульця.",sectionIndex=1}
c["subzone:boulderslide-ravine"] = "dc1f00"
P.scopedClips["subzone:boulderslide-ravine"] = {scope="overview-body",sourceHash="bf71eb",hash="dc1f00",name="Яр Кам'яного Зсуву",summary="Яр Кам'яного Зсуву — дикий відлюдний каньйон серед центральних вершин Гір Кам'яного Кігтя, куди веде Стежка Павутинника. Прямі сутички між Ордою та Альянсом його здебільшого оминули: це кам'янистий підхід до Печери Кам'яного Зсуву, де досі живуть дикі гірські звірі.",section="Яр Кам'яного Зсуву, захований осторонь Стежки Павутинника, — вузька розколина у височинах Кам'яного Кігтя. Поки лісоруби, нічні ельфи та Орда воюють за деревину й священні галявини по всьому краю, цей скелястий прохід війська майже не тривожать. Тутешня живність — дикі гірські барани та бродячі скельні звірі на кшталт скельних буревісників, що пробираються підступними уступами й прямовисними кам'яними стінами. Не зводять очей з яру й рудошукачі: на кам'янистих схилах, що ведуть углиб до печер, раз у раз проступають багаті рудні жили.",sectionIndex=1}
c["subzone:brackwell-pumpkin-patch"] = "a426c4"
P.scopedClips["subzone:brackwell-pumpkin-patch"] = {scope="overview-body",sourceHash="d1411c",hash="a426c4",name="Гарбузова Ділянка Брекуеллів",summary="Гарбузова Ділянка Брекуеллів — захоплена ферма на південному сході Лісу Елвінн. Колись домівку родини Брекуеллів, її поля й хатину цілком прибрало до рук Братство Дефіас як робочий сховок. Тут зустрічаються змовники-розбійники й звідси переправляють украдене золото.",section="Ферма Брекуеллів на південний схід від садиби Стоунфілдів колись була родючим клаптем елвіннської землі. Нині її законні господарі зникли безслідно — їх вигнала, а може, й гірше, хвиля злочинності, що здіймається. За їхньої відсутності Братство Дефіас захопило міцну хатину й зарослі поля ферми. Місце працює як схованка й перевалочний пункт, де розбійники перегруповуються подалі від пильних очей патрулів Ґолдшира. Помітні змовники на кшталт Морґана Збирача використовують відлюдну ділянку, щоб приймати партії золота, незаконно вкраденого з лісових копалень.",sectionIndex=1}
c["subzone:brambleblade-ravine"] = "dc758a"
P.scopedClips["subzone:brambleblade-ravine"] = {scope="overview-body",sourceHash="f7b9a7",hash="dc758a",name="Яр Тернистого Клинка",summary="Яр Тернистого Клинка — скелястий каньйон, що врізається в північно-східний край Плато Червоної Хмари. Це укріплене лігво шипогривів племені Щетиноспинних, які раз у раз нападають на сусіднє тауренське поселення, Табір Нарачі. Молодих тауренських сміливців посилають сюди довести свою силу й захистити батьківщину від цих лютих зайд.",section="Вирізьблений у випаленій сонцем землі Плато Червоної Хмари, Яр Тернистого Клинка густо заріс колючими хащами й усіяний стійбищами шипогривів. Плем'я Щетиноспинних використовує цю природну фортецю як плацдарм для наскоків на Табір Нарачі, загрожуючи безпеці молодих тауренів, що входять у зрілий вік. Шамани й воїни Щетиноспинних на чолі з Вождем Шарптаском Торнмантлом живуть у глибині яру серед вишколених бойових вепрів. Для Шу'хало удар у саме серце каньйону — водночас важливий обряд посвяти й сувора необхідність, щоб убезпечити рівнини.",sectionIndex=1}
c["subzone:bramblescar"] = "e44f78"
P.scopedClips["subzone:bramblescar"] = {scope="overview-body",sourceHash="a4f0ac",hash="e44f78",name="Тернистий Шрам",summary="Тернистий Шрам — потужно укріплене поселення шипогривів Гостроманів на півдні Пусток. Густі колючі терновики захищають стійбище, а його мешканці ведуть жорстоку війну із суперницьким племенем Щетиноспинів по той бік Золотого Шляху.",section="Тернистий Шрам, врізаний у порізані велетенські колючі хащі південних Пусток, — важливий редут шипогривів Гостроманів. Оборонні терновики виростають настільки густими й гострими, що відлякують випадкових мандрівників, але шипогриви всередині аж ніяк не мирні. Затято ревниві до своєї землі й ворожі до чужинців, вони раз у раз нападають на кожного, хто наблизиться до їхніх меж, бо вважають усіх, хто не шипогрив, загарбниками землі, благословенної їхніми давніми богами-вепрами.",sectionIndex=1}
c["subzone:brewnall-village"] = "8802e0"
P.scopedClips["subzone:brewnall-village"] = {scope="overview-body",sourceHash="aa311e",hash="8802e0",name="Село Брюнолл",summary="Село Брюнолл — невелике дворфське поселення в Долині Холодного Вітерцю, неподалік входу до Гномреґану. Засноване родиною Барліброю, воно служить полігоном для сміливих пивоварних дослідів і місцевої оборони від диких звірів. Хоч його й називають селом, насправді це радше сільський табір у засніжених гномських низинах Дун Мороґу.",section="Сховане серед заметів Долини Холодного Вітерцю, Село Брюнолл лежить просто посеред споконвічних гномських земель західного Дун Мороґу. Тут живе клан Барліброю — непохитні дворфські пивовари, віддані вдосконаленню прадавніх рецептів і створенню найкращого стауту. Хоч це й зветься селом, застава складається здебільшого з наметів і просто неба розставленого пивоварного начиння, а не з кам'яних будівель. Випробовуючи дослідні партії елю й відбиваючись від лютих тутешніх вовків та ведмедів, Барліброю чимало покладаються на мандрівних горян, які збирають рідкісні інгредієнти й охороняють долину.",sectionIndex=1}
c["subzone:brightwater-lake"] = "4f63c2"
P.scopedClips["subzone:brightwater-lake"] = {scope="overview-body",sourceHash="b21213",hash="4f63c2",name="Озеро Світлої Води",summary="Озеро Світлої Води — найбільша водойма Галявин Тірісфалю, що простягається оповитими імлою низинами на північний схід від Брілла. Колись тихий притулок королівства Лордерон, тепер його води холодні й темні, а посередині лежить острів, де некромант-вигнанець веде свої заборонені дослідження.",section="Озеро Світлої Води, що розкинулося північними рівнинами між містечком Брілл і Багряною Сторожовою Заставою, — тихий і моторошний орієнтир у серці Тірісфалю. Тисячі років тому його імлисті береги бачили давні битви, зокрема ранні сутички з повелителем жаху Катра'натіром. У мирні століття під владою Королівства Лордерон озеро було мальовничим сільським затишком. Сьогодні, як і решта галявин, воно давно втратило свою первозданність. Чумні Землі лежать недалеко на схід, а каламутні холодні води відбивають лише сіре небо, усохлі дерева й постійну загрозу мандрівних мурлоків і ворожої нежиті.",sectionIndex=1}
c["subzone:brightwood-grove"] = "d55aea"
P.scopedClips["subzone:brightwood-grove"] = {scope="overview-body",sourceHash="97ffec",hash="d55aea",name="Гай Брайтвуд",summary="Гай Брайтвуд — темний лісовий простір одразу на захід від Даркшира в Сутінколіссі. Колись частина мирного хліборобського краю, тепер він кишить лютими воргенами Найтбейн, що отаборилися серед зруйнованих садиб і нападають на кожного мандрівника, який підійде надто близько.",section="Гай Брайтвуд, що видніється просто з околиць Даркшира, уособлює повзучу небезпеку, яка загрожує межам міста. Садиби й огорожі, що колись розмежовували мирні ниви, тепер повалені й гниють. На їхньому місці воргени Найтбейн спорудили грубі табори й никають зарослими галявинами. Близькість цих вовкоподібних звірів — постійна загроза для міста, тож Нічна Варта й перехожі шукачі пригод мусять раз у раз проріджувати їхні лави, доки вони не захопили поселення.",sectionIndex=1}
c["subzone:brill"] = "cb4d1e"
P.scopedClips["subzone:brill"] = {scope="overview-body",sourceHash="a1d1ee",hash="cb4d1e",name="Брілл",summary="Брілл — головне поселення Відступників в серці Галявин Тірісфалю, одразу на північ від Руїн Лордерона. Колись квітуче людське містечко, тепер воно править за адміністративний і військовий осередок для щойно пробуджених мерців, що виходять за межі Похоронного Подзвону.",section="До Третьої війни Брілл був жвавим селом під владою місцевих дворян — родин Барових і Аґамандів. Цьому добробуту настав кінець, коли Кел'Тузад обрав ці місця для найперших дослідів Культу Проклятих із Чумою Нежиті. Спустошлива пошесть прокотилася населенням так швидко, що місцеве ополчення було вибите, а по собі лишила величезне братське кладовище.\n\nТепер, відбудований Відступниками під проводом Магістрата Севрена, Брілл зберігає обвітрену лордеронську архітектуру під покровом похмурої цілеспрямованості. Містечко править за командний центр краю, координуючи оборону від вторгнень Багряного Хрестового Походу, мандрівних решток Погибелі та місцевих звірів, спотворених некромантичним тлінням.",sectionIndex=1}
c["subzone:brill-town-hall"] = "1af74b"
P.scopedClips["subzone:brill-town-hall"] = {scope="overview-body",sourceHash="ef377a",hash="1af74b",name="Ратуша Брілла",summary="Ратуша Брілла — адміністративне серце поселення Брілл у центральних Галявинах Тірісфалю. Найпомітніша будівля містечка, вона править за цивільний штаб, звідки Відступники керують своїми місцевими володіннями й координують оборону галявин.",section="Поки значна частина Лордерона лежить розбита й зруйнована, Ратуша Брілла досі стоїть як діючий громадський центр під владою нежиті. Усередині Магістрат Севрен керує справами містечка зі свого подіуму, роздаючи шукачам пригод Відступників важливі доручення й розпорядження. Якщо не рахувати Лігва Осквернителя в Аратійському нагір'ї, це одна з небагатьох визнаних ратуш у відомому світі, якою справді керують Відступники, — похмура пародія й водночас дієве продовження міської бюрократії старого Лордерона.",sectionIndex=1}
c["subzone:burning-blade-coven"] = "6e8a1a"
P.scopedClips["subzone:burning-blade-coven"] = {scope="overview-body",sourceHash="9c69e9",hash="6e8a1a",name="Ковен Палаючого Клинка",summary="Схований у північних скелях Долини Випробувань, Ковен Палаючого Клинка — заражена мережа печер, що загрожує найновішим новобранцям Орди. Усередині чаяться осквернені культисти й прикликані демони, перетворивши стару мінеральну печеру на плацдарм темної магії просто на порозі Дуротару.",section="Запилені червоні гори, що обступають Долину Випробувань, колись були просто дикою місциною для випробувань молодих орків і тролів Темного Списа, які робили перші кроки на службі Орді. Та нещодавно північні печери охопили темні обряди. З гирла печери висипають біси та дрібні демони, сіючи хаос і загрожуючи новобранцям. Культ Палаючого Клинка на чолі з потаємним чорнокнижником Ярроґом Бейншедовом міцно окопався в глибині, перетворивши колись звичайний тренувальний майданчик на справжнє поле бою з демонічним скверненням.",sectionIndex=1}
c["subzone:calmbreeze-inn"] = "d74c1c"
P.scopedClips["subzone:calmbreeze-inn"] = {scope="overview-body",sourceHash="35b3a6",hash="d74c1c",name="Корчма «Тихий Вітерець»",summary="Корчма «Тихий Вітерець» — так звуться головні заклади Острова Зефрас, де можна знайти прихисток і послуги: вони є і в Селі Шен'дар, і у Валанаарі. Це важливі зупинки для мандрівників, що досліджують острів: тут працюють місцеві наставники ремесел і корчмарі, а також зберігаються історичні реліквії.",section="Корчми «Тихий Вітерець» дають прихисток серед звивистих стежок Острова Зефрас. У Селі Шен'дар корчму тримає Коріелла Калмбріз, і там же збираються острівні ремісники — зокрема наставники травництва, знімання шкур і зачарування. А у Валанаарі ще одна корчма «Тихий Вітерець» приймає місцевих подорожніх і зберігає рідкісні дивовижі, серед них — звуковий кристал із записом історії давнього повстання в Ельдре'Таласі.",sectionIndex=1}
c["subzone:camp-aparaje"] = "d2166d"
P.scopedClips["subzone:camp-aparaje"] = {scope="overview-body",sourceHash="7858ec",hash="d2166d",name="Табір Апараже",summary="Колись Табір Апараже був мирним тауренським селищем у східних височинах Гір Кам'яного Кігтя. Нині його захопило вороже плем'я Ґрімтотем: вони вирізали поселенців і забрали заставу собі.",section="Табір Апараже на кручах Гір Кам'яного Кігтя заснували мирні таурени, які хотіли спокійно жити у височинах. Той спокій розлетівся на друзки, коли нападники з сусідньої Застави Ґрімтотем на чолі з Ґрундіґом Дарклаудом без жодної причини люто вдарили по селищу. Мешканців вирізали або прогнали, а вцілілі — як-от Макаба Флетгуф — оплакують зруйнований дім і зі страхом думають про долю родичів, що потрапили в полон.",sectionIndex=1}
c["subzone:camp-narache"] = "d43e3d"
P.scopedClips["subzone:camp-narache"] = {scope="overview-body",sourceHash="28d93e",hash="d43e3d",name="Табір Нарачі",summary="Табір Нарачі — відлюдне селище на Плато Червоної Хмари в південному Малгорі. Це прабатьківська домівка племені Гоквінд і місце випробувань, де молоді таурени починають навчання. Високо над рівнинами табір береже давні традиції й невпинно стереже від зазіхань шипогривів і не зниклої загрози кентаврів.",section="Табір Нарачі, що лежить на північному краю піднесеного Плато Червоної Хмари, — головне поселення племені Гоквінд. Селище складається з кількох великих шкіряних осель і наметів: тут є спільний намет для поранених сміливців, зброярня, пекарський намет і духовний куточок для роздумів і спілкування з предками. У центрі табору колом стоять старійшини племені й наставники шляхів; тут досі дає поради поважна Прамати Гоквінд, скеровуючи щойно посвячену молодь, яка стає на шлях захисників Земної Матері.",sectionIndex=1}
c["subzone:camp-narache#faq1"] = "7863c8"
P.scopedClips["subzone:camp-narache#faq1"] = {scope="answer-only",sourceHash="706d7b",hash="7863c8",name="Табір Нарачі",question="Що таке Табір Нарачі?",answer="Табір Нарачі — стартове селище молодих тауренів на вершині Плато Червоної Хмари в південному Малгорі. Це головне стійбище племені Гоквінд, прихисток, де мисливці, воїни, друїди й шамани-початківці опановують своє ремесло, перш ніж вирушити до Села Бладгуф і Тандер Блафа."}
c["subzone:camp-narache#faq2"] = "06cce5"
P.scopedClips["subzone:camp-narache#faq2"] = {scope="answer-only",sourceHash="4951af",hash="06cce5",name="Табір Нарачі",question="Хто очолює селище?",answer="Вождь Гоквінд веде сміливців племені й керує обороною плато разом із шанованою старійшиною племені, Праматір'ю Гоквінд. Наставники й старійшини племені збираються в центрі табору, щоб навчати молодих шукачів пригод."}
c["subzone:camp-narache#faq3"] = "3d0956"
P.scopedClips["subzone:camp-narache#faq3"] = {scope="answer-only",sourceHash="ddf9e7",hash="3d0956",name="Табір Нарачі",question="Які загрози чигають на табір?",answer="Стійбищу постійно дошкуляють шипогриви Щетиноспинних, що діють із Яру Тернистого Клинка на сході. Окрім здичавілих бойових вепрів і довгоступів, що блукають довколишніми кручами, не зникла небезпека хижих ватаг кентаврів, і це тримає сміливців Гоквіндів у постійній готовності."}
c["subzone:camp-narache#faq4"] = "720a51"
P.scopedClips["subzone:camp-narache#faq4"] = {scope="answer-only",sourceHash="56054d",hash="720a51",name="Табір Нарачі",question="Чи легко мандрівникам залишити плато?",answer="Плато Червоної Хмари з усіх боків оточене стрімкими урвищами. Єдиний спуск до великих рівнин Малгору — гірська стежка, що веде на північ під охороною сміливців Гоквіндів, які не дають ворожим звірам і шипогривам влаштовувати засідки на подорожніх."}
c["subzone:camp-taurajo"] = "a4188f"
P.scopedClips["subzone:camp-taurajo"] = {scope="overview-body",sourceHash="fbea81",hash="a4188f",name="Табір Тауражо",summary="Табір Тауражо — тихе поселення тауренів на півдні Пусток, просто біля гірського перевалу, що веде на захід до Малгору. Це важливий прикордонний прихисток: утомлені мандрівники знайдуть тут корчму, припаси, наставників ремесел і вітрокрилів, що літають між рівнинами й центральним Калімдором.",section="Табір Тауражо, що стоїть біля східного виходу з перевалу до Малгору, часто стає першим місцем, де молоді таурени, які вирушають із Села Бладгуф, бачать безкраї Пустки. Оточений сухими чагарниками й порізаними плато, табір водночас застава й торговий осередок. Тут знаходять прихисток мисливці, шкірники й польові травники, а вітрокрили сполучають його з Тандер Блафом, Перехрестям і Заставою Вільного Вітру далі на півдні.",sectionIndex=1}
c["subzone:canals-stormwind-city"] = "feb6ff"
P.scopedClips["subzone:canals-stormwind-city"] = {scope="overview-body",sourceHash="dc45ce",hash="feb6ff",name="Канали (Стормвінд)",summary="Канали — мережа облицьованих каменем водних шляхів, що в'ються Стормвіндом і розділяють його квартали. Це тихі шляхи для перехожих і рибалок, але вони ховають приховані небезпеки й вхід до міської в'язниці.",section="Канали з'єднують і окреслюють квартали Стормвінда, відділяючи гомінкі ринки Торгового Кварталу від старих провулків Старого Міста, соборних садів і Дворфійського Кварталу. Кам'яні мости, арки й набережні обрамлюють тихі заклади на кшталт Виноробні Ґалліни, кравецьких крамниць і спокійних житлових будинків. Водні шляхи не лише служать місцевим купцям і рибалкам-аматорам — вони ще й ховають укріплений вхід до В'язниці, де під рівнем вулиць тримають найнебезпечніших злочинців і бунтарів Стормвінда.",sectionIndex=1}
c["subzone:canals-undercity"] = "3decc0"
P.scopedClips["subzone:canals-undercity"] = {scope="overview-body",sourceHash="2ae003",hash="3decc0",name="Канали (Андерсіті)",summary="Канали — каламутний кільцевий рів, що в'ється між окремими кварталами Андерсіті. Замість прісної води їх заповнює неприродний, отруйний зелений слиз, тож вони водночас слугують каналізацією і похмурим символом підземної твердині Відступників.",section="Канали, висічені в підземних глибинах під руїнами Лордерона, оточують серце Андерсіті й розділяють його квартали широкими руслами млявої зеленої твані. Міста живих пропускають вулицями річкову воду, щоб тримати їх у чистоті, а Відступники заповнили ці кам'яні жолоби промисловими покидьками, хімічними стоками й алхімічними відходами. Рідина ледь помітно, хворобливо світиться й випускає смердючі випари, тож перейти її звичними чарами на кшталт ходіння по воді неможливо. Попри смертоносність цієї бурди, відчайдушні рибалки часом витягають із багна дивні, зіпсовані дивовижі.",sectionIndex=1}
c["subzone:cathedral-of-light"] = "737f17"
P.scopedClips["subzone:cathedral-of-light"] = {scope="overview-body",sourceHash="c4d40e",hash="737f17",name="Собор Світла",summary="Собор Світла — духовне серце Стормвінда й головне святилище Церкви Святого Світла. Височіючи над Соборною Площею, він править за головний оплот людського духовенства й Лицарів Срібної Длані.",section="Відбудований після руйнування в Першу війну під проводом Архієпископа Алонсуса Фаола й тодішнього єпископа Бенедиктуса, Собор Світла височіє як маяк незламності. Його величезні зали й підземні катакомби прихищали зневірених біженців у найтемніші години відбудови Стормвінда. Коли під час Третьої війни Лордерон упав під натиском Погибелі, осідок Церкви перемістився на південь, до Стормвінда. Нині Архієпископ Бенедиктус опікується вірними з цієї величної зали, даючи духовне провідництво всьому Альянсу.",sectionIndex=1}
c["subzone:cathedral-square"] = "f58ec9"
P.scopedClips["subzone:cathedral-square"] = {scope="overview-body",sourceHash="79d562",hash="f58ec9",name="Соборна Площа",summary="Соборна Площа — духовне й громадське серце Стормвінда, над яким панує величний Собор Світла. Це не лише місце молитви й відданості: на гомінкій площі стоять міські установи — Ратуша, міський сиротинець і місцевий штаб Срібного світанку.",section="Соборна Площа, що лежить на північний захід від Торгового Кварталу й на південний схід від Дворфійського Кварталу, — осередок віри Королівства Стормвінд. Над обрієм панує Собор Світла — найголовніше святилище вірних Святого Світла в усьому Азероті. Жерці, паладини й цілителі збираються тут, щоб навчатися, молитися й тренуватися. Містяни, прочани й місцеві школярі на чолі зі Шкільною Наставницею Данною часто збираються на площі для розмов і роздумів.",sectionIndex=1}
c["subzone:cavern-of-mists"] = "51ce78"
P.scopedClips["subzone:cavern-of-mists"] = {scope="overview-body",sourceHash="4d51b8",hash="51ce78",name="Печера Імли",summary="Печера Імли — простора зовнішня передпечера, що веде в глибини Печер Стогонів. Її живлять підземні гейзери, які б'ють крізь скелю, а в центральному озерці й завислому тумані водяться дивні мутовані звірі, що никають біля самого входу.",section="Перш ніж спуститися в справжнє серце Печер Стогонів, мандрівники мають пройти Печеру Імли. Тут повсякчас висить густа тепла пара — її живлять природні гейзери, що б'ють із дна печери в глибоке центральне озерце. Хоч це лише вхід, спокою тут немає. Уступами й водою никають зграї рапторів, змії, слизуни й напівводяні трешадони, а поряд із ними — сумнозвісні звірі на кшталт гідри Трайґора Шмагача. Це зловісний передсмак протиприродного буяння, що гниє глибше внизу.",sectionIndex=1}
c["subzone:cenarion-enclave"] = "0a875d"
P.scopedClips["subzone:cenarion-enclave"] = {scope="overview-body",sourceHash="b7ee9a",hash="0a875d",name="Ценаріонський Анклав",summary="Ценаріонський Анклав — зелений північно-західний район Дарнасуса, головне місце зборів і осідок влади Кола Кенарія в столиці. Поки Архідруїд Малфуріон Стормрейдж спить у Смарагдовому Сні, друїдів нічних ельфів веде Архідруїд Фандрал Стаґгелм — серед величезних дупел і живого гілля цього гаю.",section="Ценаріонський Анклав розкинувся на високій терасі над Храмовими Садами. Його виплекано з прадавніх дубів і ясенів, чию кору поцятковано рунами. Збори Кола Кенарія відбуваються в спорудах, виліплених просто з живого дерева й каменю. Поки Малфуріон Стормрейдж перебуває у Смарагдовому Сні, справами тут порядкує Архідруїд Фандрал Стаґгелм: він просуває свої честолюбні задуми щодо Тельдрассила, попри давні політичні тертя з Верховною Жрицею Тірандою Віспервінд. Окрім друїдів, що медитують біля його струмків, анклав прихищає мисливців столиці та стайні, де вправні вершники вчаться приборкувати дарнасуських нічних шаблезубів.",sectionIndex=1}
c["subzone:champions-hall"] = "2a7c91"
P.scopedClips["subzone:champions-hall"] = {scope="overview-body",sourceHash="f0b3a8",hash="2a7c91",name="Зала Чемпіонів",summary="Захована в південній частині Старого Міста, Зала Чемпіонів — офіцерська казарма й збройовий склад для заслужених ветеранів Альянсу в Стормвінді. За її порогом інтенданти видають випробуваним воїнам фракції особливу зброю, лати й регалії. Вхід суворо охороняється й відкритий лише для офіцерів, що виявили звитягу на полі бою.",section="Захована за охоронюваним порогом у Старому Місті, Зала Чемпіонів — закритий прихисток для найвидатніших бійців Альянсу. Воєначальники збираються тут над тактичними мапами Азероту, щоб радитися щодо поточних походів, серед озброєння й величних знаків розрізнення. Увійти можуть лише солдати, що піднялися в ієрархії Альянсу до офіцерського звання — від Лицаря й вище. Усередині воєнні інтенданти забезпечують загартованих у боях солдатів добірною зброєю, обладунками й верховими тваринами, створеними, щоб переламати хід боротьби проти Орди в спірних краях по всьому світу.",sectionIndex=1}
c["subzone:charred-vale"] = "c5cded"
P.scopedClips["subzone:charred-vale"] = {scope="overview-body",sourceHash="8b2665",hash="c5cded",name="Обвуглена Долина",summary="Обвуглена Долина — тліюча долина на південному заході Гір Кам'яного Кігтя, спустошена безоглядною вирубкою та машинами Венчурної Компанії. Колись тут був квітучий притулок древенів і химер, а тепер долину охопило полум'я, і хазяйнують тут розлючені елементалі та ворожі гарпії.",section="Ще недавно ця південно-західна улоговина була буйним гірським лісом, який стерегли величні древені, а населяли тутешні химери й гарпії. Занепад почався з приходом Венчурної Компанії. Жадібна гоблінська зграя вирубала ліс під корінь вибуховими машинами, зіпсувала його охоронців і розбудила хаотичних вогняних елементалів. Древені зрештою відтіснили гоблінів, але земля лишилася понівеченою, випаленою й отруєною тим мерзенним начинням, яке лісоруби пустили в хід, відступаючи.",sectionIndex=1}
c["subzone:chill-breeze-valley"] = "490d33"
P.scopedClips["subzone:chill-breeze-valley"] = {scope="overview-body",sourceHash="ec8e79",hash="490d33",name="Долина Холодного Вітерцю",summary="Долина Холодного Вітерцю — суворий засніжений перевал на заході Дун Мороґу, що сполучає дворфське поселення Харанос зі змученим боями містом Гномреґан. Головний її шлях — жвава дорога для молодих мандрівників і біженців, та в її відлюдних закутках чаяться небезпечні звірі й криваві лігва.",section="Долина Холодного Вітерцю прорізає гори західного Дун Мороґу Т-подібним рівчаком. Головною стежкою зі сходу на захід постійно снують дворфи та гноми-новачки, мандруючи між Хараносом і околицями Гномреґану. Але звернути в північно-південне відгалуження долини — зовсім інша справа. Усіяні плямами крові й понівеченими тушами, ці похмурі закутки ховають лютих хижаків — насамперед диких вендіго, що гніздяться в глибоких крижаних печерах і полюють на кожного, хто необачно забреде в їхні мисливські угіддя.",sectionIndex=1}
c["subzone:clean-zone"] = "3a1a48"
P.scopedClips["subzone:clean-zone"] = {scope="overview-body",sourceHash="ee053f",hash="3a1a48",name="Чиста Зона",summary="Чиста Зона — укріплений анклав для знезараження всередині зруйнованого Гномреґана, одразу за верхньою Залою Шестерень. Це єдиний безпечний прихисток в опроміненому комплексі, де неосквернені гномські сили тримають оборону від трогів і гномів-прокажених довкола. Тут польові медики, техніки й особливі машини «Іскромат» дають перепочинок і допомагають рятувати цінне з радіоактивних руїн.",section="Хоча більша частина Гномреґана постраждала від катастрофічного викиду радіоактивних відходів, на який зважився Меккаторк, Чиста Зона лишається незараженою. Розташована стратегічно між заполоненим трогами Гуртожитком унизу й спірними коридорами Зали Шестерень нагорі, вона слугує укріпленою передовою базою. Рішучі гноми-захисники, техніки й польові медики тримають барикади вдень і вночі, щоб експедиції Альянсу мали надійний плацдарм, де можна перегрупуватися, перев'язати рани й полагодити машини.",sectionIndex=1}
c["subzone:cleft"] = "cd5dbb"
P.scopedClips["subzone:cleft"] = {scope="overview-body",sourceHash="030b34",hash="cd5dbb",name="Розколина",summary="Розколина — темна улоговина на північний захід від Доланаара на Тельдрассилі. Колись тихий куточок гілля, вона дісталася зіпсутим фурболгам-Вузлошкірам, які зробили з неї твердиню для засідок на подорожніх, що йдуть головним шляхом до Дарнасуса.",section="Розколина осторонь шляху між Доланааром і Дарнасусом стала одним із найнебезпечніших лігв на Світовому Дереві. Збожеволілі від нечистої зарази, що шириться Тельдрассилом, тутешні фурболги-Вузлошкіри укріпили цю улоговину. Із цього редуту знавіснілі звірі тероризують місцеві дороги, загрожуючи відрізати Доланаар від столиці.",sectionIndex=1}
c["subzone:cleft-of-shadow"] = "23f4fd"
P.scopedClips["subzone:cleft-of-shadow"] = {scope="overview-body",sourceHash="e62418",hash="23f4fd",name="Тіньова Розколина",summary="Тіньова Розколина, що ховається глибоко в підземних печерах під Оргріммаром, — оселя міських майстрів скритності, чаклунства й демонології. Далеко від гордого воїнського духу верхніх районів Тралла вона слугує необхідним прихистком для розбійників, чорнокнижників і магів, що діють у тіні Орди.",section="Нова Орда Тралла звеличує честь, шаманство й силу зброї, та розважливий провід розуміє, що й тоншим мистецтвам потрібне місце. Тіньова Розколина, висічена у вогких кам'яних печерах під столицею, прихищає розбійників із Братства Прудкої Тіні, чорнокнижників з Анклаву Темного Вогню й учених Чародійного Анклаву. Подалі від щоденної метушні долин цей темний квартал дає змогу знавцям отрут, енергії скверни й чародійної магії займатися своїм ремеслом не на людях, хоч і під пильним оком провідників Оргріммара.",sectionIndex=1}
c["subzone:cliffspring-falls"] = "25e266"
P.scopedClips["subzone:cliffspring-falls"] = {scope="overview-body",sourceHash="375784",hash="25e266",name="Водоспад Скельного Джерела",summary="Водоспад Скельного Джерела — величний початок важливої для Темного Узбережжя Річки Скельного Джерела, що зривається зі східних скель у прибережний ліс. Довго його шанували як головне джерело чистої питної води в краї, але останнім часом його води вразила мерзенна скверна, що шириться. Підземну печеру, яка живить водоспад, заполонили ворожі наги й таємничі культисти Молота Присмерку.",section="Водоспад Скельного Джерела, що б'є з печер високо в скелястих кручах на східному кордоні Темного Узбережжя, живить Річку Скельного Джерела, яка петляє на захід лісами й впадає в море. Здавна цей каскад давав місцевим поселенням нічних ельфів найчистішу питну воду. Проте останнім часом води стали брудними й каламутними, поширюючи хвороби й занепад природи по всьому басейну річки. Дослідники природи з'ясували, що мережу печер біля витоків водоспаду заполонили мерзенні наги й темні культисти, які плетуть змови в тіні, а демонічна скверна із сусіднього Сквернолісся загрожує просочитися крізь скелі нагір'я.",sectionIndex=1}
c["subzone:cold-hearth-manor"] = "101405"
P.scopedClips["subzone:cold-hearth-manor"] = {scope="overview-body",sourceHash="28835d",hash="101405",name="Маєток Холодного Вогнища",summary="Маєток Холодного Вогнища — уражений чумою хутір одразу на захід від Брілла, біля головної дороги Галявин Тірісфалю. Колись жвавий, гостинний маєток, славний щедрими врожаями, він утратив усіх мешканців зі спалахом Чуми Нежиті, а довколишні поля заполонила безтямна Погибель. Сьогодні Відступники убезпечили головний будинок як заставу й перевалочний пункт для подорожніх.",section="До Третьої війни ця садиба славилася теплом і гостинністю, даючи багаті врожаї в серці Лордерона. Коли Чума прокотилася королівством, уся родина та її робітники загинули й повстали знову — порожніми оболонками, прив'язаними до Погибелі. Здичавіла нежить досі шкутильгає зруйнованими полями, та сили Відступників зуміли витіснити безтямних мерців із головного будинку й повернули будівлю, зробивши з неї торговий пост і опору на дорозі до східних галявин.",sectionIndex=1}
c["subzone:coldridge-pass"] = "81797f"
P.scopedClips["subzone:coldridge-pass"] = {scope="overview-body",sourceHash="1194dd",hash="81797f",name="Перевал Холодного Кряжа",summary="Перевал Холодного Кряжа — суворий засніжений тунель, пробитий крізь південний гірський хребет Дун Мороґу. Це єдиний сухопутний шлях, що сполучає відлюдні тренувальні угіддя Долини Холодного Хребта з рештою королівства і виходить поблизу гамірного містечка Харанос. Та оскільки прохід захопили ворожі троги, кожному мандрівникові доводиться або пробиватися з боєм, або відчайдушно бігти на той бік.",section="Для молодих дворфських новобранців і гномів-новачків, що роблять перші кроки за межі Долини Холодного Хребта, Перевал Холодного Кряжа — суворий обряд посвяти. Висічений просто в скелі, цей тунель — головна ланка, що веде щойно навчених шукачів пригод на схід, до прикордонного осередку Харанос. Колись безпечний гірський коридор перетворився на небезпечну вузьку горловину, кишить лютими трогами, які вилізли з темних підземель і загрожують кожному, хто намагається пройти між захищеною долиною і ширшими просторами Дун Мороґу.",sectionIndex=1}
c["subzone:coldridge-valley"] = "5286cc"
P.scopedClips["subzone:coldridge-valley"] = {scope="overview-body",sourceHash="2b764b",hash="5286cc",name="Долина Холодного Хребта",summary="Долина Холодного Хребта — захищена засніжена долина, схована серед південно-західних височин Дун Мороґу. Її серце — селище Анвілмар, і саме тут молоді дворфи та гномські біженці вперше беруться за зброю на службі Айронфорджу. Єдиний тунель, Перевал Холодного Кряжа, сполучає цю відлюдну улоговину з рештою гірського краю.",section="Оточена прямовисними гірськими скелями, Долина Холодного Хребта лишається здебільшого відрізаною від жвавих торгових шляхів Дун Мороґу. У її серці стоїть Анвілмар — міцна кам'яна зала й селище, де бувалі дворфські наставники та гноми-вчені, що втратили дім, навчають новобранців мистецтва бою, скритності й чарів. За межами теплих вогнищ Анвілмара дно долини вкрите глибоким снігом, а в ньому нишпорять вепри та голодні зимові вовки — так новачки вперше по-справжньому куштують виживання на порубіжжі.",sectionIndex=1}
c["subzone:coldridge-valley#faq1"] = "0e420a"
P.scopedClips["subzone:coldridge-valley#faq1"] = {scope="answer-only",sourceHash="5bf399",hash="0e420a",name="Долина Холодного Хребта",question="Як вийти з Долини Холодного Хребта?",answer="Єдиний сухопутний шлях із долини веде через Перевал Холодного Кряжа — засніжений тунель, пробитий крізь гірський хребет на північний схід. За перевалом дорога прямує на схід, просто до містечка Харанос, а далі — до великої брами Айронфорджа."}
c["subzone:coldridge-valley#faq2"] = "65a2f5"
P.scopedClips["subzone:coldridge-valley#faq2"] = {scope="answer-only",sourceHash="60054f",hash="65a2f5",name="Долина Холодного Хребта",question="Чому гноми починають тут разом із дворфами?",answer="Після трагічного падіння Гномреґану, захопленого трогами й отруєного радіацією, уцілілі гноми втекли до Дун Мороґу як біженці. Король Маґні Бронзбірд прийняв народ Великого Тінкера Меккаторка, тож багато гномських учнів-вигнанців тепер навчаються пліч-о-пліч із молодими дворфами в Анвілмарі."}
c["subzone:coldridge-valley#faq3"] = "0fe937"
P.scopedClips["subzone:coldridge-valley#faq3"] = {scope="answer-only",sourceHash="315a6b",hash="0fe937",name="Долина Холодного Хребта",question="Які загрози турбують долину?",answer="Долині загрожують дві головні напасті: ворожі тролі Морозогриви, яким ненависні дворфські поселення на їхніх гірських землях, і грубі троги з племені Кам'янощелепів, що вилізли з надр землі й перекрили Перевал Холодного Кряжа. Тутешні хижаки — вовки та вепри — теж не дають спокою необачним мандрівникам."}
c["subzone:coldridge-valley#faq4"] = "b52b85"
P.scopedClips["subzone:coldridge-valley#faq4"] = {scope="answer-only",sourceHash="541513",hash="b52b85",name="Долина Холодного Хребта",question="Що таке Анвілмар?",answer="Анвілмар — центральна фортеця-оселя й поселення Долини Холодного Хребта. Тут розташувалися наставники класів, майстри-ковалі та офіцери місцевих горян, які керують обороною долини й готують щойно загартованих шукачів пригод до великого світу."}
c["subzone:command-center"] = "773b25"
P.scopedClips["subzone:command-center"] = {scope="overview-body",sourceHash="676d75",hash="773b25",name="Командний центр",summary="Командний центр, який часто називають Казармами Стормвінда, стоїть у серці Старого Міста як оперативний штаб міських офіцерів. У мирний час тут розквартировано постійне військо, але поки сили Стормвінда вислано на далекі рубежі, центр працює з невеликим кістяком ветеранів, що муштрують новобранців і місцеве ополчення.",section="Командний центр, що стоїть серед вивітрених вулиць Старого Міста, — головний гарнізон і бойовий плац Королівства Стормвінд. Зазвичай тут повно регулярної піхоти й офіцерів, але нині тут незвично порожньо. Більша частина королівської армії воює в далеких походах, тож казарми покладаються на кістяк досвідчених наставників — серед них Андер Джермейн і майстер бойових мистецтв Ву Шен, — що навчають нових воїнів, а такі постаті, як Вулф Гансрейм, муштрують стрільців, щоб зміцнити оборону міста.",sectionIndex=1}
c["subzone:commons"] = "669777"
P.scopedClips["subzone:commons"] = {scope="overview-body",sourceHash="8fb31f",hash="669777",name="Торгові Ряди",summary="Торгові Ряди — жваве торговельне серце Айронфорджа, що веде від міської брами просто в його величезні печери. Тут аж кишить купцями, мандрівниками й банкірами: це найлюдніша вулиця дворфійської столиці й головне торжище всього Альянсу.",section="Торгові Ряди лежать одразу на північний схід від Брами Айронфорджа — це перший район, що зустрічає мандрівників у гірському королівстві. На цій гамірній торговій вулиці, висіченій просто в камені, розташовані головний аукціонний дім Альянсу, Таверна «Кам'яний Вогонь» і центральний банк міста у Сховищі Айронфорджа. Широкі проспекти плавно з'єднують її з Великою Кузнею, Кварталом містиків і Військовим Кварталом, тож майже кожен, хто ходить горою, минає тутешні гамірні крамниці.",sectionIndex=1}
c["subzone:craftsmen-s-terrace"] = "f5ba91"
P.scopedClips["subzone:craftsmen-s-terrace"] = {scope="overview-body",sourceHash="59ec8d",hash="f5ba91",name="Тераса Ремісників",summary="Тераса Ремісників — гамірний район майстрів на півночі Дарнасуса. Це головний осередок ремесел і торгівлі столиці нічних ельфів: тут майстерні, наставники професій і жвава корчма. Район приймає й гостей іздалеку — зокрема тут розташоване посольство нейтрального Срібного світанку.",section="Тераса Ремісників тягнеться північним краєм міста в кронах і збирає докупи різні ремесла, на яких тримається життя Дарнасуса. Тут мають свої крамниці теслі, шкірники, алхіміки й інші майстри, що поєднують давні методи нічних ельфів із практичним ремеслом. Є тут і все потрібне для громади: корчма, розпорядник гільдій і продавці гільдійських грамот. Мости ведуть із тераси просто до Ценаріонського Анклаву на заході й до Тераси Воїна на півдні.",sectionIndex=1}
c["subzone:crag-of-the-everliving"] = "d91476"
P.scopedClips["subzone:crag-of-the-everliving"] = {scope="overview-body",sourceHash="ab6728",hash="d91476",name="Скеля Вічноживих",summary="Скеля Вічноживих — зелена печерна зала глибоко в Печерах Стогонів. Тут панують буйні зіпсовані рослини й хижі рослинні істоти, а саме місце — володіння Володаря іклів Лорда Пайтаса. У її височенних верхніх ярусах ховається прадавня істота, на честь якої названо скелю.",section="Більшу частину Печер Стогонів видовбано у вологому підземному камені, але Скеля Вічноживих аж буяє неприборканою, спотвореною рослинністю, яку живить Жахіття, що отруює сон Наралекса. Височенні мохові уступи й звивисті стежки заполонили девіантні човгуни — живі рослинні громадини, що никають підліском. Лорд Пайтас, один із занепалих учнів Наралекса, стереже середину скелі: він проміняв шляхетні друїдські обітниці на отруйні обряди Друїдів Ікла.",sectionIndex=1}
c["subzone:cragpool-lake"] = "504874"
P.scopedClips["subzone:cragpool-lake"] = {scope="overview-body",sourceHash="48df19",hash="504874",name="Озеро Скельної Заводі",summary="Озеро Скельної Заводі ховається в Кручі Вітрорізу в Горах Кам'яного Кігтя. Над його темними водами нависає величезна дерев'яна споруда Венчурної Компанії.",section="Озеро Скельної Заводі лежить глибоко в Кручі Вітрорізу, просто під височенною лісозаготівельною машинерією Венчурної Компанії. Над водою розкинулася велетенська дерев'яна конструкція — оглядовий пункт, звідки Ґерензо Ренчвісл керує роботами по всій гірській долині. На помостах угорі порядкують робітники Венчурної Компанії.",sectionIndex=1}
c["subzone:crossroads"] = "142c64"
P.scopedClips["subzone:crossroads"] = {scope="overview-body",sourceHash="7fb8ef",hash="142c64",name="Перехрестя",summary="Перехрестя — серце сполучення Орди через центральний Калімдор: воно стоїть там, де Золотий Шлях, що тягнеться з півночі на південь, перетинає дорогу від Раджета до Гір Кам'яного Кігтя. Це гамірна торгова застава, військовий плацдарм і перевалочний пункт для мандрівників між Дуротаром, Малгором і північними фронтами.",section="Як і каже назва, Перехрестя стоїть якраз на перетині Золотого Шляху й дороги зі сходу на захід, що веде від гоблінського порту Раджет до Гір Кам'яного Кігтя. Попри скромне житло, застава — гамірний осередок усього краю. Господарі вітрокрилів, крамарі, ковалі й наставники постійно працюють тут під сторожовими вежами. Для молодих воїнів із Дуротара чи Малгору це поселення часто стає першим місцем, де вони бачать, як складна мережа постачання на багатьох фронтах тримає нову Орду вкупі.",sectionIndex=1}
c["subzone:crusader-outpost"] = "d45e75"
P.scopedClips["subzone:crusader-outpost"] = {scope="overview-body",sourceHash="4d8de8",hash="d45e75",name="Застава Хрестоносців",summary="Застава Хрестоносців — укріплена сторожова вежа на скелястих пагорбах східних Галявин Тірісфалю. Її тримають ревні члени Багряного Хрестового Походу, охороняючи підступи до своєї твердині — Багряного Монастиря. З цієї висоти хрестоносці стежать за рухом на дорозі й готові відбити будь-яке вторгнення Відступників.",section="Збудована на кручах над східною дорогою, Застава Хрестоносців — головний пост раннього попередження Багряного Хрестового Походу. З високої вежі вартові стежать за рухом між Бріллом і східними краями Лордерона, щоб мандрівну нежить чи розвідувальні загони помічали задовго до того, як ті дістануться брами Монастиря. Вежа також дає гарнізону змогу вдарити з флангу по будь-якому війську, що спробує піднятися долиною до їхнього святого бастіону.",sectionIndex=1}
c["subzone:crusader-s-outpost"] = "2c0aa9"
P.scopedClips["subzone:crusader-s-outpost"] = {scope="overview-body",sourceHash="275458",hash="2c0aa9",name="Застава Хрестоносця",summary="Застава Хрестоносця — укріплена розвідувальна вежа Багряного Хрестового Походу в західних Галявинах Тірісфалю. Поруч із нею лежить Хутір Соллідена, а сама вежа — найзахідніша позиція Хрестового Походу в усьому Лордероні. Небезпечна віддаленість від головних багряних бастіонів лишає її гарнізон відрізаним у серці ворожих земель Відступників.",section="Ця кам'яна вежа на західних пагорбах Тірісфалю, одразу на захід від Похоронного Подзвону, — крайня межа влади Багряного Хрестового Походу в Лордероні. Тутешній гарнізон діє разом із уцілілими людськими робітниками сусіднього Хутора Соллідена, намагаючись стримати нежить, що насувається. З вершини вежі дозорці пильнують довколишні гарбузові поля й лісові стежки, остерігаючись і мандрівних почвар Погибелі, і патрулів з Андерсіті.",sectionIndex=1}
c["subzone:crystal-lake"] = "234008"
P.scopedClips["subzone:crystal-lake"] = {scope="overview-body",sourceHash="e14bb3",hash="234008",name="Кришталеве Озеро",summary="Кришталеве Озеро — водойма просто на схід від Ґолдшира, у серці Лісу Елвінн. Колись мирне місце, нині його береги заполонили войовничі мурлоки, перетворивши озеро на постійну небезпеку для місцевих селян і перехожих мандрівників.",section="Кришталеве Озеро за кілька хвилин ходи від корчми «Лев'яча Гордість» мало б бути ідилічним сільським прихистком, та його дошкуляє небезпечна звірина. Племена прісноводних мурлоків захопили берег і мілководдя й нападають на кожного, хто підійде надто близько. Місцевий алхімік Вільям Пестл часто наймає перехожих шукачів пригод вирушити до води, перемогти створінь і зібрати кришталеві водорості, які ті носять, для його дослідних сумішей.",sectionIndex=1}
c["subzone:cut-throat-alley"] = "a0ba2c"
P.scopedClips["subzone:cut-throat-alley"] = {scope="overview-body",sourceHash="bb4cff",hash="a0ba2c",name="Провулок Горлорізів",summary="Провулок Горлорізів — відлюдний, безлюдний закуток Стормвінда, захований за крамницями над каналом. Схований за крамничкою «Тіньова Леді» біля межі Дворфійського Кварталу, він складається з тихого дворика й порожнього будинку, відрізаних від звичайних потоків перехожих.",section="Провулок Горлорізів — один із найтихіших і найпотаємніших куточків Стормвінда. Хоча на мапах його й позначають разом із Дворфійським Кварталом, від гуркоту горнів і густої кіптяви кварталу тут немає нічого. До провулка не дістатися з жодної головної вулиці міста: єдина стежка веде просто крізь «Тіньову Леді» — невелику крамницю над каналом трохи на південь від мосту з Соборної Площі. За дверима крамниці — маленький брукований глухий кут зі штабелями ящиків, забутими бочками й одним порожнім двоповерховим будинком. Цілковито прихований від вартових і звичайних містян, він стоїть у повній тиші посеред гамору столиці.",sectionIndex=1}
c["subzone:dagger-hills"] = "fbfcbf"
P.scopedClips["subzone:dagger-hills"] = {scope="overview-body",sourceHash="624226",hash="fbfcbf",name="Кинджальні Пагорби",summary="Кинджальні Пагорби — скелястий кряж, що здіймається на півдні Вестфолу просто за сплюндрованим містечком Мунбрук. Давно занедбане короною, це кам'янисте нагір'я стало ворожим сховком для головорізів, розбійників і повзучих жахів, що загрожують довколишнім рівнинам.",section="Здіймаючись високо над напіврозваленим Мунбруком, Кинджальні Пагорби позначають зубчастий південний край Вестфолу. Позбавлене королівських патрулів зі Стормвінда, це посушливе нагір'я стало природною фортецею для Братства Дефіас. Кастетники, нишпорки й грабіжники з великої дороги чаяться серед скелястих гребенів і чагарників, нападаючи на необачних мандрівників і стережучи підступи до своїх сховків унизу.",sectionIndex=1}
c["subzone:darkcloud-pinnacle"] = "60e01f"
P.scopedClips["subzone:darkcloud-pinnacle"] = {scope="overview-body",sourceHash="1b6940",hash="60e01f",name="Шпиль Темної Хмари",summary="Шпиль Темної Хмари — укріплене тауренське поселення на кількох з'єднаних між собою столових горах на схід від Великого Підйомника в Тисячі Голок. Цю повітряну твердиню тримає агресивний клан Ґрімтотем, і звідси він сіє в краї безлад і крутить темні справи.",section="Шпиль Темної Хмари розкинувся на трьох головних столових горах, з'єднаних мотузяними мостами, і панує над улоговиною каньйону внизу. Дістатися на висоту можна лише крутим природним схилом від дна каньйону через дерев'яні мости або високою переправою біля Рейзорфен Даунс. Із цих обвітрених скель Ґрімтотеми стежать за долиною — у безпеці від випадкових нападів і далеко від решти тауренських племен.",sectionIndex=1}
c["subzone:darkened-bank"] = "cc006f"
P.scopedClips["subzone:darkened-bank"] = {scope="overview-body",sourceHash="b22545",hash="cc006f",name="Темний Берег",summary="Темний Берег — північне узбережжя Сутінколісся вздовж річки, що відділяє темний ліс від Лісу Елвінн. Тягнеться він від далекого заходу аж на схід до Гір Редріджу й позначає межу між відносно безпечною північчю та темними жахами лісу.",section="Темний Берег пролягає південним берегом річки навпроти Лісу Елвінн і утворює північний край Сутінколісся. Він тягнеться від західних закрутів річки на схід, до кам'яного мосту, що веде до Гір Редріджу. Хоч під проклятою завісою крон Сутінколісся тут і похмуро, цей берег часто стає першим прихистком для мандрівників, що вирушають на південь з Елвінна. Біля його західного краю стоїть тимчасовий табір, де знайшли притулок біженці, серед них Свен Йорґен і Ларс, — ледь-ледь за межами лісової гущавини.",sectionIndex=1}
c["subzone:darkshire"] = "85a870"
P.scopedClips["subzone:darkshire"] = {scope="overview-body",sourceHash="a8b1ae",hash="85a870",name="Даркшир",summary="Даркшир, колись відомий як Велике Селище, — потерпале поселення на сході Сутінколісся. Огорнуте нескінченним неприродним мороком і занедбане Стормвіндом, містечко тримається лише завдяки пильності Нічної Варти й упертій витривалості своїх мешканців.",section="Колись це було мирне лісове поселення під назвою Велике Селище; під час Першої війни Стара Орда спалила його, а згодом його відбудували. По-справжньому гірко доля повернулася після падіння Медіва в Каражані: його передсмертні корчі прокляли Брайтвуд, і той став темною пущею, яку нині звуть Сутінколіссям. Хоча формально місто належить Королівству Стормвінд, ратуша не отримує від корони майже ніякої допомоги. Політичний параліч у Стормвінді лишив гарнізон без людей, а кордони — без патрулів, тож мер Елло Ебонлок і місцева рада змушені в темряві вершити власне суворе, замкнене в собі правосуддя.",sectionIndex=1}
c["subzone:darkshire-town-hall"] = "6066bf"
P.scopedClips["subzone:darkshire-town-hall"] = {scope="overview-body",sourceHash="05ef40",hash="6066bf",name="Ратуша Даркшира",summary="Ратуша Даркшира стоїть на західному краю міської площі й править за осередок місцевої влади в Сутінколіссі. З її тьмяно освітлених зал мер, Лорд Елло Ебонлок, і його рада намагаються керувати поселенням, яке облягають повзуча темрява й потвори нежиті.",section="Ратуша стоїть просто на захід від головної площі, і саме тут збираються міські очільники Даркшира, щоб правити дедалі відрізанішим краєм. У її витертих негодою стінах засідає мер, Лорд Елло Ебонлок, який намагається зберегти лад і захистити людей, поки Стормвінд майже не надає воєнної допомоги. Разом із мером міські урядники на кшталт Писаря Долтрі ведуть місцеві записи й облік мандрівників, що наважуються на небезпечні дороги Сутінколісся, хоча тримати книги в порядку за таких лихих часів — справа похмура й нелегка.",sectionIndex=1}
c["subzone:darkspear-strand"] = "2a4c57"
P.scopedClips["subzone:darkspear-strand"] = {scope="overview-body",sourceHash="8712fc",hash="2a4c57",name="Побережжя Темного Списа",summary="Побережжя Темного Списа — відтинок узбережжя на півдні Дуротару, куди тролів Темного Списа винесло на берег після вигнання з Островів Відлуння. Цей пляж просто поруч із Селом Сен'джин знаменує гіркий початок материкового притулку племені під проводом Вол'джина.",section="Коли знахар Залазан збожеволів і захопив владу над Островами Відлуння, уцілілі тролі Темного Списа були змушені залишити свій дім за морем. Зневірені біженці перетнули вузьку протоку й висадилися на цьому вибіленому сонцем узбережжі. Замість розсіятися ворожими червоними пустками Дуротару, вцілілі гуртом збудували Село Сен'джин за кілька кроків від берегової лінії. Нині побережжя лишається тихим нагадуванням про вигнання, дивлячись через прибій на острови, які вони досі сподіваються повернути.",sectionIndex=1}
c["subzone:dawning-isles"] = "65babc"
P.scopedClips["subzone:dawning-isles"] = {scope="overview-body",sourceHash="e1910a",hash="65babc",name="Світанкові Острови",summary="Світанкові Острови — група низьких острівців на Озері Лордамер біля східного краю Срібнолісся. Колись ідилічні місця відпочинку, вони піддалися пошесті Чуми Нежиття, і їх заполонили агресивні мурлоки.",section="До Третьої війни Світанкові Острови славилися як мальовничі острівці серед спокійних прозорих вод Озера Лордамер. Коли Чума Нежиття прокотилася Лордероном, скверна просочилася в мілини озера. Рослинність зблідла й почала гнити, і ідилічний спокій зник. Сьогодні на мулистих берегах і в заплутаних чагарниках панує плем'я мурлоків-Темноплавців, що люто захищають свої колонії, які дедалі розростаються, від кожного, хто спробує перетнути озеро.",sectionIndex=1}
c["subzone:dawning-wood-catacombs"] = "7043b1"
P.scopedClips["subzone:dawning-wood-catacombs"] = {scope="overview-body",sourceHash="013686",hash="7043b1",name="Катакомби Світанкового Лісу",summary="Видовбані глибоко під Цвинтарем Воронячого Пагорба, Катакомби Світанкового Лісу — темний лабіринт, де кишить найлютіша нежить Сутінколісся. Тих, хто наважиться зійти в підземні ходи, чекають цілі зграї скелетів-вартових і гулів-трупоїдів.",section="Задовго до того, як сутінкове прокляття лягло на ліс, Катакомби Світанкового Лісу були величною усипальницею для шанованих мерців Великого Селища та довколишніх садиб. Тепер, похована під зруйнованим Цвинтарем Воронячого Пагорба, ця мережа темних кам'яних коридорів зберігає найсмертоноснішу нежить краю. Катакомби мають два окремі підземні крила: західні ходи тримають шеренги оживлених скелетів, що стережуть родові гробниці, а східні спускаються в мерзенне кубло, де кишать ненажерливі гулі — розносники хвороб. Самотні мандрівники рідко виживають у цих глибинах.",sectionIndex=1}
c["subzone:dead-acre"] = "beccfc"
P.scopedClips["subzone:dead-acre"] = {scope="overview-body",sourceHash="c82fbf",hash="beccfc",name="Мертвий Лан",summary="Мертвий Лан — зруйнована, ще димна садиба на південному сході Вестфолу, біля річкового мосту до Сутінколісся. Братство Дефіас спалило її дотла під час повстання, що прокотилося краєм, і тепер на почорнілих полях немає людей — лише блукають некеровані големи жнив.",section="Мертвий Лан, що лежить трохи на північ від дороги із Сентінел Гілла до Сутінколісся, колись був урожайною садибою серед ферм житниці Вестфолу. Коли Братство Дефіас підняло бунт і вигнало місцевих землевласників, ця ферма зазнала жорстокої долі. Садибу й посіви довкола підпалили, лишивши по собі обвуглені колоди, задимлену землю й механічних Вартових Урожаю, що досі блукають і жнуть безплідну землю.",sectionIndex=1}
c["subzone:dead-field"] = "d57ff8"
P.scopedClips["subzone:dead-field"] = {scope="overview-body",sourceHash="aba0b9",hash="d57ff8",name="Мертве Поле",summary="Мертве Поле — сплюндрований покинутий хутір на півночі Срібнолісся. Колись тихі сільські угіддя, тепер його захопили гнилошкірі гноли й перетворили на передовий плацдарм сил Погибелі. Неодноразові спроби Відступників очистити місцевість зазнали невдачі через баньші Найтлаш, що командує тут.",section="Від колишнього хутора на півночі Срібнолісся мало що лишилося: його живі мешканці давно загинули під час Третьої війни. Сьогодні зруйнована ділянка — база гнилошкірих гнолів, що охоче служать Погибелі. Коли їх побільшало, розвідники-скрадачі смерті, що проходили краєм, помітили ознаки неминучого військового збору, який загрожує шляхам постачання й заставам Відступників. Невеликі напади Відступників на хутір раз у раз зазнавали невдачі: їх відкидала голосна примара Найтлаш — баньші, що з'являється щоразу, коли її підвладним гнолам загрожує небезпека.",sectionIndex=1}
c["subzone:deadeye-shore"] = "28081c"
P.scopedClips["subzone:deadeye-shore"] = {scope="overview-body",sourceHash="148e57",hash="28081c",name="Берег Дедай",summary="Берег Дедай — обвіяний вітрами відтинок узбережжя на східному краю Дуротару, просто на схід від Яру Сухої Балки. Названі на згадку про легендарного вождя клану Кривавої Западини Кілроґґа Дедая, ці пустельні піски населяють здебільшого дикі раптори, скорпіди та здичавілі вепри.",section="Берег Дедай під червоними кручами центрального Дуротару дістав своє ім'я від Кілроґґа Дедая — одноокого вождя клану Кривавої Западини, що бився в Першій та Другій війнах. Згори пісок і скелясті виступи ледь помітно нагадують обрис черепа з порожньою очницею. Хоч тут немає великих поселень чи військових застав, берег аж ніяк не мирний: на пісках панує войовнича звірина, а потаємні культисти Палаючого Клинка, як відомо, спускаються до води зі своїх сховків у сусідніх ярах.",sectionIndex=1}
c["subzone:deathknell"] = "cbab43"
P.scopedClips["subzone:deathknell"] = {scope="overview-body",sourceHash="fe0f1a",hash="cbab43",name="Похоронний Подзвін",summary="Похоронний Подзвін — укріплене село у відлюдній долині південно-західних Галявин Тірісфалю. Це головне місце пробудження щойно звільненої нежиті, що виривається з хватки Короля-Ліча, аби приєднатися до Відступників. В облозі безтямних решток Погибелі, місцевих фанатиків і агресивної живності, поселення — суворе місце випробувань для тих, хто претендує на місце в королівстві Сильвани Віндраннер.",section="Схований за зубчастими пагорбами одразу на північ від кордону Срібнолісся, Похоронний Подзвін — місце, де щойно пробуджені мерці вперше розплющують очі на свою безрадісну дійсність. На відміну від більшості поселень Галявин Тірісфалю, що зберегли людські назви з часів загиблого Королівства Лордерон, Похоронний Подзвін свідомо перейменувала нежить, яка його зайняла. Саме містечко розколоте навпіл: Відступники вперто тримаються південної частини довкола старої церкви, а північна половина — разом із сільською кузнею — лишається заполонена безтямними зомбі Погибелі й здичавілими гулями. Добірні Вартові Смерті надійно тримають вузьку ущелину з долини замкненою від зайд, щоб місцеві доглядачі могли посвячувати новоприбулих у службу Королеві Баньші.",sectionIndex=1}
c["subzone:deathknell#faq1"] = "12836e"
P.scopedClips["subzone:deathknell#faq1"] = {scope="answer-only",sourceHash="66d659",hash="12836e",name="Похоронний Подзвін",question="Чому містечко перейменували на Похоронний Подзвін?",answer="Похоронний Подзвін перейменували після того, як він став поселенням нежиті, — на відміну від більшості громад Тірісфалю, що зберегли людські назви. Причина нової назви невідома."}
c["subzone:deathknell#faq2"] = "f3a75f"
P.scopedClips["subzone:deathknell#faq2"] = {scope="answer-only",sourceHash="a42ec4",hash="f3a75f",name="Похоронний Подзвін",question="Чому північну половину містечка заполонила нежить?",answer="Не кожен труп, піднятий після Третьої війни, вирвався на волю зі здоровим глуздом. Північний майдан села й кузню заполонили «Безтямні» — здичавілі зомбі, гулі й скелети, якими досі рухає залишкова воля Погибелі. Захисники Відступників регулярно вичищають їх, щоб роздобути спорядження й захистити церкву."}
c["subzone:deathknell#faq3"] = "6d204c"
P.scopedClips["subzone:deathknell#faq3"] = {scope="answer-only",sourceHash="35c231",hash="6d204c",name="Похоронний Подзвін",question="Що робить Багряний Хрестовий Похід біля Похоронного Подзвону?",answer="Загін Багряного Хрестового Походу тримає табір у пагорбах на південний схід від села. Фанатично віддані знищенню всієї нежиті без розбору, вони стежать за проходом, нападають із засідки на щойно пробуджених Відступників й обмінюються розвідданими з багряними твердинями в інших куточках Лордерона."}
c["subzone:deathknell#faq4"] = "d4eaea"
P.scopedClips["subzone:deathknell#faq4"] = {scope="answer-only",sourceHash="22c657",hash="d4eaea",name="Похоронний Подзвін",question="Чому Відступники не можуть користуватися місцевою золотою копальнею?",answer="Лощину Нічної Павутини — золоту копальню в скелях на північний захід від села — цілком заполонили агресивні павуки. Здобувати природні ресурси на кшталт золота вкрай важливо для воєнних зусиль Відступників, та поки навалу не вичищено, поселення не може розробляти жилу."}
c["subzone:decrepit-ferry"] = "e5e488"
P.scopedClips["subzone:decrepit-ferry"] = {scope="overview-body",sourceHash="7adc36",hash="e5e488",name="Ветха Переправа",summary="Ветха Переправа — зруйнований причал на східному березі Срібнолісся, звідки колись можна було переправитися через Озеро Лордамер на Острів Фенріс. Після падіння Лордерона пором знищили, перевізника вбили, а берег заполонили мерці й люті гнилошкірі гноли.",section="До Третьої війни цей причал щодня вирував рухом через Озеро Лордамер. Місцеві фермери привозили до води свіжі продукти й продавали врожай просто заможному володареві Острова Фенріс та його челяді. За помірну плату перевізник возив товари, гінців і знатних гостей між берегом і фортецею. Цій мирній торгівлі раптово настав кінець, коли королівством прокотилася Погибель. Перевізника жорстоко вбили, човни розтрощили, а пристань занепала.",sectionIndex=1}
c["subzone:deep-elem-mine"] = "d656d6"
P.scopedClips["subzone:deep-elem-mine"] = {scope="overview-body",sourceHash="242f8d",hash="d656d6",name="Шахта Глибокого Елему",summary="Шахта Глибокого Елему — копальня в самому серці Срібнолісся. Колись вона працювала, але її захопили, коли темна магія Архімага Аруґала прокотилася краєм і перетворила рудокопів на лютих воргенів.",section="Шахта Глибокого Елему, що лежить у центрі Срібнолісся, колись слугувала живим мешканцям Лордерона звичайною рудною жилою. Коли Архімаг Аруґал випустив на ліс вовчий кошмар, його дике прокляття проникло глибоко в тунелі. Робітники всередині піддалися недузі й обернулися на лютих воргенів, що покинули кайла й перетворили печеру на хиже лігво.",sectionIndex=1}
c["subzone:deeprun-tram"] = "1baa41"
P.scopedClips["subzone:deeprun-tram"] = {scope="overview-body",sourceHash="2689ae",hash="1baa41",name="Глибинний трамвай",summary="Глибинний трамвай — підземне диво гномської інженерії, що з'єднує столиці Альянсу Айронфордж і Стормвінд. Його збудували на замовлення Короля Маґні Бронзбірда після Другої війни, і тепер городяни й вояки долають величезні відстані під землею за лічені хвилини. Закриті подвійні колії пролягають під горами й озером і слугують життєво важливою артерією для військової підтримки й торгівлі Альянсу.",section="Після спустошень Другої війни Король Маґні Бронзбірд дедалі більше дратувався, бачачи, як повільно дворфійська допомога й будівельні матеріали дістаються до Стормвінда гірськими перевалами. Щоб розв'язати цю проблему й гарантувати, що дворфійські вояки зможуть швидко прийти на поміч людській столиці в скрутну годину, Маґні звернувся до Великого Тінкера Ґелбіна Меккаторка. Видатний гномський інженер розробив креслення закритої підземної залізниці, що працювала на найпередовіших технологіях. Попри всі труднощі прокладання — довелося пробиватися крізь величезне підземне озеро й без кінця воювати з навалами підземних щурів, — трамвай став вершинним досягненням Альянсу й безкоштовно перевозить тисячі мандрівників між Айронфорджем і Стормвіндом.",sectionIndex=1}
c["subzone:deepwater-tavern"] = "fdacad"
P.scopedClips["subzone:deepwater-tavern"] = {scope="overview-body",sourceHash="19992b",hash="fdacad",name="Таверна «Глибока Вода»",summary="Таверна «Глибока Вода» — гамірний приморський заїзд Гавані Менетіл серед вогких боліт Багнокраю. Це головне місце зустрічей, поповнення припасів і відпочинку для мандрівників і моряків, що проходять жвавим портовим містечком. Між щедрими чарками й портовими чутками відвідувачі часто знаходять роботу — або потрапляють у бурхливі шинкові бійки.",section="Таверна «Глибока Вода», що стоїть серед розмоклих вулиць Гавані Менетіл, дарує мандрівникам жаданий прихисток від вічно мрячних, підступних боліт за її стінами. Моряки, докери, купці й утомлені шукачі пригод збираються під її дерев'яними сволоками, щоб обмінятися новинами, погрітися біля вогню й залатати рани. Окрім звичних вигод портового заїзду, тут є свій наставник із першої допомоги та місцеві купці, що забезпечують тих, хто вирушає назустріч небезпекам боліт чи пливе за Велике Море. Атмосфера тут галаслива, а часом і небезпечна: суперечки через розлитий ель спалахують миттєво, а відомі забіяки на кшталт Тапоука «Сліма» Джана здатні зчинити бійку на всю таверну.",sectionIndex=1}
c["subzone:defias-hideout"] = "157cb4"
P.scopedClips["subzone:defias-hideout"] = {scope="overview-body",sourceHash="faa6d6",hash="157cb4",name="Схованка Дефіасу",summary="Схованка Дефіасу — непоказний занедбаний будинок на південному краю Мунбрука. Він зливається з довколишнім зруйнованим поселенням, але його горішній поверх ховає головний наземний вхід до розлогої підземної мережі Мертвих Копалень.",section="Для випадкового ока Схованка Дефіасу нічим не відрізняється від інших пограбованих садиб чи хат Мунбрука, де повно злиденних волоцюг і головорізів Дефіас. Проте її скромне нутро приховує нервовий центр південних операцій Едвіна Венкліфа. Піднявшись на горішній поверх, можна знайти отвір, що веде просто вниз — у розлогий лабіринт Мертвих Копалень. Братство кидає основні сили на охорону околиць Мунбрука й на роботи глибоко під землею, тож саму схованку охороняють нечисленно: це радше пильно стережене вузьке місце, ніж діюча твердиня.",sectionIndex=1}
c["subzone:demon-fall-canyon"] = "54c442"
P.scopedClips["subzone:demon-fall-canyon"] = {scope="overview-body",sourceHash="f9e781",hash="54c442",name="Каньйон Падіння Демона",summary="Каньйон Падіння Демона — понівечена, вражена скверною ущелина на півдні Ашенвалю. Це легендарне поле бою, де Ґроммаш Хеллскрім і Тралл зійшлися з володарем безодні Манноротом і поклали край демонічному прокляттю крові, що ціле покоління тримало орків у рабстві.",section="Цей каньйон, що врізався в суворі південні околиці Ашенвалю поблизу Пагорба Вогню Скверни та Хребта Падіння Демона, несе тяжкі шрами Третьої війни. Саме тут вождь Тралл і ватажок Ґроммаш Хеллскрім вистежили володаря безодні Маннорота, щоб зламати його владу над Ордою. У запеклому двобої Маннорот повалив Тралла, та Ґром скористався нагодою й увігнав свою сокиру, Ґоргаул, просто в груди демонові. Пекельний вибух розірвав володаря безодні, забрав і життя Ґрома, але назавжди звільнив орків від решток демонічного рабства.",sectionIndex=1}
c["subzone:demon-fall-ridge"] = "b5b494"
P.scopedClips["subzone:demon-fall-ridge"] = {scope="overview-body",sourceHash="05d291",hash="b5b494",name="Хребет Падіння Демона",summary="Хребет Падіння Демона — сплюндроване нагір'я на південному сході Ашенвалю, що височіє над каньйоном, де поліг Маннорот. Тут кишать дрібні демони й буяє згубна магія, а серце хребта — осквернене курганне лігво нічних ельфів, яке захопив Палаючий Легіон.",section="Хребет Падіння Демона, що здіймається просто на захід від Каньйону Падіння Демона й над ним, досі заплямований рештками скверни з часів Третьої війни. Якщо каньйон унизу — місце згубного зіткнення Ґроммаша Хеллскріма з володарем безодні Манноротом, то це нагір'я стало плацдармом для демонічних загарбників, що вціліли. Дрібні демони патрулюють скелясті кручі, оскверняючи давній ліс і загрожуючи кожному, хто йде південним кордоном Ашенвалю.",sectionIndex=1}
c["subzone:demont-s-place"] = "f94753"
P.scopedClips["subzone:demont-s-place"] = {scope="overview-body",sourceHash="f9cd5f",hash="f94753",name="Обійстя Демонта",summary="Обійстя Демонта — зруйнована садиба на південному заході Вестфолу, трохи на захід від покинутого містечка Мунбрук. Колись тут була робоча ділянка, але ферма занепала разом із рештою краю, і її захопили свавільні агенти Братства Дефіас. Нині її вивітрені огорожі й порожні поля — ще одна жертва згаслого добробуту королівства.",section="Обійстя Демонта, звідки видно Мунбрук і гниючі простори Мертвого Лану, колись було серед приватних родинних господарств, що годували Королівство Стормвінд. Господарський занепад і раптова поява розбійницьких ватаг позбавили ферму засобів до життя й вигнали її господарів. Як і сусідні поля, ділянка перетворилася на грубий сховок, де хазяйнують розбійники, що використовують занедбане подвір'я як продовження твердині Дефіас у Мунбруку.",sectionIndex=1}
c["subzone:dolanaar"] = "9a55f2"
P.scopedClips["subzone:dolanaar"] = {scope="overview-body",sourceHash="8ee96d",hash="9a55f2",name="Доланаар",summary="Доланаар — тихе поселення нічних ельфів у центрально-східному гіллі Тельдрассила. Розташоване на південний захід від Тінедолу, воно стає першим справжнім містечком, яке бачать молоді калдореї, залишивши захищені землі навчання. Тут збираються слідопити, друїди й ремісники, щоб скеровувати новачків і давати раду дивним недугам, що насуваються на Світове Дерево.",section="Доланаар, що лежить під пишною кроною на південний захід від Тінедолу, — важливе перехрестя для мандрівників Тельдрассила. Збудований у традиційній манері нічних ельфів, він гармонійно вплітає свої оселі й помости в ліс. Селище дає новачкам перше повне навчання в ремеслах, бойовому мистецтві й природних уміннях і стоїть на дорозі до столиці — Дарнасуса. Завдяки центральному розташуванню звістки про зіпсуту живність, агресивних фурболгів і нечистий мох із довколишнього гілля неминуче потрапляють до ради Доланаара.",sectionIndex=1}
c["subzone:dor-danil-barrow-den"] = "bd0b28"
P.scopedClips["subzone:dor-danil-barrow-den"] = {scope="overview-body",sourceHash="6c967e",hash="bd0b28",name="Курганне Лігво Дор'Даніл",summary="Курганне Лігво Дор'Даніл — давнє святилище нічних ельфів, висічене в землі центрального Ашенвалю, на південь від Застави Розщепленого Дерева. Колись тут тихо спочивали друїди, чиї духи мандрували Смарагдовим Сном, але після втручання Відступників, які відтяли духи сновидців від тіл, у лігві запанував жах.",section="Курганні лігва по всьому Калімдору — шановані святилища, де друїди нічних ельфів віками спали, мандруючи Смарагдовим Сном, поки їхні смертні тіла лежали в безпеці під землею. Коли Орда просунулася в Ашенваль, Дор'Даніл опинився глибоко в тилу ворога. Орки здебільшого не зважали на непритомних ельфів, але Відступники, нові союзники Орди, побачили в цьому нагоду. Їхні агенти пробралися в глибини й почали моторошні досліди, щоб відтяти сплячих друїдів від їхніх духів, — це розколювало розум сновидців і безнадійно зводило їх з глузду. Тепер у темних проходах кишать зловісні вбивці Відступників і люті, збожеволілі від мук духи друїдів, що вже не можуть повернутися до своїх тіл.",sectionIndex=1}
c["subzone:dormitory"] = "abbe21"
P.scopedClips["subzone:dormitory"] = {scope="overview-body",sourceHash="341d08",hash="abbe21",name="Гуртожиток",summary="Гуртожиток — житловий сектор у занепалій технологічній столиці Гномреґані. Колись тут жили незліченні гноми-містяни, а тепер він задушений радіоактивними викидами й кишить лютими опроміненими трогами.",section="Гуртожиток, що лежить одразу за камерами знезараження Чистої Зони, колись давав дах винахідникам, робітникам і родинам Гномреґана. Коли Великий Тінкер Меккаторк наказав аварійно випустити радіацію, щоб відбитися від навали трогів, цей густонаселений сектор став пасткою. Сьогодні його спільні зали й житлові відсіки цілком покинуті гномами — натомість тут хазяйнують мутовані троги, яким добре в радіоактивному мареві. Мандрівники, що спускаються до нижніх ярусів міста, мусять пробиватися крізь це трагічне нагадування про катастрофу, щоб дістатися нижньої частини Зали Шестерень.",sectionIndex=1}
c["subzone:drag"] = "21014d"
P.scopedClips["subzone:drag"] = {scope="overview-body",sourceHash="d56dd9",hash="21014d",name="Прохід",summary="Прохід — гамірна, затінена вулиця, висічена в червоній скелі Оргріммара, що з'єднує Долину Сили з Долиною Честі й Долиною Мудрості. По всьому Дуротару її знають як серце торгівлі в столиці: уздовж стін каньйону тягнуться майстерні ремісників, крамарів і умільців. Тут же ховається печерний спуск до сумнозвісної Тіньової Розколини.",section="Прохід, що тулиться глибоко між червоними стінами каньйону Оргріммара, — торговельний хребет столиці Орди. Долина Сили зосереджена на військових зборах і управлінні, а в Проході вирує щоденне міське життя. Під навісами з високих скель і шкур вулиця сповнена запахів дубильних чанів, булькотіння алхімічних казанів і брязкоту механізмів умільців. Тут збираються майстри майже всіх ремесел, щоб працювати й навчати молодих шукачів пригод, — від шкірництва й кравецтва до гоблінських інженерних майстерень, як-от «Механічна майстерня Ноґґа».",sectionIndex=1}
c["subzone:dreadmist-den"] = "28d0ad"
P.scopedClips["subzone:dreadmist-den"] = {scope="overview-body",sourceHash="bfbc49",hash="28d0ad",name="Лігво Жахливої Імли",summary="Лігво Жахливої Імли — підземна печера під скелями Піку Жахливої Імли на півночі Пусток. Її контролює культ Палаючого Клинка: печеру постійно огортає моторошний червоний серпанок, а сама вона слугує святилищем для поклоніння демонам.",section="Лігво Жахливої Імли ховається серед зубчастих схилів Піку Жахливої Імли й править культистам Палаючого Клинка за темне святилище. Усередині стоїть густа багряна пара, що огортає печеру моторошними сутінками. Далеко від пильного ока Орди на рівнинах унизу культ проводить у цих кам'яних тунелях мерзенні демонічні обряди, стереже свої блюзнірські реліквії й замишляє поширити скверну по всьому Калімдору.",sectionIndex=1}
c["subzone:dreadmist-peak"] = "83db0b"
P.scopedClips["subzone:dreadmist-peak"] = {scope="overview-body",sourceHash="3cdf3d",hash="83db0b",name="Пік Жахливої Імли",summary="Пік Жахливої Імли — зубчаста безлюдна гора, що здіймається на північний захід від Перехрестя в Пустках. Оповитий неприродним багряним маревом, пік став відлюдним прихистком для демонічних культистів Палаючого Клинка.",section="Пік Жахливої Імли, що височіє над посушливими саванами Пусток, вирізняється відчутним злом. Коли мандрівники піднімаються скелями, яскраве небо затуляє густий червонуватий серпанок — залишкове марево давнього демонічного прокляття. На вершині гори й у її підземних порожнинах таємно діє культ Палаючого Клинка, даючи прихисток чорнокнижникам, отруйникам і мерзенним греллам. Звідси культисти отруюють ближні підземні води й плетуть інтриги проти молодих сил, що встановлюють владу над центральним Калімдором.",sectionIndex=1}
c["subzone:dreamer-s-rock"] = "126d8e"
P.scopedClips["subzone:dreamer-s-rock"] = {scope="overview-body",sourceHash="38714f",hash="126d8e",name="Скеля Сновидця",summary="Скеля Сновидця — відлюдне природне святилище глибоко в Печерах Стогонів, за Волаючим Яром. Тут спить друїд із нічних ельфів Наралекс, чиє шляхетне прагнення відродити Пустки натомість породило живе жахіття. Це водночас і священна підземна обитель, і осердя порчі, що спотворює довколишній підземний світ.",section="Скеля Сновидця, що лежить у серці Печер Стогонів, — щось на кшталт імпровізованої підземної обителі друїдів. Саме тут друїд із нічних ельфів Наралекс поринув у глибокий транс, щоб дістатися підземних джерел і спрямувати Смарагдовий Сон у посушливий ґрунт Пусток. Та замість принести життя, його зв'язок перехопили темні сили. Жахіття, що спотворює його думки, тепер вихлюпується в цю залу наяву: воно калічить місцевих звірів, обертає його послідовників на отруйних Друїдів Ікла й виводить у світ живих страхітливих потвор.",sectionIndex=1}
c["subzone:dry-hills"] = "f72316"
P.scopedClips["subzone:dry-hills"] = {scope="overview-body",sourceHash="56cb96",hash="f72316",name="Сухі Пагорби",summary="Сухі Пагорби — порізаний північно-західний куточок Пусток, що притулився до передгір'їв Гір Кам'яного Кігтя. Всупереч назві, ця височина помітно зеленіша за посушливі рівнини внизу, проте має лиху славу через агресивних гарпій Відьмокрилих, що гніздяться на її скелях.",section="Сухі Пагорби, що сховалися там, де посушливі рівнини здіймаються до Гір Кам'яного Кігтя, носять не надто влучну назву: зелених кущів і чагарників тут значно більше, ніж у вибілених сонцем саванах на півдні. Та цей буйний передгірний край не обіцяє мандрівникам безпеки. На кручах панують гарпії Відьмокрилі на чолі з матріархинею Сереною Бладфезер. З цих висот їхні загони кидаються вниз на каравани з припасами, що йдуть північною ділянкою Золотого Шляху, а в чагарниках гниють покинуті орківські укріплення й зламані облогові машини.",sectionIndex=1}
c["subzone:drygulch-ravine"] = "f5a3f0"
P.scopedClips["subzone:drygulch-ravine"] = {scope="overview-body",sourceHash="8027f2",hash="f5a3f0",name="Яр Сухої Балки",summary="Яр Сухої Балки — сувора прихована ущелина серед скелястих круч східного Дуротару. Потрапити сюди можна лише через непримітний печерний прохід із Каньйону Гострого Вітру або небезпечним стрибком згори. У цьому скелястому рові гніздяться гарпії Пилового Вітру, що загрожують сусіднім обозам із припасами.",section="Глибоко врізаний у скелі на схід від Оргріммара, Яр Сухої Балки майже повністю відрізаний від звичайних мандрівників. Єдиний наземний доступ — тісний природний тунель, що веде з Каньйону Гострого Вітру. У цій захищеній западині, яку живить невелика річка, колись мирно жили орки, та дикі звірі й гарпії Пилового Вітру, які тут гніздяться, перетворили її на беззаконний закуток Дуротару. Крилаті падложерки влаштовують на крутих скелях гнізда для виводків і складають награбоване з обозів Орди, що проходять місцевими стежками.",sectionIndex=1}
c["subzone:dun-algaz"] = "b0dabe"
P.scopedClips["subzone:dun-algaz"] = {scope="overview-body",sourceHash="d2d9c7",hash="b0dabe",name="Дун Алґаз",summary="Дун Алґаз — укріплений гірський перевал і мережа тунелів, що з'єднують Лох Модан із Багнокраєм. За нього точилися бої ще в Другу війну, а нині цю важливу торгову артерію взяли в облогу орки Драконячої Пащі, перерізавши зручний шлях між землями Айронфорджа та Гаванню Менетіл.",section="Дун Алґаз старший за Війну Трьох Молотів: колись цим проходом Вайлдгаммери рушили на північ, коли їх вигнали з Айронфорджа. Перевал, глибоко врізаний у зубчасті вершини між Лох Моданом і Багнокраєм, складається з широких кам'яних тунелів, бастіонів і сторожових постів. Його стратегічне значення годі переоцінити: хто тримає Дун Алґаз, той контролює єдиний сухопутний шлях, що поєднує серце дворфійських земель із західним морем біля Гавані Менетіл.",sectionIndex=1}
c["subzone:dun-garok"] = "f8a4c1"
P.scopedClips["subzone:dun-garok"] = {scope="overview-body",sourceHash="6fb92e",hash="f8a4c1",name="Дун Ґарок",summary="Дун Ґарок — укріплений дворфійський гірський оплот на південно-східних висотах Передгір'я Гілсбреда. Під командуванням Капітана Айронгілла стійкий гарнізон застави боронить інтереси Альянсу в краї та ближні об'єкти на кшталт Шахти Лазурової Жили від ворожого наступу. Для Відступників Таррен Мілла ця вкорінена дворфійська твердиня — постійна військова загроза біля їхніх володінь.",section="Дун Ґарок, вирубаний у скелястих південно-східних пагорбах Передгір'я Гілсбреда, — добре укріплений редут айронфорджських горян і стрільців. Під командуванням Капітана Айронгілла дворфи тримають тут важливий оборонний рубіж, прикриваючи людські поселення Гілсбреда й захищаючи важливі роботи в Шахті Лазурової Жили. Міцна кам'яна архітектура й глибокі окопи дають Альянсові опору проти загроз поблизу.",sectionIndex=1}
c["subzone:dun-modr"] = "324625"
P.scopedClips["subzone:dun-modr"] = {scope="overview-body",sourceHash="9db83d",hash="324625",name="Дун Модр",summary="Дун Модр — прадавнє укріплене дворфійське містечко на півночі Багнокраю, що стереже південний підступ до Мосту Тандол. Колись важлива фортеця, яку утримували й за яку билися в кількох війнах, нещодавно впала під ударом ворожого війська дворфів Темного Заліза.",section="Дун Модр, що стоїть на північному краю Багнокраю, панує над головним сухопутним шляхом, який поєднує Каз Модан із північними людськими королівствами. Через таке важливе розташування твердиня за десятиліття бачила чимало крові. Під час Другої війни Орда захопила дворфійську фортецю й окопалася в ній, зробивши її передовим плацдармом для нападів і відсічі арміям Альянсу. Воїни Стромґарда здійснили жорстокий десант із Тол Барада, щоб відвоювати її, але орки вдарили у відповідь, і почалося криваве перетягування. Зрештою сили Альянсу під проводом лорда Андуїна Лотара відкинули загарбників на південь, за Міст Тандол, і повернули бастіон дворфам.",sectionIndex=1}
c["subzone:durnholde-keep"] = "3ca4cb"
P.scopedClips["subzone:durnholde-keep"] = {scope="overview-body",sourceHash="39b98e",hash="3ca4cb",name="Твердиня Дурнгольд",summary="Твердиня Дурнгольд — зруйнована фортеця на схід від Таррен Мілла в Передгір'ї Гілсбреда. Колись тут був осередок орківських таборів для інтернованих, які тримав Альянс, і саме тут виріс як бранець-гладіатор Вождь Тралл. Нині фортеця лежить у руїнах, а в ній засіли злочинці Синдикату.",section="Дурнгольд, збудований Альянсом, після Другої війни став штабом, що наглядав за південними таборами для інтернованих. Під командуванням честолюбного й продажного генерал-лейтенанта Еделаса Блекмура він був водночас адміністративною фортецею й гладіаторською ареною. Саме тут Блекмур виховав осиротілого малюка Ґо'ела, назвавши його Траллом і навчаючи битися заради розваги й наживи. З допомогою Тарети Фокстон Тралл утік з неволі, а згодом об'єднав розпорошені орківські клани під прапором нової Орди. Повернувшись до Дурнгольда, Тралл узяв фортецю в облогу, вбив Блекмура й закликав духів землі зруйнувати її стіни.",sectionIndex=1}
c["subzone:dust-plains"] = "8b3efe"
P.scopedClips["subzone:dust-plains"] = {scope="overview-body",sourceHash="055095",hash="8b3efe",name="Курні Рівнини",summary="Курні Рівнини — суха, вичесана вітрами південна околиця Вестфолу. Посушлива земля, рідкі чагарники, войовничі табори гнолів, а на східному узвишші — стара вежа чарівника.",section="Курні Рівнини простягаються південним Вестфолом там, де неспокійні ферми переходять у безлюдну глушину. На відміну від пограбованих хуторів на півночі, цей посушливий край давно віддали зграям здичавілих гнолів: вони влаштовують засідки на подорожніх і кидаються на кожного, хто прямує до узбережжя чи сусідніх пагорбів. На східній межі стоїть Вежа Мортвейка — самотній притулок мага, де від звірів, що блукають довколишніми пустищами, не сховаєшся.",sectionIndex=1}
c["subzone:dustwind-cave"] = "e5c0d4"
P.scopedClips["subzone:dustwind-cave"] = {scope="overview-body",sourceHash="3bf4ca",hash="e5c0d4",name="Печера Пилового Вітру",summary="Печера Пилового Вітру — відлюдна западина на вершині скель Каньйону Гострого Вітру, просто на північний схід від Гострого Пагорба. Вона служить діючим тренувальним майданчиком і таємним притулком для посвячуваних лиховісного культу Палаючого Клинка, що діє в Дуротарі.",section="Печера Пилового Вітру, що височіє над Каньйоном Гострого Вітру, — одна з найближчих і найнебезпечніших загроз Гострому Пагорбу. Багато хто гадає, що демонічні культисти збираються лише в глибоких підземеллях, та тут Палаючий Клинок навчає новобранців просто під носом у влади Орди. Потаємні культисти навчають посвячуваних забороненої темної магії та демонології, готуючи їх підривати молоду орківську державу зсередини кордонів самого Дуротару.",sectionIndex=1}
c["subzone:eastvale-logging-camp"] = "d1db3b"
P.scopedClips["subzone:eastvale-logging-camp"] = {scope="overview-body",sourceHash="466931",hash="d1db3b",name="Лісозаготівельний Табір Східної Долини",summary="Лісозаготівельний Табір Східної Долини — важливе лісорубне поселення у східних лісах Лісу Елвінн, поблизу кордону з Горами Редріджу. Табір постачає конче потрібну деревину Стормвінду й навколишнім поселенням, та його роботі невпинно заважають голодні хижаки, що нишпорять довколишніми лісами.",section="Замовлення на деревину безперервно надходять до Лісозаготівельного Табору Східної Долини від покупців з усього королівства Стормвінд, та вкластися в суворі терміни — справа нелегка. Густі хащі довкола табору кишать лютими вовками й ведмедями, які раз у раз проганяють лісорубів із ділянок, і цінний зрубаний ліс лишається покинутим у хащах. Під керівництвом Наглядачки Рейлен табір часто покладається на мандрівних шукачів пригод, щоб винищити звірину, яка насувається, і забрати повалені колоди, поки доставки не відстали безнадійно.",sectionIndex=1}
c["subzone:echo-isles"] = "6cc88c"
P.scopedClips["subzone:echo-isles"] = {scope="overview-body",sourceHash="97ad58",hash="6cc88c",name="Острови Відлуння",summary="Острови Відлуння — гроно тропічних островів просто біля південно-східного узбережжя Дуротару. Спершу їх заселили тролі Темного Списа, що втекли зі своїх прадавніх островів, та нині архіпелаг втрачено: відступник-знахар Залазан вигнав свій народ темною магією та поневоленими поплічниками.",section="Після втечі через Велике Море разом із Траллом плем'я Темного Списа обрало Острови Відлуння своїм новим домом. Та їхній мир руйнували знову і знову: спершу флот Великого Адмірала Дейліна Праудмура під час вторгнення Кул Тірасу в Дуротар, а потім — зрада зсередини. Невдовзі після того, як тролі відбили флот Праудмура, один з їхніх власних знахарів, Залазан, узявся за темні мистецтва, щоб поневолити розум одноплемінників. Вождь Вол'джин і вільні тролі Темного Списа були змушені знову залишити острови й шукати тимчасового притулку по той бік вузької протоки, у Селі Сен'джин.",sectionIndex=1}
c["subzone:echo-ridge-mine"] = "ff2135"
P.scopedClips["subzone:echo-ridge-mine"] = {scope="overview-body",sourceHash="9e4711",hash="ff2135",name="Шахта Ехо-Рідж",summary="Шахта Ехо-Рідж — невелика розробка, вирубана в північно-західних скелях Долини Нортширу. Багата на камінь і руду, вона нещодавно потрапила в лапи руйнівної навали кобольдів, що зупинила місцевий промисел Нортширу.",section="Схована в пагорбах над Абатством Нортшира, Шахта Ехо-Рідж мала постачати долині корисний камінь і метал. Натомість тунелі заполонили спритні кобольди й вигнали місцевих робітників. Маршал Макбрайд вважає цю навалу неприпустимою загрозою безпеці Нортширу та набору новобранців, тож посилає новачків просто в тунелі, щоб прорідити кобольдів і повернути шахту.",sectionIndex=1}
c["subzone:elder-rise"] = "fb0d0d"
P.scopedClips["subzone:elder-rise"] = {scope="overview-body",sourceHash="7ed989",hash="fb0d0d",name="Узвишшя Старійшин",summary="Узвишшя Старійшин лежить на схід від центрального плато Тандер Блафа; дістатися туди можна довгими підвісними мостами і з Високого, і з Середнього Узвишшя. Це духовне серце тауренської столиці: тут Коло Кенарія, тауренські друїди й жерці та Рада Старійшин, що править містом.",section="Узвишшя Старійшин, з'єднане з головними столовими горами хиткими мотузяними мостами, віддане тихим роздумам, священній мудрості й громадському правлінню. Тауренські друїди й жерці збираються тут, щоб навчати послушників шляхів природи й духовного служіння. Високо на цій горі живе Верховний Друїд Гамуул Рунтотем — шанований провідник, що повернув друїдство тауренам і налагодив тісні зв'язки з Колом Кенарія. Поруч із цими дикими святилищами стоїть Зала Старійшин, де вожді племен радяться над справами молодої столиці.",sectionIndex=1}
c["subzone:engineering-labs"] = "78614a"
P.scopedClips["subzone:engineering-labs"] = {scope="overview-body",sourceHash="5c6d3a",hash="78614a",name="Інженерні Лабораторії",summary="Інженерні Лабораторії — багатоярусний дослідницько-виробничий комплекс глибоко в Гномреґані. Цей гамірний осередок гномської винахідливості, з'єднаний із Входом до Майстерні та Стартовим відсіком, було захоплено під час радіоактивного катаклізму міста, і тепер тут кишать божевільні гноми-прокажені та некеровані механічні пристрої.",section="Інженерні Лабораторії, збудовані довкола центральної механічної споруди, займають два головні яруси, з'єднані центральним вантажним підйомником. У часи розквіту Гномреґана тутешні майстри розробляли креслення й доводили до ладу заводні винаходи. Сьогодні витоки радіації звели з глузду дослідників, що лишилися, перетворивши їх на шалених гномів-прокажених, які бездумно стережуть несправні машини разом із некерованими механізмами.",sectionIndex=1}
c["subzone:falfarren-river"] = "5c55e3"
P.scopedClips["subzone:falfarren-river"] = {scope="overview-body",sourceHash="51165e",hash="5c55e3",name="Річка Фалфаррен",summary="Річка Фалфаррен тече з північного сходу на південний захід через серце Ашенвалю: вона бере початок на схилах Гори Гіджал, а потім ховається під землю під північними горами Пусток. Річка — природний кордон між володіннями нічних ельфів довкола Астранаару на заході та заставами Орди, що наступають зі сходу. Мандрівникам варто бути обережними: тінисті береги й мілини — прихисток ворожих звірів і край відкритої війни.",section="Спускаючись із Гори Гіджал, води Фалфаррену водоспадами збігають у Ксавіан, а потім петляють між Заставою Розщепленого Дерева й Нічним Потоком. Річка не надто глибока і за звичайної погоди цілком прохідна, проте саме вона приблизно ділить центральний Ашенваль між ворожими сторонами. На заході лежать Астранаар і головні володіння калдореїв, на сході — табори й лісорубні Орди. Перейшовши дерев'яні мости головної дороги, мандрівник опиняється у спірному серці лісу, де вздовж берегів сходяться патрулі.",sectionIndex=1}
c["subzone:fallen-sky-lake"] = "3756b1"
P.scopedClips["subzone:fallen-sky-lake"] = {scope="overview-body",sourceHash="081bac",hash="3756b1",name="Озеро Впалого Неба",summary="Озеро Впалого Неба — відлюдна водойма в глибині лісів східного Ашенвалю. Воно лежить між Заставою Срібнокрилих і Трудовим Табором Бойової Пісні, що дедалі ближче підступає, а його спокійні води таять небезпеку: лісові створіння Тінявої Хащі люто захищають озеро та острів посередині.",section="Озеро Впалого Неба, що сховалося на південь від Застави Срібнокрилих і трохи на захід від Трудового Табору Бойової Пісні, дає змогу на мить побачити природну пишноту Ашенвалю такою, якою вона була, доки поблизу не застукотіли орківські сокири. Береги й острівець посеред озера населяють створіння Тінявої Хащі — осквернені чи просто ревниві до своєї землі лісовики, для яких будь-який двоногий прибулець — загроза. Серце острова — володіння могутнього Оракула Тінявої Хащі, чия присутність прив'язує місцевих лісовиків до гаю й робить їх невсипуще пильними до мандрівників.",sectionIndex=1}
c["subzone:faol-s-rest"] = "4bb020"
P.scopedClips["subzone:faol-s-rest"] = {scope="overview-body",sourceHash="fd5612",hash="4bb020",name="Спочинок Фаола",summary="Спочинок Фаола — тихе, занедбане поховання у східних Галявинах Тірісфалю, одразу на південний захід від Багряного Монастиря. Його звели як гробницю Архієпископа Алонсуса Фаола — шанованого духовного патріарха, що заснував Лицарів Срібної Длані. Сьогодні, занедбане під ураженою чумою кроною, воно править за цвинтар, де повертаються до життя ті, хто загинув біля монастиря.",section="До того як Третя війна спустошила Лордерон, ця відлюдна улоговина була місцем урочистого паломництва. Тут стоїть кам'яна гробниця Архієпископа Алонсуса Фаола, який вів Церкву Святого Світла крізь темні дні Другої війни й заснував орден паладинів, щоб захищати людство. Фаол мирно відійшов до приходу Погибелі, уникнувши смертної муки бачити падіння свого королівства. У ті світліші роки скорботні регулярно йшли дорогою зі столичного міста Лордерона, щоб лишити дари й ушанувати улюбленого патріарха.",sectionIndex=1}
c["subzone:far-watch-post"] = "9c70ba"
P.scopedClips["subzone:far-watch-post"] = {scope="overview-body",sourceHash="00c02b",hash="9c70ba",name="Далека Дозорна Застава",summary="Далека Дозорна Застава — укріплений аванпост Орди трохи на захід від мосту через Річку Південної Люті, що з'єднує Дуротар із Пустками. Як передова лінія оборони орківської батьківщини, застава захищає важливі торгові каравани від агресивних зграй шипогривів і ворожих вилазок Альянсу.",section="Далека Дозорна Застава, що стоїть біля західного підніжжя мосту з Дуротара, — перший оплот влади Орди, який бачать мандрівники, вступаючи в неозору посушливу савану Пусток. Поселення аскетичне, але практичне: його будували заради бойової готовності, а не зручності. Тут є міцна орківська сторожова вежа, землянка й облогові катапульти, заздалегідь наведені на курні рівнини. Просто на південь від головної дороги робітники доглядають загін верхових вовків, готових нести гінців чи підкріплення. Застава існує насамперед для того, щоб тримати в безпеці шлях постачання до Перехрестя: перевіряти подорожніх і відбивати набіги кочових племен шипогривів і потайних розвідників Альянсу.",sectionIndex=1}
c["subzone:fargodeep-mine"] = "9f224e"
P.scopedClips["subzone:fargodeep-mine"] = {scope="overview-body",sourceHash="b62015",hash="9f224e",name="Копальня Фарґодіп",summary="Копальня Фарґодіп — покинута золота копальня в центральному Лісі Елвінн, на південь від Ґолдшира. Колись прибуткове джерело багатства королівства Стормвінд, нещодавно її захопив войовничий клан кобольдів.",section="Копальня Фарґодіп колись давала сталий потік золота до скарбниці Стормвінда, та через дедалі меншу військову присутність королівства в Елвінні віддалені ресурси лишилися беззахисними. Кобольди швидко заполонили темні тунелі й облаштували під пагорбами гамірне кубло. Маршал Дуґан і місцева влада Ґолдшира дивляться на навалу з глибокою тривогою — не лише через втрачену руду, а й тому, що знахабнілі створіння тепер загрожують сусіднім садибам на кшталт володінь Стоунфілдів і Маклюрів.",sectionIndex=1}
c["subzone:fel-rock"] = "e83d1d"
P.scopedClips["subzone:fel-rock"] = {scope="overview-body",sourceHash="e05be4",hash="e83d1d",name="Скеля Скверни",summary="Скеля Скверни — уражена печера, схована в лісі одразу на північ від Доланаара на гіллі Тельдрассила. Колись тиха улоговина, вона занепала під впливом сатира Лорда Меленаса та його орди лютих ґреллів.",section="Скеля Скверни в лісистих пагорбах на північ від Доланаара колись була звичайною мирною печерою, вирізьбленою в дереві й камені Тельдрассила. Сьогодні це тривожне нагадування про заразу, що підкрадається до Світового Дерева. Покручене коріння й неприродні тіні панують у нутрі печери, яку заполонили рої диких ґреллів і ґреллят.",sectionIndex=1}
c["subzone:felfire-hill"] = "74c48b"
P.scopedClips["subzone:felfire-hill"] = {scope="overview-body",sourceHash="9e244c",hash="74c48b",name="Пагорб Вогню Скверни",summary="Пагорб Вогню Скверни — сплюндроване, заполонене демонами узвишшя на сході Ашенвалю. Під час Третьої війни сюди падали інфернали, і зіпсована земля досі палає демонічною силою. Орда тримає укріплені пости на мостах, що ведуть до пагорба, щоб захистити свої ближні поселення.",section="Під час нищівного вторгнення Третьої війни на Калімдор сипалися вогняні метеори: Палаючий Легіон кидав у бій своїх грізних інферналів. Кілька тих вогняних велетнів ударили в цей пагорб в Ашенвалі, випаливши давній ліс і отруївши саму землю. Сьогодні випалений край досі просякнутий енергією скверни, і тут никають демони, що пережили поразку Легіону біля Гори Гіджал.",sectionIndex=1}
c["subzone:fenris-isle"] = "4f262a"
P.scopedClips["subzone:fenris-isle"] = {scope="overview-body",sourceHash="065146",hash="4f262a",name="Острів Фенріс",summary="Острів Фенріс — великий, оповитий туманом острів на Озері Лордамер біля східного краю Срібнолісся. Колись тут стояла гамірна військова твердиня Лордерона, а тепер острів у залізних лабетах гнилошкірих гнолів-нежиті й некроманта-ренегата з Погибелі.",section="До того як Третя війна спустошила північний Лордерон, Острів Фенріс був важливою заставою королівства, опорою якої була Фортеця Фенріс. Коли Погибель пройшлася королівством, гарнізон вирізали або ж він утік у вигнання, і острів дістався мерцям. Відтоді острів став твердинею гнилошкірих гнолів — мерзенних, уражених чумою створінь, що збудували грубу імперію на берегах озера. Відступники Срібнолісся пильно стежать за островом, вважаючи його вкорінених мешканців серйозною загрозою своїм північним землям.",sectionIndex=1}
c["subzone:fenris-keep"] = "639b92"
P.scopedClips["subzone:fenris-keep"] = {scope="overview-body",sourceHash="193151",hash="639b92",name="Фортеця Фенріс",summary="Фортеця Фенріс — відокремлена кам'яна фортеця на Острові Фенріс посеред Озера Лордамер. Колись стратегічна твердиня, де стояли війська Лордерона, тепер вона в руках Погибелі під орудою мага-ренегата Тула Рейвенклова.",section="До Третьої війни Фортеця Фенріс мала стратегічне значення для королівства Лордерон: тут стояв чималий загін, що охороняв Озеро Лордамер. Коли нежить Погибелі прокотилася краєм, острівна фортеця впала разом із рештою королівства. Замість обернутися на забуті руїни, її захопив Тул Рейвенклов — зрадник, колишній чарівник Кірін-Тору. Рейвенклов став союзником Погибелі, мерзенною некромантією підкорив місцевих гнолів, створивши ненажерливу зграю гнилошкірих, і окопався глибоко в кам'яних залах фортеці.",sectionIndex=1}
c["subzone:field-of-giants"] = "941b6c"
P.scopedClips["subzone:field-of-giants"] = {scope="overview-body",sourceHash="346d7d",hash="941b6c",name="Поле Велетнів",summary="Поле Велетнів — широка рівнина на півдні Пусток між Табором Тауражо й Багном Пилоброду. Назву вона отримала від велетенських кодо, громоящерів та інших могутніх звірів, що пасуться в посушливих чагарниках, а останнім часом стала значно небезпечнішою через навалу силітидів.",section="Поле Велетнів, що простягається вздовж південної ділянки Золотого Шляху, — віддалений, суворий і погано захищений край порівняно з північними Пустками. Дерев'яні сторожові вежі при дорозі здебільшого покинуті, але сама земля вирує життям. Величезні стада велетенських звірів Калімдору блукають безкраїми рівнинами, приваблюючи і мисливців, і дослідників природи. Проте безпеки тут не знайти: дворфи-копачі з Бель Модана завзято риють на півдні, а під землею почала прокладати ходи значно зловісніша загроза.",sectionIndex=1}
c["subzone:fire-scar-shrine"] = "5ebf2c"
P.scopedClips["subzone:fire-scar-shrine"] = {scope="overview-body",sourceHash="bf1807",hash="5ebf2c",name="Святилище Вогняного Шраму",summary="Святилище Вогняного Шраму — сплюндроване святилище нічних ельфів у південно-західних лісах Ашенвалю. Колись тихе місце молитви, тепер воно осквернене демонічними силами й перетворилося на виразку скверни просто на порозі Астранаару.",section="Святилище Вогняного Шраму, що лежить на південний захід від Астранаару й на захід від Руїн Зоряного Пилу, похмуро нагадує про отруту Палаючого Легіону, яка досі лишається в Ашенвалі. Святилище піддалося демонічній скверні, яку плекають слуги таємничого Культу Темного Берега та Ради Тіней. Магія скверни перетворила довколишню землю на випалений камінь, де тепер збираються демони, відкрито кидаючи виклик захисникам лісу.",sectionIndex=1}
c["subzone:forest-s-edge"] = "414c7e"
P.scopedClips["subzone:forest-s-edge"] = {scope="overview-body",sourceHash="53fdf9",hash="414c7e",name="Узлісся",summary="Узлісся — лісистий клин землі на південно-західному порубіжжі Лісу Елвінн, обабіч якого течуть річки в бік Вестфолу. З півночі його прикриває Гарнізон Вестбрук, та ці дикі землі небезпечно заполонили гноли Річколапи під проводом горезвісного Гоґґера.",section="Узлісся на південний захід від Стормвінда, між Садом Дзеркального Озера та річками на кордоні з Вестфолом, утворює природний лісистий півострів. Попри близькість Гарнізону Вестбрук, рідкі лави армії Стормвінда лишили цей край беззахисним перед дикими звірами й загонами нападників. Серед дерев і вздовж берегів блукають вепри, та справжня загроза — скупчення гнолів Річколапів, які зробили ці ліси своїм плацдармом.",sectionIndex=1}
c["subzone:forest-song"] = "3bdab4"
P.scopedClips["subzone:forest-song"] = {scope="overview-body",sourceHash="f497e4",hash="3bdab4",name="Лісова Пісня",summary="Лісова Пісня — давні руїни нічних ельфів на північному сході Ашенвалю, неподалік від оскверненого лісу Сатирнаару та великого порталу в Тіні Віття. Нині тут майже безлюдно — лише пильний друїд Кейнет Стіллвінд стереже східний кордон від нових загроз.",section="Лісова Пісня, що сховалася в густих лісах північно-східного Ашенвалю, колись була вишуканим поселенням калдореїв. Сьогодні білі кам'яні колони й напівзруйновані арки поросли плющем і дикою папороттю. Руїни лежать на північний схід від Сатирнаару й трохи на північ від Лісозаготівельного Табору Бойової Пісні, що дедалі розростається, і з них відкривається тихий, але важливий огляд на східні стежки до Азшари й Тіні Віття. Хоч довколишні ліси потерпають від демонічної скверни й вилазок Орди, у самих руїнах панує моторошний спокій.",sectionIndex=1}
c["subzone:forgotten-pools"] = "4d43d9"
P.scopedClips["subzone:forgotten-pools"] = {scope="overview-body",sourceHash="c40f4c",hash="4d43d9",name="Забуті ставки",summary="Забуті ставки — найпівнічніша із зелених оаз, розкиданих посушливими Пустками, трохи на північний захід від Перехрестя. Цей яскравий куточок буйної зелені й води живлять підземні джерела, і за нього запекло змагаються місцеві звірі, кочові кентаври Колкари та Орда.",section="Забуті ставки, що лежать біля західної дороги з Перехрестя, разюче контрастують із висохлими саванами довкола. Густий очерет, пальми й незвичайні рослини на кшталт Налитих Грибів тісняться біля прісного берега, приваблюючи степових довгоступів, черепах-хижощелепів і жевр з усієї округи. Та оаза аж ніяк не мирна. Кентаври Колкари постійно стоять табором на берегах, ревниво стережучи воду від мандрівників, і раз у раз сходяться в сутичках із подорожніми Орди з Перехрестя.",sectionIndex=1}
c["subzone:forlorn-rowe"] = "aa814b"
P.scopedClips["subzone:forlorn-rowe"] = {scope="overview-body",sourceHash="53b742",hash="aa814b",name="Покинутий Ряд",summary="Покинутий Ряд — зловісний темний пагорб на північній межі Цвинтаря Воронячого Пагорба в Сутінколіссі. Він сумно відомий як похмуре житло Морбента Фела — некроманта, чия зла магія піднімає неспокійних мерців по всьому лісу.",section="Покинутий Ряд, що здіймається вздовж північного краю Цвинтаря Воронячого Пагорба, вічно огорнутий мороком. На вершині стоїть дім Морбента Фела — схожого на ліча некроманта, через якого довколишні нетрі заполонили ходячі мерці. Захищений мерзенними таємними чарами, господар пагорба звідси керує своїми слугами-скелетами, і весь північно-західний куток Сутінколісся стає небезпечним для мандрівників.",sectionIndex=1}
c["subzone:fray-island"] = "c76dfc"
P.scopedClips["subzone:fray-island"] = {scope="overview-body",sourceHash="5b7788",hash="c76dfc",name="Острів Бійки",summary="Острів Бійки — продуваний вітрами скелястий острівець неподалік від Узбережжя Крамарів у Пустках. Тут є груба бійцівська арена, і острів славиться як нейтральний прихисток, куди воїни з усього Азероту приїздять випробувати свою силу.",section="Острів Бійки лежить навпроти східних круч Пусток, далеко від пильного ока і Оргріммара, і Терамора. Тут гартуються воїни всіх рас і вір. У серці острова — бійцівська арена під наглядом Кланнока Маклауда, де досвідчені бійці й необстріляні новобранці сходяться в жорстоких двобоях.",sectionIndex=1}
c["subzone:freewind-post"] = "72985a"
P.scopedClips["subzone:freewind-post"] = {scope="overview-body",sourceHash="1bb999",hash="72985a",name="Застава Вільного Вітру",summary="Застава Вільного Вітру — головна застава Орди в Тисячі Голок, що височіє на одній із мальовничих кам'яних столових гір каньйону. Дістатися туди можна переважно тауренським підйомником і звивистими мотузяними мостами; це оборонний притулок від військових загонів кентаврів і важливий прикордонний плацдарм.",section="Застава Вільного Вітру, збудована просто на столових горах каньйону, захищає своїх мешканців завдяки кмітливості й висоті. Кентаври Ґалак панують на посушливому дні каньйону внизу, але не можуть ні видертися на височенні скелі, ні пробитися крізь важкі дерев'яні підйомники, що підносять мандрівників Орди в небо. Лабіринт мотузяних і дощаних мостів поєднує Вільний Вітер із сусідніми шпилями в надійне гніздо. Застава не лише тримає на відстані загони кентаврів, а й стримує верескливих гарпій, що гніздяться на кручах, і доглядає довколишні гніздовища віверн у Високосіді, де диких пташенят відбирають і виховують із них вірних вітрокрилів Орди.",sectionIndex=1}
c["subzone:frostmane-hold"] = "7a62f8"
P.scopedClips["subzone:frostmane-hold"] = {scope="overview-body",sourceHash="20f1df",hash="7a62f8",name="Твердиня Морозогривів",summary="Твердиня Морозогривів — укріплений табір і печерний комплекс, який крижані тролі Морозогриви захопили на заході Дун Мороґу. Схована серед скель на південь від Гномреґану, вона є головним плацдармом тролів-нападників, що насуваються на дворфські землі. Вартові Айронфорджа пильно стежать за твердинею, щоб оцінити зростання тролячої загрози.",section="Вирубана в морозних скелях західного Дун Мороґу, Твердиня Морозогривів складається з грубих споруд просто неба та звивистої системи печер. Для племені Морозогривів це головний оплот, який густо охороняють шкуродери та мисливці за головами. Звідси тролі влаштовують набіги на навколишні долини, випробовуючи оборону поселень на кшталт Хараноса й загрожуючи мандрівникам на гірських перевалах.",sectionIndex=1}
c["subzone:frostmane-hovel"] = "8958c7"
P.scopedClips["subzone:frostmane-hovel"] = {scope="overview-body",sourceHash="6f8abd",hash="8958c7",name="Халупа Морозогривів",summary="Халупа Морозогривів — суворе печерне лігво, сховане серед південних скель Долини Холодного Хребта в Дун Мороґу. Воно служить укріпленим притулком для войовничих тролів Морозогривів, які напирають просто на дворфські тренувальні угіддя.",section="Вирубана в південних горах, що обступають Долину Холодного Хребта, Халупа Морозогривів дає прихисток тутешнім тролям Морозогривам, які відмовляються поступитися високими снігами Айронфорджу. З грубих печер, як-от ця, тролі влаштовують безперервні набіги на місцеві дворфські табори й перерізають шляхи постачання в долину.",sectionIndex=1}
c["subzone:furlbrow-s-pumpkin-farm"] = "5f8da9"
P.scopedClips["subzone:furlbrow-s-pumpkin-farm"] = {scope="overview-body",sourceHash="f21024",hash="5f8da9",name="Гарбузова Ферма Фурлброу",summary="Гарбузова Ферма Фурлброу — захоплений хутір на півночі Вестфолу, неподалік головного шляху з Лісу Елвінн. Колись тут процвітало господарство Фермера Фурлброу та його дружини Верни, а тепер поля й хату захопили Братство Дефіас і големи жнив, що нишпорять довкола.",section="Гарбузова Ферма Фурлброу лежить біля північного кордону Вестфолу й колись славилася щедрими врожаями, що годували королівство. Усе скінчилося, коли краєм прокотилося Братство Дефіас. Розбійники прогнали Фермера Фурлброу і його дружину Верну з їхньої землі, а на полях лишили механічних големів жнив, налаштованих нападати на кожного, хто наблизиться. Будівлі зайняли бандити, поля патрулюють збунтовані машини, тож законні господарі змушені таборувати при дорозі біля Хутора Дженсена й оплакувати втрачену домівку та хліб насущний.",sectionIndex=1}
c["subzone:galardell-valley"] = "1955c1"
P.scopedClips["subzone:galardell-valley"] = {scope="overview-body",sourceHash="20fec4",hash="1955c1",name="Долина Ґалардель",summary="Долина Ґалардель — сувора й небезпечна ущелина на північно-східних висотах Гір Редріджу. Ущелину заполонили агресивні зграї гнолів, а над нею нависає тінь сумнозвісної Вежі Ілґалара.",section="Вирубана в північно-східних скелях Редріджу, Долина Ґалардель цілковито вийшла з-під контролю захисників Лейкшира. Люті гноли Редріджу никають низинами й таборують на дні каньйону під орудою жорстоких ватажків, як-от Лейтенант Фанґор. Високо над ярами здіймається темний шпиль Вежі Ілґалара — твердиня мага-ренегата Морґанта, і через це вся долина постійно наганяє страх на довколишні поселення.",sectionIndex=1}
c["subzone:gallows-end-tavern"] = "d83462"
P.scopedClips["subzone:gallows-end-tavern"] = {scope="overview-body",sourceHash="e7dfb7",hash="d83462",name="Таверна «Шибеничний Кінець»",summary="Таверна «Шибеничний Кінець» — головна корчма Брілла й серце гостинності Відступників в Галявинах Тірісфалю. Окрім притулку й трунків для втомлених подорожніх, вона править за важливий осередок наставників класів, учителів ремесел і таємних допитів.",section="Таверна «Шибеничний Кінець», що стоїть на видноті біля дороги в Бріллі, — головне місце зібрань щойно пробуджених Відступників, які залишають Похоронний Подзвін і прямують на південь, до Андерсіті. Попри своє нежиття, Відступники й далі навідуються до її зал заради товариства, торгівлі й прихистку. У корчмі мешкають наставники різних класів — вони навчають молодих воїнів, жерців, магів, розбійників і чорнокнижників, — а також крамарі й лікарі.",sectionIndex=1}
c["subzone:garren-s-haunt"] = "e16446"
P.scopedClips["subzone:garren-s-haunt"] = {scope="overview-body",sourceHash="079182",hash="e16446",name="Лігво Гаррена",summary="Лігво Гаррена — покинутий хутір у північних Галявинах Тірісфалю. Колись квітуча людська садиба, ферма занепала, коли Погибель винищила родину Гарренів, і зарослі землі заполонили здичавілі гнилошкірі гноли.",section="До Третьої війни цей хутір годував родину й давав щедрі врожаї під владою Королівства Лордерон. Коли Чума Нежиті прокотилася околицями, Погибель упала на ферму й вирізала Гаррена з усім родом. Сьогодні поля лежать сірі й усохлі, а будинок і клуня трухлявіють у вічному мороці Тірісфалю.",sectionIndex=1}
c["subzone:gates-of-ironforge"] = "f344f7"
P.scopedClips["subzone:gates-of-ironforge"] = {scope="overview-body",sourceHash="f0cc48",hash="f344f7",name="Брама Айронфорджа",summary="Брама Айронфорджа — монументальний головний вхід, що веде мандрівників зі сніжних гірських долин Дун Мороґу до дворфійської столиці. Її висічено просто в прямовисній кам'яній стіні гори, а всередині її стереже велетенська статуя Верховного Короля Модімуса Анвілмара.",section="До Брами Айронфорджа піднімаються звивистим укріпленим пандусом із середини Дун Мороґу, і її грізний фасад видно з більшої частини засніжених низин. За величезними ворітьми гості потрапляють до самого міста, де їх одразу зустрічає величезна кам'яна статуя на честь Верховного Короля Модімуса Анвілмара — легендарного правителя, що об'єднав дворфійські клани ще до Війни Трьох Молотів. Від брами дорога веде просто до гамірного торгового району — Торгових Рядів.",sectionIndex=1}
c["subzone:gates-of-orgrimmar"] = "898aa6"
P.scopedClips["subzone:gates-of-orgrimmar"] = {scope="overview-body",sourceHash="f11fd3",hash="898aa6",name="Брама Оргріммара",summary="Брама Оргріммара — грізний південний поріг столиці Орди, висічений просто в червоній скелі північного Дуротару. Обрамлений важкими дерев'яними й залізними укріпленнями, цей величний вхід з'єднує посушливі пустища за мурами з жвавими майданами Долини Сили. Він — наочне свідчення орочої витривалості й бойової сили.",section="Обрамлена високими дерев'яними частоколами, величезними залізними шипами й укріпленими дозорними вежами, головна брама стереже основну ущелину, що врізається в гори довкола Оргріммара. Для мандрівників, що наближаються від Гострого Пагорба й чагарникових рівнин Дуротару, вхід — водночас гостинний пам'ятник і суворе застереження кожному, хто насмілиться загрожувати Новій Орді. Важкоозброєні вояки Оргріммара й мисливці за головами з Темного Списа патрулюють підступи, пильно стежачи за кожним, хто входить до міста.",sectionIndex=1}
c["subzone:goblin-foundry"] = "ad85f7"
P.scopedClips["subzone:goblin-foundry"] = {scope="overview-body",sourceHash="e45ba6",hash="ad85f7",name="Гоблінська Ливарня",summary="Гоблінська Ливарня — промислова майстерня глибоко в Мертвих Копальнях, де гобліни-майстри виготовляють важкі металеві вироби для Братства Дефіас. Над залою панує величезний плавильний казан, а працюють тут гобліни-ремісники й інженери під орудою Ґілніда.",section="Вирубана в підземних глибинах Мунбрука, Гоблінська Ливарня дає Братству Дефіас потужне важке виробництво. Гобліни-ремісники й інженери працюють між плавильнями й залізними пандусами, виготовляючи якорі та гарматні ядра.",sectionIndex=1}
c["subzone:gol-bolar-quarry"] = "64ce35"
P.scopedClips["subzone:gol-bolar-quarry"] = {scope="overview-body",sourceHash="148fde",hash="64ce35",name="Кар'єр Гол'Болар",summary="Кар'єр Гол'Болар — дворфські розробки, вирубані в засніжених пагорбах південно-східного Дун Мороґу. Багатий на камінь і руду, цей колись жвавий промисел зупинився, коли його захопили люті троги, що ринули з глибин.",section="Кар'єр Гол'Болар на південний схід від Хараноса заклали дворфи Айронфорджа, щоб добувати з гір цінний камінь і мінеральні багатства. Та глибокі розкопки відкрили підземні нори й випустили на волю орду ворожих трогів, які швидко вигнали шахтарів. Нині верхній табір став осадженим плацдармом, де наглядачі, ремісники та Шукач Ґен збирають дворфських і гномських новобранців, щоб відтіснити тварюк і повернути кар'єр.",sectionIndex=1}
c["subzone:gol-bolar-quarry-mine"] = "69d13a"
P.scopedClips["subzone:gol-bolar-quarry-mine"] = {scope="overview-body",sourceHash="109a47",hash="69d13a",name="Шахта Кар'єру Гол'Болар",summary="Шахта Кар'єру Гол'Болар — захоплена розробка в самому серці Кар'єру Гол'Болар на сході Дун Мороґу. Дворфські шахтарі, що колись тут працювали, пробили тунелі в підземні печери трогів і випустили на волю шалену навалу, яка поглинула всю ділянку. Нині найглибші штольні служать оплотом бойовому загону трогів на чолі зі звірюкою Молотохребтом.",section="Шахту заклали дворфи Айронфорджа, що шукали камінь і багаті поклади руди під скелястими вершинами Дун Мороґу. Робота обірвалася раптово й криваво, коли кайла проламали стіну в прадавню систему підземних печер, де жили троги. Хлинувши з темряви, підземні тварюки зім'яли робочі бригади й змусили їх поспіхом відступити, а зрештою вихлюпнулися назовні й захопили ще й навколишній кар'єр.",sectionIndex=1}
c["subzone:gold-coast-quarry"] = "5be918"
P.scopedClips["subzone:gold-coast-quarry"] = {scope="overview-body",sourceHash="57bb46",hash="5be918",name="Кар'єр Золотого Узбережжя",summary="Кар'єр Золотого Узбережжя — відкрита копальня, врізана в урвища південно-західного Вестфолу. Колись він був цінним джерелом каменю, руди й золота для Королівства Стормвінд, а тепер його захопило Братство Дефіас, щоб живити свій дедалі ширший заколот.",section="Доки королівство ще дбало про цей край, Кар'єр Золотого Узбережжя постачав будівельний камінь і дорогоцінне золото на відбудову Стормвінда. Коли королівські війська пішли з Вестфолу й лишили околиці без захисту, розробки захопили розбійники Дефіас і збунтовані робітники. Тепер Братство патрулює кам'яні уступи, користається тим, що звідси видно все узбережжя, і вигрібає рештки руди, щоб фінансувати заколот.",sectionIndex=1}
c["subzone:gold-road"] = "2f802c"
P.scopedClips["subzone:gold-road"] = {scope="overview-body",sourceHash="772856",hash="2f802c",name="Золотий Шлях",summary="Золотий Шлях — головна артерія з півночі на південь, що перетинає посушливі простори Пусток. Простягаючись від Валу Мор'шан на кордоні з Ашенвалем повз Перехрестя аж до південних країв, він слугує життєво важливим шляхом сполучення для молодої Орди.",section="Золотий Шлях — довгий, випалений сонцем ґрунтовий тракт, що прорізає середину Пусток. На півночі він починається біля укріпленого Валу Мор'шан і Базового Табору Мор'шан, які стережуть від вилазок нічних ельфів з Ашенвалю. Прямуючи на південь, він з'єднується зі східною дорогою до Дуротара, а далі перетинає гамірне торгове поселення Перехрестя. Продовжуючись на південь повз буйні води місцевих оаз і передгір'я біля Печер Стогонів, північна ділянка тракту сягає висохлого річища, де мандрівники переходять у небезпечнішу південну частину савани.",sectionIndex=1}
c["subzone:golden-plains"] = "9e54bd"
P.scopedClips["subzone:golden-plains"] = {scope="overview-body",sourceHash="b5433a",hash="9e54bd",name="Золоті Рівнини",summary="Золоті Рівнини — просторе, залите сонцем пониззя, що простягається на південний схід від Тандер Блафа в центральному Малгорі. Таурени плекають ці розлогі пасовища як найкращі мисливські угіддя та життєво важливе пасовисько для мандрівних стад кодо.",section="Розкинувшись під високими плато Тандер Блафа, Золоті Рівнини — неприборкане серце Малгору. Мінливе море золотавої й зеленої трави дає щедрий прихисток місцевій живності, тож це одні з найцінніших традиційних мисливських угідь кочових тауренів. Хвилястим пониззям бродять великі стада кодо, а мисливці переповідають історії про легендарну здобич — насамперед про великого кодо Арра'чеа, що тихо мандрує серед високих стебел.",sectionIndex=1}
c["subzone:goldshire"] = "918809"
P.scopedClips["subzone:goldshire"] = {scope="overview-body",sourceHash="7c3fad",hash="918809",name="Ґолдшир",summary="Ґолдшир — важливе людське містечко на перехресті в центральному Лісі Елвінн, що сполучає Стормвінд із Вестфолом, Редріджем і південним порубіжжям. Відбудоване після знищення в Першій війні, нині це гамірна проміжна станція, серце якої — славетна корчма «Лев'яча Гордість», а захист — украй виснажений загін вартових Стормвінда.",section="Ґолдшир, що стоїть там, де сходяться королівські шляхи, здавна був громадським і торговим серцем сільського Елвінну. Та за сільським чаром містечка ховається дедалі більша небезпека 25 року від відкриття Темного Порталу. Військові сили Стормвінда розтягнуті до краю, Король Варіан Рінн загадково зник, і Маршал Дуґан мусить покладатися на перехожих шукачів пригод, а не на регулярні війська, щоб стримувати довколишні загрози. Войовничі гноли Річколапи напирають із західного кордону, а люті мурлоки захопили береги Озера Кам'яного Кургану та Кришталевого Озера, відбираючи життя королівських вартових і підступаючи небезпечно близько до центру містечка.",sectionIndex=1}
c["subzone:grand-vestibule"] = "fda7f2"
P.scopedClips["subzone:grand-vestibule"] = {scope="overview-body",sourceHash="8472a5",hash="fda7f2",name="Великий Вестибюль",summary="Великий Вестибюль — величний вхідний зал Багряного Монастиря в Галявинах Тірісфалю. Обабіч тягнуться багряні колони й кам'яні статуї загиблих хрестоносців; це поріг, де шукачі пригод готуються прорватися до внутрішніх залів монастиря.",section="За важкими зовнішніми воротами Монастиря лежить Великий Вестибюль — просторий мармуровий зал, присвячений бойовій гордості Багряного Хрестового Походу. Статуї закутих в обладунки героїв несуть варту біля склепінчастих кам'яних колон, а ревні вартові, учні й провидці патрулюють кам'яні плити, щоб покарати кожного, хто наважиться увійти без багряного налатника ордену. Для непроханих гостей це перший смак невблаганної дисципліни й фанатизму Хрестового Походу.",sectionIndex=1}
c["subzone:great-forge"] = "292cbd"
P.scopedClips["subzone:great-forge"] = {scope="overview-body",sourceHash="3282ca",hash="292cbd",name="Велика Кузня",summary="Велика Кузня — вогняне серце дворфійської столиці Айронфорджа, що дала їй ім'я. Вона стоїть у самому центрі міста, і її величезні горна та славетне Велике Ковадло ніколи не спочивають: тут кують легендарну зброю, і тут вирує громадське життя.",section="Велика Кузня була найпершою спорудою, яку давні дворфи звели під горою Айронфордж, і величезна столиця розрослася довкола неї концентричними кільцями. Розплавлений камінь і шлак безупинно ллються з велетенських ливарень у сяйливі жолоби, заливаючи печеру бурштиновим маревом. Посередині стоїть величезне Велике Ковадло, яким опікується Майстер Кузні Майолор Сандерф'юрі. Довкола нього збираються славетні майстри металу й день і ніч кують обладунки, знаряддя та зброю.",sectionIndex=1}
c["subzone:great-lift"] = "025db2"
P.scopedClips["subzone:great-lift"] = {scope="overview-body",sourceHash="f82a04",hash="025db2",name="Великий Підйомник",summary="Великий Підйомник — велетенська система підйомників, яку звели таурени на південному краю Пусток. Це головний шлях, яким мандрівників і вантажі спускають на сотні футів униз, у прямовисну улоговину каньйону Тисячі Голок. Попри стратегічне значення, підступатися до краю урвища дедалі небезпечніше через агресивних шипогривів, що просуваються південними пустищами.",section="Великий Підйомник, що з'єднує прямовисний край урвища на півдні Пусток із дном каньйону Тисячі Голок, — справжнє диво практичного тауренського будівництва. Зведений із важкого дерева, плетених мотузок і блоків із противагами, він має дві платформи, які безпечно переносять каравани, гінців і воїнів через прямовисне урвище, де розбився б будь-який віз. На верхній і нижній платформах вартують таурени — як-от Сміливець Мунгорн і Ґріш Лонґраннер, — які розповідають мандрівникам про дорогу попереду й стежать, щоб вантажі проходили без затримок.",sectionIndex=1}
c["subzone:greatwood-vale"] = "d9687c"
P.scopedClips["subzone:greatwood-vale"] = {scope="overview-body",sourceHash="fdb872",hash="d9687c",name="Долина Великолісся",summary="Долина Великолісся — лісиста долина у східних передгір'ях Гір Кам'яного Кігтя, куди веде небезпечна Стежка Павутинника. Нещодавно її захопило вороже плем'я Ґрімтотем і зробило плацдармом для кривавих нападів на сусідні поселення.",section="Долина Великолісся, захована осторонь Стежки Павутинника, перетворилася на криваве прикордоння. Плем'я Ґрімтотем на чолі з безжальним Ґрундіґом Дарклаудом великими силами зайняло долину, перекрило безпечний прохід і сіє жах по всіх довколишніх передгір'ях.",sectionIndex=1}
c["subzone:greenpaw-village"] = "cf7d03"
P.scopedClips["subzone:greenpaw-village"] = {scope="overview-body",sourceHash="48f3c5",hash="cf7d03",name="Село Зеленолапів",summary="Село Зеленолапів — поселення фурболгів у центральному Ашенвалі, між Притулком Рейнвуд і Притулком Срібного Вітру. Це головна домівка племені Гнилолісу, яким керують вождь Мурґут і шаман Оукпов. Охоплене демонічною скверною й оточене ворогами, село — гаряча точка для мандрівників і з Альянсу, і з Орди.",section="Село Зеленолапів, що лежить на південь від Притулку Рейнвуд і на північний схід від Притулку Срібного Вітру, колись було тихою домівкою ведмежоподібних мешканців лісу. Після Третьої війни тутешні фурболги — плем'я Гнилолісу — піддалися підступній скверні, що отруює ґрунти й духів Ашенвалю. Під владою вождя Мурґута та свого оскверненого духовного провідника, шамана Оукпова, Гнилоліс став ворожим і непередбачуваним племенем, що нападає на кожного мандрівника, який забреде на його землі.",sectionIndex=1}
c["subzone:greymane-wall"] = "82194f"
P.scopedClips["subzone:greymane-wall"] = {scope="overview-body",sourceHash="7d7a5f",hash="82194f",name="Стіна Ґреймейна",summary="Стіна Ґреймейна — масивний кам'яний вал уздовж південного прикордоння Срібнолісся. Зведена королем Ґенном Ґреймейном після Другої війни, вона відгороджує королівство Ґілнеас від зовнішнього світу неприступними замкненими брамами.",section="Після Другої війни король Ґенн Ґреймейн затаїв образу на Альянс Лордерона — надто через податки на утримання орківських таборів для інтернованих і будівництво Замку Незерґард. Вирішивши, що Ґілнеас віддав досить грошей і крові за чужі біди, Ґреймейн вийшов з Альянсу й наказав звести колосальний мур поперек перешийка півострова. Так він покинув землі, що належали лордові Даріусу Кроулі, — серед них Село Пайрвуд і Амбермілл, — і ті опинилися на північному боці каміння. Коли Третя війна привела до його підніжжя Чуму Нежиття й незліченних відчайдушних біженців, брами лишилися безжально замкненими.",sectionIndex=1}
c["subzone:grim-batol"] = "c18966"
P.scopedClips["subzone:grim-batol"] = {scope="overview-body",sourceHash="1cd976",hash="c18966",name="Ґрім Батол",summary="Ґрім Батол — прадавня зруйнована дворфійська гірська фортеця, що нависає над східним краєм Багнокраю. Її збудували Вайлдгаммери, покинули через темне прокляття під час Війни Трьох Молотів, а згодом орки Драконячої Пащі облаштували тут лігво для розведення драконів. Її запечатані брами досі лишаються зловісною виразкою на тілі нагір'я.",section="Після давньої міжусобиці трьох кланів тан Кардрос Вайлдгаммер видовбав Ґрім Батол у зубчастих горах на схід від боліт. Під час Війни Трьох Молотів, що спалахнула згодом, чаклунка Темного Заліза Модґуд узяла фортецю в облогу. Кардрос її здолав, проте перед смертю Модґуд накинула на це каміння мерзенну тінь. Через залишки цієї порчі в залах стало неможливо жити, і вцілілі Вайлдгаммери мусили покинути своє пишне королівство й піти на північ, у Пригір'я.",sectionIndex=1}
c["subzone:grizzled-den"] = "c983b0"
P.scopedClips["subzone:grizzled-den"] = {scope="overview-body",sourceHash="1fb83b",hash="c983b0",name="Сиве Лігво",summary="Сиве Лігво — печера серед засніжених пагорбів на південний захід від Хараноса. Вона відома як лігво лютих вендіго з крижаним подихом, що водяться в Дун Мороґу.",section="Вирубане глибоко в скелях на південний захід від Хараноса, Сиве Лігво відоме серед місцевих горян як місце, де гніздяться зграї вендіго Дун Мороґу. Ці люті мавпоподібні звірі обдають непроханих гостей крижаним подихом і гуртуються, щоб боронити свої нори. Попри небезпеку, відважні мисливці часто спускаються в глибини печери по густі гриви вендіго, за які добре платять ремісники, що оббивають теплим хутром холодні крісла та сидіння карет.",sectionIndex=1}
c["subzone:grizzlepaw-ridge"] = "3382cc"
P.scopedClips["subzone:grizzlepaw-ridge"] = {scope="overview-body",sourceHash="189cca",hash="3382cc",name="Хребет Сивої Лапи",summary="Хребет Сивої Лапи — порізаний скелястий схил, що здіймається на південь від Телсамара в Лох Модані. Серед місцевих горян він має лиху славу через численних диких ведмедів на чолі з легендарним звіром Старим Сажотлапом.",section="Хребет Сивої Лапи, що нависає над дорогою на південь від Телсамара й межує на заході з Долиною Кам'яного Уламка, — суворий край, де панують хижі звірі. Схили захопили ведмеді, ревниві до своєї території, і вони становлять небезпеку для мандрівників, що обходять гори. Глибоко в хребті живе Старий Сажотлап — величезний і надзвичайно лютий ведмідь, якого бояться місцеві мисливці. Мандрівники між дворфійськими поселеннями мають пильно стежити за узліссям і кам'янистими терасами нагорі.",sectionIndex=1}
c["subzone:grol-dom-farm"] = "b73934"
P.scopedClips["subzone:grol-dom-farm"] = {scope="overview-body",sourceHash="4a67e4",hash="b73934",name="Ферма Ґрол'дом",summary="Ферма Ґрол'дом — скромна орківська садиба на півночі Пусток, при дорозі між Дуротаром і Перехрестям. Тут живе Кранал Фісс зі своєю родиною: вони розводять свиней на посушливих рівнинах, попри постійні напади агресивних місцевих шипогривів.",section="Ферма Ґрол'дом, заснована після того, як орки оселилися в Дуротарі, — одна з перших спроб Орди господарювати на сухих просторах Пусток. Невелику садибу доглядають орк Кранал Фісс і його діти: вони переважно розводять свиней, тримаючи оборону від суворих звірів і агресивних нападників-шипогривів із Гостроманів, що никають на ближніх кряжах. Це самотній, суворий хутір, який дає молодій орківській державі важливу їжу.",sectionIndex=1}
c["subzone:grommash-hold"] = "d05e74"
P.scopedClips["subzone:grommash-hold"] = {scope="overview-body",sourceHash="45ce08",hash="d05e74",name="Фортеця Ґроммаш",summary="Фортеця Ґроммаш — укріплений осідок Вождя Тралла високо в червоних скелях Долини Мудрості в Оргріммарі. Названа на честь жертви Ґроммаша Хеллскріма, фортеця слугує командним центром і політичним серцем Нової Орди.",section="Фортеця Ґроммаш, що височіє в спокійній Долині Мудрості, — королівський двір і стратегічне святилище Орди. Вбудована у височенні стіни каньйону, вона всередині помітно темна й прохолодна: Вождь Тралл зробив це навмисно, щоб посланці, прохачі й воєначальники на аудієнціях лишалися пильними й тверезими. Тут Тралл обмірковує оборону Калімдору, дослухаючись до досвідчених радників, як-от Ейтріґґа, і приймаючи вождів народів, як-от Вол'джина.",sectionIndex=1}
c["subzone:grove-of-the-ancients"] = "3faf0b"
P.scopedClips["subzone:grove-of-the-ancients"] = {scope="overview-body",sourceHash="2aefee",hash="3faf0b",name="Гай Прадавніх",summary="Гай Прадавніх — священне святилище нічних ельфів серед руїн давнього храму на південному сході Темного Узбережжя. Цей тихий прихисток біля Річки Дикого Закруту — місце збору духів природи, і його оберігає шановане Древо Знань на ім'я Ону.",section="Гай Прадавніх, що сховався біля південно-східних гір Темного Узбережжя, — мирний прихисток серед старого храмового каміння. Крізь його серце тече бурхлива Річка Дикого Закруту, даючи тихий притулок на узбережжі, яке дедалі більше потерпає від скверни й неспокійних звірів. Гай слугує місцем зустрічей Кола Прадавніх, де духи природи й калдореї дбають про крихку рівновагу лісу.",sectionIndex=1}
c["subzone:gryphon-roost"] = "8cdc31"
P.scopedClips["subzone:gryphon-roost"] = {scope="overview-body",sourceHash="5aa470",hash="8cdc31",name="Сідало Грифона",summary="Сідало Грифона, що примостилося на мурах трохи на схід від Торгового Кварталу Стормвінда, — головний вузол повітряних подорожей столиці. Ним опікується людина-приборкувач грифонів Дунґар Лонґдрінк, і тут живуть величні звірі, що переносять гінців, солдатів і шукачів пригод по всіх Східних Королівствах.",section="Сідало Грифона, що стоїть на укріпленнях над каналом Торгового Кварталу, з'єднує столицю з віддаленими гарнізонами й поселеннями Альянсу по всіх Східних Королівствах. Мережею польотів керує досвідчений приборкувач Дунґар Лонґдрінк, що прокладає маршрути до Айронфорджа, Лейкшира, Сентінел Гілла й далі.",sectionIndex=1}
c["subzone:gunther-s-retreat"] = "d544e1"
P.scopedClips["subzone:gunther-s-retreat"] = {scope="overview-body",sourceHash="93a144",hash="d544e1",name="Притулок Ґунтера",summary="Притулок Ґунтера — відлюдне острівне святилище посеред Озера Світлої Води в центральних Галявинах Тірісфалю. Це сховок Ґунтера Аркануса — некроманта-відступника, що вирвався з-під влади Погибелі самою лише силою волі. Недовірливий до всіх чужинців, самітник оточив свій табір вірними поплічниками-нежиттю, щоб тримати зайд на відстані.",section="Притулок Ґунтера посеред імлистих вод Озера Світлої Води — непримітний острівний табір, який легко сплутати з іще одним гніздом Погибелі. Його господар, Ґунтер Арканус, досяг того, що вдавалося небагатьом смертним чаклунам: піднятий нежиттю, він завдяки своїй таємній майстерності вирвав власну душу із залізної хватки Короля-Ліча без жодної сторонньої допомоги. Нікому не довіряючи, Ґунтер вирішив, що решта нежиті, яка блукає Лордероном, досі маріонетки Погибелі. Він усамітнився на цьому безлюдному острові, щоб у спокої вправлятися у своєму ремеслі, і виставив вартових-зомбі роздирати кожного, хто перетне воду.",sectionIndex=1}
c["subzone:hall-of-arms"] = "3f9950"
P.scopedClips["subzone:hall-of-arms"] = {scope="overview-body",sourceHash="f3f071",hash="3f9950",name="Зала Зброї",summary="Зала Зброї — штаб військової потуги Айронфорджа й головний арсенал дворфійського королівства. Ця укріплена споруда у Військовому Кварталі навчає дворфійських бійців і керує розгортанням важкої броні та бойових літальних машин.",section="Зала Зброї в південно-східному куті Військового Кварталу — оперативний командний центр збройних сил Айронфорджа. Окрім досвідчених наставників воїнів і мисливців, тут розташовані величезне сховище й плацдарм механізованої війни. Важкі парові танки збирають і обслуговують просто на місці, щоб підсилювати Альянс на полях битв, а гірокоптери й літальні машини підіймають промисловими конвеєрами й запускають крізь вертикальні шахти в склепінні печери — просто до Летовища Айронфорджа нагорі.",sectionIndex=1}
c["subzone:hall-of-arms-northshire"] = "02d1a5"
P.scopedClips["subzone:hall-of-arms-northshire"] = {scope="overview-body",sourceHash="7ad0d7",hash="02d1a5",name="Зала Зброї (Нортшир)",summary="Зала Зброї — військове крило Абатства Нортшира, на південь від Головної Зали. Тут бувалі наставники муштрують найновіших новобранців армії Стормвінда в мистецтві меча, щита та святого бою.",section="Поки клірики та вчені гортають давні фоліанти по той бік двору, у Бібліотечному Крилі, Зала Зброї дзвенить брязкотом затупленої сталі та важким ритмом військової муштри. Розташована з південного боку Абатства Нортшира, ця зала — головне місце підготовки необтесаних бійців з людей і побожних прагнучих, що беруться за зброю заради армії Стормвінда. Тут загартовані бойові наставники й паладини-ментори навчають основних стійок, дисципліни та засад, потрібних, щоб боронити Ліс Елвінн від кобольдів, розбійників Дефіас і гнолів-нападників, що насуваються.",sectionIndex=1}
c["subzone:hall-of-explorers"] = "12cf3a"
P.scopedClips["subzone:hall-of-explorers"] = {scope="overview-body",sourceHash="af8c17",hash="12cf3a",name="Зала Дослідників",summary="Зала Дослідників — просторе археологічне крило Айронфорджа й гамірний штаб дворфійської Ліги Дослідників. Почасти музей, почасти архів, почасти штаб експедицій — вона збирає реліквії, скам'янілості й давні томи з усіх куточків Азерота, щоб скласти докупи забуте походження дворфійської раси.",section="Зала Дослідників, яку іноді називають Зібранням Дослідників, займає північно-східну печеру Айронфорджа. Це нервовий центр усіх археологічних починань, схвалених Альянсом. Під проводом Верховного Дослідника Мунінна Маґелласа науковці й польові агенти координують розкопки в далеких краях і надсилають додому загадкові реліквії, давні механізми титанів і доісторичні кістки. Простора Бібліотека посередині слугує водночас відкритим музеєм і закритим сховищем історичних знань.",sectionIndex=1}
c["subzone:hall-of-gears"] = "81769e"
P.scopedClips["subzone:hall-of-gears"] = {scope="overview-body",sourceHash="0e5481",hash="81769e",name="Зала Шестерень",summary="Зала Шестерень — багатоярусна промислова зала в занепалому місті Гномреґан, одразу за Годинниковим Ходом. Колись гамірний осередок механічного руху, тепер вона лежить у руїнах, залита отруйним мулом, і в ній блукають слизуни та опромінені троги.",section="Зала Шестерень, що лежить одразу за Годинниковим Ходом, наочно показує катастрофічний занепад столиці гномів. Вона поділена на два головні рівні: верхні містки тримають агресивні опромінені троги, що продираються крізь обвалені шахти доступу. Унизу підлога залита калюжами радіоактивних викидів, де в отруйних стоках буяють їдкі слизуни й живі отруйні елементалі.",sectionIndex=1}
c["subzone:hall-of-legends"] = "d54de6"
P.scopedClips["subzone:hall-of-legends"] = {scope="overview-body",sourceHash="765210",hash="d54de6",name="Зала Легенд",summary="Зала Легенд — елітне військове святилище й казарми офіцерів Орди в Долині Сили в Оргріммарі. За її охоронюваним порогом поборники Орди сходяться над бойовими планами й озброюються найкращою зброєю, здобутою в сутичках по всьому Азероту й поза ним.",section="Зала Легенд, що стоїть осторонь гамірних вулиць Долини Сили, — закритий оплот для випробуваних офіцерів Орди. За охоронюваним входом стратеги й посланці від різних народів — серед них Вождь Ертбайнд із Тандер Блафа, Кровний Стражник Гіні'вана з Темного Списа та Радник Віллінґтон з Андерсіті — радяться над мапами спірних земель і військовим становищем обох фракцій. Сюди пускають лише воїнів, що довели свою міць і досягли звання Кам'яного Стражника чи вищого, — тут вони отримують здобич і озброєння, гідні свого становища.",sectionIndex=1}
c["subzone:hall-of-mysteries"] = "901599"
P.scopedClips["subzone:hall-of-mysteries"] = {scope="overview-body",sourceHash="65cfea",hash="901599",name="Зала Таїнств",summary="Зала Таїнств, що ховається в Кварталі містиків Айронфорджа, — духовне й наукове серце міста для всього чародійського й божественного. У її освітлених синім покоях дворфи й гноми вивчають давні тексти, осягають таїнства Святого Світла й плетуть чародійні зачарування — подалі від брязкоту Великої Кузні.",section="Осяяна незвичним синім і фіолетовим світлом, Зала Таїнств різко вирізняється з-поміж решти Айронфорджа. Довкола панують камінь, залізо й важкі лати, а під п'ятьма високими колонами зали знаходять прихисток учені в м'яких, плинних мантіях. Зала поєднує чародійську науку й святе служіння: тут штаб дворфійського жрецтва й Ордену Срібної Длані в Каз Модані. Тут молоді жерці й лицарі вивчають священні тексти, як-от Фоліант Божественності, і отримують настанови, перш ніж мандри поведуть їх далі — до Собору Світла в Стормвінді.",sectionIndex=1}
c["subzone:hall-of-the-brave"] = "f367bf"
P.scopedClips["subzone:hall-of-the-brave"] = {scope="overview-body",sourceHash="b3e771",hash="f367bf",name="Зала Хоробрих",summary="Зала Хоробрих — величні казарми воїнів на східних висотах Долини Честі в Оргріммарі. Це головний вишкільний осередок і гільдійний дім для бійців передової, муштрувальників і розпорядників битв Орди.",section="Зала Хоробрих, що здіймається над спокійними водами й тренувальними колами Долини Честі, — важливий військовий осередок Орди, яка набирає сили. Всередині бувалі офіцери й досвідчені воїни навчають новачків суворих основ ближнього бою, опанування стійок і дисципліни. Зала заставлена тренувальними опудалами й зброєю, а розпорядники битв збирають тут бійців для великих битв по всьому Азероту.",sectionIndex=1}
c["subzone:helm-s-bed-lake"] = "c06677"
P.scopedClips["subzone:helm-s-bed-lake"] = {scope="overview-body",sourceHash="cc002c",hash="c06677",name="Озеро Ложа Гелма",summary="Озеро Ложа Гелма — замерзла водойма серед південно-східних пагорбів Дун Мороґу. Доглянута ополонка в товстій кризі дає місцевим горянам і мандрівникам украй потрібну прісну воду. Та береги стали небезпечними через хижу звірину, трогів, що насуваються, і ворожих лазутчиків Темного Заліза.",section="Озеро Ложа Гелма тихо лежить під товстим шаром зимової криги на південному сході Дун Мороґу. Місцеві дворфи підтримують прорубану в кризі ополонку, щоб черпати чисту прісну воду. Переходити замерзле плесо досить безпечно, а от затримуватися біля берегів стає дедалі ризикованіше. Узліссям блукають дикі звірі, по хребтах нишпорять зігнані з місця троги, а осередок ворожих дворфів Темного Заліза захопив покинуту оселю просто на південь від води і люто нападає з засідки на кожного, хто проходить повз.",sectionIndex=1}
c["subzone:heroes-vigil"] = "6b4739"
P.scopedClips["subzone:heroes-vigil"] = {scope="overview-body",sourceHash="1936a1",hash="6b4739",name="Дозор Героїв",summary="Дозор Героїв — тиха священна галявина на центральному острові Озера Кам'яного Кургану на сході Лісу Елвінн. Її серце — пам'ятник, відомий як Камінь Пам'яті, присвячений полеглим у Першій війні. Та нині святиня здебільшого занедбана Стормвіндом і захоплена небезпечними чародіями-відступниками.",section="Зведений після Першої війни, Дозор Героїв зосереджений довкола Каменя Пам'яті — кам'яного кола з написами на честь солдатів і городян, убитих, коли Стара Орда плюндрувала Ґолдшир і навколишні долини. Колись шанований як священний оплот віри й жертовності, дозор поступово випав з уваги нинішніх правителів Стормвінда, і його освячена земля заросла й лишилася без нагляду солдатів королівства.",sectionIndex=1}
c["subzone:hidden-path"] = "10848f"
P.scopedClips["subzone:hidden-path"] = {scope="overview-body",sourceHash="7ac785",hash="10848f",name="Прихована Стежка",summary="Прихована Стежка — відлюдна гірська стежина, що в'ється скелями над Долиною Випробувань у Дуротарі. Для майбутніх шаманів, що шукають священний Камінь Духів, це обряд посвяти, а ще звідси відкривається непомічений краєвид на суворі кордони Пусток.",section="Прорізана в червоних вершинах довкола Долини Випробувань, Прихована Стежка навмисне така, щоб її було важко помітити з дна каньйону. Наставники скеровують сюди молодих шаманів, щоб ті довели свою уважність і дисципліну, перш ніж спілкуватися з духами біля Каменя Духів. На найвищих відтинках стежки мандрівникам відкриваються широкі краєвиди, що тягнуться на захід, до хвилястих саван Пусток.",sectionIndex=1}
c["subzone:high-rise"] = "997fa9"
P.scopedClips["subzone:high-rise"] = {scope="overview-body",sourceHash="2a9f27",hash="997fa9",name="Високе Узвишшя",summary="Високе Узвишшя — найвищий ярус центральної столової гори Тандер Блафа, корона тауренської столиці. Тут вирує амфітеатр довкола спільного вогнища, а поруч працюють досвідчені ремісники, торговці зброєю й майстри кулінарії. На відміну від нижніх ярусів, ця вершина сполучена з рештою міста лише підвісними мотузяними мостами й гніздовищем вітрокрилів.",section="Високе Узвишшя стоїть на вершині головного плато Тандер Блафа, де гуляють вільні вітри високо над хвилястими рівнинами Малгору. Це головне місце зборів об'єднаних племен: у центрі — амфітеатр просто неба й вогнище, де городяни слухають важливі оголошення племен і доленосні рішення. У навколишніх наметах і дерев'яних ятках працюють відомі купці, зброярі й наставники кулінарії, як-от «Кухня Аски» та «Наживка та Снасті на Вершині Гори». Нижні яруси сполучені з преріями Малгору величезними дерев'яними підйомниками, а Високе Узвишшя лишається у висоті: дістатися сюди можна передусім через гніздовище вітрокрилів і розлогі мотузяні мости до сусідніх Узвишшя Старійшин та Узвишшя Мисливців.",sectionIndex=1}
c["subzone:high-seat"] = "a7292e"
P.scopedClips["subzone:high-seat"] = {scope="overview-body",sourceHash="b3560d",hash="a7292e",name="Високий Престол",summary="Високий Престол — велична тронна зала Айронфорджа між Торговими Рядами й Великою Кузнею. З цієї піднесеної зали Король Маґні Бронзбірд править дворфійським королівством разом із королівськими радниками й літописцями. Тут-таки розташований запечатаний прохід, що веде вниз, у давні глибини Старого Айронфорджа.",section="Високий Престол височіє над жвавими кільцями Айронфорджа — це королівський осідок влади Каз Модану. У цій склепінчастій залі Король Маґні Бронзбірд вислуховує прохачів, радиться з порадниками й керує обороною північних бастіонів Альянсу. Поруч із ним — королівські сановники, як-от Королівська Історикиня Архесонус і Сенатор Барін Редстоун. Високий Престол лишається символом непохитної влади Бронзбірдів і дворфійської стійкості в неспокійні для Азерота часи.",sectionIndex=1}
c["subzone:highperch"] = "dc9fc9"
P.scopedClips["subzone:highperch"] = {scope="overview-body",sourceHash="1f3df2",hash="dc9fc9",name="Високосід",summary="Високосід — плато в західній частині Тисячі Голок, що здіймається високо над дном каньйону. Воно славиться як головне гніздовище диких віверн та їхніх родичів — вітрокрилів. Тут живуть люті зграї, що боронять своїх малят серед обвітрених скель.",section="Високосід, що круто здіймається з дна каньйону, — суворий прихисток для віверн, споконвічних мешканців Калімдору. Плато дає природний захист від хижаків і відкритий злітний майданчик для мисливських польотів над Тисячею Голок. Тут зграї віверн живуть під захистом пильних ватажків і ватажниць, стережучи свої гнізда. Звірі люто боронять свою територію від будь-якого чужинця, якому вдасться видертися в їхні високі володіння.",sectionIndex=1}
c["subzone:hillsbrad-fields"] = "93fca0"
P.scopedClips["subzone:hillsbrad-fields"] = {scope="overview-body",sourceHash="f51499",hash="93fca0",name="Поля Гілсбреду",summary="Поля Гілсбреду охоплюють оброблені угіддя й сільське поселення Гілсбред на заході Передгір'я Гілсбреда. Це одна з небагатьох уцілілих людських громад колишнього Лордерона, що не скорилася Погибелі й не приєдналася до фанатичного Багряного Хрестового Походу, а тепер її фермери й ополченці постійно відбивають напади Відступників із сусіднього Таррен Мілла.",section="Поля Гілсбреду, що розкинулися садами, гарбузовими грядками й пасовищами між Пагорбом Дарроу й Шахтою Лазурової Жили, постачають необхідні припаси Саутшору й уцілілому опору Альянсу. Поки більша частина Лордерона загинула від чуми нежиття, люди Гілсбреда встояли й гордо зберегли королівські табарди та геральдику свого полеглого королівства. Під проводом Магістрата Бернсайда й Ради Гілсбреда містечко діє як незалежна громада в постійній облозі. Місцевий коваль Веррінґтан і його учні озброюють населення, щоб кожен фермер і робітник був готовий боронити свою землю.",sectionIndex=1}
c["subzone:howling-vale"] = "1f2ebf"
P.scopedClips["subzone:howling-vale"] = {scope="overview-body",sourceHash="178b26",hash="1f2ebf",name="Виюча Долина",summary="Виюча Долина, що сховалася в північно-центральному Ашенвалі біля кордону зі Скверноліссям, — темна улоговина, яку заполонили дикі, чужі цьому світу вовкоподібні звірі — воргени Терровульф. Глибоко в її печерах ховається давнє Святилище Мел'Тандріс — освячені Елуною руїни, тісно пов'язані з трагічним походженням прокляття воргенів на Калімдорі.",section="На північ від дороги до Сквернолісся спокійна велич Ашенвалю поступається моторошному хижому виттю. У долині ростуть давні дерева, а між ними блукають осквернені ватажки зграй Терровульф та агресивні звірі. У її серці — печера, що береже пам'ять про Мел'Тандріс, давню жрицю нічних ельфів. Колись святилище було місцем тихої молитви, але його спокійні зали занепали й лежать у руїнах, осквернені дикими вовколюдьми, чиє походження бентежить Вартових, що стоять неподалік.",sectionIndex=1}
c["subzone:hunter-rise"] = "a85dd8"
P.scopedClips["subzone:hunter-rise"] = {scope="overview-body",sourceHash="04413b",hash="a85dd8",name="Узвишшя Мисливців",summary="Узвишшя Мисливців — одна з високих столових гір, що складають місто Тандер Блаф; воно лежить трохи на південь від центральної скелі. Це головне місце навчання й збору для тауренських воїнів, мисливців, слідопитів і майстрів зі здирання шкур. На його вітряних майданчиках молоді воїни відточують бойові навички й готуються до битв.",section="Узвишшя Мисливців, з'єднане із сусідніми скелями хиткими мотузяними мостами, віддане бойовим традиціям тауренів. Його осердя — Зала Мисливця, де досвідчені стрільці, слідопити й воїни передають свою науку молодшим поколінням. Довкола неї — тренувальні майданчики з опудалами, стійками для зброї й стовпами для вичинки шкур: це жвавий осередок для тих, хто живе списом, луком і шкурою.",sectionIndex=1}
c["subzone:hushed-bank"] = "8205a6"
P.scopedClips["subzone:hushed-bank"] = {scope="overview-body",sourceHash="74eeef",hash="8205a6",name="Притихлий Берег",summary="Притихлий Берег — темне західне узбережжя Сутінколісся вздовж річки, що відділяє ліс від Вестфолу. Тягнеться він від роздоріжжя біля Трьох Кутів на південь до Долини Стренглторну — тихий, але небезпечний ліс, де никають хижі звірі й ховаються темні таємниці.",section="Пролягаючи річковою межею між Сутінколіссям і Вестфолом, Притихлий Берег позначає перехід від відкритих рівнин і осяяних сонцем ферм до всеосяжних неприродних сутінків. Тут через річку перекинуто критий дерев'яний міст — шлях для мандрівників, що прямують на захід із похмурого лісу. Береги заполонили густий підлісок і повзучий туман, а великі павуки й голодні лісові вовки підстерігають необачних подорожніх, що зійшли з битого шляху.",sectionIndex=1}
c["subzone:iris-lake"] = "40f664"
P.scopedClips["subzone:iris-lake"] = {scope="overview-body",sourceHash="4ad270",hash="40f664",name="Озеро Ірисів",summary="Озеро Ірисів — отруєна водойма в північно-центральному Ашенвалі, на схід від Астранаару. Колись чисті води озера набули хворобливого жовто-зеленого відтінку через демонічну скверну, що стікає зі Сквернолісся, а на його берегах тепер нишпорять ворожі болотяні звірі.",section="Озеро Ірисів, що лежить між Астранааром і місячним колодязем, який доглядає Шаель'дрін, — похмуре нагадування про рани Третьої війни. Енергія скверни, що сходить на південь з отруєних висот Сквернолісся, отруїла улоговину, і колись прозорі води перетворилися на смердюче жовто-зелене багно. Скверна спотворила місцеві рослини й духів води, породивши агресивних болотяних звірів, що кидаються на кожного мандрівника, який підійде надто близько.",sectionIndex=1}
c["subzone:ironband-s-compound"] = "514131"
P.scopedClips["subzone:ironband-s-compound"] = {scope="overview-body",sourceHash="c5334e",hash="514131",name="Поселення Айронбенда",summary="Поселення Айронбенда — укріплена застава серед засніжених пагорбів на південь від Озера Ложа Гелма на сході Дун Мороґу. Колись домівка шукача Стурджі Айронбенда, табір захопили ворожі дворфи Темного Заліза, які нападають на кожного, хто підійде надто близько.",section="Це поселення на південь від Озера Ложа Гелма заснував Стурджі Айронбенд, і колись воно було опорним пунктом у засніженій глушині Дун Мороґу. Усе змінилося, коли лазутчики Темного Заліза просунулися глибоко в землі Бронзбірдів і захопили його для себе. Нині поселення, повне ворожих дворфів, служить передовою базою противника, що загрожує мандрівникам і сусіднім селищам просто під носом в Айронфорджа.",sectionIndex=1}
c["subzone:ironband-s-excavation-site"] = "4ca445"
P.scopedClips["subzone:ironband-s-excavation-site"] = {scope="overview-body",sourceHash="ebbbc6",hash="4ca445",name="Місце розкопок Айронбенда",summary="Місце розкопок Айронбенда — великі дворфійські розкопки на південному сході Лох Модану, трохи на південь від озера й на південний захід від Хутора Далекоходів. Археологічні роботи під проводом Шукача Айронбенда раптово зупинилися, коли траншеї заполонили агресивні, непередбачувані троги.",section="Гнаний дворфійським прагненням розкрити своє давнє походження від Титанів, Шукач Айронбенд заклав ці розлогі розкопки на суворих кручах південно-східного Лох Модану. Те, що починалося як багатообіцяльна справа, швидко обернулося лихом, коли копачі потривожили незвично лютих і великих підземних трогів. Створіння вирвалися з-під землі, відкинули рудокопів і отаборилися серед розкиданих інструментів, поламаних візків і напіввідкопаних реліквій.",sectionIndex=1}
c["subzone:ironbeard-s-tomb"] = "d7a252"
P.scopedClips["subzone:ironbeard-s-tomb"] = {scope="overview-body",sourceHash="86403a",hash="d7a252",name="Гробниця Айронбірда",summary="Гробниця Айронбірда — осквернене дворфійське поховання на захід від дороги, що веде на північ до Дун Модра в Багнокраї. Тут є цвинтар просто неба й кам'яна статуя того, чиє ім'я носить гробниця, але склепом давно не користуються: усе довкола кишить їдкими слизунами. Мандрівники рідко заходять у цю западину — хіба що шукаючи загублених речей, які поглинув слиз.",section="Гробниця Айронбірда, що височіє над болотами при дорозі на північ до Дун Модра, свідчить про давню присутність дворфів у Багнокраї. Над довколишнім цвинтарем пильнує величезна кам'яна статуя — певно, самого Айронбірда. Та урочистий спокій тут більше не вартує. Підземний склеп геть заполонили слизуни різних чорних і багряних порід, і гробницю осквернено. Дворфи більше не приносять сюди своїх мерців, а ті, хто наважується потривожити склепи, роблять це здебільшого для того, щоб порпатися в рештках, які перетравили слизуни, що там чатують.",sectionIndex=1}
c["subzone:ironclad-cove"] = "790b63"
P.scopedClips["subzone:ironclad-cove"] = {scope="overview-body",sourceHash="459d20",hash="790b63",name="Бухта Айронклад",summary="Бухта Айронклад — величезна підземна печера, захована під Вестфолом, де розташувалися підземна корабельня й док. Тут Братство Дефіас таємно будує свій бойовий броненосець, а сама печера має прямий вихід до моря.",section="Бухта Айронклад, захована в найглибшій точці Мертвих Копалень, — це велетенська морська печера, перетворена на укріплену верф. Тут Едвін Венкліф і Братство Дефіас збудували величезний бойовий корабель — броненосець. Печеру заповнюють дерев'яні риштування, острівці й вантажні містки, на яких чатують пірати Дефіас, матроси й наглядачі. Саме її існування відкриває справжній розмах загрози: Венкліф не просто збирається грабувати хутори Вестфолу, а готує власний флот, здатний обстрілювати береги самого Стормвінда.",sectionIndex=1}
c["subzone:ironforge-airfield"] = "a274f7"
P.scopedClips["subzone:ironforge-airfield"] = {scope="overview-body",sourceHash="861241",hash="a274f7",name="Летовище Айронфорджа",summary="Сховане високо серед засніжених вершин на північний схід від Айронфорджа, це віддалене дворфське летовище служить полігоном і плацдармом для гномських літальних машин та дворфських горян. Не позначене на головних дорогах, плато височіє над зубчастими скелями Дун Мороґу і крутим спуском до Багнокраю.",section="Високогірне летовище, що здійнялося далеко над уторованими стежками Дун Мороґу, — тихе диво співпраці в Альянсі. Під захистом навколишніх вершин дворфська кладка закріплює вітряні гребені, а гномські літальні машини стоять уздовж відкритих злітних смуг. Горяни стежать за околицями пліч-о-пліч з інженерами, що на лютому морозі закручують шестерні й оглядають двигуни, які пихкають парою.",sectionIndex=1}
c["subzone:ivar-patch"] = "016091"
P.scopedClips["subzone:ivar-patch"] = {scope="overview-body",sourceHash="865af5",hash="016091",name="Ділянка Івара",summary="Ділянка Івара — сплюндрована гарбузова ферма на півночі Срібнолісся. Колись це була квітуча хліборобська садиба Лордерона, але її мешканці загинули під час Третьої війни й обернулися на ненажерливих, бездумно ворожих гулів.",section="До того як Третя війна прокотилася Лордероном, ця гарбузова ділянка була заможною садибою фермера на ім'я Івар, у якого працювала весела ватага наймитів і слуг. Коли Погибель поширила Чуму Нежиття селами, ферма загинула цілком. Івар, його родина й робітники не повстали з уцілілим розумом, як вільні Відступники, а обернулися на гниючих диких гулів, приречених никати зруйнованою землею.",sectionIndex=1}
c["subzone:jaggedswine-farm"] = "f10c07"
P.scopedClips["subzone:jaggedswine-farm"] = {scope="overview-body",sourceHash="bd5f69",hash="f10c07",name="Ферма Зубчастого Вепра",summary="Ферма Зубчастого Вепра — скромна тваринницька садиба на півночі Дуротару, просто на південь від головного входу до Оргріммара. Вона складається з дерев'яної комори, просторого загону та багнистого водопою і є важливим джерелом харчів: тут вирощують витривалих свиней для сусідньої столиці Орди.",section="Вирвана в нещадної, випаленої сонцем землі Дуротару, Ферма Зубчастого Вепра втілює сувору правду про те, чого вартує прогодувати таку міську твердиню, як Оргріммар. Червоний ґрунт краю дає скупі врожаї, тож міцна худоба конче потрібна, щоб нагодувати тисячі орківських воїнів і робітників. Серце ферми — дерев'яна комора, широкий дерев'яний загін і природний ставок-водопій, де свиней зганяють, розводять і забивають, щоб комори Орди не порожніли.",sectionIndex=1}
c["subzone:jangolode-mine"] = "606698"
P.scopedClips["subzone:jangolode-mine"] = {scope="overview-body",sourceHash="4f98b6",hash="606698",name="Шахта Джанґолод",summary="Шахта Джанґолод — багата копальня серед пологих пагорбів Вестфолу. Колись вона була важливим джерелом руди й сировини для Стормвінда, але тепер її захопили бандити з Братства Дефіас.",section="Ще до занепаду Вестфолу Шахта Джанґолод безперервно давала метал, без якого не обходилися ні відбудова Стормвінда, ні його постачання. Коли лад почав розвалюватися, а королівство відкликало гарнізони, Братство Дефіас захопило копальню для власних потреб. Тепер бандити розробляють багаті жили для себе й запекло обороняють свою підземну здобич.",sectionIndex=1}
c["subzone:jasperlode-mine"] = "58c627"
P.scopedClips["subzone:jasperlode-mine"] = {scope="overview-body",sourceHash="9979c7",hash="58c627",name="Яшмова копальня",summary="Яшмова копальня — розробка заліза й мінералів у північно-центральному Лісі Елвінн, що колись постачала Стормвінду життєво важливі ресурси. Нині штольні заполонили рої кобольдів і смертоносні велетенські павуки, і королівство, якому бракує ресурсів, не може її повернути.",section="Яшмова копальня історично була одним із найприбутковіших гірничих промислів Стормвінда, даючи сталі мінеральні багатства поруч із сусіднім Фарґодіпом. Коли військо королівства розтягнулося до краю, обороняючись від зовнішніх загроз і заворушень, місцеві гарнізони не змогли захистити штольні. Кобольди скористалися нагодою, зарилися всередину, вигнали людей-шахтарів і почали складати вкрадене золото й лойові свічки.",sectionIndex=1}
c["subzone:jerod-s-landing"] = "d0fc92"
P.scopedClips["subzone:jerod-s-landing"] = {scope="overview-body",sourceHash="2b12fc",hash="d0fc92",name="Пристань Джерода",summary="Пристань Джерода — скромний річковий причал на елвіннському березі річки Назферіті. Нині захоплена Братством Дефіас, застава служить таємним перевалочним пунктом для незаконних вантажів, які переправляють водними шляхами королівства.",section="Схована на східних водах річки Назферіті, Пристань Джерода дає річковий доступ, що сполучає Ліс Елвінн із сусідніми землями. Колись звичайний човновий причал, нині місце міцно опинилося в руках Братства Дефіас. Під пильним оком начальника пристані з Дефіас розбійники використовують причал як вузол, куди надходять товари, награбовані в Горах Редріджу, і звідки річкові вантажі непомітно сплавляють униз за течією до володінь на кшталт Вежі Клейвена у Вестфолі.",sectionIndex=1}
c["subzone:kargathia-keep"] = "a7db18"
P.scopedClips["subzone:kargathia-keep"] = {scope="overview-body",sourceHash="e4b0e1",hash="a7db18",name="Фортеця Карґатія",summary="Фортеця Карґатія — укріплена твердиня Орди на східному краю Лісозаготівельного Табору Бойової Пісні в Ашенвалі. Тут розташований штаб наглядачів табору: фортеця стереже річковий кордон і забезпечує швидке підкріплення просто з Оргріммара.",section="Фортеця Карґатія, що стоїть на східному краю Лісозаготівельного Табору Бойової Пісні, трохи на захід від Річки Південної Люті, — командний центр лісозаготівель Орди в Ашенвалі. Цю укріплену заставу, обнесену важкими барикадами з шипами, займають наглядач Ґортак і його офіцери. Завдяки вигідному розташуванню над річковим кордоном клан Бойової Пісні може стежити за ворожими вилазками й швидко отримувати підкріплення з сусідніх Дуротара та Оргріммара, щойно вдарять загони нічних ельфів.",sectionIndex=1}
c["subzone:kharanos"] = "f84118"
P.scopedClips["subzone:kharanos"] = {scope="overview-body",sourceHash="925b56",hash="f84118",name="Харанос",summary="Харанос — гамірне гірське поселення в засніженому серці Дун Мороґу, трохи нижче дорогою від Айронфорджа. Головний осередок для мандрівників, що залишають Долину Холодного Хребта, містечко має кузню, гномські майстерні та славетну Ґуральню Тандербрю.",section="Харанос стоїть при головній дорозі Дун Мороґу — це перше справжнє містечко, що вітає новобранців з Анвілмара. Попри лютий холод і пронизливі вітри, поселення процвітає завдяки дворфській упертості та гномській винахідливості. Його серце — ревуча громадська кузня та Ґуральня Тандербрю, що славиться на всі східні гори одним із найкращих елів Каз Модану. Між заклопотаними ремісниками та втомленими мандрівниками, що шукають тепла, містечко лишається головним плацдармом для будь-яких справ у нижніх горах.",sectionIndex=1}
c["subzone:kodo-rock"] = "c2f56e"
P.scopedClips["subzone:kodo-rock"] = {scope="overview-body",sourceHash="6ae7c8",hash="c2f56e",name="Камінь Кодо",summary="Камінь Кодо — природний кам'яний монумент на рівнинах Плато Червоної Хмари, між Табором Нарачі та Яром Тернистого Клинка. Тихо стоячи серед трав Малгору, він слугує раннім місцем паломництва для молодих тауренських шаманів, що вчаться спілкуватися з духами землі. Через скромний силует на тлі хвилястого краєвиду мандрівникам треба добре придивлятися, щоб його помітити.",section="Камінь Кодо стоїть приблизно на півдорозі між Табором Нарачі та ворожими землями шипогривів у Яру Тернистого Клинка; біля його підніжжя помітна латка витоптаної землі. Йому бракує величі високих круч, що оточують Плато Червоної Хмари, але своїм обрисом він нагадує шанованих кодо, що бродять пасовищами. Для мандрівних одноплемінників це тихий природний маяк серед обвітрених рівнин Малгору.",sectionIndex=1}
c["subzone:kolkar-crag"] = "a4a93c"
P.scopedClips["subzone:kolkar-crag"] = {scope="overview-body",sourceHash="090395",hash="a4a93c",name="Круча Колкарів",summary="Круча Колкарів — випалена сонцем зубчаста ущелина на півдні Дуротару, яку захопили ворожі кентаври клану Колкар. Цей анклав під проводом Воєначальника Колканіса служить плацдармом для злагоджених набігів на сусідні поселення Орди.",section="Схована в суворих каньйонах південного Дуротару, Круча Колкарів — опорна база войовничого клану Колкар. Попри посушливу й нещадну місцевість, ці кентаври укріпили природні горловини ущелини. З цього яру їхні розвідники та грабіжники пильно стежать за навколишніми рівнинами, шукаючи слабких місць у володіннях орків і Темного Списа. Для молодих воїнів, що навчаються в Долині Випробувань або патрулюють південне узбережжя, Круча Колкарів — найближчий організований фронт ворожих кентаврів.",sectionIndex=1}
c["subzone:lake-al-ameth"] = "336358"
P.scopedClips["subzone:lake-al-ameth"] = {scope="overview-body",sourceHash="f23a38",hash="336358",name="Озеро Ал'Амет",summary="Озеро Ал'Амет — одна з найбільших прісних водойм високо в гіллі Тельдрассила, одразу на південь від Доланаара. Колись тиха пристань, де не було нічого, крім простого дерев'яного причалу, тепер має небезпечні береги через буйне збурення місцевої рослинності.",section="Озеро Ал'Амет одразу на південь від селища Доланаар — важлива природна улоговина в серці Тельдрассила. Попри тихі води й майже відсутні поселення, спокою тут не стало. Зграї збурених деревляників і паростків деревляників нишпорять край води, збожеволілі від неприродної хвороби, що шириться Світовим Деревом. Друїди й дослідники з Доланаара часто посилають мандрівників на ці береги збирати насіння й виполювати агресивних створінь, перш ніж скверна пошириться глибше в довколишній ліс.",sectionIndex=1}
c["subzone:lake-everstill"] = "e35461"
P.scopedClips["subzone:lake-everstill"] = {scope="overview-body",sourceHash="0bb4c9",hash="e35461",name="Озеро Незрушне",summary="Озеро Незрушне — широка блакитна водойма в самому серці Гір Редріджу, на березі якої лежить містечко Лейкшир. Колись славетне тихою риболовлею й чистими гірськими водами, останнім часом воно стало підступним: його береги й води заполонили агресивні племена мурлоків і хижі озерні звірі.",section="Розкинувшись у центральній улоговині Редріджу, Озеро Незрушне — мальовниче тло й життєво важливий водний шлях для Лейкшира. Його кришталево чисті води стікають на схід, до грізних висот Кам'яної Варти. Через озеро перекинуто центральний міст міста, і віддавна воно годувало місцеву торгівлю й тихих рибалок, але кожен, хто пройдеться берегом сьогодні, побачить, що від його мирної слави не лишилося й сліду через загрози, які насуваються з дикої місцевості.",sectionIndex=1}
c["subzone:lake-falathim"] = "77f424"
P.scopedClips["subzone:lake-falathim"] = {scope="overview-body",sourceHash="a5e4b6",hash="77f424",name="Озеро Фалатім",summary="Озеро Фалатім — спокійна водойма серед лісистих пагорбів західного Ашенвалю, на південний захід від Посту Маестри. Його шанують за те, що місячне світло Елуни торкається його поверхні і вдень, і вночі, тож колись воно було улюбленим місцем відпочинку нічних ельфів. Проте останнім часом береги заполонили агресивні мурлоки, і священний прихисток став небезпечним.",section="Озеро Фалатім, що сховалося на південний схід від Зорамського Узмор'я, калдореї здавна любили як тихе місце, де можна поплавати й порибалити. Місцеві перекази кажуть, що лагідне сяйво Елуни спочиває на цих водах цілодобово, і вдень, і вночі. Та попри це священне благословення, люті мурлоки рушили вглиб суходолу й захопили береги: вони гніздяться тут цілими зграями й проганяють і мандрівників, і вчених.",sectionIndex=1}
c["subzone:lakeridge-highway"] = "889457"
P.scopedClips["subzone:lakeridge-highway"] = {scope="overview-body",sourceHash="a2363b",hash="889457",name="Шосе Лейкрідж",summary="Шосе Лейкрідж — старий шлях уздовж південного берега Озера Незрушного в Горах Редріджу. До Першої війни це була важлива й жвава артерія, але тепер вона занепала й стоїть пусткою. Нині мандрівки дорогою небезпечні через зграї гнолів і орків Блекрок, що никають довкола.",section="До спустошень Першої війни Шосе Лейкрідж було гомінким торговим шляхом крізь Редрідж: ним везли товари й ходили люди вздовж південного берега Озера Незрушного. У ті мирні дні мандрівники могли подорожувати між поселеннями долини й східними висотами під захистом Королівства Стормвінд. Ця безпека розсипалася, коли краєм пройшла Орда, лишивши східний Редрідж спірним і спустошеним.",sectionIndex=1}
c["subzone:lakeshire"] = "d8a53e"
P.scopedClips["subzone:lakeshire"] = {scope="overview-body",sourceHash="d7aa13",hash="d8a53e",name="Лейкшир",summary="Лейкшир — головне людське поселення в Горах Редріджу, що лежить на північному березі Озера Незрушного. Мальовниче містечко, яким править Магістрат Соломон і яке охороняє Маршал Марріс, нині на межі загибелі через безупинні напади орків Блекрок, агресивних зграй гнолів і прибережних мурлоків.",section="Колись мирна гавань у передгір'ях на схід від Стормвінда, Лейкшир став найзапеклішим рубежем королівства. Міський гарнізон у Фортеці Кам'яної Варти жорстоко розгромили орки клану Блекрок, що насунули з півночі, а темне чаклунство згуртувало місцеві зграї гнолів Тіньової Шкури в організовані загони грабіжників. Диверсанти Блекрок навіть зруйнували частину мосту через Озеро Незрушне, і Бригадир Ослоу зі своєю бригадою ледве відновлює прогін під постійною загрозою нападу. Мурлоки заполонили береги озера, гноли нишпорять високими перевалами — захисники Лейкшира на межі сил.",sectionIndex=1}
c["subzone:lakeshire-inn"] = "3420e3"
P.scopedClips["subzone:lakeshire-inn"] = {scope="overview-body",sourceHash="e68069",hash="3420e3",name="Корчма Лейкшира",summary="Корчма Лейкшира — осередок громадського життя й головний прихисток обложеного Лейкшира. Розташована в самому серці Гір Редріджу, вона дає тепло, ель і безпечний нічліг місцевим мешканцям та втомленим мандрівникам, яким доводиться мати справу з довколишніми небезпеками.",section="Корчма Лейкшира на березі Озера Незрушного дає короткий перепочинок від ватаг гнолів і орків Блекрок, що тиснуть на місто. Попри дедалі відчайдушніше воєнне становище Лейкшира, тут панує затишна, гомінка атмосфера. Шинкар Деніелс і Корчмарка Бріанна обслуговують місцевих і мандрівників, подаючи глеки елю, вино й гарячі страви. Це важливе місце зустрічей, де містяни обмінюються новинами, топлять смуток у чарці й шукають найманих клинків, щоб боронити східний кордон королівства.",sectionIndex=1}
c["subzone:lakeshire-town-hall"] = "570470"
P.scopedClips["subzone:lakeshire-town-hall"] = {scope="overview-body",sourceHash="5fb0fb",hash="570470",name="Ратуша Лейкшира",summary="Ратуша Лейкшира — адміністративний осередок Гір Редріджу, що стоїть у серці приозерного поселення. Тут Магістрат Соломон керує місцевими справами, борючись із безупинними загрозами від орків Блекрок і гнолів.",section="Ратуша Лейкшира — стара кам'яна будівля, яку за ці роки старанно оновлювали не раз. Вона займає чільне місце в Лейкширі, і саме тут працює Магістрат Соломон — добрий і відданий справі очільник, якому доручено підтримувати лад на східних теренах Королівства Стормвінд. Воєнні сили Стормвінда розпорошені, королівської допомоги обмаль, тож тиха канцелярія перетворилася на справжній командний центр, де щодня розглядають відчайдушні заклики до добровольців і найманців.",sectionIndex=1}
c["subzone:library-ironforge"] = "09847c"
P.scopedClips["subzone:library-ironforge"] = {scope="overview-body",sourceHash="188118",hash="09847c",name="Бібліотека (Айронфордж)",summary="Бібліотека, що ховається в східному крилі Зали Дослідників, — найголовніша в Айронфорджі скарбниця історичних знань, археологічних реліквій і давніх переказів. Ліга Дослідників ретельно дбає про неї: тут зберігаються численні історичні томи й рідкісні артефакти, знайдені під час розкопок по всьому Азероту.",section="Бібліотека займає величезну залу всередині Зали Дослідників, і саме тут дворфійські вчені перебирають реліквії та польові звіти, які шукачі пригод привозять з усього світу. Полиці, якими опікується Ліга Дослідників, ущерть заставлені основоположними хроніками про Війну Трьох Молотів, давні Тролячі війни й походження дворфійської раси. З питаннями про рідкісні книжки чи пошук в архіві звертаються до Бібліотекарки Мей Пейлдаст.",sectionIndex=1}
c["subzone:library-wing-northshire"] = "a8bbd8"
P.scopedClips["subzone:library-wing-northshire"] = {scope="overview-body",sourceHash="f8b87c",hash="a8bbd8",name="Бібліотечне Крило (Нортшир)",summary="Бібліотечне Крило — тихе, заставлене книжками південне крило Абатства Нортшира в Лісі Елвінн. Це прихисток для вчених, де жерці та маги-початківці, що долучаються до оборони Стормвінда, отримують перші настанови.",section="Бібліотечне Крило, що відгалужується на південь від Головної Зали Абатства Нортшира, вміщує запилені полиці, пюпітри для читання й тихі ніші, присвячені розумовій і духовній підготовці. Поки військові новобранці муштруються в північній Залі Зброї, майбутні маги та жерці збираються тут, щоб осягнути основи таємної магії та Святого Світла. Нині Жриця Анетта наставляє жерців-новачків у справах віри та зцілення, а Келден Бремен навчає магів-початківців надавати форму первісній стихійній енергії.",sectionIndex=1}
c["subzone:lion-s-pride-inn"] = "9aebdc"
P.scopedClips["subzone:lion-s-pride-inn"] = {scope="overview-body",sourceHash="e37cfb",hash="9aebdc",name="Корчма «Лев'яча Гордість»",summary="Корчма «Лев'яча Гордість» — гамірна таверна та громадський осередок Ґолдшира в Лісі Елвінн. Поколіннями її тримає родина Фарлі, і це головне місце перепочинку, зустрічей і найму для мандрівників, що вирушають на південь від Стормвінда.",section="Корчма «Лев'яча Гордість» на перехресті Лісу Елвінн — жвавий центр Ґолдшира. Її тримає Шинкар Фарлі під традиційним гаслом закладу — «Відпочинок і спокій для втомлених і змерзлих», — пропонуючи теплі вогнища, міцні напої та кімнати втомленим шукачам пригод, що щойно вийшли з Нортширу. Родина Фарлі з гордістю порядкує тут уже багато поколінь, ще з часів правління Короля Ллейна Рінна I. Оскільки Ґолдшир лежить на важливих торгових шляхах між Стормвіндом, Вестфолом, Редріджем і Сутінколіссям, корчма — незамінне місце збору, де міські маршали, місцеві ремісники й бувалі наставники діляться новинами та наймають перехожих найманців.",sectionIndex=1}
c["subzone:longshore"] = "00091e"
P.scopedClips["subzone:longshore"] = {scope="overview-body",sourceHash="5b1141",hash="00091e",name="Лонгшор",summary="Лонгшор — широке піщане узбережжя, що тягнеться вздовж усього західного краю Вестфолу. Попри мальовничі простори, берег славиться своєю небезпекою: тут повно агресивних мурлоків, а біля узбережжя розкидані уламки кораблів.",section="Лонгшор тягнеться вздовж усього західного Вестфолу й є одним із найширших суцільних пляжів у Східних Королівствах. Проте спокою подорожнім він не дарує. Прибій належить мурлокам на чолі з горезвісними страховиськами на кшталт Старого Мутноокого, а мілини встелені рештками затонулих суден — серед них і розбиті ельфійські військові кораблі. Ближче до півдня самотні поселенці, як-от Дафна Стілвелл, ледве тримаються проти розбійників Дефіас — а звідти через воду видно Маяк Вестфолу.",sectionIndex=1}
c["subzone:lordamere-lake"] = "78040e"
P.scopedClips["subzone:lordamere-lake"] = {scope="overview-body",sourceHash="223164",hash="78040e",name="Озеро Лордамер",summary="Озеро Лордамер — одна з найбільших прісних водойм Східних Королівств, що межує з Галявинами Тірісфалю, Срібноліссям і Горами Альтерак. Колись гамірне водне серце людської цивілізації на півночі, тепер воно належить некромантам Погибелі, диким мурлокам і тіні нежиті, що шириться над його холодними водами й островами.",section="У золоту добу Альянсу Лордерона Озеро Лордамер лежало на перехресті людської влади. Місто Лордерон, столиця королівства, стерегло його північні береги, біля південного краю височіло місто-держава чарівників Даларан, а гористий східний край облямовувало королівство Альтерак. Колись торгові судна й рибальські човни безстрашно перетинали його широкий, оповитий туманом простір. Після спустошень Третьої війни озеро з осередку торгівлі перетворилося на природний бар'єр, що відділяє землі Відступників у Тірісфалі та Срібноліссі від підступних висот Альтерака.",sectionIndex=1}
c["subzone:lushwater-oasis"] = "d9b111"
P.scopedClips["subzone:lushwater-oasis"] = {scope="overview-body",sourceHash="2fa94e",hash="d9b111",name="Оаза Буйних Вод",summary="Оаза Буйних Вод — одна з трьох живодайних водойм посушливих Пусток, трохи на південь від Перехрестя. Попри пишну зелень, оаза сповнена небезпек: тут кишать агресивні кентаври Колкари, а ще тут вхід до Печер Стогонів. Її отруєні води добре знайомі рибалкам, які шукають дивну Девіантну Рибу.",section="Оаза Буйних Вод, до якої недалеко йти на південь від Перехрестя, обіцяє оманливий перепочинок серед вибілених сонцем просторів Пусток. Пальмові крони й свіжі джерела приваблюють спраглих звірів з усієї савани, але береги захопили кентаври Колкари, що чатують, аби вбивати і дичину, і необережних мандрівників. Оаза — ще й брама до Печер Стогонів, чиї розлогі підземні ходи просочують згубну енергію у ставки нагорі, породжуючи неприродних звірів і химерні мутації.",sectionIndex=1}
c["subzone:maclure-vineyards"] = "239949"
P.scopedClips["subzone:maclure-vineyards"] = {scope="overview-body",sourceHash="cbb8d3",hash="239949",name="Виноградники Маклюрів",summary="Виноградники Маклюрів — розлогий сільськогосподарський маєток на півдні Лісу Елвінн, що належить родині Маклюрів. Відомий виноградом і вином для королівства Стормвінд, маєток не менш сумнозвісний через тривалу запеклу ворожнечу з сусідньою родиною Стоунфілдів.",section="Виноградники Маклюрів серед буйних пагорбів південного Лісу Елвінн мали б бути мирним прихистком виноробства та хліборобства. Натомість щоденну працю затьмарює люте давнє суперництво зі Стоунфілдами, що живуть трохи далі дорогою. Між господарствами глибоко вкорінилися звинувачення в крадіжках і злопам'ятство, і пристрасті не вщухають навіть тоді, коли спільні біди — голодні вепри та кобольди, що насуваються, — загрожують обом садибам.",sectionIndex=1}
c["subzone:maestra-s-post"] = "816d1e"
P.scopedClips["subzone:maestra-s-post"] = {scope="overview-body",sourceHash="45e465",hash="816d1e",name="Пост Маестри",summary="Пост Маестри — невелике поселення Альянсу в західному Ашенвалі, при дорозі на північний захід від Астранаару й на південь від Руїн Ордил'Аран. Його охороняють Вартові нічних ельфів, а ще тут живуть люди — рідкісні гості в прадавньому лісі Калімдору. Пост слугує передовою вартою проти загроз, що насуваються.",section="Пост Маестри, що стоїть під кронами західного Ашенвалю, — це струнка вежа нічних ельфів і відкритий будиночок. Тут важлива зупинка для мандрівників, що прямують між Темним Узбережжям і більшим осередком — Астранааром. Попри спокійну ельфійську архітектуру, застава завжди насторожі. Місцеві Вартові пильно стежать за довколишніми нетрями, де заворушилися осквернені фурболги, а загони Орди неподалік раз у раз загрожують шляхам постачання Альянсу.",sectionIndex=1}
c["subzone:mage-quarter"] = "eb5562"
P.scopedClips["subzone:mage-quarter"] = {scope="overview-body",sourceHash="c69363",hash="eb5562",name="Квартал магів",summary="Квартал магів — чародійне серце Стормвінда, що лежить за каналами в південно-західному куті столиці. Над його брукованими вулицями й крамницями езотеричних товарів височіє Святилище Чародія, де чарівники королівства вдосконалюють своє мистецтво. Та під ученою поверхнею кварталу ховаються й тіньові закутки, де знайшли притулок адепти куди темніших мистецтв.",section="До Кварталу магів ведуть мости через канали із Соборної Площі чи Торгового Кварталу, і він цілком присвячений містичним потребам Альянсу. Довкола шпиля Святилища Чародія збираються людські чарівники та їхні союзники, щоб вивчати плетиво таємної магії й навчати учнів. Довколишні вулиці заповнюють торговці тканинами для кравців, реагентами, алхімічним приладдям і зачарованими палицями, і квартал живе власним відокремленим життям, присвяченим дослідженням і обороні королівства.",sectionIndex=1}
c["subzone:magic-quarter"] = "b9c655"
P.scopedClips["subzone:magic-quarter"] = {scope="overview-body",sourceHash="b2e4e6",hash="b9c655",name="Магічний Квартал",summary="Магічний Квартал — північно-східний район Андерсіті, осередок чародійних студій і темного чаклунства Відступників. Над кварталом панує зловісний Храм Проклятих, а живуть тут знавці і чародійних мистецтв, і магії скверни.",section="Магічний Квартал займає північно-східну частину підземного міста: тут Відступники бережуть свою чародійну спадщину й заглиблюються в темніші методи. Осердя району — похмурий Храм Проклятих, архітектурна пам'ятка Погибелі, яку нежить із вільною волею пристосувала для своїх потреб. Під його тінистими склепіннями маги тонко керують магічною енергією, а поруч чорнокнижники спілкуються з демонічними істотами, тож квартал став осердям інтелектуальної сили й окультних досліджень у Лордероні.",sectionIndex=1}
c["subzone:main-hall-northshire"] = "87bf13"
P.scopedClips["subzone:main-hall-northshire"] = {scope="overview-body",sourceHash="9d5475",hash="87bf13",name="Головна Зала (Нортшир)",summary="Головна Зала — центральна вхідна зала Абатства Нортшира в Лісі Елвінн. Це головне перехрестя, що сполучає подвір'я абатства з його верхньою вежею, Залою Зброї та Бібліотечним Крилом. Сюди з'являються щойно набрані шукачі пригод з людей, щоб отримати перші доручення на службі королівству Стормвінд.",section="Ступивши крізь величні арки Абатства Нортшира, відвідувачі одразу потрапляють до Головної Зали. Як центральний вузол будівлі, вона спрямовує прибулих учнів і церковний люд між окремими крилами абатства: військовою Залою Зброї з одного боку, ученим Бібліотечним Крилом з іншого та сходами, що ведуть у вежу абатства. Тихе святилище зали затьмарює безперервна боротьба в долині, бо офіцери скликають дужих новоприбулих боронити кордони королівства.",sectionIndex=1}
c["subzone:malaka-jin"] = "cd0565"
P.scopedClips["subzone:malaka-jin"] = {scope="overview-body",sourceHash="eaff9d",hash="cd0565",name="Малака'джин",summary="Малака'джин — невеликий табір Орди в нижніх пагорбах Гір Кам'яного Кігтя, трохи південніше Застави Ґрімтотем. Тут живуть переважно мисливці-тролі з племені Темного Спису, а саме поселення — проста придорожня станція й мисливська застава для мандрівників, що підіймаються з Пусток у суворі гори.",section="Малака'джин, захований біля головного шляху в Гори Кам'яного Кігтя, дає жаданий прихисток мандрівникам Орди, що рушають у спірні височини. Тут живе ватага загартованих мисливців-тролів, які добувають собі прожиток серед скель і чагарників. Живуть вони скромно, але постачають припаси, продають утомленим шукачам пригод свіжу дичину й пильно стежать за ворожими гірськими звірами та войовничими тауренами Ґрімтотем, що чатують вище на стежках.",sectionIndex=1}
c["subzone:malden-s-orchard"] = "cf55b4"
P.scopedClips["subzone:malden-s-orchard"] = {scope="overview-body",sourceHash="dceada",hash="cf55b4",name="Сад Малдена",summary="Сад Малдена — зруйнований хутір на півночі Срібнолісся, названий на честь господаря-людини, що втік під час навали Погибелі на Лордерон. Давно покинуті темні вічнозелені дерева заросли, а угіддями никають люті чорні ворги. Напівзруйнована хата в саду правила за тимчасовий прихисток розвідникові-Відступникові, якого відрізало від загону.",section="До Третьої війни ця садиба постачала свіжі фрукти містам Лордерона, а доглядав її фермер на ім'я Малден. Коли Погибель пройшлася королівством, Малден покинув свою землю, рятуючись від чуми. Відтоді сад задихається під темними туманами Срібнолісся, що підступають. Вічнозелені дерева стоять необрізані, плоди гниють незібраними на уражених гілках, і ділянку цілком відвоювали дикі хижаки.",sectionIndex=1}
c["subzone:manor-mistmantle"] = "db9c1d"
P.scopedClips["subzone:manor-mistmantle"] = {scope="overview-body",sourceHash="3709f7",hash="db9c1d",name="Маєток Містмантл",summary="Маєток Містмантл — занепала садиба серед темних пагорбів північно-східного Сутінколісся, на північ від Даркшира. Колись це було пристойне родинне обійстя, а тепер — руїна й жах, де кишать гулі, прив'язані до її сумнозвісного господаря.",section="Маєток Містмантл, що стоїть на захід від Притону Жебрака, — похмурий пам'ятник убивству й божевіллю. Подвір'я заполонив тлін, а довкола зруйнованої будівлі никають люті гулі, що її охороняють. Серед гнилі й зів'ялої рослинності єдина ознака живої краси на всій садибі — самотня сумна квітка в занедбаному саду: Сльоза Тіллоа.",sectionIndex=1}
c["subzone:mast-room"] = "083a7a"
P.scopedClips["subzone:mast-room"] = {scope="overview-body",sourceHash="051fe5",hash="083a7a",name="Щоглова Кімната",summary="Щоглова Кімната — простора підземна лісопильня глибоко в Мертвих Копальнях. Тут під наглядом гобліна Сніда та його теслів обробляють деревину, вирубану у Вестфолі."}
c["subzone:master-s-glaive"] = "2f5cb6"
P.scopedClips["subzone:master-s-glaive"] = {scope="overview-body",sourceHash="b94580",hash="2f5cb6",name="Глефа Володаря",summary="Глефа Володаря — давня моторошна пам'ятка в південно-західній частині Темного Узбережжя, де велетенська адамантитова зброя стирчить, устромлена в колосальний скам'янілий череп. Місцеві нічні ельфи здавна шанували це місце як священну таємницю, але тепер тут кишать культисти Молота Присмерку, яких приваблює залишкова злоба давньої сутності.",section="Глефа Володаря, що здіймається із землі Темного Узбережжя, — масивне адамантитове лезо, глибоко встромлене в колосальний скам'янілий череп. Жоден запис не називає ні істоти, що загинула тут, ні руки, що вгородила лезо. Ону, Древо Знань, каже лише, що на цьому місці впав старий-престарий володар землі, а нічні ельфи довго вірили, що таку велетенську зброю могли тримати лише титани. Сьогодні пробитий моноліт стоїть суворим скам'янілим пам'ятником тієї забутої боротьби.",sectionIndex=1}
c["subzone:menethil-harbor"] = "e59ba9"
P.scopedClips["subzone:menethil-harbor"] = {scope="overview-body",sourceHash="5ecd23",hash="e59ba9",name="Гавань Менетіл",summary="Гавань Менетіл — добре укріплене дворфійське портове містечко на острові біля західного берега Багнокраю. Збудоване на місці старої орківської верфі й назване на честь короля Теренаса Менетіла II, воно є головною морською артерією, що з'єднує Східні Королівства з далекими берегами Калімдору. Захищене могутніми кам'яними мурами та міцними вежами Фортеці Менетіл, це жвавий осередок для купців, вояків у відпустці й просолених шукачів пригод.",section="Уперше це місце прислужилося Вождеві Орґріму Думхаммеру під час Другої війни, коли Орда будувала тут армаду вторгнення з дерева й заліза, награбованих у Каз Модані. Після розгрому орків великий адмірал Дейлін Праудмур наглядав за відбудовою стоянки, перетворивши її на найкращу гавань Альянсу, і назвав її на честь покійного короля Лордерону Теренаса Менетіла II. Попри віддалене розташування серед боліт, це добре захищений бастіон: його обороняють могутні мури, єдина гребля з мостом і чотири кам'яні сторожові вежі Фортеці Менетіл.",sectionIndex=1}
c["subzone:merchant-coast"] = "766741"
P.scopedClips["subzone:merchant-coast"] = {scope="overview-body",sourceHash="905b5c",hash="766741",name="Узбережжя Крамарів",summary="Узбережжя Крамарів — смуга східного берега Пусток над Великим Морем. Тут панує гамірний гоблінський порт Раджет, а назва узбережжя походить від прибуткової морської торгівлі, хоча за нього постійно змагаються пірати.",section="Узбережжя Крамарів, що тягнеться східним краєм Пусток, — важлива морська артерія, яка з'єднує центральний Калімдор зі Східними Королівствами й Терамором. Назва вшановує працьовитих гоблінських торговців картелю Стімвідл, чий нейтральний порт Раджет приймає вантажі від кожного, у кого водяться гроші. Проте відкриті морські шляхи приваблюють не лише торгові кораблі: Флібустьєри Південних морів нишпорять пісками й ближніми водами, полюють на купецькі судна й облаштовують на пляжах свої темні справи.",sectionIndex=1}
c["subzone:military-ward"] = "b67bb9"
P.scopedClips["subzone:military-ward"] = {scope="overview-body",sourceHash="a5376f",hash="b67bb9",name="Військовий Квартал",summary="Військовий Квартал — бойове серце Айронфорджа, де розташовані командні споруди міста, майстри зброї й казарми. Тут, під яскраво-червоними стягами, дворфійські вояки, мисливці й облогові інженери вправляються поруч із механізованими облоговими машинами й літальними апаратами.",section="Військовий Квартал лежить у північній частині гірської твердині й зосереджує оборонні сили Айронфорджа на гамірному плацдармі. У центральному комплексі — Залі Зброї — працюють наставники воїнів і мисливців та розпорядники битв, а в ангарах стоять дворфійські літальні машини й парові танки. Довкола плаців і тренувальних опудал розташовані крамниці — «Лати й кольчуги Креґгелма», «Мисливське спорядження Ґолдф'юрі», «Зброя Тімберлайна», — тож квартал став головним місцем збору для гірських вояків і захисників міста.",sectionIndex=1}
c["subzone:mirage-raceway"] = "51aa9f"
P.scopedClips["subzone:mirage-raceway"] = {scope="overview-body",sourceHash="55d762",hash="51aa9f",name="Перегони Міражу",summary="Перегони Міражу — імпровізований інженерний полігон на мерехтливих солончаках Тисячі Голок. Він виник із запеклого суперництва між гоблінським майстром Поззіком і гномом-інженером Фіззлом Брассболтсом: тут ракетні автомобілі змагаються на розпеченій землі. Траса — нейтральне місце, куди приходять і Альянс, і Орда, щоб робити ставки, майструвати й уболівати за улюблені машини.",section="Перегони Міражу розкинулися на безкраїй білій пустелі Мерехтливих Низин і народилися із запеклої давньої ворожнечі двох майстрів-винахідників: гобліна Поззіка й гнома Фіззла Брассболтса. Вирішивши раз і назавжди з'ясувати, чия раса технічно кмітливіша, обидва збудували власні ракетні гоночні машини, найняли суперницькі команди й щодня зводять їх у шалених швидкісних двобоях. Невпинне змагання перетворило голі солончаки на гамірний осередок винахідництва, диверсій і випробувань: кожна команда відчайдушно шукає бодай якоїсь механічної переваги.",sectionIndex=1}
c["subzone:mirkfallon-lake"] = "243c18"
P.scopedClips["subzone:mirkfallon-lake"] = {scope="overview-body",sourceHash="a09ab2",hash="243c18",name="Озеро Міркфаллон",summary="Озеро Міркфаллон лежить у високогірній улоговині в центрі Гір Кам'яного Кігтя, під прямовисними скелями Кручі Вітрорізу. Його води й береги кишать дикою живністю: тут водяться агресивні слизуни, бродячі громові ящери та віверни, що спускаються сюди з висоти.",section="Озеро Міркфаллон лежить у самому центрі хребта Кам'яного Кігтя, між гірськими перевалами, що ведуть на південь до Стежки Павутинника й на північ до Піка Кам'яного Кігтя. Наповнене високогірними стоками, озеро — родюча оаза посеред скелястих вершин: сюди сходять на водопій громові ящери, а віверни злітають зі своїх гнізд високо вгорі. У воді живуть ще й дивні булькотливі слизуни, тож це спокійне гірське озерце стає небезпечною переправою для самотніх мандрівників.",sectionIndex=1}
c["subzone:mirror-lake"] = "c2799d"
P.scopedClips["subzone:mirror-lake"] = {scope="overview-body",sourceHash="637166",hash="c2799d",name="Дзеркальне Озеро",summary="Дзеркальне Озеро — мальовнича водойма на північному заході Лісу Елвінн, біля саду. Живлене лагідним водоспадом під скелями Стормвінда, його спокійне плесо приховує небезпеки на берегах — від розбійників Дефіас, що тут нишпорять, до дивних збурень у місцевих лей-лініях.",section="Дзеркальне Озеро під високими валами Стормвінда мало б бути мирним прихистком для рибалок і втомлених мандрівників. Натомість довколишніми садами скрадаються розбійники Братства Дефіас, тож будь-яке тривале перебування тут небезпечне для місцевих. Ще гірше: містичні збурення по всьому Азероту почали викривлювати природні канали таємної енергії по всьому лісу. Маги зі Святилища Чародія пильно наглядають за озером і посилають учнів брати проби його течій, щоб переконатися, що хаотичні таємні стоки не отруюють громади нижче за течією.",sectionIndex=1}
c["subzone:mirror-lake-orchard"] = "6bb205"
P.scopedClips["subzone:mirror-lake-orchard"] = {scope="overview-body",sourceHash="533cb0",hash="6bb205",name="Сад Дзеркального Озера",summary="Сад Дзеркального Озера — тихий гай із хатиною на південному березі Дзеркального Озера на заході Лісу Елвінн. Колись мирна садиба біля Громових водоспадів, нині він у руках розбійників Дефіас, які визискують околицю, поки вартові Стормвінда дивляться деінде.",section="Схований біля спадаючих вод Громових водоспадів, Сад Дзеркального Озера колись був родючою садибою, що користалася чистими водами Дзеркального Озера. Нині мирна хатина захоплена спритними злодіями й розбійниками під кольорами Братства Дефіас. Поки військо королівства розтягнуте до краю, а Король Варіан Рінн зник, сільські маєтки на кшталт цього саду стали легкою здобиччю для злочинців, що шукають сховків по всій елвіннській околиці.",sectionIndex=1}
c["subzone:mist-s-edge"] = "43b77a"
P.scopedClips["subzone:mist-s-edge"] = {scope="overview-body",sourceHash="b7f7cd",hash="43b77a",name="Край Імли",summary="Край Імли — довге, продуване вітрами узбережжя, що тягнеться на північ від Обердайна західним краєм Темного Узбережжя. Оповиті вологим морським туманом, ці сірі пляжі всіяні уламками кораблів, рештками велетенських морських створінь і мандрівними зграями крабів і мурлоків.",section="Край Імли, що тягнеться західним краєм Темного Узбережжя, — це вологі піски, кам'янисті припливні калюжі й вічний прибережний туман. Пляж — справжнє морське кладовище, всіяне тушами морських велетнів, що розкладаються, плавником і розтрощеними ребрами розбитих суден. Хоч берег здається безлюдним, він кишить падальниками: передусім агресивними крабами й ревнивими до своєї території племенами мурлоків, що гніздяться в прибої.",sectionIndex=1}
c["subzone:misty-pine-refuge"] = "24557b"
P.scopedClips["subzone:misty-pine-refuge"] = {scope="overview-body",sourceHash="2948b3",hash="24557b",name="Притулок Туманних Сосен",summary="Притулок Туманних Сосен — невелика будівля-застава Срібного світанку серед морозних снігів центрального Дун Мороґу.",section="Розташований серед обвіяних вітрами пагорбів Дун Мороґу, Притулок Туманних Сосен — непримітна застава Срібного світанку в дворфському краї. Поки навколишні скелі патрулюють горяни Айронфорджа, у притулку живе Отець Ґевін, єдиний представник ордену в цих краях, що дає тихе вогнище посеред лютої негоди й небезпек, які загрожують гірським дорогам.",sectionIndex=1}
c["subzone:mo-grosh-stronghold"] = "ddfd93"
P.scopedClips["subzone:mo-grosh-stronghold"] = {scope="overview-body",sourceHash="567f76",hash="ddfd93",name="Твердиня Мо'ґрошів",summary="Твердиня Мо'ґрошів — укріплене лігво огрів, викопане в північно-східних пагорбах Лох Модану. Ці жорстокі велетні, що засіли серед давніх обвітрених руїн, постійно загрожують дворфійським поселенням унизу.",section="Твердиня Мо'ґрошів, що ховається серед скель північно-східного Лох Модану, — головна база клану огрів Мо'ґрош у краї. Громили, що засіли в печерах і зовнішніх таборах, нападають на дворфійські каравани з припасами й становлять постійну небезпеку для спокою Телсамара. Грубе каміння, розкидане довкола табору, свідчить, що колись тут було давніше поселення, доки незграбні огри не захопили цю землю й не насипали своїх характерних курганів.",sectionIndex=1}
c["subzone:molsen-farm"] = "f20974"
P.scopedClips["subzone:molsen-farm"] = {scope="overview-body",sourceHash="ec8cdb",hash="f20974",name="Ферма Молсена",summary="Ферма Молсена — покинутий хутір у хліборобському краї Вестфолу. Колись ця родюча земля годувала Стормвінд, а тепер ферма лежить у руїнах: спершу прийшло Братство Дефіас, а по ньому лишилися механічні големи жнив, що й досі нишпорять полями.",section="Як і чимало хуторів Вестфолу, Ферма Молсена стала жертвою королівської байдужості та злочинного заколоту. Коли Братство Дефіас узяло край під свою руку, фермерів вигнали — а то й гірше, — і вони покинули і врожай, і будівлі. Тепер замість женців неприбраними полями нишпорять ворожі механічні Вартові Урожаю та блукають розбійники, тож ферма небезпечна для кожного, хто мандрує цим краєм.",sectionIndex=1}
c["subzone:moonbrook"] = "5c8f32"
P.scopedClips["subzone:moonbrook"] = {scope="overview-body",sourceHash="33c994",hash="5c8f32",name="Мунбрук",summary="Колись Мунбрук був жвавим хліборобським і гірницьким містечком на південному заході Вестфолу, а тепер це беззаконне місто-примара. Його цілком захопило Братство Дефіас і використовує як укріплену ширму, за якою ховається їхній підземний штаб у Мертвих Копальнях.",section="До Першої війни Мунбрук був важливою громадою в самому серці житниці Вестфолу: тут жили фермерські родини, а поруч давали прибуток золоті шахти Мертвих Копалень. Стара Орда спалила його вщент, після Другої війни його старанно відбудували, та спокій тривав недовго. Дім Вельмож у Стормвінді не дбав про поселення, військового захисту воно не мало — і не змогло вистояти перед мстивою Гільдією Каменярів, коли та подалася в глушину. Бандити прогнали чесних хуторян, і городянам разом з учителями довелося тікати до Сентінел Гілла та Лісу Елвінн.",sectionIndex=1}
c["subzone:moonshrine-ruins"] = "5f00be"
P.scopedClips["subzone:moonshrine-ruins"] = {scope="overview-body",sourceHash="1773d8",hash="5f00be",name="Руїни Місячної Святині",summary="Руїни Місячної Святині — затоплений простір давньої архітектури нічних ельфів глибоко в Чорноглибинних Печерах. Колись присвячені поклонінню Елуні, ці напівзруйновані зали осквернив і захопив культ Молота Присмерку.",section="За печерним Ставком Аск'ар лежать Руїни Місячної Святині — сумне свідчення давнього минулого нічних ельфів на узбережжі Ашенвалю. У цих напівзатоплених залах колись лунали співи на честь Місячної Богині Елуни, але Великий Розкол зруйнував храм і затопив його нижні яруси морською водою. Сьогодні каламутні води кишать дикими морськими звірами — від агресивних крабів до змієподібних трешадонів, а культ Молота Присмерку хазяйнує серед каміння, правлячи темні ритуали, що глузують зі священного походження святині.",sectionIndex=1}
c["subzone:moonspray"] = "a3f0c4"
P.scopedClips["subzone:moonspray"] = {scope="overview-body",sourceHash="d1e2f3",hash="a3f0c4",name="Місячні Бризки",summary="«Місячні Бризки» — транспортне судно Альянсу з Флоту калдореїв. Воно перевозить мандрівників через води, що відділяють материковий Калімдор від велетенського Світового Дерева, Тельдрассилу.",section="«Місячні Бризки» — незамінна нитка між доками Обердайна на березі Темного Узбережжя й Селищем Рут'теран біля коріння Тельдрассилу. Перетинаючи Приховане Море, судно перевозить шукачів пригод, гінців і важливі припаси між відокремленим святилищем нічних ельфів у кроні Світового Дерева й давнім материком Калімдору.",sectionIndex=1}
c["subzone:moonwell-ashenvale"] = "e4d6bd"
P.scopedClips["subzone:moonwell-ashenvale"] = {scope="overview-body",sourceHash="3c9a3b",hash="e4d6bd",name="Місячний колодязь (Ашенваль)",summary="Це відлюдне святилище, яке нічні ельфи звуть Місячним Колодязем Чистоти, лежить у центральному Ашенвалі, на схід від Озера Ірисів і на захід від Притулку Рейнвуд. Його благословенні води несуть ласку Елуни, живлячи прадавній ліс і очищаючи землю від повзучої скверни. Мандрівники Альянсу й вартові нічних ельфів часто приходять до його тихої чаші, щоб очистити осквернені артефакти, знайдені в лісі.",section="Цей місячний колодязь, що сховався під кронами центрального Ашенвалю, — духовна опора калдореїв. Його сяйливі води черпають приховану магію природи та світло Місячної Богині. Довколишній ліс потерпає від скверни сатирів, демонічної отрути й вирубок, тож чисті святилища на кшталт цього стають рятівною ниткою для тих, хто намагається зцілити ліс.",sectionIndex=1}
c["subzone:mor-shan-rampart"] = "807d5a"
P.scopedClips["subzone:mor-shan-rampart"] = {scope="overview-body",sourceHash="78fb88",hash="807d5a",name="Вал Мор'шан",summary="Вал Мор'шан — потужно укріплена барикада Орди на північному кордоні Пусток, що стереже вхід до Ашенвалю. Збудований переважно кланом Бойової Пісні, він захищає землі Орди від контрударів нічних ельфів і водночас слугує плацдармом для вилазок углиб лісу.",section="Вал Мор'шан, що стоїть на північному кінці Золотого Шляху, позначає межу між посушливими рівнинами Пусток і прадавніми кронами Ашенвалю. Цей оплот із важких колод, оборонних частоколів і укріплених сторожових веж звели, щоб стримати відплатні удари нічних ельфів, обурених вирубками Орди. Він водночас і щит, що береже північну браму до глибин Калімдору, і передовий плацдарм для загонів, які прориваються на північ до Астранаару.",sectionIndex=1}
c["subzone:mortwake-s-tower"] = "f4c231"
P.scopedClips["subzone:mortwake-s-tower"] = {scope="overview-body",sourceHash="dd827b",hash="f4c231",name="Вежа Клавена",summary="Вежа Клавена, яку ще звуть Вежею Дефіас, — укріплена сторожова вежа біля річки на південному сході Вестфолу. Нею командує розбійник Клавен Мортвейк, і для контрабанди краденого через кордони королівства вона слугує важливою перевалочною точкою.",section="Вежа Клавена стоїть у прикордонні на північ від Кинджальних Пагорбів і є важливим осередком Братства Дефіас у південному Вестфолі. Разом із Пристанню Джерода на тому боці річки, у Лісі Елвінн, вона править за приймальний пункт і перевалочну базу для контрабанди, награбованої в Горах Редріджу. Звідси видно всі водні шляхи, тож Братство непомітно проводить свої вантажі повз королівські патрулі й ховає від очей Корони всю мережу постачання.",sectionIndex=1}
c["subzone:mystic-ward"] = "03870f"
P.scopedClips["subzone:mystic-ward"] = {scope="overview-body",sourceHash="366b53",hash="03870f",name="Квартал містиків",summary="Квартал містиків — північно-західний район Айронфорджа, тихий прихисток дворфійської столиці для духовного служіння й чародійних студій. Його легко впізнати за прохолодними блідо-блакитними стягами й тихими залами: він разюче відрізняється від дзвону ковадел сусідньої Великої Кузні. Найвеличніша його споруда, Зала Таїнств, збирає жерців, паладинів і магів під печерними кам'яними арками.",section="Дворфи славляться по всьому Азероту майстерністю в кузні та на полі бою, а Квартал містиків уособлює тихіші, розумові й духовні пошуки королівства. Позначений блідо-блакитною геральдикою, цей печерний квартал поєднує гамірні Торгові Ряди з Покинутою Печерою та Великою Кузнею. Тут купці постачають ученим і чародіям вбрання, сувої та алхімічні реагенти — у крамницях на кшталт «Бойового чарівника» чи «Містичного вбрання Мейви». Над районом панує велична Зала Таїнств, де святі дисципліни Святого Світла перетинаються з вивіреним мистецтвом чародійної магії й де настанови отримують ті, хто володіє невидимими силами на захист Альянсу.",sectionIndex=1}
c["subzone:mystral-lake"] = "053003"
P.scopedClips["subzone:mystral-lake"] = {scope="overview-body",sourceHash="1ef764",hash="053003",name="Озеро Містраль",summary="Озеро Містраль — найбільша водойма Ашенвалю, що лежить у південно-центральній частині лісу, трохи нижче Притулку Срібного Вітру. Колись це був тихий прихисток під охороною водяних елементалів, вірних нічним ельфам, але відколи місцевих елементалів осквернили, води озера стали небезпечними.",section="Озеро Містраль, що розкинулося на південь від Притулку Срібного Вітру й на схід від Долини Глибокого Кігтя, калдореї здавна цінували за чисті води й мирних елементалів-охоронців. Та темне втручання зруйнувало давній спокій. Маг-ренегат Сарілус Фоулборн обернув свої чари проти водяних духів озера й перетворив їх на ворожих, лютих створінь. Сьогодні дорога часто приводить мандрівників і з Орди, і з Альянсу до цих неспокійних берегів, де їм доводиться протистояти гніву духів, які колись оберігали ліс.",sectionIndex=1}
c["subzone:night-run"] = "cf823e"
P.scopedClips["subzone:night-run"] = {scope="overview-body",sourceHash="c985fa",hash="cf823e",name="Нічний Потік",summary="Нічний Потік — невелика відлюдна застава сатирів на оточеному кручами пагорбі в східно-центральному Ашенвалі. Тут живуть демонічні сатири Мускусу Скверни, які перетворили давні ельфійські руїни на осквернений табір, де ховають темну магію душ.",section="Нічний Потік — найменша й найвіддаленіша з трьох головних твердинь сатирів в Ашенвалі, поряд із Ксавіаном і Сатирнааром. Поселення, що ховається серед напівзруйнованої ельфійської кладки й поламаних колон, виступає на високому гребені, обмеженому стрімкими неприступними кручами. Щоб дістатися сюди, доводиться або йти кружним шляхом уздовж Річки Фалфаррен біля вод Ксавіана, або пробиратися небезпечним північним уступом над Притулком Рейнвуд. Попри скромні розміри, це гніздо дуже небезпечне: сатири Мускусу Скверни діють разом із таємничим Культом Темного Берега й закріплюють тут спотворені самоцвіти душ, що збирають демонічну есенцію в лісі.",sectionIndex=1}
c["subzone:nightmare-vale"] = "b9b161"
P.scopedClips["subzone:nightmare-vale"] = {scope="overview-body",sourceHash="808d9b",hash="b9b161",name="Долина Жахіть",summary="Долина Жахіть — тіниста улоговина в південно-західних Галявинах Тірісфалю, одразу на захід від Застави Хрестоносця. Колись пишний лісовий притулок, тепер її дерева всохли від пошесті, а серед покручених стовбурів нишпорять люті хижаки.",section="До Третьої війни ця долина була зеленою частиною сільського Тірісфалю, повною співочих птахів і звичайної лісової дичини. Після чуми Погибелі рослинність почорніла й згнила. Ненажерливі темні гончаки й величезні кажани-вампіри пожерли місцеву живність, обернувши улоговину на похмурий притулок падложерів і хижих звірів.",sectionIndex=1}
c["subzone:nightsong-woods"] = "902ada"
P.scopedClips["subzone:nightsong-woods"] = {scope="overview-body",sourceHash="53c7a8",hash="902ada",name="Ліс Нічної Пісні",summary="Ліс Нічної Пісні — охоплений боями східний простір Ашенвалю, що тягнеться від Притулку Рейнвуд до кордонів Азшари. Це головне поле битви між нічними ельфами, які боронять свій священний ліс, і кланом Бойової Пісні, що заготовляє деревину для Орди. Серед його тінистих галявин давні гаї протистоять укріпленим таборам, а довкола не вщухає демонічна скверна.",section="Ліс Нічної Пісні, що простягається через Ашенваль на схід аж до Азшари, — край, де насильство тільки наростає. Річка Фалфаррен розтинає його західну частину, утворюючи хитку межу між поселеннями Альянсу та загарбаними землями Орди. Далі на схід ліс розпадається на запекло спірні території, де Застава Розщепленого Дерева керує походами Орди проти Вартових Срібнокрилих. Орківські сокири невпинно вирубують південні гаї, живлячи розширення Орди й залишаючи голі просіки, що доводять калдореїв до люті. Небезпеки додають твердині сатирів на кшталт Сатирнаару й Ксавіана та демонічні рештки в Каньйоні Падіння Демона й на Пагорбі Вогню Скверни, які отруюють східні крони.",sectionIndex=1}
c["subzone:north-coast"] = "c32381"
P.scopedClips["subzone:north-coast"] = {scope="overview-body",sourceHash="b7fabf",hash="c32381",name="Північне Узбережжя",summary="Північне Узбережжя — похмура, оповита туманом смуга берега, що позначає північний край Галявин Тірісфалю вздовж Великого Моря. Отруєні падінням Лордерона, холодні пляжі всіяні гнилою морською живністю, і їх запекло боронять племена ворожих мурлоків.",section="До Третьої війни ці північні води й кам'янисті пляжі були частиною мирного північного рубежу Лордерона. Коли Чума Нежиті прокотилася континентом, її згубна пошесть стекла з круч і отруїла узбережжя. Води стали холодними й каламутними, викидаючи туші велетенських морських створінь, що тепер гниють на піску серед вічного прибережного туману.",sectionIndex=1}
c["subzone:north-gate-outpost"] = "322d51"
P.scopedClips["subzone:north-gate-outpost"] = {scope="overview-body",sourceHash="125e2e",hash="322d51",name="Застава Північної Брами",summary="Застава Північної Брами — укріплений дворфський табір високо на Перевалі Північної Брами в Дун Мороґу. Охороняючи суворий шлях між засніженим серцем земель Айронфорджа та Лох Моданом, тутешні горяни боронять мандрівників від ворожої звірини, якою кишать скелі.",section="Розташоване посеред Перевалу Північної Брами, це невелике поселення — північно-східний поріг Дун Мороґу. Дворфські горяни, що стоять тут, очищають головну дорогу від хижаків і стежать за рухом крізь гірські тунелі до Лох Модану. Суворий клімат і круті яри роблять патрулювання небезпечним, тож гарнізон часто просить мандрівників обшукати навколишні хребти в пошуках зниклих патрулів і небезпечних хижаків.",sectionIndex=1}
c["subzone:north-gate-pass"] = "0f00b5"
P.scopedClips["subzone:north-gate-pass"] = {scope="overview-body",sourceHash="95ee3a",hash="0f00b5",name="Перевал Північної Брами",summary="Перевал Північної Брами — важливий гірський шлях, що з'єднує засніжені скелі Дун Мороґу з пологою улоговиною Лох Модану. Це північний коридор крізь вершини Каз Модану під наглядом укріпленої дворфійської застави. Мандрівники, що прямують до північних низин Багнокраю, часто йдуть цим високим шляхом.",section="Перевал Північної Брами, вирубаний у прямовисних скелях Каз Модану, — північна артерія, що з'єднує високі замерзлі долини Дун Мороґу з помірними водами Лох Модану. Спустившись крутими гірськими тунелями, мандрівники, що виходять із заходу, бачать широкий простір долини з озером. Оскільки перевал лежить недалеко від шляхів, що спускаються в Багнокрай, ним постійно ходять дворфійські гінці, купці й мандрівні шукачі пригод. Його стратегічне значення тримає Застава Північної Брами, де горяни пильно вартують від трогів і гірських хижаків.",sectionIndex=1}
c["subzone:north-tide-s-hollow"] = "39f620"
P.scopedClips["subzone:north-tide-s-hollow"] = {scope="overview-body",sourceHash="e5816c",hash="39f620",name="Лощина Північного Припливу",summary="Лощина Північного Припливу — дикий куточок Срібнолісся трохи на північ від Гробниці. Тут никають дикі воргени-Мунрейджі, вірні архімагові-ренегату Аруґалу, і галявина править за базу для звірів, що полюють у прибережних лісах.",section="Лощина Північного Припливу, захована в густому лісі на північ від поселення Відступників — Гробниці, — під владою лютої зграї Мунрейджів. Ці дикі воргени, що потрапили до Лордерона через безрозсудне чаклунство Архімага Аруґала, облаштували грубі табори по всій лощині. Збудовані лише з найпотрібнішого для витривалих звірів, ці грубі прихистки правлять за передовий плацдарм небезпечно близько до шляхів, якими ходять Відступники.",sectionIndex=1}
c["subzone:north-tide-s-run"] = "cb852f"
P.scopedClips["subzone:north-tide-s-run"] = {scope="overview-body",sourceHash="5f3133",hash="cb852f",name="Потік Північного Припливу",summary="Потік Північного Припливу — продуване вітрами північно-західне узбережжя Срібнолісся, що тягнеться краєм Великого Моря. Позначений самотнім багаттям і напівзатонулим кораблем, цей відтинок піску відомий як відлюдне місце випробувань для мандрівних друїдів, що шукають гармонії з водами.",section="Потік Північного Припливу, що тягнеться північно-західним краєм Срібнолісся, — це холодний пісок, гуркітливий прибій і смуга Великого Моря. Його найпомітніша прикмета — напівзатонулий корабель, небезпечно похилений на мілині біля пляжу. Окрім уламків, єдина ознака людського життя тут — скромне багаття, яке доглядає Воллас Сліпий, що несе тиху варту біля хвиль, які плещуть об берег.",sectionIndex=1}
c["subzone:northshire-abbey"] = "3fc860"
P.scopedClips["subzone:northshire-abbey"] = {scope="overview-body",sourceHash="c57380",hash="3fc860",name="Абатство Нортшира",summary="Абатство Нортшира — історичний монастир у Долині Нортширу серед північних передгір'їв Лісу Елвінн. Відбудоване після знищення в Першій війні, воно є духовним серцем Братства Нортшира й головним осередком підготовки нових захисників, що відгукнулися на поклик королівства Стормвінд.",section="Століття тому клірики з Лордерону вирушили на південь, у королівство Стормвінд, щоб ширити поклоніння Святому Світлу, і заснували Святий Орден Нортширських Кліриків та їхнє абатство. Монастир швидко став опорою життя королівства: він дбав про хворих і навіть доглядав юного Вартового Медіва в роки його коми. Під час Першої війни абатство зазнало повторюваних нападів розбійників і Орди орків, що завершилися його цілковитим знищенням. Коли Альянс Лордерону звільнив цей край у Другій війні, Архієпископ Алонсус Фаол допоміг відбудувати святиню й наново заснував її захисників як Братство Нортшира.",sectionIndex=1}
c["subzone:northshire-abbey#faq1"] = "eda1fb"
P.scopedClips["subzone:northshire-abbey#faq1"] = {scope="answer-only",sourceHash="5fc645",hash="eda1fb",name="Абатство Нортшира",question="Що таке Братство Нортшира?",answer="Братство Нортшира — релігійний орден кліриків, жерців і паладинів з осідком в Абатстві Нортшира. Спершу його століття тому заснували клірики-місіонери з Лордерону, а після Першої війни Архієпископ Алонсус Фаол заснував його наново, щоб готувати вірних захисників і зберігати священне писання."}
c["subzone:northshire-abbey#faq2"] = "1cee36"
P.scopedClips["subzone:northshire-abbey#faq2"] = {scope="answer-only",sourceHash="055569",hash="1cee36",name="Абатство Нортшира",question="Чому Абатство Нортшира зруйнували в Першій війні?",answer="Під час Першої війни абатство мало для Стормвінда стратегічне й духовне значення. Орки підбурили людських розбійників напасти на нього, а після того, як напіворчиху Ґарону ненадовго тримали тут у полоні, потужний натиск Орди зрівняв святу землю з землею. Абатство лишалося в руїнах до кінця війни, доки Альянс не вигнав орківські клани й не відбудував його."}
c["subzone:northshire-abbey#faq3"] = "1cf05a"
P.scopedClips["subzone:northshire-abbey#faq3"] = {scope="answer-only",sourceHash="429615",hash="1cf05a",name="Абатство Нортшира",question="Чому біля абатства розбійники Дефіас і кобольди?",answer="Військо Стормвінда розтягнуте до краю, захищаючи далекі кордони, тож околиці охороняються погано. Спритні кобольди заполонили місцеві золоті копальні, а Братство Дефіас користається прогалинами, щоб грабувати мандрівників, дошкуляти тутешнім виноградникам і спустошувати бібліотеку абатства заради таємних фоліантів і святих реліквій."}
c["subzone:northshire-abbey#faq4"] = "f3dbd9"
P.scopedClips["subzone:northshire-abbey#faq4"] = {scope="answer-only",sourceHash="ef6c66",hash="f3dbd9",name="Абатство Нортшира",question="Що пов'язує Абатство Нортшира з Мертвими Копальнями?",answer="Під час Першої війни вождь огрів на ім'я Турок викрав з Абатства Нортшира священний Фоліант Божественності й сховався в Мертвих Копальнях. Сер Андуїн Лотар очолив похід у глибини, щоб повернути святе писання, і потрапив у пастку, доки королівський рятувальний загін не визволив його й не повернув фоліант під опіку абатства."}
c["subzone:northshire-valley"] = "268862"
P.scopedClips["subzone:northshire-valley"] = {scope="overview-body",sourceHash="556ca7",hash="268862",name="Долина Нортширу",summary="Сховавшись у північних горах Лісу Елвінн, Долина Нортширу — мирна колиска й тренувальна база для наймолодших захисників королівства Стормвінд. Оточена природними перешкодами, вона дає прихисток старовинному Абатству Нортшира, родючим виноградникам і багатій Шахті Ехо-Рідж. Та попри спокійний вигляд, долині дедалі дошкуляють розбійники, кобольди й витіснені з лісів хижаки.",section="Долину Нортширу обрамляють майже неприступні гірські хребти, і єдина дорога веде звідси на південь, крізь укріплену браму, до Ґолдшира та решти Лісу Елвінн. Пасовищами в'ється прозора річка, що далі на південь впадає в Кришталеве Озеро. У серці долини стоїть Абатство Нортшира — давнє святилище, де навчають Святого Світла, а рекрутів тренують Лицарі Срібної Длані та досвідчені ветерани. За мурами абатства лежать щедрі Виноградники Нортшира й Шахта Ехо-Рідж: разом вони утворюють самодостатній куточок земель Стормвінда, що здається далеким від воєн решти світу.",sectionIndex=1}
c["subzone:northshire-vineyards"] = "580e76"
P.scopedClips["subzone:northshire-vineyards"] = {scope="overview-body",sourceHash="74a062",hash="580e76",name="Виноградники Нортшира",summary="Виноградники Нортшира — доглянуті виноградні поля просто на схід від Абатства Нортшира, у захищеній улоговині долини. Колись мирне джерело вина для кліриків, нині поля опинилися під владою Братства Дефіас та їхніх місцевих розбійників.",section="Виноградники Нортшира на схід від Абатства Нортшира, за струмком, утілюють тихе хліборобське життя долини. Поля доглядають місцеві робітники, як-от Міллі Осворт, та через дедалі більші заворушення вони лишилися беззахисними. Розбійники, пов'язані з Братством Дефіас, яких на місці очолює горлоріз на ім'я Ґаррик Педфут, захопили угіддя. Злодії зайняли поля не заради простого вандалізму: вони грабують урожай і позбавляють місцевих хліборобів засобів до існування, даючи новобранцям Братства легку опору просто під носом в абатства.",sectionIndex=1}
c["subzone:old-ironforge"] = "75026e"
P.scopedClips["subzone:old-ironforge"] = {scope="overview-body",sourceHash="b7af77",hash="75026e",name="Старий Айронфордж",summary="Старий Айронфордж, який ще називають Зібранням Танів, — прадавня підземна зала просто під Високим Престолом Айронфорджа. Висічена глибоко в корінні гори над сяйливими жилами магми, вона — родове серце дворфійської столиці. Нині її важкі ворота в королівській тронній залі зачинені й пильно охороняються.",section="Під троном Короля Маґні Бронзбірда на Високому Престолі лежить печерна зала, відома як Старий Айронфордж, або Зібрання Танів. Глибоко в цих вогняних підземних підвалинах звивисті кам'яні мости перекинуто над озерами лави. Задовго до того, як гамірні зали Великої Кузні й Торгових Рядів сповнилися відлунням сучасної дворфійської торгівлі, перші тани збиралися в цих печерних глибинах, щоб радитися й правити гірським королівством.",sectionIndex=1}
c["subzone:old-town"] = "f38da0"
P.scopedClips["subzone:old-town"] = {scope="overview-body",sourceHash="141119",hash="f38da0",name="Старе Місто",summary="Старе Місто — найдавніший і найсуворіший квартал Стормвінда, що здебільшого вцілів під час руйнувань Першої війни. Замість блискучих кам'яних площ тут вузькі провулки з вивітреною цеглою, робітничі житлові будинки й гамірні воєнні установи. Тут розташовані Командний центр королівського війська й таємний штаб SI:7.",section="Поки решту Стормвінда після Першої війни каменярі старанно відбудовували з нуля, Старе Місто уникло цілковитої руйнації. Йому не знадобилася повна перебудова, тож воно так і не отримало бездоганних мармурових фасадів і величних каналів, як Торговий Квартал чи Соборна Площа. Натомість це досі простий, тісний квартал, де живуть трудящі, робітники й найбідніші містяни. Його бруковані вулиці вужчі, брудніші й значно хаотичніші, ніж у решті столиці, але саме вони зберігають справжній дух довоєнного Стормвінда.",sectionIndex=1}
c["subzone:olsen-s-farthing"] = "6f0db0"
P.scopedClips["subzone:olsen-s-farthing"] = {scope="overview-body",sourceHash="3e58e2",hash="6f0db0",name="Олсенів Наділ",summary="Олсенів Наділ колись був квітучою садибою при головному торговому шляху через Срібнолісся. Після Третьої війни поля занепали, і їх заполонили підняті раби-мерці, підвладні некромантові-ренегату Тулу Рейвенклову.",section="Доки чума не поглинула Лордерон, Олсенів Наділ був жвавою хліборобською садибою з прямим виходом на головний сухопутний торговий шлях Срібнолісся. Сьогодні його оброблені поля задушені бур'янами, будівлі лежать розбиті, а будь-яку пам'ять про чесну хліборобську працю стерла некромантія Погибелі. Раби-нежить, скуті як невільники й нападники під командуванням Тула Рейвенклова, блукають голою землею, вбиваючи кожного мандрівника, що підійде надто близько.",sectionIndex=1}
c["subzone:oracle-glade"] = "92db53"
P.scopedClips["subzone:oracle-glade"] = {scope="overview-body",sourceHash="0a4d83",hash="92db53",name="Галявина Оракула",summary="Галявина Оракула в північно-західному Тельдрассилі — священне лісове святилище, домівка дивовижного Дерева Оракула й найголовнішого місячного колодязя Світового Дерева. Попри мирне призначення — бути осередком єднання й пильності — галявина потерпає від постійних наскоків гарпій Кривавого Пера.",section="Галявина Оракула тихо лежить між Дарнасусом і Озером Джерела — важливий вузол єднання нічних ельфів із природою. У її центрі стоїть Дерево Оракула, прадавній велет, чиє могутнє гілля нагадує обриси орла, що сидить на ведмеді. Поруч мерехтить перший і наймогутніший зі священних місячних колодязів Тельдрассила — оаза місячної магії, омита ласкою Елуни. Разом із Колом Древніх Дерево Оракула наглядає за гіллям острова, скидаючи кору з написами, що правлять за важливі послання Архідруїду Фандралу Стаґгелму про здоров'я Світового Дерева.",sectionIndex=1}
c["subzone:palemane-rock"] = "bb6276"
P.scopedClips["subzone:palemane-rock"] = {scope="overview-body",sourceHash="41bb0d",hash="bb6276",name="Скеля Пейлмейн",summary="Скеля Пейлмейн — печера й стійбище в західних горах Малгору. Це головна твердиня войовничого племені гнолів Пейлмейн, що постійно дошкуляє й загрожує сусіднім тауренам із Села Бладгуф.",section="Скеля Пейлмейн лежить на західному краю трав'янистих рівнин Малгору: розлоге стійбище просто неба перед глибокою тінистою печерою, вирубаною в гірському схилі. Гноли Пейлмейн оголосили своїми і нутро печери, і передгір'я одразу за нею. Ворожі й ревниві до своєї території, вони люто боронять лігво й нападають на мисливців, подорожніх і розвідників, що підходять до їхнього скелястого притулку занадто близько.",sectionIndex=1}
c["subzone:park"] = "8c8037"
P.scopedClips["subzone:park"] = {scope="overview-body",sourceHash="60bc5a",hash="8c8037",name="Парк",summary="Парк, що лежить уздовж західного краю Стормвінда між Соборною Площею й Кварталом магів, — пишний зелений прихисток для тихих роздумів. Присвячений природі й відпочинку посеред гамірної кам'яної столиці, він став головною гаванню для нічних ельфів, що приїздять у гості, і тут працюють єдині наставники друїдів у Східних Королівствах.",section="Поки в решті Стормвінда панують бруковані доріжки, височенні вапнякові мури й тісні ринкові ятки, Парк дарує тихий подих дикої природи. Спершу його облаштували як тихе місце відпочинку для містян, але згодом він природно перетворився на анклав для посланців нічних ельфів і мандрівників, що прибувають з-за Великого Моря. Під тінистими кронами, довкола Місячного Колодязя в центрі, квартал приносить у серце людського королівства клаптик священних галявин Калімдору.",sectionIndex=1}
c["subzone:petitioner-s-chamber"] = "00a444"
P.scopedClips["subzone:petitioner-s-chamber"] = {scope="overview-body",sourceHash="e1f1c8",hash="00a444",name="Палата Прохача",summary="Палата Прохача, відома також як Зала Прохачів, — передпокій одразу біля головного пандуса Фортеці Стормвінда. Це офіційна приймальня для знаті, церковних достойників і підданих, що прагнуть аудієнції в корони. Ті, хто чекає тут, часто згають години за розмовами, чаркою чи чеканням на ласку регента.",section="Палата Прохача, що відкривається праворуч, щойно піднімешся до Фортеці Стормвінда, — місце, де державні справи зустрічаються з буденною бюрократією. Вельможі на кшталт Графа Ремінгтона Ріджвелла й високі церковники, як-от Єпископ ДеЛаве, коротають тут час, чекаючи аудієнції в короля-хлопчика Андуїна Рінна й Верховного Лорда Болвара Фордрагона. За блискучою личиною придворного етикету це ідеальний куточок замку для пліток, тихого лобіювання й з'ясування, хто насправді має вплив у королівстві.",sectionIndex=1}
c["subzone:pig-and-whistle-tavern"] = "bce297"
P.scopedClips["subzone:pig-and-whistle-tavern"] = {scope="overview-body",sourceHash="e3601b",hash="bce297",name="Таверна «Свиня і Свисток»",summary="Таверна «Свиня і Свисток» — гомінкий шинок у суворому кварталі Старого Міста в Стормвінді. Це улюблене місце зустрічей для мандрівників Альянсу, місцевих робітників і бувалих ветеранів, що згадують давні війни королівства.",section="Таверна «Свиня і Свисток», що стоїть серед похмурих звивистих провулків Старого Міста, дає тепло, ель і нічліг тим, хто ходить грубішим кварталом столиці. Поки міська знать збирається на соборних площах і мармурових майданах, цей заклад обслуговує простих містян, трудящих і мандрівників, що щойно з дороги. Усередині можна знайти купців на кшталт славетного торговця рецептами Кендора Кабонки, а також сивих ветеранів, що цмулять із кухлів, згадуючи Першу й Другу війни.",sectionIndex=1}
c["subzone:pool-of-ask-ar"] = "d236e4"
P.scopedClips["subzone:pool-of-ask-ar"] = {scope="overview-body",sourceHash="100791",hash="d236e4",name="Ставок Аск'ар",summary="Ставок Аск'ар — розлоге затоплене печерне озеро глибоко в Чорноглибинних Печерах. Тут кишать водяні звірі й мерзенні наги-загарбники, а води ховають давню архітектуру нічних ельфів і таємні проходи, що ведуть углиб оскверненого святилища.",section="Ставок Аск'ар, що лежить одразу за Затопленим Сакелумом, заповнює величезне підземне склепіння каламутною холодною водою. Природні печери й давня кладка стали гніздовищем для завеликих черепах-кусачок і глибоководних крабів, над якими панує велетенський давній черепаховий звір на ім'я Ґаму-Ра. Наги, що захопили храм, використовують цей затоплений поріг як оборонний плацдарм, стережучи залиті водою підходи, що ведуть углиб комплексу — до леді Саревесс і Руїн Місячної Святині.",sectionIndex=1}
c["subzone:pools-of-arlithrien"] = "fb9eeb"
P.scopedClips["subzone:pools-of-arlithrien"] = {scope="overview-body",sourceHash="e4a387",hash="fb9eeb",name="Озерця Арлітрієну",summary="Озерця Арлітрієну — скупчення відлюдних джерел у західному Тельдрассилі, одразу на південь від брами Дарнасуса. Колись тихий притулок довкола священного місячного колодязя, це місце занепало й стало небезпечним, коли на нього посунули місцева живність і ворожі фурболги-Вузлошкіри.",section="Озерця Арлітрієну в тінистому гіллі на південь від Дарнасуса задумували як тихе місце природної гармонії. У їхньому серці — кам'яний місячний колодязь, посудина для вод, сповнених ласки Елуни. Та попри близькість до столиці нічних ельфів святилище стало небезпечним. Збурені звірі бродять мілководдям, а невпинна ворожість витіснених фурболгів-Вузлошкірів змусила нічних ельфів облишити звичний догляд за місцем, і мирне диво опинилося в тіні недуги, що охоплює острів.",sectionIndex=1}
c["subzone:pools-of-vision"] = "8b208b"
P.scopedClips["subzone:pools-of-vision"] = {scope="overview-body",sourceHash="61d8d7",hash="8b208b",name="Ставки Видінь",summary="Ставки Видінь — підземна печера під Узвишшям Духів у Тандер Блафі. Зі своїми нерухомими водами й тьмяними гротами цей відлюдний підземний куточок став головним осередком Відступників у тауренській столиці.",section="Осяяні сонцем вершини Тандер Блафа належать вітрові, землі й небу, а Ставки Видінь ховаються просто під Узвишшям Духів, у тінистій відлюдності. Сюди веде непомітна печерна стежка від мосту на узвишшя, і цей підземний грот дарує зовсім інший спочинок, ніж відкриті хатини нагорі. Тут у темряві збираються туманні води, і в цій відокремленості заклиначі Орди сходяться далеко від гамірних центральних висот.",sectionIndex=1}
c["subzone:pyrewood-village"] = "e69aab"
P.scopedClips["subzone:pyrewood-village"] = {scope="overview-body",sourceHash="d3db14",hash="e69aab",name="Село Пайрвуд",summary="Село Пайрвуд — відокремлене людське поселення на півдні Срібнолісся, під Фортецею Шадовфенг. Колись частина Ґілнеаса, а потім покинуте по той бік Стіни Ґреймейна, воно ховає жахливу таємницю, яку наклав на живих мешканців божевільний архімаг Аруґал.",section="Колись Пайрвуд був заможним ґілнеаським поселенням, що належало лордові Даріусу Кроулі. Коли після Другої війни король Ґенн Ґреймейн вирішив відгородити своє королівство величезною Стіною Ґреймейна, Пайрвуд і його сусіда Амбермілл покинули на північному боці. Відрізані від батьківщини, містяни лишилися цілком беззахисними під час Третьої війни, коли Погибель крокувала Лордероном. Хоч вони пережили першу хвилю нежиті, справжній кошмар почався, коли маг Аруґал знайшов прихисток у фортеці над селом.",sectionIndex=1}
c["subzone:ragefire-chasm-classic"] = "8d9a4f"
P.scopedClips["subzone:ragefire-chasm-classic"] = {scope="overview-body",sourceHash="ba9f02",hash="8d9a4f",name="Провалля Лютого Вогню (класика)",summary="Провалля Лютого Вогню — розлога мережа вулканічних тунелів просто під Оргріммаром, до якої можна потрапити крізь тінисті глибини Тіньової Розколини. Хоч ці вогняні печери лежать під суверенною столицею Орди, тут кишать ворожі троги й підступне коло культистів, вірних Раді Тіней.",section="Під кам'яними вулицями й укріпленими вежами Оргріммара лежить Провалля Лютого Вогню — підступна мережа підземних печер, сповнених магми. Нещодавно тунелі заполонили дикі троги Лютого Вогню, що вибралися нагору з глибоких підземних розломів. Маґата Ґрімтотем із тауренів намагалася мирно домовитися з цими істотами, але її пропозиції брутально відкинули. Якщо трогів не спинити, вони прокопаються ще глибше в підвалини самого міста.",sectionIndex=1}
c["subzone:raptor-grounds"] = "2ecea3"
P.scopedClips["subzone:raptor-grounds"] = {scope="overview-body",sourceHash="34c03e",hash="2ecea3",name="Угіддя Рапторів",summary="Угіддя Рапторів — відлюдна долина серед курних пагорбів південних Пусток, яку захопили раптори Сонцелускі. На відміну від звичайних диких звірів, ця зграя виявляє моторошну кмітливість, уміє користуватися знаряддями й має нестримну пристрасть красти блискучі дрібнички з ближніх поселень.",section="Угіддя Рапторів, що лежать на захід від Твердині Північної Варти, — головна гніздова територія рапторів Сонцелуских. Мандрівники швидко помічають, що ці створіння — далеко не бездумні хижаки: вони виявляють неприродний розум, будують грубі сховища, виготовляють примітивні знаряддя й злагоджено полюють. Гнані невгамовною пристрастю до всього блискучого й незвичного, раптори раз у раз нападають на каравани й табори Орди, тягнучи монети, дрібнички й припаси до своїх лігв у каньйоні.",sectionIndex=1}
c["subzone:ratchet"] = "51d7cf"
P.scopedClips["subzone:ratchet"] = {scope="overview-body",sourceHash="4ec7fd",hash="51d7cf",name="Раджет",summary="Раджет — гамірне нейтральне портове містечко картелю Стімвідл на східному узбережжі Пусток. Його заснував головний інженер Ґазлоу після того, як допоміг збудувати Оргріммар, і тепер це головний морський торговий вузол, що з'єднує центральний Калімдор зі Східними Королівствами.",section="Раджет, що стоїть на посушливому узбережжі між Дуротаром і Багном Пилоброду, дає безпечну гавань кожному, хто має гроші. Заснований заповзятливим інженером Ґазлоу після Третьої війни, порт виріс із контрабандистів, вигнанців і сміливих торговців, що прагнули поживитися на прикордонні Калімдору. Він діє під прапором картелю Стімвідл і суворо тримає нейтралітет між Ордою та Альянсом. Кораблі на кшталт «Мрії Діви» регулярно ходять через Велике Море до Буті Бей, перевозячи товари, найманців і сировину між континентами. Місцеві вишибали пильно стежать за доками й нещадно лупцюють кожного, хто має дурість почати бійку й завадити торгівлі.",sectionIndex=1}
c["subzone:ravaged-caravan"] = "430f4e"
P.scopedClips["subzone:ravaged-caravan"] = {scope="overview-body",sourceHash="c854e6",hash="430f4e",name="Сплюндрований Караван",summary="Сплюндрований Караван — димуче згарище на північно-східному березі Озера Кам'яного Бика в Малгорі. Колись це була валка з припасами для копалень Наглядача Фіззпрокета, та її перехопили й знищили місцеві таурени, сповнені рішучості покласти край гоблінському визиску їхньої батьківщини.",section="Сплюндрований Караван на пагорбі над Озером Кам'яного Бика — свідчення ранньої сутички між тауренами Села Бладгуф і Венчурною Компанією, що насувалася на край. Валка везла шахтарське спорядження, креслення й обладнання на розкопки Наглядача Фіззпрокета, але тауренські захисники відрізали її й розтрощили, перш ніж вона дісталася мети. Попри розгром, уперті вцілілі з Венчурної Компанії досі чіпляються за розбиті вози й тліючі ящики, ревно стережучи рештки вантажу.",sectionIndex=1}
c["subzone:raven-hill"] = "726f12"
P.scopedClips["subzone:raven-hill"] = {scope="overview-body",sourceHash="c493ba",hash="726f12",name="Воронячий Пагорб",summary="Воронячий Пагорб — спустошене, зруйноване село на заході Сутінколісся, що лежить у довгій тіні величезного Цвинтаря Воронячого Пагорба. Колись жваве людське поселення, тепер воно покинуте всіма, крім жменьки наляканих захожих і невидимих духів.",section="Воронячий Пагорб, що стоїть при західному шляху Сутінколісся трохи на північ від Хутора Аддла, — сумна тінь самого себе. Коли темна магія й жахи нежиті прокотилися краєм Великого Селища, живі подалися на схід, до Даркшира, або взагалі покинули ці землі. Нині дерев'яні хати гниють у вічному мороці, і мандрівники обходять їх стороною, боячись і неспокійних мерців, що сходять із сусіднього цвинтаря, і невидимих Незримих, що чаяться між руїнами стін.",sectionIndex=1}
c["subzone:raven-hill-cemetery"] = "ee94ae"
P.scopedClips["subzone:raven-hill-cemetery"] = {scope="overview-body",sourceHash="0720e4",hash="ee94ae",name="Цвинтар Воронячого Пагорба",summary="Цвинтар Воронячого Пагорба — величезне прокляте кладовище, що розкинулося на заході Сутінколісся. Колись тихе місце поховань для місцевих сіл, тепер воно заполонене ордами ходячих мерців, падложерних самітників і безжальних грабіжників могил.",section="Доки темрява не поглинула Світанковий Ліс, Цвинтар Воронячого Пагорба був головним місцем спочинку для довколишніх поселень. Коли на край упало темне чаклунство, мерці перестали лежати в могилах. Скелети, гулі й шкандибаючі жахіття вигрібалися з-під землі, розширюючи похмурі межі цвинтаря. Нині це одна з найнебезпечніших виразок Сутінколісся. Тут никають не лише гнилі потвори й велетенські павуки, а й зневірені грабіжники могил, що прагнуть безкарно сплюндрувати родові склепи, поки місцева влада безсила.",sectionIndex=1}
c["subzone:ravenholdt-manor"] = "e5a936"
P.scopedClips["subzone:ravenholdt-manor"] = {scope="overview-body",sourceHash="a514fe",hash="e5a936",name="Маєток Рейвенголдт",summary="Маєток Рейвенголдт, що сховався високо в горах над Передгір'ям Гілсбреда, — відлюдна штаб-квартира гільдії злодіїв і вбивць, відомої як Рейвенголдт. Під наглядом Лорда Джораха Рейвенголдта маєток дає потайний прихисток, де майстри скритності гострять своє ремесло далеко від очей влади.",section="Маєток Рейвенголдт, захований за вузьким гірським перевалом і звивистою печерою на північний захід від Твердині Дурнгольд, стоїть відокремлено на прикордонні Гір Альтерак. Маєток належить Лордові Джораху Рейвенголдту — вельможі, що тримає дисципліноване товариство розбійників, убивць і розвідників. На його землях є тихий сад і тренувальна арена просто неба під наглядом майстрів бою на кшталт Майстра Канґа — дисципліноване місце, щоб відпрацьовувати зламування замків, виготовлення отрут і ближній бій. Хоч маєток радо приймає тих, хто має хист до таємних справ, незграбних чужинців і непроханих гостей пильна варта зустрічає холодною підозрою.",sectionIndex=1}
c["subzone:raynewood-retreat"] = "25236b"
P.scopedClips["subzone:raynewood-retreat"] = {scope="overview-body",sourceHash="0df9d1",hash="25236b",name="Притулок Рейнвуд",summary="Притулок Рейнвуд — давня застава нічних ельфів довкола величезного великого дерева в північно-центральному Ашенвалі. Під охороною дріад і кенарійських захисників вона пильно стежить за північними перевалами до оскверненого Сквернолісся. Тут же живе Хранитель Орданус — старший син Кенарія, на якого полюють зловісні чужі сили.",section="Тисячоліття тому, під час давньої Війни Сатирів, задовго до нинішніх чвар між Альянсом і Ордою, Притулок Рейнвуд був військовим плацдармом для захисників-нічних ельфів. Табір і досі зберігає своє священне бойове призначення. Застава, що лежить між місячним колодязем Шаель'дрін і заполоненими сатирами руїнами Нічного Потоку, перебуває під пильною охороною кенарійських захисників, дракончиків-фей і Сестер-реготух. Разом вони невсипуще стежать за скверною, що сповзає зі Сквернолісся просто з півночі.",sectionIndex=1}
c["subzone:razor-hill"] = "0267d9"
P.scopedClips["subzone:razor-hill"] = {scope="overview-body",sourceHash="3be60d",hash="0267d9",name="Гострий Пагорб",summary="Гострий Пагорб — головне поселення Орди в центральному Дуротарі, що лежить на стратегічному перехресті між Долиною Випробувань, Пустками та Оргріммаром. Збудоване довкола помітних укріплених казарм, воно є плацдармом і навчальним осередком для молодих воїнів з орків і тролів, які випробовують себе в суворій глушині.",section="Збудований на важливому географічному вузлі, Гострий Пагорб сполучає північний Дуротар із прибережними поселеннями на півдні та розлогими рівнинами Пусток за Річкою Південної Люті. Поселення, над яким височіють казарми з каменю та дерева й класичні орківські землянки, заклали ще на зорі заснування Дуротару. Невдовзі після Третьої війни людські війська з Кул Тірасу заманили Орду в засідку саме тут під виглядом зустрічі посланців — напад зірвався, бо замість Тралла пішов Рекссар. Нині застава повністю укріплена проти нових вторгнень із узбережжя.",sectionIndex=1}
c["subzone:razor-hill-watchtower"] = "f78b23"
P.scopedClips["subzone:razor-hill-watchtower"] = {scope="overview-body",sourceHash="a7403b",hash="f78b23",name="Сторожова вежа Гострого Пагорба",summary="Ця міцна застава на червоних кам'яних кручах над Гострим Пагорбом служить постом раннього попередження для серця Дуротару. Фурл Скорнброу пильно стежить за запиленими рівнинами й узбережжям, оберігаючи поселення внизу від загроз, що насуваються.",section="Збудована з грубого дерева й залізного каркаса, Сторожова вежа Гострого Пагорба охороняє поселення Гострий Пагорб і навколишні каньйони. Дуротару невпинно загрожують морські піхотинці Кул Тірасу на східному березі, шипогриви-нападники, що нишпорять чагарниками, та культисти Палаючого Клинка, які чаяться в сусідніх скелях. З цієї піднесеної точки на гребені дозорець помічає бойові загони, димові сигнали та вторгнення задовго до того, як вони дістануться брами поселення.",sectionIndex=1}
c["subzone:razorfen-downs"] = "860716"
P.scopedClips["subzone:razorfen-downs"] = {scope="overview-body",sourceHash="c0474a",hash="860716",name="Рейзорфен Даунс",summary="Рейзорфен Даунс — родова столиця й священний лабіринт-усипальниця шипогривів, видовбаний глибоко у велетенських колючих хащах на межі південних Пусток і Тисячі Голок. Колись їхня найсвятіша обитель, тепер він підпав під владу нежиті Погибелі й перетворився на гнійний оплот некромантії.",section="Рейзорфен Даунс, що споконвіку шанувався як родова столиця й місце поховань раси шипогривів, лежить серед велетенських скам'янілих терновищ, які виросли з полеглого напівбога Агамаґґана. Переказ каже, що його арковий вхід вирізано просто з пащі самого Великого Вепра. Століттями верховні жерці племені Мертвої Голови доглядали ці глибокі звивисті нори й шанували своїх небіжчиків. Та попри священність цього місця для вепролюдей, лабіринт кісток і терну нещодавно спіткало лихо, значно темніше за будь-які сварки за воду Пусток.",sectionIndex=1}
c["subzone:razorfen-downs-classic"] = "6da29d"
P.scopedClips["subzone:razorfen-downs-classic"] = {scope="overview-body",sourceHash="29bf51",hash="6da29d",name="Рейзорфен Даунс (класичний)",summary="Рейзорфен Даунс — прадавнє родове кладовище й традиційна столиця шипогривів, що ховається глибоко серед велетенських колючих терновиків на півдні Пусток. Нещодавно агенти нежиті з Погибелі на чолі з лічем Амненнаром Хладоносцем захопили лабіринт, підняли мертвих шипогривів і погрожують поширити свою владу на весь центральний Калімдор.",section="Рейзорфен Даунс, що виріс із тих самих велетенських скам'янілих лоз, що й сусідній Рейзорфен Краул, лежить там, де під час Війни Прадавніх поліг давній напівбог-вепр Аґамаґґан. Покоління за поколінням цей колючий лабіринт був священним некрополем і осередком влади шипогривів під пильною охороною містиків племені Мертвої Голови. Для шипогривів густі терновики — свята земля, просякнута кров'ю їхнього божественного праотця.",sectionIndex=1}
c["subzone:razorfen-kraul-classic"] = "ed6088"
P.scopedClips["subzone:razorfen-kraul-classic"] = {scope="overview-body",sourceHash="a51c9d",hash="ed6088",name="Рейзорфен Краул (класичний)",summary="Рейзорфен Краул — прадавнє серце земель шипогривів, вирізане глибоко у велетенських колючках, що виросли з крові полеглого напівбога-вепра Аґамаґґана. Цим укріпленим лабіринтом править безжальна стара Чарлґа Рейзорфленк, і звідси вирушають криваві набіги на південні Пустки.",section="Десять тисяч років тому, під час Війни Прадавніх, велетенський напівбог-вепр Аґамаґґан загинув у бою з Палаючим Легіоном, рятуючи Азерот. Там, де його священна кров просочилася в ґрунт південного Калімдору, із землі вирвалися величезні непрохідні колючі лози. Шипогриви, які вважають себе смертними нащадками Великого Вепра, оселилися в цих густих терновиках, шануючи його жертву. Гущавина, відома як Рейзорфен Краул, — їхній найшанованіший редут, де повно воїнів-шипогривів, приборкувачів звірів і шаманів, що підкоряють собі землю.",sectionIndex=1}
c["subzone:razormane-grounds"] = "04d216"
P.scopedClips["subzone:razormane-grounds"] = {scope="overview-body",sourceHash="f3f1fe",hash="04d216",name="Угіддя Гостроманів",summary="Угіддя Гостроманів — передовий табір шипогривів Гостроманів, що пробиваються зі Пусток на схід, у центральний Дуротар. Забитий колючими чагарями й обгризеними тушами дичини, цей наїжачений табір є передовою у нескінченній війні шипогривів з орками Оргріммара.",section="Розкинувшись під червоними скелями центрального Дуротару, Угіддя Гостроманів позначають найдальшу східну межу просування шипогривів зі Пусток. Обплутаний густими колючками й оточений вибіленими кістками, табір — постійна небезпека для мандрівників уздовж Річки Південної Люті. Його очолюють такі постаті, як Капітан Флет Таск із бойової варти та Геолорд Моттл, що влаштовують набіги на сусідні орківські поселення й обози. Попри регулярні патрулі з Гострого Пагорба та сусідніх застав, Гостромани невтомно поповнюють лави, проростаючи з колючок швидше, ніж Орда встигає їх викорчувати.",sectionIndex=1}
c["subzone:razorwind-canyon"] = "f11733"
P.scopedClips["subzone:razorwind-canyon"] = {scope="overview-body",sourceHash="5fff52",hash="f11733",name="Каньйон Гострого Вітру",summary="Каньйон Гострого Вітру — звивиста скеляста балка, розділена головною дорогою між Гострим Пагорбом і Оргріммаром. Заселений войовничими гарпіями Пилового Вітру, каньйон становить постійну небезпеку для мандрівників, що прямують на північ, до столиці Орди.",section="Каньйон Гострого Вітру обступає центральну артерію, що з'єднує Гострий Пагорб з Оргріммаром, прорізаючи шляхи і в східні кручі, і в західні чагарники в бік Ферми Тор'крена. Каньйон — місце гніздування гарпій Пилового Вітру, територіальних створінь, які без вагань нападають на мандрівників, що підійдуть надто близько до їхніх сідал. Їхня присутність так близько до торгових шляхів столиці робить зачистку цих балок постійною потребою для захисників Дуротару.",sectionIndex=1}
c["subzone:red-rocks"] = "476fa1"
P.scopedClips["subzone:red-rocks"] = {scope="overview-body",sourceHash="fcc4f7",hash="476fa1",name="Червоні Скелі",summary="Червоні Скелі — висока піщаникова круча в північно-східному Малгорі, священне прабатьківське поховальне місце тауренів. Тут полеглих звитяжців ввіряють Земній Матері через очисне полум'я, а молоді сміливці підіймаються на тихі висоти шукати мудрості предків.",section="Багряні скельні утворення Червоних Скель, що здіймаються над рівнинами північно-східного Малгору, позначають священний поріг між світом живих і наступним. Тауренська традиція береже цю урочисту землю для найдоблесніших героїв — вождів, захисників і звитяжців, що віддали життя, засновуючи й боронячи Тандер Блаф. Їхні рештки ввіряють небу й землі на обрядових вогнищах, повертаючи духи Земній Матері та Небесному Батькові. Та це й місце духовного початку: тут молоді таурени завершують обряди посвяти, вшановуючи могили предків і спілкуючись із вітром.",sectionIndex=1}
c["subzone:remtravel-s-excavation"] = "21e60c"
P.scopedClips["subzone:remtravel-s-excavation"] = {scope="overview-body",sourceHash="3fc0b2",hash="21e60c",name="Розкопки Ремтревела",summary="Розкопки Ремтревела — місце археологічних розкопок на півдні Темного Узбережжя. Експедиція, яку заснував дворф Шукач Ремтревел, нещодавно натрапила на давні підземні руїни й ненавмисно розбудила ворожих трогів і кам'яних големів, які швидко захопили кар'єр.",section="Шукач Ремтревел прибув на Темне Узбережжя в пошуках реліквій далекого минулого й заклав сміливі розкопки далеко від безпечного Обердайна. Розкопуючи давні шари, його загін наткнувся на рій підземних трогів Гравієкременю й на кремезних кам'яних големів, похованих під землею. Науковий кар'єр умить перетворився на небезпечну зону: рудокопи розбіглися, а Ремтревел квапливо намагався врятувати свої найцінніші знахідки.",sectionIndex=1}
c["subzone:render-s-rock"] = "d3c1d1"
P.scopedClips["subzone:render-s-rock"] = {scope="overview-body",sourceHash="6bf3c1",hash="d3c1d1",name="Скеля Рендера",summary="Скеля Рендера — печерна твердиня в північно-західних кручах Гір Редріджу, неподалік високого перевалу, що веде до Палаючих Степів. Її тримають люті орки Блекрок: для них це передовий оплот і діючий плацдарм для набігів на долини внизу.",section="Видовбана в скелястих висотах на північ від Лейкшира, Скеля Рендера — укріплена мережа печер клану Блекрок, що вдерся в край. З цього зручного для оборони оплоту біля гірського перевалу до Палаючих Степів бувалі орки Блекрок спрямовують напади на місцевих захисників Редріджу. Її темні глибини суворо охороняються, тож будь-який рейд усередину — небезпечна справа для тих, хто хоче перерізати орочі шляхи постачання чи визволити полонених, захоплених у цій війні.",sectionIndex=1}
c["subzone:render-s-valley"] = "074183"
P.scopedClips["subzone:render-s-valley"] = {scope="overview-body",sourceHash="3d1616",hash="074183",name="Долина Рендера",summary="Долина Рендера — відлюдний табір орків Блекрок на південному сході Гір Редріджу. Він укріплений далеко не так, як величезні твердині Кам'яної Варти, але все одно становить постійну загрозу для мандрівників і тримає полонених, захоплених у довколишніх землях.",section="Захована серед кам'янистих кряжів на південний схід від Озера Незрушного, Долина Рендера служить допоміжним табором для орків Блекрок, що діють у Редріджі. На відміну від добре укріплених фортець і кам'яних веж північних круч, тут лише скромне скупчення бойових наметів, прапорів і сторожових постів. Загін тут менший і гірше озброєний, ніж головні сили клану, проте місцеві воїни грабують дороги, нападають на мандрівників і тримають бранців у грубих клітках під вартою.",sectionIndex=1}
c["subzone:rethban-caverns"] = "1b6e53"
P.scopedClips["subzone:rethban-caverns"] = {scope="overview-body",sourceHash="23cb3d",hash="1b6e53",name="Печери Ретбану",summary="Печери Ретбану — розлога мережа печер у північно-західних кручах Гір Редріджу. Їх заполонили агресивні гноли Редріджу, а найбільше вони відомі як єдине джерело рідкісної ретбанської руди.",section="Видовбані глибоко в північно-західних горах над Озером Незрушним, Печери Ретбану служать укріпленим оплотом місцевих гнолів. Під хитрим проводом Ардо Діртпо зграя люто стереже покручені ходи й підземні зали, нападаючи на кожного мандрівника, що підійде надто близько до входу на схилі.",sectionIndex=1}
c["subzone:ridgepoint-tower"] = "a62d4e"
P.scopedClips["subzone:ridgepoint-tower"] = {scope="overview-body",sourceHash="daf77e",hash="a62d4e",name="Вежа Ріджпойнт",summary="Вежа Ріджпойнт — укріплений вартовий пост, що стереже східне порубіжжя Лісу Елвінн. Її тримають вартові Стормвінда, і вона служить оплотом раннього попередження проти ворожих вторгнень, що загрожують серцю королівства. Її вартові пильнують небезпечні проходи до сусідніх диких земель.",section="Вежа Ріджпойнт, що стоїть на чатах на височині східного Лісу Елвінн, позначає останній бастіон прямої влади Стормвінда, перш ніж починаються неприборкані нетрі. Розквартирований тут гарнізон невпинно стежить за навколишніми долинами та дорогами. Поки напруга на континенті зростає, ця кам'яна сторожова вежа дбає, щоб загрози, які насуваються, помічали й зупиняли, перш ніж вони зможуть зашкодити фермам і поселенням ближче до Нортширу та Ґолдшира.",sectionIndex=1}
c["subzone:rocktusk-farm"] = "8c077f"
P.scopedClips["subzone:rocktusk-farm"] = {scope="overview-body",sourceHash="3a026c",hash="8c077f",name="Ферма Кам'яного Ікла",summary="Ферма Кам'яного Ікла — невелике свиняче ранчо на півночі Дуротару, трохи далі дорогою за брамою Оргріммара. Притулена до укріплених підступів до столиці, садиба постачає мешканцям міста конче потрібне м'ясо та харчі.",section="Вирвана в посушливій землі Дуротару, Ферма Кам'яного Ікла розводить витривалих свиней, пристосованих до суворого пустельного клімату. Через горезвісно сухий і кам'янистий ґрунт Дуротару вирощувати збіжжя важко, тож свинарські ферми — життєво важлива нитка, що годує дедалі численніше населення Оргріммара. Притулена до укріплених околиць столиці, садиба тішиться безпекою, якої рідко знайдеш у суворих нетрях червоних каньйонів.",sectionIndex=1}
c["subzone:rogues-quarter"] = "94a188"
P.scopedClips["subzone:rogues-quarter"] = {scope="overview-body",sourceHash="b83296",hash="94a188",name="Квартал Розбійників",summary="Квартал Розбійників — тьмяно освітлений район у південно-східному крилі Андерсіті. Тут збираються розвідники, вбивці й таємні агенти Відступників, а також ремісники, що їм допомагають.",section="Квартал Розбійників, що ховається в південно-східній частині підземного міста, збирає найхитріших і найсмертоносніших із тих, хто вижив серед Відступників. За життя чимало з них були злодіями, кишеньковими злодюжками чи безшумними клинками королівства Лордерон; після смерті їхнє вміння скрадатися, труїти й заплутувати сліди знадобилося, щоб захищати молоду державу від Погибелі й Багряного Хрестового Походу. У районі тихо вирує життя: це потаємний прихисток, де агенти гострять кинджали, варять смертельні отрути й відточують таємні навички.",sectionIndex=1}
c["subzone:roland-s-doom"] = "7e8127"
P.scopedClips["subzone:roland-s-doom"] = {scope="overview-body",sourceHash="41c61d",hash="7e8127",name="Погибель Роланда",summary="Погибель Роланда — покинута, оповита тінню шахта в південно-східних пагорбах Сутінколісся, трохи на схід від Гнилого Саду. Колись звичайна копальня, тепер вона сумно відома як небезпечне лігво лютих воргенів.",section="Погибель Роланда, вирубана в кряжах на схід від Гнилого Саду, давно перестала бути робочою шахтою. Натомість вона стала жорстоким плацдармом для зграї воргенів Найтбейн, яку очолюють такі звірі, як Кишкодер і Нефару. Темні тунелі відлунюють утробним гарчанням і смердять вогкою землею та кров'ю, тож для необачних мандрівників це один із найнебезпечніших закутків усього Сутінколісся.",sectionIndex=1}
c["subzone:rolling-plains"] = "60f39d"
P.scopedClips["subzone:rolling-plains"] = {scope="overview-body",sourceHash="329009",hash="60f39d",name="Хвилясті Рівнини",summary="Хвилясті Рівнини розкинулися на південних просторах Малгору, між Селом Бладгуф і кордоном Пусток. На цих обвітрених пасовищах буяють стада дичини, та вони ж вимагають постійної пильності через ватаги кентаврів, що нишпорять довкола, і агресивних гарпій.",section="Простягаючись на південь від Села Бладгуф до природних земляних воріт у Пустки, Хвилясті Рівнини втілюють безмежні простори тауренської батьківщини. Край кишить дичиною, без якої племенам не вижити: тут водяться степові вовки, стада кодо, рівнинні пуми й прудкі довгоступи. Для молодих мисливців, що доводять свою вартість старійшинам, ці розлогі савани — незамінний полігон, де випробовують уміння вистежувати, терпіння й шану до природи.",sectionIndex=1}
c["subzone:rotting-orchard"] = "270f05"
P.scopedClips["subzone:rotting-orchard"] = {scope="overview-body",sourceHash="130c82",hash="270f05",name="Гнилий Сад",summary="Гнилий Сад — сплюндрований, покинутий фруктовий сад на півдні Сутінколісся. Колись він давав урожай сусідньому Даркширу, а тепер занепав і кишить ненажерливими вовкоподібними хижаками — зграєю Найтбейн.",section="Гнилий Сад, що лежить на схід від зруйнованого Хутора Йорґенів і на захід від Цвинтаря Тихих Садів, — похмуре свідчення занепаду Сутінколісся. Дерева вгинаються під зморщеними, зіпсованими плодами, а напіврозвалені стодоли й господарські будівлі воргени Найтбейн перетворили на грубі табори. Переслідувачі Найтбейн никають покрученими хащами, а темні чаклуни — Тіньові Ткачі — плетуть зловісну магію серед трухлявих колод. Зграя кориться своєму лютому ватажкові Марусу, що никає довколишніми лісами, стережучи захоплені володіння.",sectionIndex=1}
c["subzone:royal-gallery"] = "59ab58"
P.scopedClips["subzone:royal-gallery"] = {scope="overview-body",sourceHash="0f451a",hash="59ab58",name="Королівська Галерея",summary="Захована у Фортеці Стормвінда за внутрішнім садом, Королівська Галерея — тиха зала пам'яті. Тут стоять чудові статуї й витончені мистецькі твори на честь видатних постатей з історії королівства й Великого Альянсу.",section="Королівська Галерея прилягає до Королівської Бібліотеки, одразу за зеленим внутрішнім садом Фортеці Стормвінда. У залі стоять статуї велетнів, що творили історію краю: короля Ллейна Рінна, полеглого правителя Стормвінда; Великого Адмірала Дейліна Праудмура з Кул Тірасу; і Мари Фордрагон, пращурки нинішнього регента. Це водночас приватний музей шляхетної спадщини й тихий прихисток для придворних гостей на кшталт Леді Дени Кеннеді.",sectionIndex=1}
c["subzone:royal-library"] = "921ee4"
P.scopedClips["subzone:royal-library"] = {scope="overview-body",sourceHash="f531a6",hash="921ee4",name="Королівська Бібліотека",summary="Захована глибоко в кам'яному крилі Фортеці Стормвінда, Королівська Бібліотека зберігає спільну пам'ять, сувої хронік і трактати королівства. Під пильним оком Головного Бібліотекаря Мілтона Шіфа на її полицях лежать важливі записи про давні війни, загублені легенди й краї за морем.",section="Поки Фортеця Стормвінда наїжачується закутими в броню вартовими й двірськими інтригами, Королівська Бібліотека дарує острівець ученої тиші. Під наглядом Мілтона Шіфа зала служить головним архівом історії південних людей: тут зберігаються вцілілі тексти з часів до Першої війни, нові воєнні хроніки й повернуті фоліанти. Учені Альянсу, жерці й мандрівники можуть вільно гортати відкриті трактати — від створення першого Альянсу Лордерону до недавньої появи Орди Тралла в Калімдорі.",sectionIndex=1}
c["subzone:royal-quarter"] = "6a5cc8"
P.scopedClips["subzone:royal-quarter"] = {scope="overview-body",sourceHash="be03c5",hash="6a5cc8",name="Королівський Квартал",summary="Королівський Квартал — відокремлений осідок влади в Андерсіті й тронна зала Леді Сильвани Віндраннер. Тут Королева Баньші керує Відступниками разом із повелителем жаху Варіматрасом, що втілює її волю, під охороною добірного загону Королівських Стражів Жаху.",section="Королівський Квартал, захований за височенними арками й тінистими коридорами й відомий також як Зала Темної Леді, — політичний і військовий нервовий центр Відступників. Сильвана Віндраннер тримає двір у цій печерній підземній залі, плануючи виживання своєї нежиті з вільною волею й знищення Погибелі. Важко закуті Королівські Стражі Жаху стоять на варті вздовж підвищення, дбаючи, щоб непрохані гості й можливі вбивці ніколи не дісталися до їхньої королеви.",sectionIndex=1}
c["subzone:ruins-of-mathystra"] = "beafb9"
P.scopedClips["subzone:ruins-of-mathystra"] = {scope="overview-body",sourceHash="25985b",hash="beafb9",name="Руїни Матістри",summary="Руїни Матістри — напівзруйновані рештки давнього міста нічних ельфів на північному узбережжі Темного Узбережжя. Розбиті під час Великого Розколу десять тисяч років тому, прибережні руїни тепер заполонили ворожі наги Штормової Луски, а серед них никають невловимі примарні шаблезуби.",section="Десять тисячоліть тому Матістра була гамірним поселенням нічних ельфів, домівкою високої знаті з Високородних. Коли під час Великого Розколу обвалилося Колодязь Вічності, катастрофічні хвилі зруйнували прибережне місто, повалили його величні мармурові арки й змили більшу частину кладки в море. Вцілілі нічні ельфи покинули зруйноване місто заради менших лісових селищ далі на півдні, залишивши затоплені двори й потріскані фундаменти Матістри невблаганним прибережним стихіям.",sectionIndex=1}
c["subzone:ruins-of-ordil-aran"] = "0ec33b"
P.scopedClips["subzone:ruins-of-ordil-aran"] = {scope="overview-body",sourceHash="72ad4f",hash="0ec33b",name="Руїни Ордил'Аран",summary="Руїни Ордил'Аран — напівзруйновані залишки давнього поселення нічних ельфів на північному заході Ашенвалю, між Постом Маестри й Притулком Батрана. Колись тут ховалися культисти тіні, але нещодавно повалене каміння захопили осквернені фурболги Будякохутрі.",section="Від первісної архітектури калдореїв в Ордил'Арані мало що лишилося — хіба вивітрені колони, потріскані арки й порослі мохом камені. Певний час ці відлюдні руїни були лігвом Культу Темного Берега, чиї прихильники ховалися серед уламків і влаштовували засідки на мандрівників на північно-західних стежках Ашенвалю. Проте нещодавно люті фурболги з племені Будякохутрих вигнали культистів у кривавій сутичці. Тіла полеглих адептів Темного Берега досі лежать на землі, а агресивні фурболги патрулюють околиці, затято охороняючи руїни й давнє Серцедерево, що росте всередині.",sectionIndex=1}
c["subzone:ruins-of-stardust"] = "f36ee2"
P.scopedClips["subzone:ruins-of-stardust"] = {scope="overview-body",sourceHash="4b3af1",hash="f36ee2",name="Руїни Зоряного Пилу",summary="Руїни Зоряного Пилу — давнє зруйноване святилище нічних ельфів на острові посеред озера в південно-західному Ашенвалі. Колись тихе місце молитви, тепер воно потерпає від скверни: води острова й місцеві болотяні звірі отруєні демонічною гниллю, що стікає зі Сквернолісся. Та попри всюдисущу пошесть, серед руїн досі буяють сяйливі кущі зоряного пилу, що зберігають могутню цілющу силу.",section="Руїни Зоряного Пилу, що лежать на самотньому острові на південь від Астранаару, колись були шанованим святим місцем нічних ельфів. Сьогодні над водою висить моторошний хворобливий жовто-зелений серпанок — наслідок мерзенної демонічної гнилі, що стікає на південь зі Сквернолісся, як і на сусідньому Озері Ірисів. Місцеві рослини обернулися на ворожих болотяних звірів, що нишпорять серед поваленої кладки; їхню вдачу зіпсувало отруєне озеро.",sectionIndex=1}
c["subzone:rut-theran-village"] = "007258"
P.scopedClips["subzone:rut-theran-village"] = {scope="overview-body",sourceHash="1c9558",hash="007258",name="Селище Рут'теран",summary="Селище Рут'теран — прибережна пристань біля південного підніжжя Тельдрассила. Головна морська гавань Дарнасуса, вона з'єднує відлюдне Світове Дерево з материковим Калімдором поромом і маршрутами гіпогрифів.",section="Селище Рут'теран край води, під височенним Тельдрассилом, — поріг між столицею нічних ельфів і широким світом. Поки Дарнасус спочиває в гіллі високо вгорі, Рут'теран дає господарську основу, потрібну, щоб його утримувати. Під деревами вигинається містичний портал, що вмить переносить подорожніх між берегом і Дарнасусом. Для морських мандрівок із пристані селища ходить пором просто до Обердайна на материку, на Темному Узбережжі, а наставники польотів доглядають сідала навчених гіпогрифів.",sectionIndex=1}
c["subzone:saldean-s-farm"] = "243488"
P.scopedClips["subzone:saldean-s-farm"] = {scope="overview-body",sourceHash="82dd6b",hash="243488",name="Ферма Салдина",summary="Ферма Салдина — єдиний хутір у Вестфолі, який Братство Дефіас не захопило й не спустошило. Ним володіють уперті Фермер Салдін і його дружина Салма, і їхня хата лишається рідкісним безпечним прихистком серед лихоліття.",section="Поки сусідні землі падали під натиском розбійників і механічних диверсій, родина Салдінів відмовилася покинути свою землю. Фермер Салдін і його дружина Салма залишилися на хуторі й частують перехожих гарячою стравою та добрим словом. Та попри їхню стійкість, поля потерпають від збунтованих големів жнив, розкиданих рівнинами, тож родина тримається ближче до стін хати.",sectionIndex=1}
c["subzone:satyrnaar"] = "da4a72"
P.scopedClips["subzone:satyrnaar"] = {scope="overview-body",sourceHash="be3a79",hash="da4a72",name="Сатирнаар",summary="Сатирнаар — давнє зруйноване поселення нічних ельфів на північному сході Ашенвалю, яке цілком опинилося в руках сатирів Похмурого Серця. Розташоване трохи осторонь головної дороги між Заставою Розщепленого Дерева й Азшарою, це найкраще збережена й найдоступніша з твердинь сатирів у лісі.",section="Сатирнаар, що лежить на північний схід від Застави Розщепленого Дерева й на південний захід від Лісової Пісні, — одне з трьох головних поселень сатирів в Ашенвалі поряд із Ксавіаном і Нічним Потоком. На відміну від руїн у глибині нетрів, Сатирнаар порівняно добре зберігся: серед напівзруйнованої ельфійської архітектури стоять намети. Це гамірний табір сатирів Похмурого Серця, через який торговий шлях неподалік стає небезпечним для мандрівників, що прямують на схід до Азшари. Ба більше, тут визрівають темні зв'язки: сатири уклали союз із таємничим Культом Темного Берега й ховають серед оскверненого каміння один із його підступних самоцвітів душ.",sectionIndex=1}
c["subzone:scarlet-raven-tavern"] = "77c24d"
P.scopedClips["subzone:scarlet-raven-tavern"] = {scope="overview-body",sourceHash="2e06c5",hash="77c24d",name="Таверна «Багряний Крук»",summary="Таверна «Багряний Крук» — осередок громадського життя й головний заїзд Даркшира, що дає прихисток біля вогнища посеред мороку Сутінколісся. Під орудою Шинкаря Смітса тут збираються змучені місцеві, перехожі шукачі пригод і нажахані мандрівники, що тікають від жахів за межами міста.",section="Таверна «Багряний Крук», що стоїть неподалік серця Даркшира, підтримує вогонь у своєму вогнищі, хоч вічні сутінки й душать довколишній ліс. Колись тут вирувало життя: Маршал Гаґґард і Вартові Стормвінда заходили на кухоль після патрулів. Нині справи підупали разом із безпекою міста. Шинкар Смітс наливає похмурим, стривоженим відвідувачам, що тулються тут від холоду й страху. І все ж таверна лишається незамінним перехрестям чуток — саме звідси мандрівники починають шукати відповіді на темні явища, що поглинають край.",sectionIndex=1}
c["subzone:scarlet-watch-post"] = "dad72b"
P.scopedClips["subzone:scarlet-watch-post"] = {scope="overview-body",sourceHash="b991f9",hash="dad72b",name="Багряна Сторожова Застава",summary="Багряна Сторожова Застава — відособлена сторожова вежа на скелястих пагорбах північно-східних Галявин Тірісфалю, одразу на північ від Багряного Монастиря. Її тримає пильний гарнізон хрестоносців, і єдине її призначення — берегти вразливий північний фланг монастиря від обхідних нападів.",section="Багряна Сторожова Застава на скелястих висотах за Багряним Монастирем — важливий бастіон раннього попередження для фанатиків унизу. Поки південна дорога до монастирської брами людна й добре укріплена, скелясті кручі вздовж північного узбережжя Тірісфалю дають спокусливий обхідний шлях для диверсантів. Щоб закрити цю сліпу пляму, Багряний Хрестовий Похід тримає цю укріплену кам'яну вежу — одну з кількох застав хрестоносців, розкиданих по Галявинах Тірісфалю. Під суворим командуванням Капітана Мелраша змішаний загін неофітів, передових бійців і побожних братів-ченців невпинно пильнує кручі, щоб ні Погибель, ні Відступники не заскочили орден зі спини.",sectionIndex=1}
c["subzone:screaming-gully"] = "a8f812"
P.scopedClips["subzone:screaming-gully"] = {scope="overview-body",sourceHash="dc86e0",hash="a8f812",name="Волаючий Яр",summary="Волаючий Яр — перша розлога підземна печера одразу за входом до Печер Стогонів. Залита протиприродним сяйвом грибів і мілкою водою, вона править за зовнішній оплот спотворених Друїдів Ікла та їхніх мутованих звірів.",section="Ступивши за поріг Печер Стогонів, мандрівник одразу потрапляє у Волаючий Яр — відлунну прірву, де вітер стогне в підземних розколинах. Тут, далеко від посушливих Пусток нагорі, яр заріс вологими хащами, оповитий задушливим туманом і повний лютих звірів, спотворених Смарагдовим Жахіттям. Над залою пильнує Володарка іклів Леді Анакондра в оточенні послушників Друїдів Ікла та лютих девіантних рапторів, а мілкими протоками внизу патрулюють прадавні кусючі черепахи на кшталт Креша.",sectionIndex=1}
c["subzone:scuttle-coast"] = "dd17f2"
P.scopedClips["subzone:scuttle-coast"] = {scope="overview-body",sourceHash="042780",hash="dd17f2",name="Дріботливе Узбережжя",summary="Дріботливе Узбережжя — побитий хвилями східний берег Дуротару між Гострим Пагорбом і Фортецею Тіраґард. Скелястий пляж усіяний затонулими уламками флоту Кул Тірасу під проводом Адмірала Дейліна Праудмура, тож це жваве місце для збирачів Орди й невідступне нагадування про недавню морську війну.",section="Дріботливе Узбережжя, що тягнеться вздовж східного краю Дуротару до Великого Моря, набуло свого похмурого вигляду під час вторгнення Великого Адмірала Дейліна Праудмура. Коли флот Кул Тірасу напав на молоду державу Дуротар, люті бої з Ордою загнали чимало людських кораблів на зубчасті мілини й розтрощили їх на тріски. Нині берег завалений порослими мушлями колодами, поламаним такелажем і врятованими бочками з вантажем. Для сусідніх таборів Гострого Пагорба узбережжя — водночас і невідступна загроза безпеці, і цінне джерело віднайдених припасів та покинутих механізмів Альянсу.",sectionIndex=1}
c["subzone:sen-jin-village"] = "a1c9ee"
P.scopedClips["subzone:sen-jin-village"] = {scope="overview-body",sourceHash="1df698",hash="a1c9ee",name="Село Сен'джин",summary="Село Сен'джин — прибережне поселення на південних берегах Дуротару, притулок для тролів Темного Списа. Засноване Вождем Вол'джином після того, як його народ вигнали з прадавнього дому на Островах Відлуння, селище вшановує його полеглого батька, знахаря Сен'джина. Нині це крихкий прихисток, зосереджений на виживанні, травництві й поверненні вкраденого.",section="Коли темний знахар Залазан зрадив Темний Спис і захопив владу над Островами Відлуння, Вождь Вол'джин був змушений перевести вцілілих через протоку на материк Дуротару. Там, під прибережними скелями, з видом на воду, вони поставили грубі хатини й заснували Село Сен'джин. Поселення носить ім'я батька Вол'джина — шанованого старійшини, що пожертвував собою під час Третьої війни, рятуючи свій народ від прибережних мурлоків. Попри тісний союз з Ордою Тралла, тутешні тролі живуть у тіні вигнання, щодня дивлячись через мілини на втрачений дім.",sectionIndex=1}
c["subzone:sentinel-hill"] = "16e83a"
P.scopedClips["subzone:sentinel-hill"] = {scope="overview-body",sourceHash="059fb4",hash="16e83a",name="Сентінел Гілл",summary="Сентінел Гілл — головна твердиня Альянсу у Вестфолі й командний центр Народного ополчення. Довкола — зарослі поля, гноли-мародери й ворожі розбійники, тож цей укріплений пагорб — єдиний надійний оплот для законослухняних мешканців краю.",section="Сентінел Гілл височіє на узвишші в центрі Вестфолу й править за життєво важливий прихисток на беззаконних землях. Тут є таверна, схожа на казарму, гніздо грифонів, звідки летять до Стормвінда й далі, кузня та лісопилка, а над усім панує велична Вежа Вартових. Довколишні землі дісталися розбійникам і хижим звірам, але табір утримує хиткий периметр, де мандрівники, знесилені фермери й новобранці можуть перевести подих під пильним оком досвідчених захисників.",sectionIndex=1}
c["subzone:sentinel-tower"] = "1a0710"
P.scopedClips["subzone:sentinel-tower"] = {scope="overview-body",sourceHash="58abb5",hash="1a0710",name="Вежа Вартових",summary="Вежа Вартових вінчає вершину Сентінел Гілла — це головний оглядовий пункт і штаб захисників Вестфолу. Звідси Ґраян Стаутмантл і Народне ополчення відчайдушно обороняються від бандитів, гнолів і дедалі темнішої тіні Братства Дефіас.",section="Вежа Вартових, зведена на гребені Сентінел Гілла, — військове серце неспокійного Вестфолу. Офіційна армія Стормвінда здебільшого відсутня й допомоги не дає, тож місцеві добровольці й ветерани об'єдналися, щоб звести центральний редут. Із кам'яної вежі дозорці бачать усю курну рівнину — від покинутих гарбузових грядок до туманних берегів — і вчасно попереджають, коли на дорогах з'являються розбійники чи загони гнолів.",sectionIndex=1}
c["subzone:sepulcher"] = "b70a6b"
P.scopedClips["subzone:sepulcher"] = {scope="overview-body",sourceHash="bb3c82",hash="b70a6b",name="Гробниця",summary="Гробниця — головне поселення й твердиня Відступників у Срібноліссі. Колись звичайне лордеронське кладовище й склеп над західним узбережжям, тепер це укріплений прихисток Орди від загроз довкола.",section="Гробниця, що стоїть на пагорбах над узбережжям Лордерона, спершу була тихим кладовищем і склепом при західній дорозі. Після Третьої війни щойно звільнені Відступники пристосували давнє кам'яне склепіння та його землі під важливу заставу. Оточена ворожими силами з усіх боків — дикими воргенами на півдні, недобитками Погибелі на сході й чарівниками Кірін-Тору, що стежать з Амбермілла, — Гробниця дає мандрівникам Срібнолісся рідкісний прихисток, припаси й командування.",sectionIndex=1}
c["subzone:sewers"] = "980ed8"
P.scopedClips["subzone:sewers"] = {scope="overview-body",sourceHash="460a89",hash="980ed8",name="Каналізація",summary="Каналізація — розлога підземна дренажна мережа, що дає ще один вхід просто до Андерсіті. Вона пролягає під пагорбами на захід від зруйнованого палацу Лордерона й дає змогу приборкувачам кажанів і обережним мандрівникам оминути хиткі підйомники, що спускаються з тронної зали.",section="До того як чума знищила Лордерон, ці кам'яні водостоки були звичайною каналізацією королівської столиці. Та у Відступників Сильвани Віндраннер стічні тунелі стали частиною зовнішньої оборони Андерсіті. Прохід виходить на поверхню на захід від руїн, поблизу спірної Багряної Вартової Вежі в Галявинах Тірісфалю, і веде рівним, прямим схилом усередину. Приборкувачі кажанів Відступників використовують цей печерний хід, щоб швидко переносити вершників до підземних кілець, цілком оминаючи повільні підйомники-клітки. Оскільки він обходить добре укріплені двори на поверхні, це небезпечне вразливе місце, яке ворожі лазутчики постійно намагаються використати.",sectionIndex=1}
c["subzone:shadow-grave"] = "632f70"
P.scopedClips["subzone:shadow-grave"] = {scope="overview-body",sourceHash="21f038",hash="632f70",name="Тіньова Могила",summary="Тіньова Могила — кам'яний склеп на вершині похилого цвинтаря над Похоронним Подзвоном у Галявинах Тірісфалю. Це фізична точка пробудження, де щойно звільнені Відступники скидають заціпеніння смерті й послаблену владу, яку над ними мав Король-Ліч.",section="Тіньова Могила, схована в скелястих передгір'ях за Могилами Похоронного Подзвону, — простий кам'яний мавзолей із надзвичайним призначенням. У його вологих склепіннях трупи, підняті для безтямної служби Погибелі, поступово пробуджуються до вільної волі. Під пильним оком доглядачів на кшталт Гробаря Мордо ці щойно звільнені мерці підводяться з кам'яних плит і роблять перші тремтливі кроки у світ, що їх зневажає, рушаючи стежкою вниз до Похоронного Подзвону, щоб присягнути Королеві Баньші.",sectionIndex=1}
c["subzone:shadowglen"] = "0b5cc2"
P.scopedClips["subzone:shadowglen"] = {scope="overview-body",sourceHash="e5dd95",hash="0b5cc2",name="Тінедол",summary="Тінедол — відлюдна сутінкова долина в північно-східному гіллі Тельдрассила. Над нею височіє велике дерево-курган Алдрассил; це безпечний прихисток, де молоді нічні ельфи роблять перші кроки на службі, перш ніж вирушити в широкий світ.",section="Тінедол, схований у північно-східній кроні Тельдрассила, оточений високими хребтами, що відгороджують його від решти світу. Залита вічними сутінками долина зосереджена довкола Алдрассила — велетенського дерева-кургану, у чиєму видовбаному стовбурі живуть старійшини, жриці й наставники молодих нічних ельфів, що починають навчання. Єдиний шлях із долини веде на південь вузьким гірським проходом до Села Зоряного Вітерця й Доланаара, тож Тінедол — одне з найзахищеніших самою природою й наймирніших святилищ Світового Дерева.",sectionIndex=1}
c["subzone:shadowglen#faq1"] = "49eb24"
P.scopedClips["subzone:shadowglen#faq1"] = {scope="answer-only",sourceHash="fa93ed",hash="49eb24",name="Тінедол",question="Що таке Тінедол?",answer="Тінедол — захищений стартовий гай нічних ельфів у північно-східній частині Тельдрассила. Це мирний, відлюдний прихисток довкола великого дерева Алдрассил, де новачки навчаються в наставників, перш ніж вирушити мандрувати Світовим Деревом."}
c["subzone:shadowglen#faq2"] = "806ac6"
P.scopedClips["subzone:shadowglen#faq2"] = {scope="answer-only",sourceHash="edcde5",hash="806ac6",name="Тінедол",question="Що за величезне дерево в центрі долини?",answer="Це Алдрассил — дерево-курган, що становить серце Тінедолу. Його видовбане нутро править за оселю громади й осередок навчання, де нічні ельфи-новачки зустрічають наставників класів, учителів і доглядачів."}
c["subzone:shadowglen#faq3"] = "d0e3cd"
P.scopedClips["subzone:shadowglen#faq3"] = {scope="answer-only",sourceHash="387040",hash="d0e3cd",name="Тінедол",question="Які загрози є в Тінедолі?",answer="Головна загроза — на північному заході, у Печері Тіньової Нитки: печера кишить отруйними павуками, що раз у раз виповзають у гай. Молодим захисникам доручають винищувати павуків і втихомирювати неспокійну місцеву живність."}
c["subzone:shadowglen#faq4"] = "ada488"
P.scopedClips["subzone:shadowglen#faq4"] = {scope="answer-only",sourceHash="75c263",hash="ada488",name="Тінедол",question="Як вийти з Тінедолу?",answer="Тінедол повністю оточений хребтами, за винятком єдиної стежки на південь. Цей вузький гірський прохід веде на південь, до Села Зоряного Вітерця й поселення Доланаар."}
c["subzone:shadowthread-cave"] = "0896b4"
P.scopedClips["subzone:shadowthread-cave"] = {scope="overview-body",sourceHash="9df1b3",hash="0896b4",name="Печера Тіньової Нитки",summary="Печера Тіньової Нитки — волога печера в північно-західних скелях Тінедолу на Тельдрассилі. Здавна заселена тутешніми павуками Вебвуда, вона нещодавно стала небезпечно агресивною під владою їхньої матки — Ґітіісс Мерзенної.",section="Печера Тіньової Нитки в тінистій околиці Тінедолу здавна була природним лігвом велетенських павуків Тельдрассила. Раніше ці павуки тихо співіснували з молодим гіллям Світового Дерева. Та віднедавна їхня вдача стала люто територіальною. Товсті шари павутиння Вебвуда тепер душать кам'яні коридори, а агресивність виводку становить пряму загрозу молодим калдореям, що роблять перші кроки за межі Алдрассила.",sectionIndex=1}
c["subzone:shimmer-ridge"] = "fbbe7b"
P.scopedClips["subzone:shimmer-ridge"] = {scope="overview-body",sourceHash="ba2c78",hash="fbbe7b",name="Мерехтливий Хребет",summary="Мерехтливий Хребет — суворе високогір'я на півночі Дун Мороґу, просто на захід від Брами Айронфорджа. Скелясті висоти, зайняті ворожими тролями Морозогривами, складаються з двох таборів, з'єднаних хистким мостом, і славляться як єдине місце, де можна зібрати потужне мерехтливе зілля.",section="Мерехтливий Хребет на скелястих схилах одразу на захід від величної брами Айронфорджа служить дієвим редутом племені тролів Морозогривів. Поділений на два табори обабіч провалля й з'єднаний дерев'яним прогоном, анклав пильно охороняють тролі-збирачі та їхні приручені гірські вепри. Близькість до головної дороги та дворфської столиці робить його постійною загрозою для мандрівників і гірських патрулів, які мусять повсякчас остерігатися зухвалих набігів із висоти.",sectionIndex=1}
c["subzone:shimmering-flats"] = "576560"
P.scopedClips["subzone:shimmering-flats"] = {scope="overview-body",sourceHash="288da0",hash="576560",name="Мерехтливі Низини",summary="Мерехтливі Низини — безкраї солончаки на південно-східному краю Тисячі Голок, на межі з пустелею Танаріс. Колись тут було дно прадавнього озера, а тепер ця випалена сонцем рівнина славиться шаленими механічними змаганнями на Перегонах Міражу та суворими пустельними звірами.",section="Мерехтливі Низини простягаються під сліпучим південним сонцем — величезне висохле дно озера без жодної рослинки, де тут і там біліють вибілені сонцем кістки черепах і навіть дерев'яний остов прадавнього вітрильника. Цілковито рівна, без жодного горбка поверхня робить низини найкращим на Калімдорі полігоном для експериментальних машин. У самому центрі солончаків лежать Перегони Міражу, де гноми й гобліни-винахідники безупинно змагаються, чиї ракетні автомобілі, гірокоптери й двигуни розженуться найшвидше, — і часто це закінчується вогняними аваріями та димними вирвами на білій кірці.",sectionIndex=1}
c["subzone:shining-strand"] = "6d3d48"
P.scopedClips["subzone:shining-strand"] = {scope="overview-body",sourceHash="4a0131",hash="6d3d48",name="Осяйне Узмор'я",summary="Осяйне Узмор'я — смуга берега Озера Лордамер на сході Срібнолісся, що тягнеться на південь від Руїн Лордерона до суворих передгір'їв Альтерака. Колись тут панували агресивні мурлоки-Темноплавці, а тепер береги стали спірною землею, де табори Відступників стежать за водою й сходяться в сутичках із воргенами, що наступають.",section="Осяйне Узмор'я, що тягнеться східним краєм Срібнолісся, межує з туманними водами Озера Лордамер. Колись плем'я мурлоків-Темноплавців заснувало на цих мілинах кілька агресивних поселень, і кожен, хто намагався йти дорогою вздовж озера, наражався на смертельну небезпеку. Хоч Темноплавці здебільшого перебралися на схід, до Світанкових Островів, на березі аж ніяк не спокійно. Розвідники й аптекарі Відступників закріпилися на узмор'ї, відбиваючись від диких воргенів, що виходять із глибини лісу, і пильно стежачи і за водами, і за пагорбами на межі з Альтераком.",sectionIndex=1}
c["subzone:shrine-of-aessina"] = "44888c"
P.scopedClips["subzone:shrine-of-aessina"] = {scope="overview-body",sourceHash="928640",hash="44888c",name="Святилище Аессіни",summary="Святилище Аессіни — священна ельфійська пам'ятка в лісах південно-західного Ашенвалю, присвячена давньому духові лісу, природи й диких створінь. Воно лежить між Постом Маестри й Астранааром і лишається тихим прихистком серед дедалі гостріших прикордонних чвар.",section="Святилище Аессіни, що сховалося на захід від Астранаару, вшановує таємничу Дику Богиню — утілення серця й духу глибоких лісів. Покоління нічних ельфів та їхніх лісових родичів шанували це тихе місце, єднаючись тут із природою далеко від гамірних доріг. Проте тепер, коли Орда проникає в Ашенваль, щоб рубати ліс і закріплюватися, мир у священних місцях по всьому краю став хитким.",sectionIndex=1}
c["subzone:shrine-of-the-dormant-flame"] = "19d3e9"
P.scopedClips["subzone:shrine-of-the-dormant-flame"] = {scope="overview-body",sourceHash="dd732d",hash="19d3e9",name="Святиня Приспаного Полум'я",summary="На найвищій вершині на північний захід від Долини Випробувань стоїть Святиня Приспаного Полум'я — відлюдне святилище, яке шанують шамани Орди. Під проводом його самотнього хранителя Телфа Джулама посвячувані здійснюють небезпечний підйом, щоб поспілкуватися зі стихією вогню й довести свою духовну майстерність.",section="Щоб дістатися Святині Приспаного Полум'я, треба здолати вузьку звивисту стежку, що починається біля Річки Південної Люті на південно-західному краю її водозбору. Високо над червоними скелями Дуротару гірська вершина відкриває панорамний краєвид на околиці, та один хибний крок над прірвою означає певну смерть. У цьому тихому прихистку блукає Телф Джулам — самотній відлюдник, якому доручено наглядати за священними обрядами. Для майбутніх шаманів з орків і тролів, що проходять обряд Поклику Вогню, жаровня святині — горнило, де вони мають розпалити приспане вугілля жариною переможеного елементаля, доводячи, що здатні спілкуватися з руйнівними духами полум'я й шанувати їх.",sectionIndex=1}
c["subzone:shrine-of-the-fallen-warrior"] = "cb9d04"
P.scopedClips["subzone:shrine-of-the-fallen-warrior"] = {scope="overview-body",sourceHash="21ab7f",hash="cb9d04",name="Святиня Полеглого Воїна",summary="На відлюдному кряжі на захід від Перехрестя лежить Святиня Полеглого Воїна — тихий пам'ятник, з якого видно безкраї червоні савани Пусток. Тут стоїть кам'яний постамент з ініціалами «МК» і спочиває тіло полеглого орка-воїна, а оберігає це місце лагідний Цілитель Духів на ім'я Койтер.",section="Святиня Полеглого Воїна, що сховалася високо на пагорбах на північний захід від Перехрестя, — напрочуд урочистий прихисток серед пилу й небезпек Пусток. Щоб знайти її, мандрівникам доведеться піднятися звивистою стежкою на південний захід від вершини, аж до пологого кургану. На його верхівці стоїть різьблений кам'яний пам'ятник, на постаменті якого вирізьблено ініціали «МК». Перед ним спочиває закутий в обладунки орк-воїн, а вдень і вночі його стереже Цілитель Духів на ім'я Койтер. Тут не сурмлять бойові роги — лише тиша й роздуми на честь героя, що колись ходив землями Калімдору.",sectionIndex=1}
c["subzone:silver-stream-mine"] = "e3e0f0"
P.scopedClips["subzone:silver-stream-mine"] = {scope="overview-body",sourceHash="67f615",hash="e3e0f0",name="Шахта Срібного Потоку",summary="Шахта Срібного Потоку — вичерпана дворфійська копальня на півночі Лох Модану, між Станцією Алґаз і Каменетесною Греблею. Колись багата срібна жила королівства Айронфордж, вироблену порожнину перетворили на склад Ліги Шахтарів, доки її не заполонила паскудь. Сьогодні в тунелях засіли кобольди Тунельні Пацюки, що ховають викрадене спорядження й рідкісні мінеральні дивовижі.",section="Колись Шахта Срібного Потоку давала багато цінної руди, щедро поповнюючи запаси срібла Айронфорджа. З часом дворфійські кайла вгризлися так глибоко, що вичерпали головні жили, і розлогі зали перетворилися на порожній підземний комплекс. Замість кидати здобуті тяжкою працею виробки, Ліга Шахтарів обернула шахти на надійний склад для інструментів, ящиків рудокопів і спорядження з усього краю. Це також єдине відоме джерело рідкісних Заряджених Самоцвітів Розлому, по які приходять допитливі знавці таємної магії, шукаючи тонких кравецьких інгредієнтів.",sectionIndex=1}
c["subzone:silverwind-refuge"] = "45d3df"
P.scopedClips["subzone:silverwind-refuge"] = {scope="overview-body",sourceHash="19ec1b",hash="45d3df",name="Притулок Срібного Вітру",summary="Притулок Срібного Вітру — тихе поселення нічних ельфів у південно-центральному Ашенвалі, трохи на північ від Озера Містраль. Під захистом Вартових і союзних водяних елементалів воно гостинно приймає мандрівників на лісових стежках.",section="Притулок Срібного Вітру, що лежить між спокійними водами Озера Містраль і Озером Ірисів на півночі, — поряд з Астранааром один із головних перевалочних пунктів нічних ельфів у центральному Ашенвалі. Тут є затишна корчма, ремісники та наставники, які навчають мандрівників травництва, алхімії, білування й полювання. Під охороною стійких Вартових і місцевих духів води цей прихисток — мирна зупинка для союзників, що мандрують тінистим прадавнім лісом.",sectionIndex=1}
c["subzone:silverwing-grove"] = "4b1dee"
P.scopedClips["subzone:silverwing-grove"] = {scope="overview-body",sourceHash="e3cba5",hash="4b1dee",name="Гай Срібнокрилих",summary="Гай Срібнокрилих, що сховався в південно-центральному Ашенвалі біля Озера Впалого Неба, — місце збору Вартових Срібнокрилих. З цієї укріпленої улоговини воїни нічних ельфів збирають сили Альянсу, щоб відкинути лісорубів клану Бойової Пісні, які прорубуються крізь ліс.",section="Гай Срібнокрилих, захований під смарагдовими кронами на південний захід від Застави Срібнокрилих, — важливий військовий плацдарм Вартових Срібнокрилих. Це не тихий лісовий притулок, а бойове серце запеклої боротьби нічних ельфів за землю проти лісорубень Орди в Ущелині Бойової Пісні. Тут збираються високі офіцери Альянсу, припаси й розвідники: звідси організовують сутички й скликають героїв боронити прадавній Ашенваль від орківської експансії.",sectionIndex=1}
c["subzone:silverwing-outpost"] = "e3b916"
P.scopedClips["subzone:silverwing-outpost"] = {scope="overview-body",sourceHash="b20798",hash="e3b916",name="Застава Срібнокрилих",summary="Застава Срібнокрилих — укріплений гарнізон нічних ельфів у південно-центральному Ашенвалі, на схід від Річки Фалфаррен. Під командуванням Дуріель Мунфаєр це найсхідніший оплот Альянсу проти Орди в спірному лісі.",section="Застава Срібнокрилих, що лежить на південний захід від Застави Розщепленого Дерева й трохи на північ від кордону з Пустками, займає вкрай небезпечну позицію. Вона стоїть на східному березі Річки Фалфаррен — на запекло спірній території, яку патрулює Орда, — і прикриває собою володіння нічних ельфів у глибині лісу. Дуріель Мунфаєр та її Вартові Срібнокрилих перебувають у постійній облозі: орки неподалік сповнені рішучості цілком вигнати нічних ельфів із цього краю.",sectionIndex=1}
c["subzone:sishir-canyon"] = "2ebb54"
P.scopedClips["subzone:sishir-canyon"] = {scope="overview-body",sourceHash="c603ea",hash="2ebb54",name="Каньйон Сішир",summary="Каньйон Сішир — дика ущелина в Горах Кам'яного Кігтя, що прорізає шлях на схід крізь скелясті височини. Тут кишать жахливі глибокомохові павуки, а все довкола обснуване павутинням; це небезпечний підхід до Руїн Ельдре'тара. Ті, хто зважиться пройти його заплутаними глибинами, муситимуть мати справу з отруйними павуками та їхньою матір'ю виводку.",section="Каньйон Сішир, що відгалужується від гірських доріг хребта Кам'яного Кігтя, — підступний природний коридор до прадавніх Руїн Ельдре'тара. Це зовсім не тиха гірська стежка: ущелину геть заполонили глибокомохові павуки. Їхні липкі шовкові полотнища та грона яєчних коконів укривають кам'янисту землю й скельні стіни, перетворюючи яр на живе гніздо. Мандрівники й вартові, що прямують до ельфійських руїн за ним, мусять прорубувати собі шлях крізь рої лютих павуків-ткачів.",sectionIndex=1}
c["subzone:skittering-dark"] = "7162b2"
P.scopedClips["subzone:skittering-dark"] = {scope="overview-body",sourceHash="482fa1",hash="7162b2",name="Шурхотлива Пітьма",summary="Шурхотлива Пітьма — покинута шахта й темна лісова улоговина на заході Срібнолісся. Її заполонили агресивні велетенські павуки, і печера та ліси довкола густо обплетені павутинням і небезпечні для необачних звірів і мандрівників.",section="Шурхотлива Пітьма, що сховалася серед пагорбів трохи на схід від західного узбережжя Потоку Північного Припливу, колись була діючою шахтою. Сьогодні її штреки геть задушені павутинням і стали розлогим гніздом велетенських павуків. Біля входу никає тіниста прядильниця Кретіс, а павуки полюють на все, що підійде надто близько.",sectionIndex=1}
c["subzone:skull-rock"] = "7e5786"
P.scopedClips["subzone:skull-rock"] = {scope="overview-body",sourceHash="0ac4a5",hash="7e5786",name="Череп-скеля",summary="Череп-скеля — печера в східних прибережних скелях Дуротару, просто на схід від Оргріммара. Вона служить укріпленим ковеном демонічного культу Палаючого Клинка просто під носом у столиці.",section="Схована під скелями північно-східного Дуротару, Череп-скеля — одна з найнебезпечніших твердинь культу Палаючого Клинка в цьому краї. Темні культисти, орки-шанувальники Скверни та прикликачі збираються глибоко у звивистих тунелях, щоб практикувати демонічні мистецтва й плести змови проти молодої Орди. Осередок очолює небезпечний чорнокнижник Ґазз'уз, чиї дії безпосередньо загрожують сусідній брамі Оргріммара та мандрівникам на східному узбережжі.",sectionIndex=1}
c["subzone:slaughtered-lamb"] = "a555ee"
P.scopedClips["subzone:slaughtered-lamb"] = {scope="overview-body",sourceHash="07ae0f",hash="a555ee",name="Зарізане Ягня",summary="Захована в Кварталі магів Стормвінда, таверна «Зарізане Ягня» здається лише тихим і сумнівним шинком. Але під її підлогою розлогі катакомби ховають святилище й тренувальні зали заборонених чорнокнижників Альянсу.",section="На поверхні «Зарізане Ягня» не пропонує нічого, крім темних кутків і нечисленних відвідувачів, яких обслуговує шинкар Джарел Мур, що радить випадковим гостям триматися подалі від тіней. І це попередження буквальне. Спустившись задніми ходами, можна знайти підземний комплекс склепів і кіл виклику, де людські чорнокнижники та їхні колеги, що перебралися сюди з Каз Модану, відкрито вивчають таємниці скверни, сховавшись від несхвальних очей Церкви Святого Світла й Кірін-Тору.",sectionIndex=1}
c["subzone:sludge-fen"] = "95d024"
P.scopedClips["subzone:sludge-fen"] = {scope="overview-body",sourceHash="0db12c",hash="95d024",name="Багнисте Болото",summary="Багнисте Болото — отруйне промислове нафтове родовище Венчурної Компанії на північному сході Пусток. Колись тут було чисте, кришталево-блакитне озерце, але відколи гобліни звели бурові вишки й машини, водойма перетворилася на масну трясовину. Роботами керує Наглядач Луґвізл, і родовище постійно приваблює промислових шпигунів і диверсантів від суперників із Раджета.",section="До приходу Венчурної Компанії Багнисте Болото було незайманим озерцем кришталево чистої води, яке живили природні джерела посеред посушливих Пусток. Гнана невситимою жадобою прибутку, Венчурна Компанія розгорнула над улоговиною широкі нафтові бурові роботи й перетворила водойму на заповнене мулом сховище, вкрите густими промисловими відходами. Під орудою Наглядача Луґвізла гобліни-бурильники, інженери й наглядачі цілодобово качають сиру нафту, не зважаючи на руйнування природи. Тепер вода загусла від стоків і отруйних залишків, а місцеве водне життя задихається під мастилом.",sectionIndex=1}
c["subzone:solliden-farmstead"] = "91e5a4"
P.scopedClips["subzone:solliden-farmstead"] = {scope="overview-body",sourceHash="ec68f0",hash="91e5a4",name="Хутір Соллідена",summary="Хутір Соллідена — діюча людська гарбузова ферма в західних Галявинах Тірісфалю, одразу на північ від Похоронного Подзвону. Це рідкісний виняток у північному Лордероні: живі тутешні фермери, що пережили Чуму Нежиті й запекло тримаються своєї землі під тінню Багряного Хрестового Походу.",section="Поки більша частина Лордерона обернулася на руїну й гниль, поля Хутора Соллідена досі дають здорові врожаї. Поселення веде свій родовід від тих століть, коли дворянські родини-переселенці зі Строму придбали піонерські наділи по всьому Тірісфалю. Сьогодні ці вцілілі люди-фермери живуть під пильним щитом Багряного Хрестового Походу, що патрулює з сусідньої вежі. Травмовані й замкнуті, вони боронять свою садибу з непохитною ворожістю, нападаючи на всіх чужинців, що наближаються, — і з Орди, і з Альянсу.",sectionIndex=1}
c["subzone:south-gate-outpost"] = "e345d1"
P.scopedClips["subzone:south-gate-outpost"] = {scope="overview-body",sourceHash="17b181",hash="e345d1",name="Застава Південної Брами",summary="Застава Південної Брами — укріплений дворфійський гірський пост на Проході Південної Брами між Дун Мороґом і Лох Моданом. Горяни, що тримають засніжену південну дорогу, оберігають постійний потік мандрівників між морозними висотами Айронфорджа й помірною долиною Озера.",section="Застава Південної Брами, що стоїть посередині високого гірського розрізу Проходу Південної Брами, позначає межу між засніженими схилами Дун Мороґу й зеленою улоговиною Лох Модану. Тут несуть службу айронфорджські горяни, яким доручено патрулювати кам'янисті серпантини й тримати небезпечних звірів подалі від головного шляху. На відміну від своїх родичів, що ледве дають собі раду на Заставі Північної Брами, тутешні захисники здебільшого вже убезпечили свою ділянку дороги, тож мандрівники, прочани й торгові вози, що прямують до Телсамара, можуть подорожувати відносно безпечно.",sectionIndex=1}
c["subzone:south-gate-pass"] = "a81d03"
P.scopedClips["subzone:south-gate-pass"] = {scope="overview-body",sourceHash="e7d30b",hash="a81d03",name="Прохід Південної Брами",summary="Прохід Південної Брами — головний гірський шлях, що з'єднує засніжені висоти Дун Мороґу з улоговиною Лох Модану. Оточений дворфійськими тунелями й дозорними постами, він править за найкоротшу дорогу між Айронфорджем і поселенням Телсамар.",section="Прохід Південної Брами, прорубаний просто крізь хребет Каз Модану, з'єднує високі гори Дун Мороґу з пологою долиною Лох Модану на сході. Залишивши позаду холодні схили, мандрівники виходять крізь кам'яні арки в тепліше серце дворфійських земель. Оскільки шлях веде просто до Телсамара, ним постійно ходять горяни, гінці й щойно вишколені шукачі пригод, що вирушають зі столиці.",sectionIndex=1}
c["subzone:south-tide-s-run"] = "92922c"
P.scopedClips["subzone:south-tide-s-run"] = {scope="overview-body",sourceHash="041fb0",hash="92922c",name="Південна Течія Припливу",summary="Південна Течія Припливу — самотнє південно-західне узбережжя Срібнолісся, що тягнеться вздовж холодних вод Великого Моря. Ці вологі піски й прибій, що облямовують лісисті нутрощі краю, — південна пара до Потоку Північного Припливу.",section="Південна Течія Припливу, що тягнеться південно-західним краєм Срібнолісся, — безлюдна межа між лісом і Великим Морем. На відміну від захищених східних доріг, що ведуть униз до Стіни Ґреймейна, цей відкритий берег бере на себе всю силу західних припливів і лишається похмурою дикою місциною, майже не зачепленою поселеннями в глибині краю.",sectionIndex=1}
c["subzone:southern-gold-road"] = "cac282"
P.scopedClips["subzone:southern-gold-road"] = {scope="overview-body",sourceHash="3db874",hash="cac282",name="Південна Золота Дорога",summary="Південна Золота Дорога — важливий пустельний тракт, що тягнеться південною половиною Пусток і з'єднує центральні рівнини з Великим Підйомником. Це незамінна артерія торгівлі в краї: нею рухаються каравани, припаси й мандрівники між віддаленими куточками Калімдору.",section="Офіційно Південна Золота Дорога починається біля кам'яного мосту, що розділяє північну й південну половини Пусток, і тягнеться просто на південь, аж до Великого Підйомника, яким спускаються в Тисячу Голок. Як і північна частина, що зветься просто Золотим Шляхом, цей курний тракт має назву завдяки нескінченному потоку прибуткових купецьких караванів. Попри постійні напади місцевих племен шипогривів і хижаків, що никають саваною, це один із найжвавіших далеких шляхів континенту, яким возять товари між віддаленими заставами й гамірними портами.",sectionIndex=1}
c["subzone:southshore"] = "905187"
P.scopedClips["subzone:southshore"] = {scope="overview-body",sourceHash="28827b",hash="905187",name="Саутшор",summary="Саутшор — приморський людський порт у Передгір'ї Гілсбреда й одна з небагатьох уцілілих твердинь Альянсу в занепалому Лордероні. Колись сонне рибальське селище, тепер це оплот в облозі, якому постійно загрожують гарнізон Відступників у Таррен Міллі, свавільні розбійники Синдикату й прибережні потвори.",section="Саутшор уперше прославився під час Першої війни, коли на його берег висадилися човни з біженцями, що вціліли після падіння королівства Стормвінд. Хоч під час Другої війни за нього билися й навіть захоплювали, його відбудували, і згодом він пережив жахи Третьої війни. Сьогодні, коли решта Лордерона лежить у руїнах або під владою Відступників, Саутшор лишається затято вірним Великому Альянсу. Він дає прихисток людям, що втратили домівки, ветеранам-паладинам Срібної Длані й ученим Кірін-Тору.",sectionIndex=1}
c["subzone:spirit-rise"] = "27822c"
P.scopedClips["subzone:spirit-rise"] = {scope="overview-body",sourceHash="25ea7c",hash="27822c",name="Узвишшя Духів",summary="Узвишшя Духів — північно-західна столова гора Тандер Блафа, головне святилище тауренської столиці для духовних і шаманських студій. Тут, під опікою духовних провідників на кшталт племені Скайчейсер, нагорі стоять священні зали навчання, а внизу печера спускається до Ставків Видінь.",section="Узвишшя Духів, що височіє над рівнинами Малгору, віддане єднанню зі стихіями й духами предків. З'єднане з центральною горою мотузяними мостами, воно прихищає Залу Духів і павільйон Духовного зцілення, де молоді й бувалі шамани збираються, щоб поглибити зв'язок із землею, повітрям, вогнем і водою. Плем'я Скайчейсер має на узвишші помітну присутність і веде шукачів давніми традиціями.",sectionIndex=1}
c["subzone:spirit-rock"] = "3f495a"
P.scopedClips["subzone:spirit-rock"] = {scope="overview-body",sourceHash="e24632",hash="3f495a",name="Камінь Духів",summary="Камінь Духів — священна скеля на суворих кручах над Долиною Випробувань у Дуротарі. Дістатися до неї можна звивистою стежкою, відомою як Прихована Стежка; це відлюдне святе місце, де посвячувані безпосередньо спілкуються зі стихійними силами землі.",section="Над червоним каньйоном, де молоді воїни та розвідники Орди починають навчання, Камінь Духів стоїть як вівтар єднання з духами. Відокремлений від гамору Долини Випробувань, він доступний лише Прихованою Стежкою, що в'ється скелястим гребенем. Майбутні шамани здійснюють паломництво до цього пустельного виступу, щоб випити традиційну сапту й, пронизавши завісу тілесного світу, почути гуркіт і шепіт самої землі.",sectionIndex=1}
c["subzone:splintertree-post"] = "7a98d5"
P.scopedClips["subzone:splintertree-post"] = {scope="overview-body",sourceHash="3d0355",hash="7a98d5",name="Застава Розщепленого Дерева",summary="Застава Розщепленого Дерева — головна фортеця Орди у східному Ашенвалі, на північний захід від Пагорба Вогню Скверни. Заснована Ґроммашем Хеллскрімом і кланом Бойової Пісні під час Третьої війни, вона слугує потужно укріпленим оплотом проти нічних ельфів і плацдармом для захоплення нових земель.",section="Застава Розщепленого Дерева, вирубана просто в прадавньому лісі, — головний військовий і постачальний осередок Орди у східному Ашенвалі. Її заснували Ґроммаш Хеллскрім і клан Бойової Пісні, коли орки вперше вдерлися в ліс під час Третьої війни, і вона досі лишається добре озброєним анклавом, який обороняють переважно розвідники й воїни — орки та таурени. Тут є господар вітрокрилів, корчма й надійні шляхи постачання до Оргріммара, тож застава — опора спірної присутності Орди під кронами лісу.",sectionIndex=1}
c["subzone:splithoof-crag"] = "66b645"
P.scopedClips["subzone:splithoof-crag"] = {scope="overview-body",sourceHash="cb40e1",hash="66b645",name="Круча Розколотого Копита",summary="Круча Розколотого Копита — укріплене поселення кентаврів Ґалак під північними скелями Тисячі Голок. Поряд зі столовими горами це один з головних осередків племені, що стереже вхід до Твердині Розщепленого Копита. Мандрівникам, які йдуть дном каньйону, доводиться мати справу з агресивними дозорами Ґалак, що никають біля круч.",section="Круча Розколотого Копита тулиться до прямовисної північної скельної стіни Тисячі Голок, трохи на схід від височенного Шпиля Темної Хмари. Це давній осередок кентаврів Ґалак із грубими наметовими таборами й ґрунтовими стежками, що в'ються поміж скель. У серці селища, під самою кручею, лежить Твердиня Розщепленого Копита — підземна печера, де зберігається Роздвоєне Копито, прадавня реліквія кентаврів, яку оберігає священна жаровня.",sectionIndex=1}
c["subzone:splithoof-hold"] = "bb4c84"
P.scopedClips["subzone:splithoof-hold"] = {scope="overview-body",sourceHash="5bccb1",hash="bb4c84",name="Твердиня Розщепленого Копита",summary="Твердиня Розщепленого Копита — глибока печерна твердиня, видовбана в камені Кручі Розколотого Копита в Тисячі Голок. Її тримає плем'я кентаврів Ґалак: печера править за укріплене лігво, а в ній стоїть Прадавня Жаровня, де вічно горить священне полум'я.",section="Твердиня Розщепленого Копита, захована всередині Кручі Розколотого Копита, — укріплений сховок кентаврів Ґалак. На відміну від обвітреного дна каньйону, ця замкнена печера дає їм прихисток, вузькі проходи, які легко боронити, і надійне укриття від племен-суперників і мандрівників, що йдуть крізь Голки.",sectionIndex=1}
c["subzone:stagnant-oasis"] = "0f70b9"
P.scopedClips["subzone:stagnant-oasis"] = {scope="overview-body",sourceHash="d42a32",hash="0f70b9",name="Застояна оаза",summary="Застояна оаза — одна з цінних водойм у посушливому серці Пусток, між Золотим Шляхом і Узбережжям Крамарів. Оточена буйними пальмами й захоплена кентаврами Колкарами, вона своїми каламутними водами й берегами живить своєрідних місцевих звірів, зокрема черепах-хижощелепів і мандрівних кодо.",section="Застояна оаза, що сховалася на схід від Золотого Шляху й углиб суходолу від Узбережжя Крамарів, — важливий зелений куточок серед курних чагарників Пусток. Як і сусідні води, ставок живить густу зелень і агресивних черепах-хижощелепів, а ослаблені кодо Пусток часто забрідають сюди, відбившись від величезних стад Поля Велетнів. Проте мандрівникам варто бути обережними: кентаври Колкари тримають табори на берегах і люто бережуть право на воду від кожного, хто зайде на їхню землю.",sectionIndex=1}
c["subzone:starbreeze-village"] = "fd1aad"
P.scopedClips["subzone:starbreeze-village"] = {scope="overview-body",sourceHash="7e0505",hash="fd1aad",name="Село Зоряного Вітерця",summary="Село Зоряного Вітерця — покинуте поселення нічних ельфів на схід від Доланаара на Тельдрассилі. Колись тихе лісове сільце, воно нещодавно дісталося збожеволілим фурболгам племені Вузлошкірів. Зруйноване поселення тепер стоїть як кричущий символ скверни, що просочується в коріння Світового Дерева.",section="Село Зоряного Вітерця, що лежить на південний схід від Тінедолу, просто за дорогою від Доланаара, колись було домівкою мирних родин нічних ельфів під гіллям Тельдрассила. Сьогодні село в руїнах, а його дерев'яні будівлі заполонили агресивні фурболги-Вузлошкіри. Здичавілі від лиховісної скверни, що вразила гілля Світового Дерева, звіролюди вигнали ельфійських мешканців і тепер люто боронять зруйновані землі.",sectionIndex=1}
c["subzone:steelgrill-s-depot"] = "2c8362"
P.scopedClips["subzone:steelgrill-s-depot"] = {scope="overview-body",sourceHash="ba8cd2",hash="2c8362",name="Склад Стілґрила",summary="Склад Стілґрила — гамірна інженерна майстерня й ремонтна станція просто на схід від Хараноса в Дун Мороґу. Під наглядом Белдіна Стілґрілла та його бригади майстрів вона служить передовим осередком обслуговування машин, постачання для тінкерів і збору брухту.",section="Склад Стілґрила трохи осторонь засніженої дороги на схід від Хараноса гуде брязкотом металу, шипінням парових клапанів і гулом дослідних двигунів. Дворфські шахтарі та дивакуваті гноми-інженери збираються тут серед важкої техніки, крокуючих механізмів і купи сирої руди, вивезеної з сусідніх кар'єрів. Поки Дун Мороґ потерпає від невпинних безчинств трогів і нестачі деталей, Белдін Стілґрілл зі своєю бригадою підтримує машини Альянсу в робочому стані, тож для мандрівників, яким на лютому морозі потрібні запчастини чи технічна порада, склад — незамінна зупинка.",sectionIndex=1}
c["subzone:stendel-s-pond"] = "5b43f8"
P.scopedClips["subzone:stendel-s-pond"] = {scope="overview-body",sourceHash="ae8916",hash="5b43f8",name="Ставок Стендела",summary="Ставок Стендела — невелика водойма, можливо, отруєна, на південний захід від Сентінел Гілла у Вестфолі. Довкола нишпорять гноли, поряд видніються могили, але попри зловісні небезпеки це одне з небагатьох місць у висохлому краї, де можна порибалити в прісній воді.",section="Ставок Стендела, захований на південний захід від Сентінел Гілла, дарує тиху перерву серед курних рівнин Вестфолу, хоча небезпека завжди поруч. Мулкими берегами бродять гноли, а розкидані кістяки й дві самотні могили натякають, що чи то вода, чи то звірі довкола смертельні для необачних подорожніх. Та рибалки все одно ризикують сюди ходити заради косяків шавлієвої риби.",sectionIndex=1}
c["subzone:stillwater-pond"] = "b7e30f"
P.scopedClips["subzone:stillwater-pond"] = {scope="overview-body",sourceHash="85ecbc",hash="b7e30f",name="Ставок Тихої Води",summary="Ставок Тихої Води — тиха застояна водойма одразу на захід від Брілла в Галявинах Тірісфалю. Колись улюблене місце пікніків і купання живих дітей Лордерона, він перетворився на каламутну калюжу, де водяться кістяні риби й нишпорять небезпечні падложери.",section="До Третьої війни й спустошень Чуми Нежиті Ставок Тихої Води був тихим прихистком для люду Галявин Тірісфалю. Родини з сусідніх сіл збиралися на його трав'янистих берегах на пообідні пікніки, а діти, замалі для підступних глибин Озера Світлої Води, вчилися плавати на його мілинах. Сьогодні ідилічні води стали мертвими й сірими. Живі давно зникли, лишивши тільки кістяних риб, що шмигають під поверхнею, і блукаючу нежить, що тиняється довколишніми лісами.",sectionIndex=1}
c["subzone:stone-cairn-lake"] = "bb303a"
P.scopedClips["subzone:stone-cairn-lake"] = {scope="overview-body",sourceHash="7b855a",hash="bb303a",name="Озеро Кам'яного Кургану",summary="Озеро Кам'яного Кургану — кільцеподібна водойма на північному сході Лісу Елвінн. У його центрі лежить острів, увінчаний Дозором Героїв — меморіалом полеглим у Першій війні. Колись тихе місце для роздумів, нині озеро тривожать ворожі мурлоки на берегах і чародії-відступники, що зайняли острів.",section="Озеро Кам'яного Кургану завдячує назвою помітному кам'яному меморіалу, зведеному на великому острові в його центрі. Цей пам'ятник, відомий як Дозор Героїв, поставили на честь тяжких людських втрат у Першій війні проти Орди орків. Колись родини та прочани безпечно діставалися острова, щоб ушанувати полеглих, дивлячись через спокійні води на урочисту кам'яну кладку. Та нині небезпечні чародії-відступники розбили табір просто біля меморіалу, перетворивши місце священної пам'яті на ворожий редут.",sectionIndex=1}
c["subzone:stonebull-lake"] = "1c5630"
P.scopedClips["subzone:stonebull-lake"] = {scope="overview-body",sourceHash="827b6c",hash="1c5630",name="Озеро Кам'яного Бика",summary="Озеро Кам'яного Бика — тихе водоймище у формі підкови, що огортає Село Бладгуф у центральному Малгорі. Живлене чистими водами, що стікають із рівнин, воно дає прісну воду, вдосталь риби й мирні береги молодим тауренам, які дорослішають під проводом Кайрна Бладгуфа.",section="Огинаючи Село Бладгуф із трьох боків, Озеро Кам'яного Бика визначає географію центрального Малгору. Дерев'яний міст перетинає найвужче місце озера, несучи головну ґрунтову дорогу між поселенням і великим плато Тандер Блафа на півночі. Спокійні води повняться місцевою рибою, тож береги облюбували мисливці на спочинку, втомлені мандрівники й рибалки-учні, що опановують ремесло під безкраїм відкритим небом.",sectionIndex=1}
c["subzone:stonefield-farm"] = "6be610"
P.scopedClips["subzone:stonefield-farm"] = {scope="overview-body",sourceHash="38f0b4",hash="6be610",name="Ферма Стоунфілдів",summary="Ферма Стоунфілдів — діюча садиба на півдні Лісу Елвінн. Тут живе родина Стоунфілдів, що давно загрузла в запеклій ворожнечі із сусідами Маклюрами.",section="Ферма Стоунфілдів серед хвилястої зелені на південь від Ґолдшира вирощує збіжжя для королівства, водночас плекаючи люту, десятиліттями давню образу на сусідні Виноградники Маклюрів. Злопам'ятство між господарствами породжує дрібні сварки, взаємні звинувачення в крадіжках і постійну напругу. Та за ворожими перепалками юний Томмі Джо Стоунфілд таємно покохав Мейбелл Маклур, і це тихе кохання може або перекинути міст між родинами, або розпалити ще більший гнів.",sectionIndex=1}
c["subzone:stonefire-tavern"] = "ed3e72"
P.scopedClips["subzone:stonefire-tavern"] = {scope="overview-body",sourceHash="d5a5ac",hash="ed3e72",name="Таверна «Кам'яний Вогонь»",summary="Таверна «Кам'яний Вогонь» — головний заїзд для мандрівників у гірському місті Айронфорджі. Вона стоїть у гамірних Торгових Рядах, одразу на північ від міської брами, і дає шукачам пригод з усього Каз Модану тепле вогнище, міцний дворфійський ель і місце для відпочинку.",section="Таверна «Кам'яний Вогонь» стоїть одразу на північ від брами фортеці, у Торгових Рядах, і вважається найкращим шинком Айронфорджа. Її тримає Шинкар Файрбрю разом зі своєю донькою Ґвенною: утомлені подорожні знаходять тут ситні страви, місцеве пиво й нічліг під горою. Хто ховається від лютих гірських снігів Дун Мороґу, хто обмінюється байками й припасами, перш ніж вирушити вглиб міста, — мандрівники з усіх куточків Альянсу раз у раз збираються біля її ревучого вогнища.",sectionIndex=1}
c["subzone:stonesplinter-valley"] = "181607"
P.scopedClips["subzone:stonesplinter-valley"] = {scope="overview-body",sourceHash="0a025c",hash="181607",name="Долина Кам'яного Уламка",summary="Долина Кам'яного Уламка — сувора гірська долина на південному заході Лох Модану, яку заполонили ворожі троги. Колись незаймана альпійська улоговина, тепер вона перетворилася на укріплений табір під грубою орудою трогівського ватажка Ґраумуґа.",section="Долина Кам'яного Уламка, що сховалася серед скелястих схилів південно-західного Лох Модану, колись була тихою альпійською улоговиною. Тому спокою настав кінець, коли хвилі підземних трогів видерлися на поверхню по всьому Каз Модану. Захопивши долину, плем'я Кам'яного Уламка швидко перетворило скелясті ущелини на грубі укріплення: риє лігва, ставить барикади й полює на все, що забреде надто близько. Через їхню численність долина стала відкритою раною на дорогах південного Лох Модану, і горяни з Телсамара змушені наймати відчайдушних найманців, щоб ті проріджували лави трогів і знищили їхнього велетенського ватажка Ґраумуґа.",sectionIndex=1}
c["subzone:stonetalon-peak"] = "2743ac"
P.scopedClips["subzone:stonetalon-peak"] = {scope="overview-body",sourceHash="a529d2",hash="2743ac",name="Пік Кам'яного Кігтя",summary="Пік Кам'яного Кігтя — прадавнє святилище нічних ельфів у зеленій високогірній долині на північно-західному краю Гір Кам'яного Кігтя. Священне для калдореїв і доглянуте місцевими друїдами, воно є головним оплотом Альянсу серед цих скелястих висот.",section="Високо над посушливим пилом нижніх хребтів Пік Кам'яного Кігтя розкривається пишним, оповитим туманом святилищем. Цю долину здавна вважали священною й просякнутою прадавньою магією: тут збереглися руїни, вік яких сягає тисячоліть, — з тих часів, коли в краї стояли храми на честь королеви Азшари, ще до Великого Розколу. Нині вартові калдореїв і друїди знову мирно доглядають це місце: тут затишний притулок із підземною обителлю друїдів і важливою пристанню гіпогрифів Альянсу.",sectionIndex=1}
c["subzone:stonewatch"] = "688aea"
P.scopedClips["subzone:stonewatch"] = {scope="overview-body",sourceHash="ce4839",hash="688aea",name="Кам'яна Варта",summary="Кам'яна Варта — укріплена твердиня в центрі Гір Редріджу, збудована, щоб захищати довколишні людські землі від вторгнень із півночі. Колись тут стояли солдати Стормвінда, а тепер фортецю тримають у жорстокому кулаці орки Блекрок, і вона становить безпосередню загрозу для сусіднього Лейкшира.",section="Кам'яна Варта, що височіє над урвищами біля Водоспаду Кам'яної Варти, складається з міцної вежі та фортеці, зведених, щоб стерегти підступи з боку Палаючих Степів. Спершу її тримали захисники Лейкшира, але укріплення впало, коли чорнокнижник-ренегат Морґант уклав союз із кланом Блекрок. Сповнені темної магії, орки-загарбники розгромили місцевий людський гарнізон — 12-й Шабельний полк — і захопили фортецю. Згодом Морґант обернувся проти союзників і відступив до сусідньої Вежі Ілґалара з армією гнолів Тіньової Шкури, але орки Блекрок і далі міцно тримають фортецю під командою Генерала Ґат'Ілзоґґа та Лейтенанта Таріл'зуна.",sectionIndex=1}
c["subzone:stonewatch-falls"] = "e81b09"
P.scopedClips["subzone:stonewatch-falls"] = {scope="overview-body",sourceHash="7dacb0",hash="e81b09",name="Водоспад Кам'яної Варти",summary="Водоспад Кам'яної Варти — мальовничий водоспад і глибоке гірське плесо на сході Гір Редріджу, яких живлять води, що витікають з Озера Незрушного. Він спадає схилом під грізними висотами Кам'яної Варти, а його відлюдні води захопило вороже плем'я мурлоків.",section="Витікаючи зі східної річки Озера Незрушного, Водоспад Кам'яної Варти спадає скелястою місцевістю під твердинею орків Блекрок — Кам'яною Вартою. Падаюча вода видовбала глибоке плесо, сховане біля підніжжя гори. Попри природну красу, мандрівники рідко зупиняються помилуватися краєвидом: плесо заполонила зграя лютих мурлоків, що будує грубі очеретяні халупи й нападає на кожного, хто необачно ступить на берег.",sectionIndex=1}
c["subzone:stonewatch-keep"] = "78ce2d"
P.scopedClips["subzone:stonewatch-keep"] = {scope="overview-body",sourceHash="11595e",hash="78ce2d",name="Фортеця Кам'яної Варти",summary="Фортеця Кам'яної Варти — укріплена кам'яна твердиня, що нависає над сходом Гір Редріджу; колись її звело й утримувало Королівство Стормвінд. Тепер її захопило військо орків Блекрок, і вона стала передовою базою, звідки їхні воєначальники тероризують Лейкшир.",section="Фортеця Кам'яної Варти колись захищала східні кряжі й оберігала поселенців Лейкшира від ворожих вторгнень. Цей мир розлетівся на друзки, коли чорнокнижник-ренегат Морґант уклав союз із кланом Блекрок. Посилені темною магією, орки з лютою жорстокістю штурмували фортецю, розгромили людських захисників і захопили її. Хоча згодом Морґант покинув союзників, звів сусідню Вежу Ілґалара й підкорив місцевих гнолів, загарбники Блекрок таки зміцнили свою владу над Кам'яною Вартою й перетворили колишній бастіон Альянсу на укріплений плацдарм для наступу на долину.",sectionIndex=1}
c["subzone:stonewatch-tower"] = "bdcbd3"
P.scopedClips["subzone:stonewatch-tower"] = {scope="overview-body",sourceHash="85df94",hash="bdcbd3",name="Вежа Кам'яної Варти",summary="Вежа Кам'яної Варти — кам'яна сторожова вежа в захопленій твердині Кам'яної Варти на північному сході Редріджу. Колись її доглядали захисники Лейкшира, а тепер клан Блекрок захопив цю заставу, щоб стежити за довколишніми кряжами й убезпечити свій гірський бастіон.",section="Збудована Королівством Стормвінд, щоб стерегти високі гірські перевали над Озером Незрушним, Вежа Кам'яної Варти була передовою розвідувальною посестрою Фортеці Кам'яної Варти. З її висоти вартові легко бачили східні кряжі й попереджали Лейкшир про будь-яку загрозу з Палаючих Степів. Ця мережа раннього попередження розвалилася, коли орки Блекрок Генерала Ґат'Ілзоґґа спустилися з висот, розгромили людських захисників і забрали твердиню для власних воєнних потреб. Нині вежа наїжачилася вартовими Блекрок, і жоден розвідник Альянсу не підійде до фортеці непоміченим.",sectionIndex=1}
c["subzone:stonewrought-dam"] = "d5aa80"
P.scopedClips["subzone:stonewrought-dam"] = {scope="overview-body",sourceHash="045605",hash="d5aa80",name="Каменетесна Гребля",summary="Каменетесна Гребля — колосальне інженерне диво дворфів на північному краю Лох Модану. Вона стримує води Лоху, утворюючи величезне високогірне озеро, і водночас осушує Багнокрай унизу, перетворюючи його на придатні для життя болота.",section="Каменетесна Гребля, що перетинає каньйон на схід від Дун Алґаза, вважається одним із найбільших будівельних тріумфів дворфійської цивілізації. Спроєктована майстром-архітектором Темного Заліза Франклорном Форджрайтом, гребля зведена за його новаторською технікою каменетесання. Затримавши води гірської улоговини, гребля подвоїла площу Лоху й водночас поступово знизила рівень води на півночі, тож болотиста улоговина Багнокраю постала з колись цілком затопленої долини.",sectionIndex=1}
c["subzone:stormwind-gate"] = "021241"
P.scopedClips["subzone:stormwind-gate"] = {scope="overview-body",sourceHash="7a6d19",hash="021241",name="Брама Стормвінда",summary="Брама Стормвінда — монументальний укріплений вхід, що сполучає Ліс Елвінн зі Стормвіндом. Під невпинною охороною королівських вартових цей поріг — головна межа між спокійними лісами та величною Долиною Героїв.",section="Брама Стормвінда, що височіє над південною дорогою Лісу Елвінн, служить і оборонним оплотом, і церемоніальним порогом столиці. Міські вартові Стормвінда невпинно стежать за кам'яним порталом, охороняючи підступи з лісу, а регулярні патрулі крокують між зовнішньою аркою та Долиною Героїв. Попри тривалі заворушення по всьому Елвінну, величезна брама з заліза й каменю лишається широко відчиненою, щоб вітати мандрівників, купців і захисників, що повертаються, у серці Альянсу.",sectionIndex=1}
c["subzone:stormwind-keep"] = "b20a93"
P.scopedClips["subzone:stormwind-keep"] = {scope="overview-body",sourceHash="7358a2",hash="b20a93",name="Фортеця Стормвінда",summary="Фортеця Стормвінда височіє над столицею як кам'яна твердиня й осідок влади Королівства Стормвінд. Відбудована після руйнування в Першу війну, нині вона прихищає королівський двір юного короля-хлопчика Андуїна Рінна та його регента, Верховного Лорда Болвара Фордрагона.",section="Фортеця Стормвінда, що стоїть на плато над усім містом, — водночас палац і воєнний бастіон. Первісну твердиню спалила дотла Стара Орда, коли наприкінці Першої війни вбили короля Ллейна. Знову зведена на старих підвалинах після того, як Альянс повернув королівство, відбудована фортеця вміщує не лише велику тронну залу й Воєнну Кімнату, а й тихі садові дворики та простору Королівську Бібліотеку.",sectionIndex=1}
c["subzone:stormwind-stockade"] = "e8c242"
P.scopedClips["subzone:stormwind-stockade"] = {scope="overview-body",sourceHash="ba5823",hash="e8c242",name="В'язниця Стормвінда",summary="Захована під каналами вздовж північного краю Кварталу магів, В'язниця — головний каземат суворого режиму в Стормвінді. Призначена для вбивць, політичних бунтарів і чужоземних ворогів, ця підземна фортеця нещодавно поринула в цілковитий хаос після злагодженого бунту в'язнів.",section="Зазвичай нею опікується Наглядач Телвотер, і саме сюди королівство кидає найнебезпечніших в'язнів — від головорізів і агентів Дефіас до полонених орків Блекрок і дворфів Темного Заліза. Проте жорстокий бунт, організований хитрим змовником Дефіас Базілом Треддом, цілком витіснив тюремну варту. Тепер в'язні вільно розгулюють нижніми камерами, перетворивши твердиню на фортецю бунту. Телвотер, якому ледве вдалося втримати вхід, покладається на вільних шукачів пригод, які мають зануритися в підземні коридори й придушити заколот, доки той не вихлюпнувся в канали.",sectionIndex=1}
c["subzone:stormwind-stockade-classic"] = "d2535e"
P.scopedClips["subzone:stormwind-stockade-classic"] = {scope="overview-body",sourceHash="2c420e",hash="d2535e",name="В'язниця Стормвінда (класична)",summary="В'язниця Стормвінда — укріплена підземна в'язниця під кварталом каналів у Стормвінді. Спершу збудована для дрібних злочинців, жорстоких найманців і політичних бунтарів, нещодавно вона поринула в хаос після жорстокого бунту в'язнів.",section="Захована біля каналів між Старим Містом і Кварталом магів, В'язниця — головна каральна установа Королівства Стормвінд. Під орудою Наглядача Телвотера підземний комплекс тримає найнебезпечніших лиходіїв королівства: головорізів Братства Дефіас, орка-грабіжника з Блекрок, огра й навіть дворфа-лазутчика з Темного Заліза. Нещодавно злагоджений тюремний бунт, організований хитрим злочинцем Базілом Треддом, здолав гарнізон: уцілілих вартових вигнали, а внутрішні зали цілком опинилися під владою каторжників.",sectionIndex=1}
c["subzone:stoutlager-inn"] = "cdcb0d"
P.scopedClips["subzone:stoutlager-inn"] = {scope="overview-body",sourceHash="406fda",hash="cdcb0d",name="Корчма «Міцний Лагер»",summary="Корчма «Міцний Лагер» — жваве серце Телсамара й головний прихисток для мандрівників у Лох Модані. Сховавшись під пологими пагорбами біля озера, вона пропонує теплі вогнища, міцний дворфійський ель і гамірне місце зустрічей для шукачів пригод і місцевих мешканців.",section="Корчма «Міцний Лагер», що стоїть у самому Телсамарі, — осередок громадського життя західного Лох Модану. Рудокопи, горяни й мандрівники, що йдуть між Дун Мороґом і Багнокраєм, зупиняються тут, щоб обмінятися чутками, знайти нічліг і випити ситного дворфійського пива. Поки нетрі за Телсамаром стають дедалі небезпечнішими через трогів і кобольдів, товсті кам'яні стіни й палахкі вогнища «Міцного Лагеру» дають надійний прихисток.",sectionIndex=1}
c["subzone:strahnbrad"] = "bb430e"
P.scopedClips["subzone:strahnbrad"] = {scope="overview-body",sourceHash="4015ac",hash="bb430e",name="Странбрад",summary="Странбрад — зруйноване людське поселення на північно-східних висотах Гір Альтерак, біля кордону із Західними Чумними Землями. Колись знане як місце, де принц Артас Менетіл уперше дав відсіч нападникам-оркам Блекрок, містечко відтоді занепало й стало укріпленою твердинею злочинного Синдикату.",section="Странбрад спершу належав королівству Альтерак, а після Другої війни увійшов до Лордерона, і його лихо почалося напередодні Третьої війни. Орки клану Блекрок напали на поселення, щоб захопити людей для жертвоприношень Палаючому Легіону, і принц Артас Менетіл разом із Лицарями Срібної Длані вирушив на захист містечка. Хоч Артас прогнав нападників і вбив їхнього наглядача рабів, містечко зазнало тяжких втрат. Коли невдовзі по тому Лордерон упав під натиском Погибелі, Странбрад кинули напризволяще стихіям.",sectionIndex=1}
c["subzone:sun-rock-retreat"] = "ce77b3"
P.scopedClips["subzone:sun-rock-retreat"] = {scope="overview-body",sourceHash="006eb5",hash="ce77b3",name="Притулок Сонячної Скелі",summary="Притулок Сонячної Скелі — прихована святиня Орди високо серед центральних вершин Гір Кам'яного Кігтя, трохи південніше Озера Міркфаллон. Тут верховодять таурени й орки, і це головний плацдарм та пункт постачання Орди в краї. А ще селище стоїть на священній землі, яку таурени здавна шанують за її глибокий духовний відгук.",section="Притулок Сонячної Скелі, захований у гірській улоговині на південь від Озера Міркфаллон, здавна мав для тауренів духовне значення. За давнім переказом, Ан'ше — Сонце — поцілувало саме ту вершину, на якій стоїть селище. Ще задовго до приходу Орди тауренські шамани й прочани ходили сюди на обряди, що прочиняють завісу смертного світу, і черпали силу з міцного зв'язку цієї землі з царством духів.",sectionIndex=1}
c["subzone:talondeep-path"] = "3e6661"
P.scopedClips["subzone:talondeep-path"] = {scope="overview-body",sourceHash="85ce8e",hash="3e6661",name="Стежка Глибокого Кігтя",summary="Стежка Глибокого Кігтя — звивистий підземний тунель, що пронизує гірський хребет між Ашенвалем і Горами Кам'яного Кігтя. Тут не трапляється ні ворожих істот, ні подорожніх: це тихий природний підземний перехід, що з'єднує Озеро Містраль із Кручею Вітрорізу.",section="Під суворим гребенем, що розділяє Ашенваль і Гори Кам'яного Кігтя, захована Стежка Глибокого Кігтя — тихий підземний шлях. Він з'єднує ліси трохи на захід від Озера Містраль із північно-західними околицями Кручі Вітрорізу. На відміну від небезпечних наземних стежок, де чатують хижаки й воюють ворожі сторони, у тунелі моторошно спокійно: ні ворожих звірів, ні таборів — лише безліч звивистих бічних кишень, розколин і природних ніш у скелі. Нагорі ще проглядають рештки прадавньої дороги — натяк на те, що колись мандрівники долали високі вершини, поки ця захищена печера не стала найзручнішим шляхом крізь камінь.",sectionIndex=1}
c["subzone:talondeep-vale"] = "153f97"
P.scopedClips["subzone:talondeep-vale"] = {scope="overview-body",sourceHash="8c3d18",hash="153f97",name="Долина Глибокого Кігтя",summary="Долина Глибокого Кігтя — тиха лісиста улоговина в південно-центральному Ашенвалі. Вона межує з Притулком Срібного Вітру, Руїнами Зоряного Пилу та входом до Гір Кам'яного Кігтя і править мандрівникам за мирний зелений коридор на шляху південним Калімдором.",section="Долина Глибокого Кігтя, що сховалася під густими кронами південно-центрального Ашенвалю, — перехрестя кількох знаних місць. Зі сходу її обрамлює Притулок Срібного Вітру, поблизу лежать моторошні Руїни Зоряного Пилу, а далі здіймається кам'янистий підйом до Гір Кам'яного Кігтя. Затінена прадавніми деревами, долина лишається диким лісовим краєм, яким проходять стражі й вартові нічних ельфів та випадкові мандрівники, прямуючи між серцем лісу й високими скелями за ним.",sectionIndex=1}
c["subzone:tarren-mill"] = "1421a2"
P.scopedClips["subzone:tarren-mill"] = {scope="overview-body",sourceHash="94b1aa",hash="1421a2",name="Таррен Мілл",summary="Таррен Мілл — обложена застава Відступників у північній частині Передгір'я Гілсбреда, під Горами Альтерак. Колись мирне людське хліборобське село, тепер це головний оплот Орди в Гілсбреді, що постійно воює з містечком Альянсу Саутшор на півдні.",section="До Третьої війни Таррен Мілл був квітучим хліборобським містечком, вірним королівству Лордерон. Під час Другої війни він прославився, коли сили Альянсу визволили полонених лучників із високих ельфів із сусідніх орківських таборів, і це забезпечило Альянсові Лордерона повну підтримку Кель'Таласу. Проте сьогодні колишніх живих мешканців містечка вже немає — їхнє місце зайняли Відступники. Будівлі обвітрені й струхлявілі, поля порожні, а старий млин мовчить, поки нові мешканці-нежить укріплюють поселення від постійних загроз — гірських звірів, злочинців Синдикату й загонів Альянсу.",sectionIndex=1}
c["subzone:temple-gardens"] = "61cac9"
P.scopedClips["subzone:temple-gardens"] = {scope="overview-body",sourceHash="8c116c",hash="61cac9",name="Храмові Сади",summary="Храмові Сади — тихе, сповнене води серце Дарнасуса, що оточує невеликі острівці трохи на північ від Храму Місяця. Тут, серед мостів і бездоганної зелені, розташовані міський банк і чарівний портал-дерево, що веде до підніжжя Тельдрассила.",section="Храмові Сади розкинулися на водах у центрі Дарнасуса й слугують роздоріжжям столиці нічних ельфів. Дерев'яні мости з'єднують їхні доглянуті острівці з Ценаріонським Анклавом на півночі, гамірними терасами на сході та величним святилищем — Храмом Місяця — на півдні. Нічні ельфи дбайливо плекають плинні води й буйну зелень цього куточка, і тут панує спокій, що дарує відпочинок і мандрівникам, і жрицям.",sectionIndex=1}
c["subzone:temple-of-the-moon"] = "5b7152"
P.scopedClips["subzone:temple-of-the-moon"] = {scope="overview-body",sourceHash="97f665",hash="5b7152",name="Храм Місяця",summary="Храм Місяця в Дарнасусі — духовне серце нічних ельфів і осідок влади на Тельдрассилі. Святилище, яким опікується Верховна Жриця Тіранда Віспервінд, є головною оселею Сестринства Елуни. У його високих мармурових ярусах ховається священна місячний колодязь, чиї благословенні води зцілюють і єднають із Місячною Богинею.",section="Храм Місяця звели невдовзі після Третьої війни, коли нічні ельфи оселилися на Тельдрассилі. Це одна з найбільших кам'яних споруд, збудованих руками сучасних калдореїв. Більшість мармуру для нього видобули на материковому Калімдорі й переправили через море за допомогою магії. Посеред храму розлилася широка місячний колодязь під наглядом статуї Гайдене, і освячені води випромінюють тиху силу. Храм — не лише місце молитви й тихих роздумів для прочан, а й політична вершина Дарнасуса: тут перебуває Верховна Жриця Тіранда Віспервінд, що веде свій народ на порозі непевної нової доби.",sectionIndex=1}
c["subzone:the-den"] = "cdfdeb"
P.scopedClips["subzone:the-den"] = {scope="overview-body",sourceHash="9655c9",hash="cdfdeb",name="Лігво",summary="Лігво — захищена печера в серці Долини Випробувань на південному заході Дуротару. Головна опорна база для молодих шукачів пригод з орків і тролів, вона дає бойову та магічну підготовку, перш ніж вони вирушать у широкий світ.",section="Сховане в червоних стінах каньйону Долини Випробувань, Лігво служить суворим полігоном. У його висіченому в скелі сутінковому нутрі бійці, чаклуни й мисливці-новачки з'являються до ветеранів на кшталт Ґорнека та Зуріти Фарґейз. Саме тут пташенята отримують перші бойові настанови, припаси та початкові обряди посвяти, які гартують їх до суворої дійсності Дуротару й більших випробувань, що чекають на нову Орду.",sectionIndex=1}
c["subzone:the-loch"] = "0c68d2"
P.scopedClips["subzone:the-loch"] = {scope="overview-body",sourceHash="cc8c48",hash="0c68d2",name="Озеро",summary="Озеро — величезна прісна водойма, що панує в долині Лох Модан. Його стримує монументальна Каменетесна Гребля; це найбільша водойма Каз Модану й життєва сила довколишніх дворфійських поселень.",section="Озеро, що займає середину Лох Модану, — одне з найбільших внутрішніх озер відомого світу; змагатися з ним можуть хіба Озеро Лордамер і Озеро Дарроумер на півночі. Його води годують місцевих рибалок і правлять за мирне тло для містечка Телсамар і ближніх мисливських хуторів. Проте під спокійною поверхнею никають агресивні трешадони й прісноводні хижаки, тож перепливати його небезпечно.",sectionIndex=1}
c["subzone:thelsamar"] = "bdb635"
P.scopedClips["subzone:thelsamar"] = {scope="overview-body",sourceHash="99cdd0",hash="bdb635",name="Телсамар",summary="Телсамар — головне дворфійське поселення Лох Модану, що притулилося на західних кручах над великим озером. Розташоване на головній дорозі між Дун Мороґом і Багнокраєм, воно слугує гамірним осередком торгівлі, гостинності й громадської оборони від трогів і огрів, що наступають довкола.",section="Телсамар — головний оплот мирного дворфійського життя в долині. Збудований із традиційного для Каз Модану каменю й дерева, він має жваву Корчму «Міцний Лагер», сідало грифонів, ремісничі майстерні й чимало крамарів. Оскільки містечко стоїть просто на шляху, що з'єднує Прохід Південної Брами до Дун Мороґу з Перевалом Алґаз до Багнокраю, майже всі мандрівники краю проходять під його теплими вогнищами й міцними дахами.",sectionIndex=1}
c["subzone:thistlefur-hold"] = "a916cc"
P.scopedClips["subzone:thistlefur-hold"] = {scope="overview-body",sourceHash="c67191",hash="a916cc",name="Твердиня Будякохутрих",summary="Твердиня Будякохутрих — печерне лігво в північній частині Села Будякохутрих у західно-центральному Ашенвалі. Фурболги Будякохутрі, що живуть тут, колись були мирними ведмедями лісу, але піддалися скверні й нападають на кожного чужинця, який наближається.",section="Твердиня Будякохутрих, що ховається в північній частині Села Будякохутрих, — серце володінь племені. Тутешні фурболги збожеволіли, відколи до їхніх рук потрапив Ідол Ремулоса, і впали у звірячу лють, що робить їх небезпечними і для мандрівників, і для сусідів. Глибоко у звивистих печерах плем'я тримає награбовані реліквії — зокрема тролячі обереги, що цікавлять Темний Спис, — а також бранців у дерев'яних клітках, як-от ув'язненого тауренського воїна Руула Сноугуфа.",sectionIndex=1}
c["subzone:thistlefur-village"] = "12cad7"
P.scopedClips["subzone:thistlefur-village"] = {scope="overview-body",sourceHash="13bd48",hash="12cad7",name="Село Будякохутрих",summary="Село Будякохутрих — розлоге поселення в лісі на північ від Астранаару, у західно-центральному Ашенвалі. Це головна домівка племені фурболгів Будякохутрих, які стали жертвою темної скверни й люто нападають на кожного чужинця, що наближається до їхніх лігв.",section="Село Будякохутрих, що лежить трохи на північ від Астранаару — прихистку нічних ельфів, — колись було частиною мирних лісових громад, споконвічних для Ашенвалю. Проте зловісна скверна, що просочилася в прадавні ліси, цілком поглинула плем'я Будякохутрих. Тепер геть збожеволілі й украй ворожі фурболги люто стережуть стежки, що в'ються крізь їхнє поселення. Плем'я кориться двом надзвичайно лютим ватажкам — Далові Бладкло й Рорґішу Джаулу, чия невгамовна агресія становить постійну загрозу для мандрівників і ближніх поселень.",sectionIndex=1}
c["subzone:thistlefuzz-arcanery"] = "2cb1ae"
P.scopedClips["subzone:thistlefuzz-arcanery"] = {scope="overview-body",sourceHash="46eb6e",hash="2cb1ae",name="Чародійня Тіслфаз",summary="Чародійня Тіслфаз — відома майстерня й академія магічного мистецтва на схід від Великої Кузні в Айронфорджі. Її тримають переважно гноми, і це найкращий у столиці прихисток для зачаровувачів і вчених, що прагнуть вплітати магію в метал і пергамент. Її жваві покої гудуть чародійною енергією просто поруч із ревучими вогнями дворфійської промисловості.",section="Чародійня Тіслфаз, що тулиться одразу на схід від гуркітливої Великої Кузні, разюче контрастує з дзвоном ковадел дворфійських ковалів. На двох її поверхах збираються вчені, практики й учні, щоб опанувати тонкі дисципліни зачарування й магічних студій. Дворфи Айронфорджа воліють змінювати сталь м'язами й вогнем, а гноми Чародійні показують, як чисту чародійну енергію можна вплести просто у зброю, обладунки й дивовижні знаряддя. Це незамінний прихисток для заклиначів у гірській твердині.",sectionIndex=1}
c["subzone:thorn-hill"] = "23e6c5"
P.scopedClips["subzone:thorn-hill"] = {scope="overview-body",sourceHash="bed4c6",hash="23e6c5",name="Тернистий Пагорб",summary="Тернистий Пагорб — укріплений анклав шипогривів Гостроманів на високих кряжах на схід від Перехрестя в Пустках. Поселення слугує передовою базою для бойових загонів шипогривів, які нападають на шляхи постачання Орди між Дуротаром і нутрощами савани.",section="Тернистий Пагорб, що стоїть на північному схилі порізаних пагорбів між Дуротаром і Перехрестям, пильно оглядає головні торгові коридори Пусток. Тут зібралися небезпечні сили племені Гостроманів: мисливці, навчені вовки й геоманти, що підкоряють собі землю. Під проводом містиків на кшталт Старшого Містика Рейзорснаута тутешні шипогриви дедалі запекліше нападають на каравани Орди з припасами. Оскільки цей гірський табір стоїть так близько від важливих шляхів, вартові Перехрестя вважають Тернистий Пагорб однією з найнагальніших військових загроз у центральній савані.",sectionIndex=1}
c["subzone:three-corners"] = "9099a9"
P.scopedClips["subzone:three-corners"] = {scope="overview-body",sourceHash="76c9b0",hash="9099a9",name="Три Кути",summary="Три Кути — важливе роздоріжжя одразу за західним кордоном Гір Редріджу. Звідси дороги розходяться до трьох сусідніх містечок — Ґолдшира, Лейкшира й Даркшира, — і саме тут пролягає межа між серцем королівства та небезпечною дикою місцевістю Редріджу. Над перехрестям стоїть сторожова вежа Вартових Стормвінда, що стримує навалу зграй гнолів.",section="Розташовані на західному краю Гір Редріджу, Три Кути з'єднують три ключові поселення Альянсу: Ґолдшир у Лісі Елвінн на заході, Лейкшир на північному сході й Даркшир у Сутінколіссі на півдні. Через це стратегічне роздоріжжя Стормвінд звів посеред перехрестя Вартову Вежу. Місцеві вартові й розвідники, що несуть тут службу, намагаються очистити шляхи від агресивних гнолів Редріджу, які постійно загрожують мандрівникам і возам із припасами між краями.",sectionIndex=1}
c["subzone:thunder-falls"] = "6cd62a"
P.scopedClips["subzone:thunder-falls"] = {scope="overview-body",sourceHash="afdd16",hash="6cd62a",name="Громові водоспади",summary="Громові водоспади — відлюдна гірська ущелина, схована серед північно-західних височин Лісу Елвінн. Затиснута між прямовисними скелями й живлена ревучими каскадами, вона приховує тиху хатину над річкою, що потрапила до рук місцевих розбійників.",section="Сховані серед зубчастих хребтів над Дзеркальним Озером, Громові водоспади — незвичайна географічна розколина. Ущелину прорізає стрімкий гірський потік, що вливається через недоступний північний каскад, а потім обривається з обох боків видовищними водоспадами. З одного боку вода падає в Дзеркальне Озеро, а нижня течія тече на захід, до суворих кордонів Вестфолу. Попри ревучі води, на березі стоять невелика хатина, причал і кузня просто неба, та нині мирну галявину привласнили собі розбійники.",sectionIndex=1}
c["subzone:thunder-ridge"] = "0a8652"
P.scopedClips["subzone:thunder-ridge"] = {scope="overview-body",sourceHash="f1708a",hash="0a8652",name="Громовий Хребет",summary="Громовий Хребет — суворий каньйон на заході Дуротару, просто на південний захід від Оргріммара, на берегах Річки Південної Люті. Колись буйний гай прадавніх дерев, де паслися стада громових ящерів, каньйон зазнав жорстокого вирубування від людських лісорубів і темного чаклунства. Нині розлючені звірі та культисти, що лишилися, невпинно загрожують сусіднім поселенням.",section="Ще недавно Громовий Хребет був рідкісним зеленим прихистком у посушливому Дуротарі, який живили прадавні дерева. Його тиха рівновага розлетілася невдовзі після Третьої війни, коли людські зайди з Кул Тірасу почали рубати тутешній ліс, доводячи місцевих громових ящерів до шалу. Пізніше чаклунство Скверни в руках Палаючого Клинка довершило руйнування: воно здерло крони й лишило по собі голу, відкриту ущелину, де нині без упину блукають розлючені звірі, що плюються блискавками.",sectionIndex=1}
c["subzone:thunderbrew-distillery"] = "381c00"
P.scopedClips["subzone:thunderbrew-distillery"] = {scope="overview-body",sourceHash="2c9c8a",hash="381c00",name="Ґуральня Тандербрю",summary="Ґуральня Тандербрю — гамірна корчма й головне місце зустрічей у Хараносі в Дун Мороґу. Славетна на всі усюди своїми міцними елями, вона водночас є діючою пивоварнею і необхідним місцем перепочинку для мандрівників, що долають засніжені гірські перевали. Усередині гостей чекають тепле вогнище, холодні кухлі та чимало наставників класів і місцевих ремісників.",section="Ґуральня Тандербрю в самому центрі Хараноса — серце громадського життя південного Дун Мороґу. Заснована кланом Тандербрю — його започаткував Аркілус Тандербрю, а підтримують його нащадки — пивоварня славиться на весь Каз Модан міцними зігрівними елями, звареними, щоб проганяти пронизливий гірський холод. Вона працює як місцева корчма, якою в залі порядкує Шинкар Белм, пропонуючи втомленим горянам ревучий вогонь, ситну страву та ліжко, щоб перечекати хуртовину.",sectionIndex=1}
c["subzone:thunderhorn-water-well"] = "9b862e"
P.scopedClips["subzone:thunderhorn-water-well"] = {scope="overview-body",sourceHash="6ebddf",hash="9b862e",name="Водяна Криниця Тандергорнів",summary="Водяна Криниця Тандергорнів — життєво важливе джерело води на хвилястих рівнинах центрального Малгору, на шляху між Селом Бладгуф і Тандер Блафом. Як і всі криниці долини, вона живить племена та стада, що бродять пасовищами. Берегти цю воду чистою й захищеною конче потрібно, щоб підтримувати життя на батьківщині тауренів.",section="Водяна Криниця Тандергорнів серед розлогих пасовищ центрального Малгору сягає просто в чисті водоносні шари, що живлять долину. Для кочових тауренів та їхніх новозаснованих сіл такі спільні криниці означають життя, поживу й щедрість Земної Матері. Вода на випалених сонцем рівнинах дорогоцінна, тож хто володіє криницями — той володіє самою землею. Зайди на кшталт Венчурної Компанії не раз накидали оком на ці джерела, намагаючись прибрати їх до рук задля промислового визиску й зруйнувати крихку рівновагу, за яку борються племена.",sectionIndex=1}
c["subzone:tidus-stair"] = "43e02e"
P.scopedClips["subzone:tidus-stair"] = {scope="overview-body",sourceHash="8ac84d",hash="43e02e",name="Сходи Тідуса",summary="Сходи Тідуса — природне скельне утворення з широких кам'яних терас-сходинок над Узбережжям Крамарів, на південний схід від Раджета. Сховане біля Великого Моря, воно стало тихим прихистком для двох тауренів-шаманів, що єднаються з припливами й духами води.",section="Сходи Тідуса, що спускаються до прибою на південний схід від Раджета, нагадують величезні обвітрені кам'яні сходинки, вирубані просто в прибережних кручах. Довколишні Пустки посушливі, курні й неспокійні, а на цій тихій ділянці над Узбережжям Крамарів панує шум хвиль. На терасах стоїть скромна хатина, де живуть таурени Іслен Вотерсір і Магрен Скайсір. Далеко від гамірних торгових доків гоблінів вони проводять дні за риболовлею, спостерігають за обрієм і шукають прозріння в прибережних духів води.",sectionIndex=1}
c["subzone:tinker-town"] = "697d0c"
P.scopedClips["subzone:tinker-town"] = {scope="overview-body",sourceHash="6dbba0",hash="697d0c",name="Містечко Майстрів",summary="Містечко Майстрів — гамірний гномський квартал у підземному дворфійському місті Айронфорджі. Заснований як прихисток для біженців після трагічного падіння Гномреґана, він став осідком уряду у вигнанні на чолі з Великим Тінкером Ґелбіном Меккаторком і головною кінцевою станцією Глибинного трамвая.",section="Коли підземні троги захопили високотехнологічне місто Гномреґан, дворфи Айронфорджа відчинили браму тим, хто вцілів. Щоб прихистити раптовий наплив біженців, їм віддали печерний район, де раніше жили дворфи й був вхід до Глибинного трамвая. Під пильним оком Великого Тінкера Ґелбіна Меккаторка та його ради Містечко Майстрів швидко перетворилося на жвавий осередок дзижчання шестерень, експериментальної алхімії й хитромудрих пристроїв. Хоч гноми й живуть тут тісно, як гості в кам'яному місті, вони відтворили подобу своєї цивілізації довкола величезного кулястого механізму й сповнені рішучості повернути свою підземну батьківщину.",sectionIndex=1}
c["subzone:tinkers-court"] = "6c8a39"
P.scopedClips["subzone:tinkers-court"] = {scope="overview-body",sourceHash="efed04",hash="6c8a39",name="Двір Майстрів",summary="Двір Майстрів — велика зала ради в самому серці Гномреґана. Колись гамірний осідок Великого Тінкера та його правлячої ради, тепер це похмура твердиня зрадника — Мехінженера Термаплаґа.",section="До катастрофи, що зруйнувала Гномреґан, Двір Майстрів був громадським і політичним серцем народу. Саме тут Великий Тінкер Ґелбін Меккаторк збирав радників і майстрів-винахідників, серед них Тінкмайстра Оверспарка, щоб обговорювати технічні досягнення, вирішувати громадські справи й спрямовувати гномське суспільство. Двір уособлював вершину гномської винахідливості й врядування і лежав одразу за промисловими цехами Інженерних Лабораторій і Стартового відсіку.",sectionIndex=1}
c["subzone:tiragarde-keep"] = "b167eb"
P.scopedClips["subzone:tiragarde-keep"] = {scope="overview-body",sourceHash="20de16",hash="b167eb",name="Фортеця Тіраґард",summary="Фортеця Тіраґард — укріплена людська твердиня на Дріботливому Узбережжі Дуротару, на південь від Гострого Пагорба. Збудована під час вторгнення Великого Адмірала Дейліна Праудмура, зруйнована цитадель досі утримується ворожою кул-тіраською морською піхотою під проводом Лейтенанта Бенедикта. Це зухвала, невиправна скалка в боці Орди просто на її рідній землі.",section="Зведена під час походу Великого Адмірала Дейліна Праудмура на знищення щойно заснованого королівства Тралла, Фортеця Тіраґард дала флоту Кул Тірасу укріплений плацдарм на червоних берегах Дуротару. Хоч Орда зрештою прорвала облогу й убила Праудмура на Острові Терамор, фортецю так і не покинули повністю. Війська постачання під проводом Лейтенанта Бенедикта знову зайняли розтрощені кам'яні стіни, виконуючи незмінний наказ покійного Адмірала вести з орками безкомпромісну війну й цілком відкидаючи мир, укладений Леді Джайною Праудмур.",sectionIndex=1}
c["subzone:tower-of-althalaxx"] = "3b6a56"
P.scopedClips["subzone:tower-of-althalaxx"] = {scope="overview-body",sourceHash="28e01d",hash="3b6a56",name="Вежа Альталакса",summary="Вежа Альталакса — давній шпиль Високородних на півночі Темного Узбережжя, неподалік від берега. До Великого Розколу це був відлюдний прихисток чаклуна Атрікуса Нарассіна, а тепер його заполонили демонічні культисти й чорнокнижники, що практикують темні мистецтва.",section="Десять тисяч років тому королева Азшара оселила улюблених слуг із Високородних у приморських містах Амет'Аран і Башал'Аран і поставила над ними могутнього чаклуна Атрікуса Нарассіна. Віддаляючись від міських справ, Атрікус вирішив усамітнитися в сусідній Вежі Альталакса. Коли Великий Розкол зруйнував давній Калімдор, вежа встояла на пустельному березі Темного Узбережжя — тихі руїни забутої ельфійської магії.",sectionIndex=1}
c["subzone:tower-of-azora"] = "dbc5e9"
P.scopedClips["subzone:tower-of-azora"] = {scope="overview-body",sourceHash="4367dd",hash="dbc5e9",name="Вежа Азори",summary="Вежа Азори — струнка чародійська вежа, що здіймається на сході Лісу Елвінн, на північ від Гарбузової Ділянки Брекуеллів. Під проводом Архімага Теокрітуса з людей цей анклав служить ученою заставою, втягнутою в мовчазну магічну ворожнечу з ворожою вежею в сусідніх Горах Редріджу.",section="Вежа Азори при східній дорозі до Гір Редріджу — таємне святилище, яке майже цілком обслуговують чаклуни-гноми. Під опікою Архімага Теокрітуса ці вчені вивчають дивні дивовижі й дають магічні настанови мандрівним чаклунам. Дика магічна аура довкола шпиля часом викривлює навколишню звірину, тож слугам-гномам доводиться давати раду зачарованому хатньому начинню та мутованим комахам, що повзуть повз двері.",sectionIndex=1}
c["subzone:tower-of-ilgalar"] = "ddd9d3"
P.scopedClips["subzone:tower-of-ilgalar"] = {scope="overview-body",sourceHash="c6bb30",hash="ddd9d3",name="Вежа Ілґалара",summary="Вежа Ілґалара — відлюдний шпиль високо в кручах східних Гір Редріджу. Колись прихисток чарівника, тепер вона поринула в тінь як схованка Морґанта — вигнаного зі Стормвінда чаклуна, що командує дикими гнолами краю й практикує темну магію.",section="Вежа Ілґалара, що нависає над східним Редріджем, — особисте святилище Морґанта. Вигнаний із Кварталу магів Стормвінда за захоплення забороненою магією, чаклун-ренегат сховався на цих суворих висотах, щоб глибше пірнути в темні мистецтва без втручання влади. Замість жити самітником, Морґант підкорив собі місцевий клан гнолів Тіньової Шкури і поставив їх лютими вартовими довкола підніжжя шпиля. Усередині вежа кишить викликаними демонічними гончаками й тріщить тіньовою силою — постійна похмура загроза для обложеного Лейкшира внизу.",sectionIndex=1}
c["subzone:trade-district"] = "8629dc"
P.scopedClips["subzone:trade-district"] = {scope="overview-body",sourceHash="4ffa3b",hash="8629dc",name="Торговий Квартал",summary="Торговий Квартал — гамірне торговельне серце Стормвінда, що лежить одразу за головною брамою й Долиною Героїв. Це головний осередок і для шукачів пригод, і для містян: тут міський банк, аукціонний дім, реєстр гільдій і різноманітні крамниці.",section="Пройшовши під кам'яними арками з Долини Героїв, мандрівники потрапляють просто в Торговий Квартал. Ця жвава відкрита площа — головний ринок і логістичний вузол Стормвінда. У її центрі стоїть Аукціонний дім, а неподалік — Скарбниця Стормвінда, головний банк міста, і популярна таверна «Позолочена Троянда». Квартал пов'язує воєнний анклав Старого Міста, тиху Соборну Площу й чародійні вулиці Кварталу магів, тож монети, сировина й спорядження для пригод швидко обертаються королівством.",sectionIndex=1}
c["subzone:trade-quarter"] = "c47bdc"
P.scopedClips["subzone:trade-quarter"] = {scope="overview-body",sourceHash="a747aa",hash="c47bdc",name="Торговий Квартал",summary="Торговий Квартал — центральне осердя Андерсіті, що лежить просто під підйомниками з Руїн Лордерона. Це живе економічне серце Відступників: тут головні банківські сховища, аукціонний ринок і найважливіші міські служби. Від цього кільцевого вузла склепінчасті коридори розходяться до навколишніх кварталів.",section="Спустившись із розтрощеної поверхні Лордерона, мандрівники сходять із підйомників у відлунний кам'яний простір Торгового Кварталу. Квартал має ярусне кругле планування: на центральному майданчику — міська скарбниця й центральний банк, обрамлені мостами над отруйними стічними каналами. На навколишніх терасах гудуть торговці, гільдійні реєстратори й аукціоністи, що торгуються в моторошному присмерку. Навіть найпростіший нічліг тут сповнений прагматизму Відступників: місцева корчма пропонує не м'які ліжка, а дерев'яні труни без оббивки. Від цього центрального вузла кам'яні арки ведуть до спеціалізованих кварталів міста, тож саме тут неминуче перетинаються всі справи столиці.",sectionIndex=1}
c["subzone:tradesmen-s-terrace"] = "6b2713"
P.scopedClips["subzone:tradesmen-s-terrace"] = {scope="overview-body",sourceHash="7106ca",hash="6b2713",name="Тераса Ремісників",summary="Південна Тераса Ремісників — гамірне торговельне серце Дарнасуса, що розкинулося вздовж південного краю міста. Під розлогими дерев'яними склепіннями столиці нічних ельфів тут зібралися майстри, купці й місцевий аукціонний дім. Тераса — головна торгова ланка, що пов'язує ремісників із шукачами пригод, які мандрують Тельдрассилом і далеко за його межами.",section="Південна Тераса Ремісників займає південну частину Дарнасуса й зосереджує в собі все торговельне життя столиці. Більша частина міста віддана тихому спогляданню, диким святилищам і духовним обов'язкам, а тут збираються крамарі, ремісники й купці, що обслуговують і місцевих калдореїв, і мандрівників з усього Альянсу. Тут є головний аукціонний дім Дарнасуса, крамниці з припасами й товарами для ремесел — тож саме тут збираються в дорогу ті, хто вирушає в дикі краї. Широкі стежки ведуть звідси на північ, просто до Тераси Воїна, і на захід — до спокійних вод Храмових Садів і величного Храму Місяця.",sectionIndex=1}
c["subzone:train-depot"] = "1901d5"
P.scopedClips["subzone:train-depot"] = {scope="overview-body",sourceHash="bb6ce1",hash="1901d5",name="Депо потяга",summary="Депо потяга — підземний транспортний вузол одразу під наземними входами до Гномреґана в Дун Мороґу. Колись гамірний осередок гномського залізничного руху, тепер воно кишить ворожими гномами-прокаженими й трогами-загарбниками.",section="Депо потяга, що лежить біля підніжжя великого підйомника з Дун Мороґу, колись було головним вузлом залізничного сполучення в підземному диві Гномреґана. Сьогодні платформи й колії лежать у руїнах. Викиди, що опромінили місто, перетворили робітників, які лишилися, на шалених гномів-прокажених, а підземні троги заполонили колії. Дослідники, що спускаються до зруйнованого міста, мусять пройти цей плацдарм, щоб дістатися глибших секторів, як-от Годинникового Ходу, Вантажної Кімнати й внутрішніх інженерних цехів.",sectionIndex=1}
c["subzone:tranquil-gardens-cemetery"] = "79200b"
P.scopedClips["subzone:tranquil-gardens-cemetery"] = {scope="overview-body",sourceHash="debb41",hash="79200b",name="Цвинтар Тихих Садів",summary="Цвинтар Тихих Садів лежить трохи на південний схід від Даркшира в Сутінколіссі. Попри мирну назву, тут кишать шкандибаючі скелети й гулі, і колишнє місце поховань стало безпосередньою загрозою для сусіднього міста.",section="Колись тихий спочинок для покійних мешканців Великого Селища, Цвинтар Тихих Садів тепер аж ніяк не спокійний. Коли над Сутінколіссям запанували темні прокляття, поховані тут мерці почали вигрібатися з могил. Скелети-воїни, скелети-маги й блукаюча нежить, що населяють ці надгробки, порівняно слабкі проти жахів, що чаяться глибше в лісі, але через близькість до Даркшира вони становлять для містян невпинну загрозу.",sectionIndex=1}
c["subzone:tundrid-hills"] = "57c7f7"
P.scopedClips["subzone:tundrid-hills"] = {scope="overview-body",sourceHash="b66bd2",hash="57c7f7",name="Тундридські Пагорби",summary="Тундридські Пагорби — суворий засніжений відтинок високогір'я в південно-центральному Дун Мороґу, просто на захід від Кар'єру Гол'Болар. Скелясті перевали, де водиться небезпечна гірська звірина, випадкові мандрівники перетинають нечасто.",section="Простягшись між Долиною Холодного Хребта та низинами східного Дун Мороґу, Тундридські Пагорби пропонують суворий шлях навпростець тим, хто хоче оминути головні дороги через Харанос. Та за зручність доводиться дорого платити. Зубчастими засніженими схилами нишпорять люті хижаки, тож ці землі небезпечні для необачних мандрівників, які сходять з уторованої стежки, не оголивши зброї.",sectionIndex=1}
c["subzone:twilight-grove"] = "4effed"
P.scopedClips["subzone:twilight-grove"] = {scope="overview-body",sourceHash="5548d3",hash="4effed",name="Сутінковий Гай",summary="Захований у самому центрі Сутінколісся, Сутінковий Гай — дивовижний куточок пишної калімдорської рослинності, що разюче контрастує з похмурим, сплюндрованим лісом довкола. Під височенним великим деревом, серед давньої архітектури нічних ельфів, тут є місячний колодязь і величезна смарагдова брама, що веде просто до Смарагдового Сну.",section="Захований за крутими схилами кратера в серці Сутінколісся, Сутінковий Гай здається в Східних Королівствах чимось геть чужорідним. Давні альтанки нічних ельфів, яскраво-зелені луки й тихий місячний колодязь оточують безіменне велике дерево, що височіє над похмурими кронами. Тисячоліття тому архідруїд Фандрал Стаґгелм і його коло посадили тут зачаровану гілку Нордрассілу, щоб очистити отруйну скверну, що піднімалася з глибин землі. Дерево прижилося як провідник природи: воно пропускає первісну силу Смарагдового Сну у світ яви, і цей кратер квітне навіть під вічним мороком Сутінколісся.",sectionIndex=1}
c["subzone:twilight-shore-darkshore"] = "f547ce"
P.scopedClips["subzone:twilight-shore-darkshore"] = {scope="overview-body",sourceHash="5a660b",hash="f547ce",name="Сутінковий Берег (Темне Узбережжя)",summary="Сутінковий Берег — порізана смуга узбережжя на півдні Темного Узбережжя, що тягнеться на південь від Довгої Обмілини аж до кордону з Ашенвалем. Його похмурі, оповиті туманом пляжі перериваються стрімкими морськими кручами, острівцями й підступним прибоєм. Тут кишать агресивні племена мурлоків і ненажерливі морські хижаки на кшталт трешадонів.",section="Сутінковий Берег, що тягнеться на південь від Довгої Обмілини, повз руїни Амет'Арану, до Ашенвалю, — одна з найсуворіших і найнегостинніших ділянок Темного Узбережжя. Сірий пісок поступається гострим, побитим хвилями кручам і розкиданим скелястим острівцям. Тутешні води славляться ворожістю: той, хто попливе біля берега, наразиться на напади ревнивих трешадонів і морських повзунів, а на самих пляжах панують численні табори агресивних мурлоків.",sectionIndex=1}
c["subzone:twilight-vale"] = "617c96"
P.scopedClips["subzone:twilight-vale"] = {scope="overview-body",sourceHash="36040f",hash="617c96",name="Сутінкова Долина",summary="Сутінкова Долина охоплює густі, затінені південні ліси Темного Узбережжя, що тягнуться до кордону з Ашенвалем. У її мороці никають осквернені фурболги, скажені ведмеді й люті нічні шаблезуби, тож сходити з дороги тут небезпечно. Це похмурий поріг між отруєним узбережжям і священними лісами на півдні.",section="Сутінкова Долина, що простягається від давніх руїн Амет'Арану аж до кордону з Ашенвалем, огортає південь Темного Узбережжя вічними сутінками. Скверна, що охоплює північний Калімдор, глибоко вгризлася в місцевих звірів. Скажені ведмеді блукають поряд з дикими нічними шаблезубами, а темним лісом никають ворожі племена фурболгів. І вартові, і мандрівники радять триматися головної дороги: варто ступити між дерева бодай на кілька кроків — і чекай швидкої смертельної засідки.",sectionIndex=1}
c["subzone:valgan-s-field"] = "19a4fd"
P.scopedClips["subzone:valgan-s-field"] = {scope="overview-body",sourceHash="44c061",hash="19a4fd",name="Поле Валґана",summary="Поле Валґана — покинута пшенична ферма на півночі Срібнолісся з видом на Озеро Лордамер. Колись мальовнича садиба, тепер вона спустіла, і її заполонили дикі воргени-Мунрейджі, яких випустив Архімаг Аруґал.",section="Поле Валґана, що лежить трохи на захід від Осяйного Узмор'я й на північ від ближньої річки, колись було заможною пшеничною фермою з чудовим видом на Озеро Лордамер. Те мирне життя зникло, коли Погибель прокотилася Лордероном і змусила господаря, Валґана, тікати — або загинути. Без догляду зруйновані будівлі потрапили в пазурі диких воргенів-Мунрейджів, що спускаються з Фортеці Шадовфенг. Ще до Третьої війни тут якийсь час жив маг Аруґал, і рештки його таємних досліджень тепер привертають увагу Відступників.",sectionIndex=1}
c["subzone:valley-of-heroes"] = "056f16"
P.scopedClips["subzone:valley-of-heroes"] = {scope="overview-body",sourceHash="d6b6d8",hash="056f16",name="Долина Героїв",summary="Долина Героїв — монументальний південний в'їзд до Стормвінда, що веде мандрівників кам'яним мостом через рів. Обабіч височіють статуї на честь провідників Експедиції Альянсу до Дренору, і долина водночас вражає гостей і служить добре укріпленим контрольним пунктом.",section="Статуї вздовж мосту, зведені під час великої відбудови Стормвінда після Другої війни, вшановують командирів Експедиції Альянсу. Ці поборники пройшли крізь Темний Портал на Дренор, рідний світ орків, щоб назавжди запечатати розлам, і віддали життя, аби Азерот вижив. Мандрівники, що прямують на північ до Торгового Кварталу, проходять під ликами Архімага Хадґара, Курдрана Вайлдгаммера, Рейнджер-капітана Аллерії Віндраннер, Командувача Сил Даната Троллбейна й Верховного Генерала Туральйона.",sectionIndex=1}
c["subzone:valley-of-honor"] = "0e1433"
P.scopedClips["subzone:valley-of-honor"] = {scope="overview-body",sourceHash="c6cb80",hash="0e1433",name="Долина Честі",summary="Долина Честі — бойове осердя й квартал воїнів Оргріммара, що ховається в північно-східних каньйонах столиці. Тут розташовані міські казарми, гільдії воїнів і мисливців та розпорядники битв, що скеровують сили Орди по всьому Азероту. Серед гарячих кузень, тренувальних кіл і тихих вод Орда гартує свою силу й пам'ятає свою бойову спадщину.",section="Долина Честі, захована за високими гребенями каньйону, — головний військовий квартал Оргріммара. Тут повсякдення визначають брязкіт тренувальної зброї й дзвін ковальських ковадел. Над долиною панує Зала Хоробрих — місце збору бувалих воїнів і розпорядників битв, що координують походи на таких фронтах, як Долина Альтерак та Ущелина Бойової Пісні. Поруч розташовані вишкільні місця для приборкувачів звірів і мисливців, тож район цілком присвячений спорядженню, муштрі й мобілізації захисників передової Орди.",sectionIndex=1}
c["subzone:valley-of-kings"] = "260602"
P.scopedClips["subzone:valley-of-kings"] = {scope="overview-body",sourceHash="8a1c8c",hash="260602",name="Долина Королів",summary="Долина Королів — пишний каньйон у південно-західному куточку Лох Модану, просто на південь від проходу до Дун Мороґу. Це пильно охоронювана брама до вогняної Палючої Ущелини, обабіч якої стоять монументальні кам'яні постаті, висічені на згадку про Війну Трьох Молотів. Мандрівники тут ступають під давньою дворфійською історією, водночас наражаючись на загрозу від загарбників Блекрок і трогів.",section="Найвеличніша окраса долини — дві колосальні статуї, що зображують короля Мадорана Бронзбірда й Верховного Тана Кардроса Вайлдгаммера. Висічені на спільне замовлення їхніх синів після смерті обох, ці кам'яні велетні дивляться на перевал до випалених південних земель. Вони стоять як тривкий пам'ятник спільній перемозі у Війні Трьох Молотів і вічне застереження кланові Темного Заліза, нагадуючи кожному, хто дивиться на південь, про руїну, яку накликав на Гори Редріджу виклик Рагнароса.",sectionIndex=1}
c["subzone:valley-of-spirits"] = "b6af79"
P.scopedClips["subzone:valley-of-spirits"] = {scope="overview-body",sourceHash="b38eda",hash="b6af79",name="Долина Духів",summary="Долина Духів, що тулиться до західних скель Оргріммара, — давній осідок племені Темного Списа в столиці Орди. Повна хатин під стріхою, тотемних стовпів-тікі й спокійних озерець, вона разюче відрізняється від навколишнього червоного каменю й закутої в залізо орочої архітектури.",section="Долина Духів відгалужується на захід від гамірної Долини Сили — це пишний і тихий анклав, відданий тролям Темного Списа. Коли плем'я оселилося в Дуротарі разом з орками Тралла, ця спокійна кишеня серед скель стала їхнім міським місцем збору. Тролячі ремісники, духовидці й чаклуни збираються біля дерев'яних містків і звивистих потічків, займаючись своїми мистецтвами подалі від сухої спеки головних вулиць.",sectionIndex=1}
c["subzone:valley-of-strength"] = "6af249"
P.scopedClips["subzone:valley-of-strength"] = {scope="overview-body",sourceHash="ce72c4",hash="6af249",name="Долина Сили",summary="Долина Сили — гамірна центральна площа Оргріммара, що зустрічає кожного, хто минає височенну головну браму міста. Тут розташовані міський банк, центральний аукціонний дім і корчма «Зламане Ікло», тож долина — живе торговельне й адміністративне серце столиці Орди.",section="Ступіть за укріплену дерев'яну браму Оргріммара — і ви в Долині Сили. Висічена глибоко в червоній скелі каньйонів Дуротару, ця долина — головний майдан Орди. Шукачі пригод, купці й воїни з усіх союзних народів сходяться на її курявих площах: діляться бойовими історіями за кухлем у корчмі «Зламане Ікло» чи полагоджують важливі торгові справи в центральному банку й на аукціоні. Це гамірне свідчення сили та єдності, які орки виборювали на своїй новій батьківщині.",sectionIndex=1}
c["subzone:valley-of-trials"] = "24f1a7"
P.scopedClips["subzone:valley-of-trials"] = {scope="overview-body",sourceHash="4622dc",hash="24f1a7",name="Долина Випробувань",summary="Схована за суворими червоними скелями південного Дуротару, Долина Випробувань служить полігоном для нових новобранців Орди. Молоді орки та їхні союзники — тролі Темного Списа — приходять сюди довести свою силу й заслужити місце серед воїнів Калімдору. Ті, хто переживе сувору звірину й приховані загрози долини, виходять готовими боронити свою молоду державу.",section="Долина Випробувань створена, щоб відсіяти слабких, перш ніж ті ступлять у ширші простори Дуротару. Під наглядом вождів і наставників, що стоять у висіченому в скелі прихистку, відомому як Лігво, молодих бійців кидають у випалену сонцем балку полювати на скорпідів, винищувати войовничих вепрів і наводити лад серед ледачих робітників, що заготовляють скупий ліс. Випробування безкомпромісне: хто доведе свою вправність, здобуває право вирушити далі справжнім солдатом Орди, а хто зазнає невдачі — лишається біліти під пустельним сонцем.",sectionIndex=1}
c["subzone:valley-of-trials#faq1"] = "4cc49c"
P.scopedClips["subzone:valley-of-trials#faq1"] = {scope="answer-only",sourceHash="acbcba",hash="4cc49c",name="Долина Випробувань",question="Яке призначення Долини Випробувань?",answer="Це традиційний полігон для новобранців Орди — насамперед молодих орків і тролів Темного Списа. У її захищених каньйонах нові шукачі пригод виконують суворі завдання, щоб показати бойову вправність, інстинкт виживання та вірність, перш ніж їм дозволять вирушити в решту Дуротару."}
c["subzone:valley-of-trials#faq2"] = "d5a3d9"
P.scopedClips["subzone:valley-of-trials#faq2"] = {scope="answer-only",sourceHash="c722ec",hash="d5a3d9",name="Долина Випробувань",question="Що таке Лігво?",answer="Лігво — печера, висічена в скелях приблизно посередині долини. У ній розташувалися наставники класів, торговці та наглядачі на кшталт Ґорнека, які скеровують новобранців, споряджають їх і стежать за їхніми успіхами під час перших випробувань."}
c["subzone:valley-of-trials#faq3"] = "17b492"
P.scopedClips["subzone:valley-of-trials#faq3"] = {scope="answer-only",sourceHash="d24bb0",hash="17b492",name="Долина Випробувань",question="Чому на тренувальному майданчику для новачків є демони?",answer="Культисти Палаючого Клинка влаштували таємний ковен у північних печерах. Хоч наставники й використовують їхніх слабких фамільярів, щоб випробовувати новобранців, присутність культу натякає, що потаємні сили на кшталт Ради Тіней шукають опори просто на порозі Дуротару."}
c["subzone:valley-of-trials#faq4"] = "8cbfb0"
P.scopedClips["subzone:valley-of-trials#faq4"] = {scope="answer-only",sourceHash="809191",hash="8cbfb0",name="Долина Випробувань",question="Хто такий Саркот?",answer="Саркот — незвично великий отруйний скорпід, що живе на скелястих висотах долини. Через його лють і смертоносність наставники доручають перспективним новобранцям уполювати його, щоб перевірити їхню відвагу, і принести на доказ його понівечену клешню."}
c["subzone:vault-of-ironforge"] = "4a4c26"
P.scopedClips["subzone:vault-of-ironforge"] = {scope="overview-body",sourceHash="26a6db",hash="4a4c26",name="Сховище Айронфорджа",summary="Сховище Айронфорджа — головний банк і скарбниця дворфійської столиці. Воно розташоване в гамірних Торгових Рядах, просто навпроти аукціонного дому, і тут городяни й мандрівники з усього Альянсу надійно зберігають свої статки. Роботою Сховища опікуються Дініта й шанована родина Стоунмантлів.",section="Висічене глибоко в гірській скелі Торгових Рядів, Сховище Айронфорджа — символ дворфійської фінансової надійності й майстерності. Торгівля в місті квітне, тож мандрівники, вояки й купці щодня приходять сюди, щоб покласти на зберігання монети, реліквії й припаси під пильним оком міської варти й касирів. Під наглядом Дініти й надійної родини Стоунмантлів ця установа дарує клієнтам з Альянсу цілковитий спокій.",sectionIndex=1}
c["subzone:venomweb-vale"] = "35040b"
P.scopedClips["subzone:venomweb-vale"] = {scope="overview-body",sourceHash="2b573d",hash="35040b",name="Долина Отруйного Павутиння",summary="Долина Отруйного Павутиння — тіниста долина у східних Галявинах Тірісфалю, одразу на південь від Багряного Монастиря. Колись пишний ліс, повний дичини, долина виродилася в уражене чумою гніздо, яке заполонили агресивні отруйні павуки. Невідомо більшості перехожих, вона зберігає й давню спадщину — як священне місце зібрань Ради Тірісфалю.",section="Перш ніж чума поглинула Лордерон, ця долина була мирним куточком соковитої трави й зелених дерев, який любили місцеві мисливці, що вистежували оленів і кроликів. Сьогодні в краєвиді панують гниль і повзучий морок. Велетенські отруйні павуки кишать серед дерев і улоговин на чолі зі страхітливим павуком Срі'скалком. Північний край долини межує із землями Багряного Хрестового Походу, де темні гончаки нишпорять біля укріпленого Багряного Табору під командуванням Лейтенанта Сандерса.",sectionIndex=1}
c["subzone:venture-co-mine"] = "363f37"
P.scopedClips["subzone:venture-co-mine"] = {scope="overview-body",sourceHash="fadc91",hash="363f37",name="Шахта Венчурної Компанії",summary="Шахта Венчурної Компанії, схована у східних кручах Малгору, — самовільна промислова копальня, якою заправляють жадібні гоблінські пройдисвіти. Хоч таурени відмовили їм у праві на видобуток, Венчурна Компанія все одно вгризлася в пагорби, загрожуючи природній рівновазі рівнин.",section="Коли Венчурна Компанія попросила права вигрібати з Малгору корисні копалини, таурени навідріз відмовили. Корпоративний картель знехтував ними й усе одно прорив тунелі глибоко в східну гірську стіну під орудою Наглядача Фіззпрокета. Розлогий комплекс має три входи: наземний тунель під охороною найманих горлорізів, стрімкий оглядовий виступ на скелі та верхній прохід до невеликої лісозаготівлі. Машини, дим і купи шлаку, що насуваються на край, — відверте осквернення священної землі.",sectionIndex=1}
c["subzone:vul-gol-ogre-mound"] = "6abf21"
P.scopedClips["subzone:vul-gol-ogre-mound"] = {scope="overview-body",sourceHash="551fc8",hash="6abf21",name="Огрський Курган Вул'Ґол",summary="Огрський Курган Вул'Ґол — улоговина на півдні Сутінколісся, яку захопили огри Скалкокулаків на чолі з громилою Ззарк'Вулом. Колись тут стояли людські садиби, а тепер зруйновані хати й підземна печера завалені тушами та награбованим добром клану.",section="Захований у тіні на південний захід від роздоріжжя, звідки дорога веде до Долини Стренглторну, Огрський Курган Вул'Ґол — осідок клану Скалкокулаків в Сутінколіссі. Колись улоговина була мирними нивами, але її мешканці давно втекли або загинули, лишивши по собі порожні хатини, які тепер захопили незграбні огри й облаштували собі грубі сховища. У печері під пагорбом купи вбитих чорних ведмедів свідчать про ненажерливий апетит клану. Ватажок Ззарк'Вул панує над табором і збирає дивні дрібнички поряд із буденним награбованим скарбом.",sectionIndex=1}
c["subzone:war-quarter"] = "8dc0b4"
P.scopedClips["subzone:war-quarter"] = {scope="overview-body",sourceHash="d747ae",hash="8dc0b4",name="Воєнний Квартал",summary="Воєнний Квартал — північно-західний район Андерсіті, командний пункт і бойовий вишкільний осередок Відступників. У його відлунних кам'яних залах вояки, жерці й ремісники Лордерона відточують зброю й тіньову магію, захищаючи своє молоде королівство. Тут розташовані зали навчання воїнів і жерців, майстри зброї й важке виробництво.",section="Воєнний Квартал займає північно-західну частину підземного міста й слугує оплотом бойової сили Відступників. Під його похмурими кам'яними арками рядові вартові й добірні поборники збираються, щоб вправлятися в збройному бою. На відміну від звичних казарм у королівствах живих, цей військовий осередок поєднує безжальну залізну війну з моторошними обрядами тіні: тут стоїть зловісний Вівтар Темряви, де духовна дисципліна зливається з військовими прагненнями.",sectionIndex=1}
c["subzone:war-room"] = "70d6d6"
P.scopedClips["subzone:war-room"] = {scope="overview-body",sourceHash="aa965e",hash="70d6d6",name="Воєнна Кімната",summary="Захована глибоко у Фортеці Стормвінда, Воєнна Кімната — стратегічний нервовий центр війська Альянсу. Оточена зброєю, історичними воєнними фоліантами й тактичними мапами, вона служить місцем, де генерали й стратеги стежать за далекими фронтами й координують оборону королівства.",section="Відгалужуючись від величних покоїв Фортеці Стормвінда, Воєнна Кімната облаштована саме для воєнної логістики й планування походів на найвищому рівні. Її кам'яні стіни прикрашають ряди зброї — мечі, мушкетони й навіть важкі гармати. На столах поруч складено купи воєнних трактатів та історичних хронік — як-от розповіді про Другу війну, Падіння Стормвінда й Битву за Ґрім Батол. У центрі кімнати стоїть великий стіл із тактичною мапою, за яким командувачі оцінюють розташування сил Альянсу по всьому Азероту, поки королівський двір вирішує державні справи за кілька кроків звідси.",sectionIndex=1}
c["subzone:warrior-s-terrace"] = "3f8d76"
P.scopedClips["subzone:warrior-s-terrace"] = {scope="overview-body",sourceHash="3e22cb",hash="3f8d76",name="Тераса Воїна",summary="Тераса Воїна — східний район Дарнасуса, водночас бойовий вишкільний осередок і укріплена брама столиці. Вона височіє над дорогою вглиб Тельдрассила, і тут розташовані міські розпорядники битв, наставники воїнів і загони Вартових.",section="Тераса Воїна, яку іноді називають Залою Правосуддя, лежить на східному порозі Дарнасуса й слугує головним оборонним бастіоном проти вторгнень із диких хащ Тельдрассила. Важкоозброєні Вартові верхи на нічних шаблезубах стережуть її високі арковані брами й пильно наглядають за прибулими. На відкритих майданах тераси молоді бійці вправляються поруч із бувалими ветеранами — на просторих полях для поєдинків і стрільбищах. Район дбає й про практичні військові потреби: тут працюють зброярі, майстри обладунків і розпорядники битв, які скеровують сили нічних ельфів по всьому світу.",sectionIndex=1}
c["subzone:warsong-labor-camp"] = "9e3925"
P.scopedClips["subzone:warsong-labor-camp"] = {scope="overview-body",sourceHash="4971c6",hash="9e3925",name="Трудовий Табір Бойової Пісні",summary="Трудовий Табір Бойової Пісні — відокремлена застава Орди для заготівлі деревини, що сховалася на південному сході Ашенвалю. Тут працюють лісоруби Бойової Пісні під охороною орківських вартових: вони рубають ліс, щоб живити розбудову Дуротара, попри ворожість довколишнього лісу.",section="Трудовий Табір Бойової Пісні, що лежить на схід від Озера Впалого Неба й на південний захід від Курганного Лігва Дор'Даніл, існує з однією важливою метою — заготовляти густий ліс Ашенвалю. Сухі рівнини Дуротара майже не дають придатної деревини, щоб будувати міста на кшталт Оргріммара, тож клан Бойової Пісні змушений просуватися вглиб спірних лісів. Тут працюють витривалі лісоруби й орківська охорона, і табір живе майже відрізаним від світу, перемелюючи прадавні дерева попри постійну загрозу з боку розвідників нічних ельфів і бойових загонів Альянсу.",sectionIndex=1}
c["subzone:warsong-lumber-camp"] = "a2cc1f"
P.scopedClips["subzone:warsong-lumber-camp"] = {scope="overview-body",sourceHash="dc62a2",hash="a2cc1f",name="Лісозаготівельний Табір Бойової Пісні",summary="Лісозаготівельний Табір Бойової Пісні — укріплена орківська лісорубня в глибині Ашенвалю, де клан Бойової Пісні заготовляє деревину для Орди. Його опора — укріплена Фортеця Карґатія, і табір водночас є економічною артерією для ближніх поселень Орди та невгамовною провокацією для нічних ельфів. Безупинний гул гоблінських подрібнювачів, що вгризаються в прадавнє віття, робить цю галявину однією з головних гарячих точок лісової війни.",section="Лісозаготівельний Табір Бойової Пісні, вирубаний просто в густих кронах східного Ашенвалю, — промисловий рушій, що живить розширення Орди на Калімдорі. Орки-робітники й наймані гоблінські інженери оголюють ліс гуркітливими подрібнювачами, перетворюючи велетенські стовбури на деревину для стін застав на кшталт сусідньої Застави Розщепленого Дерева й для розбудови молодої держави Дуротар. Табір добре укріплений від постійних контрударів нічних ельфів: його серце — частоколи Фортеці Карґатія та псарня, де тримають лютих бойових вовків клану. Для Бойової Пісні кожне зрубане дерево — це виживання й сила; для корінних Вартових кожне лезо пилки — святотатство.",sectionIndex=1}
c["subzone:weathered-nook"] = "528bc0"
P.scopedClips["subzone:weathered-nook"] = {scope="overview-body",sourceHash="671262",hash="528bc0",name="Обвітрений Закуток",summary="Обвітрений Закуток — відлюдна розколина з прихистком, що примостилася високо над дном каньйону під північними скелями Тисячі Голок. Звідси видно безкрає море кам'яних шпилів, і тут знаходять скромну домівку та тихий притулок самотні таурени, які шукають спокійних роздумів далеко від гамірних поселень.",section="Обвітрений Закуток, видовбаний у прямовисній пісковиковій стіні на північ від Застави Вільного Вітру, легко проминути, коли йдеш улоговиною каньйону внизу. Природний схил в'ється вгору стіною й виводить на захищений уступ і печеру, куди не дістають вітри. Тут немає ні військової застави, ні великого поселення — закуток слугує скромною оселею для самотніх мандрівників, як-от Дорн Плейнстокер і Прейт Клаудсір, даруючи безпеку, усамітнення й широкий краєвид на обвітрені плато-голки.",sectionIndex=1}
c["subzone:webwinder-path"] = "62201e"
P.scopedClips["subzone:webwinder-path"] = {scope="overview-body",sourceHash="c83164",hash="62201e",name="Стежка Павутинника",summary="Стежка Павутинника — звивиста гірська дорога в Горах Кам'яного Кігтя, що з'єднує тролячу заставу Малака'джин з Озером Міркфаллон. Вона пролягає крізь дикі скелі й густі високогірні ліси, де живуть агресивні павуки та тутешні звірі.",section="Стежка Павутинника, що біжить від поселення Орди Малака'джин до Озера Міркфаллон, — одна з головних доріг крізь нижні Гори Кам'яного Кігтя. Як і годиться за назвою, шлях славиться густим павутинням, натягнутим високо серед крон і зубчастих скель. Мандрівникам на цій звивистій дорозі доводиться пильно дивитися під ноги, ділячи второвану стежку з гірськими павуками, що чатують на здобич, агресивними громовими ящерами та войовничими баранами, які стережуть свою територію.",sectionIndex=1}
c["subzone:wellspring-lake"] = "cd633f"
P.scopedClips["subzone:wellspring-lake"] = {scope="overview-body",sourceHash="87b434",hash="cd633f",name="Озеро Джерела",summary="Озеро Джерела — тиха прісна водойма високо в гіллі Тельдрассила, на північний схід від Дарнасуса. Живлене природними джерелами з глибин Світового Дерева, воно дає початок звивистій Річці Джерела. Колись мирний притулок рибалок нічних ельфів, береги озера стали жертвою скверни, що збурює живність Тельдрассила.",section="Озеро Джерела під кроною між Дарнасусом і Галявиною Оракула калдореї здавна плекали як тихий прихисток для риболовлі й роздумів. Його прозорі води беруть початок із підземних джерел, що біжать велетенським гіллям Світового Дерева, а далі стікають на північ Річкою Джерела. Та останнім часом підступна пошесть почала охоплювати довколишні хащі. Агресивні павуки, нічні шаблезуби, що нишпорять довкола, і збурені деревляники тепер бродять берегами, і колись ідилічний ставок став підступним місцем для необачних мандрівників.",sectionIndex=1}
c["subzone:wellspring-river"] = "f9a239"
P.scopedClips["subzone:wellspring-river"] = {scope="overview-body",sourceHash="158985",hash="f9a239",name="Річка Джерела",summary="Річка Джерела витікає з природного джерела в Тельдрассилі й біжить на північ з Озера Джерела, аж поки не зривається з гілля велетенським водоспадом в океан далеко внизу. Колись мирне джерело прісної води для всієї живності Світового Дерева, її береги стали небезпечними через збурену місцеву живність.",section="Живлена глибокими природними джерелами в гіллі Тельдрассила, Річка Джерела несе воду на північ з Озера Джерела через зелений ліс, а тоді велично падає з краю великого дерева в море внизу. Попри мирне довкілля, береги річки стають дедалі небезпечнішими. Деревляники, що живуть уздовж води, знавісніли й стали ворожими: вони люто нападають на мандрівників і друїдів, які намагаються підійти до річки.",sectionIndex=1}
c["subzone:westbrook-garrison"] = "bd8441"
P.scopedClips["subzone:westbrook-garrison"] = {scope="overview-body",sourceHash="9e2b9e",hash="bd8441",name="Гарнізон Вестбрук",summary="Гарнізон Вестбрук — застава вартових Стормвінда на західному краю Лісу Елвінн, поблизу кордону з Вестфолом. Її тримає перевантажена, погано забезпечена жменька вартових під проводом Помічника Рейнера, і це перша лінія оборони королівства проти гнолів Річколапів, що насуваються, і розбійників-відступників.",section="Гарнізон Вестбрук, що стоїть там, де Ліс Елвінн починає рідшати в бік Вестфолу, — важливий, але знесилений спостережний пункт. Оскільки більшу частину армії Стормвінда відрядили за кордон або скувала політична інертність у столиці, застава лишилася критично нечисленною. Помічник Рейнер і його жменька вартових мусять патрулювати західні дороги, водночас відбиваючись від знахабнілих злодіїв і лютих гнолів Річколапів, що заполонили південні ліси. Не маючи змоги добитися офіційного підкріплення від Маршала Дуґана в Ґолдширі, гарнізон майже цілком покладається на мандрівних шукачів пригод, щоб убезпечити шлях.",sectionIndex=1}
c["subzone:westfall-lighthouse"] = "92c749"
P.scopedClips["subzone:westfall-lighthouse"] = {scope="overview-body",sourceHash="7dd9a5",hash="92c749",name="Маяк Вестфолу",summary="Маяк Вестфолу стоїть на скелястому острівці біля південно-західного берега Вестфолу й колись застерігав кораблі від підступних мілин Великого Моря. Нині живих доглядачів маяка вже немає: їх вигубив жорстокий напад горезвісного мурлока Старого Мутноокого, і за вогнем наглядає лише дух Капітана Ґрейсона.",section="Маяк, зведений на підступних південно-західних скелях Вестфолу, довго вказував безпечний шлях кораблям, що йшли узбережжям поблизу Стормвінда. Та коли закон і порядок у краї розвалилися, а королівські патрулі порідшали, прибережні небезпеки розрослися без упину. Спершу маяк доглядала родина наглядачів, але войовничі племена мурлоків витіснили їх углиб суходолу. Сім'я мужньо повернулася, щоб знову запалити вогонь, однак сумнозвісний мурлок-грабіжник Старий Мутноокий зібрав родичів у другий, безжальний наступ — родину вирізали, а маяк згас.",sectionIndex=1}
c["subzone:whelgar-s-excavation-site"] = "3d6673"
P.scopedClips["subzone:whelgar-s-excavation-site"] = {scope="overview-body",sourceHash="6fd6db",hash="3d6673",name="Місце Розкопок Велґара",summary="Місце Розкопок Велґара — дворфійські археологічні розкопки на західних пагорбах Багнокраю. Експедиція мала відкопати прадавні реліквії титанів і доісторичні таємниці, але скінчилася катастрофою, коли кар'єр заполонили люті плямисті раптори. Уцілілі копачі тепер застрягли на гребені над розкопками, відрізані від своїх знахідок.",section="Дворфійські рудошукачі, що шукали прадавні скам'янілості й таємниці землян, вирили величезний кар'єр між Гаванню Менетіл і Дун Модром. Та розкопані доісторичні рештки накликали гнів місцевих плямистих рапторів. Не маючи ні сил, ні спорядження, археологи відступили на гребінь над розкопками, покинувши намети, інструменти й відкопані реліквії серед хижаків, що там никають.",sectionIndex=1}
c["subzone:whispering-forest"] = "6496fb"
P.scopedClips["subzone:whispering-forest"] = {scope="overview-body",sourceHash="1904fe",hash="6496fb",name="Шепітливий Ліс",summary="Шепітливий Ліс — відлюдний гірський ліс, схований за стрімкими скелями на захід від Похоронного Подзвону. Майже відрізаний від решти Галявин Тірісфалю, він ховає моторошну живність, таємниче відьмине коло й глибоко вкорінену скверну, що спить далеко під землею.",section="Шепітливий Ліс, який ховають Камінь Північного Лику й Фортеця Бандаріон, здається зовсім чужим довколишньому ураженому чумою королівству. Хоч тут водяться хворі олені й мандрівні хижаки, тут також є тихе озеро й дивне коло велетенських грибів, що світяться моторошною енергією під завислою хмарою імли. Примарний Лицар Скорботи блукає відьминим колом, прив'язаний до нього клятвою, серед природної магії, яка немов кидає виклик зруйнованій Погибеллю землі.",sectionIndex=1}
c["subzone:whispering-shore"] = "a58a1e"
P.scopedClips["subzone:whispering-shore"] = {scope="overview-body",sourceHash="aabf12",hash="a58a1e",name="Шепітливий Берег",summary="Шепітливий Берег — похмура смуга узбережжя в західних Галявинах Тірісфалю; одразу на південь від нього лежить Хутір Соллідена. Колись тихий і щедрий притулок рибалок Лордерона, його холодні води відтоді захопило люте плем'я мурлоків.",section="До того як Третя війна прокотилася північним Лордероном, Шепітливий Берег славився серед місцевих як улюблена рибальська гавань, відома спокійними водами й багатими уловами. Сьогодні крижані бризки Великого Моря б'ються об порожній берег, позбавлений свого мирного минулого. Води стали холодними й темними, без колишньої щедрості, і кожен нещасний мандрівник, що спуститься з пагорбів, ризикує потрапити в засідку ревнивих до своєї території прибережних мешканців.",sectionIndex=1}
c["subzone:whitereach-post"] = "8501cd"
P.scopedClips["subzone:whitereach-post"] = {scope="overview-body",sourceHash="d126fb",hash="8501cd",name="Застава Білого Рубежу",summary="Застава Білого Рубежу — невеликий табір Орди при запорошеній дорозі каньйоном Тисячі Голок. Ця скромна придорожня станція неподалік від Табору Е'ток дає змогу перепочити й пильно стежить за суворим пустельним шляхом. Для мандрівників між Фераласом і солончаками це острівець безпеки Орди під грізними пісковиковими стовпами.",section="Застава Білого Рубежу, що примостилася при второваній дорозі глибинами Тисячі Голок, — одна з кількох скромних опор Орди, відвойованих у суворої місцевості. Розташована поблизу Табору Е'ток, застава допомагає Орді надійно триматися на дні каньйону й стежити за рухом між обвітреними столовими горами. Вона не така укріплена, як великий підйомник чи головні племінні поселення, проте для гінців, розвідників і шукачів пригод, що перетинають спірні пустища, без неї не обійтися.",sectionIndex=1}
c["subzone:wildbend-river"] = "c808cd"
P.scopedClips["subzone:wildbend-river"] = {scope="overview-body",sourceHash="288121",hash="c808cd",name="Річка Дикого Закруту",summary="Річка Дикого Закруту — отруєний потік, що петляє південними лісами Темного Узбережжя поблизу Гаю Прадавніх. Стікаючи просто з осквернених висот Сквернолісся, її води несуть демонічну отруту до моря, загрожуючи довколишній дикій природі.",section="Річка Дикого Закруту прорізає південь Темного Узбережжя й тече на захід повз священний Гай Прадавніх, а потім впадає в море. Замість живити ліс чистою водою, вона несе скверну з гір. Річка — пряме продовження Річки Кривавої Отрути зі Сквернолісся: вона мчить скелястими кряжами, несучи мерзенні отруєні стоки в природу Темного Узбережжя. Нічні ельфи пильно стежать за її берегами, виглядаючи спотворених звірів і повзуче поширення демонічної пошесті.",sectionIndex=1}
c["subzone:wildmane-water-well"] = "ed524d"
P.scopedClips["subzone:wildmane-water-well"] = {scope="overview-body",sourceHash="675e25",hash="ed524d",name="Водяна Криниця Вайлдмейнів",summary="Водяна Криниця Вайлдмейнів — найпівнічніша зі священних криниць, розкиданих по Малгору; вона лежить одразу на північ від плато Тандер Блафа. Життєво важлива для рівнин і їхніх стад, вона стала гарячою точкою, на яку націлилися гоблінські пройдисвіти, прагнучи перекрити тауренам джерело життя.",section="Поколіннями кочові таурени покладалися на священні криниці, викопані по золотавих рівнинах Малгору, щоб напувати свій народ і мандрівні стада кодо. Криниця Вайлдмейнів стереже північні простори одразу за тінню Тандер Блафа. Її надзвичайна важливість робить її принадною ціллю для ворогів племен. Гобліни Венчурної Компанії споганили її своїми отрутами, аби прибрати до рук водопостачання всього краю, і лише обряд очищення з тотемом, виготовленим тауренами, зможе знову зробити її води чистими.",sectionIndex=1}
c["subzone:windfury-ridge"] = "7b67ac"
P.scopedClips["subzone:windfury-ridge"] = {scope="overview-body",sourceHash="7602ae",hash="7b67ac",name="Хребет Люті Вітру",summary="Хребет Вітрофурій — суворе високогір'я, що обступає пасовища Малгору. Сумнозвісний лютими гарпіями, а також хижими вовками й пумами, він становить постійну небезпеку для подорожніх, зате дарує тауренським майстрам цінне пір'я.",section="Хребет Вітрофурій різко здіймається над тихими рівнинами Малгору й править за мисливські угіддя гарпій Вітрофурій. Ці люті крилаті створіння гніздяться високо в кручах і охоче кидаються згори на необачних мандрівників, що обходять пагорби. Скелясту місцевість також населяють степові вовки й дикі гірські пуми, тож хребет — один із найпідступніших кордонів тауренського серця краю. Попри небезпеку, хоробрі тауренські воїни часто полюють на гарпій: їхнє яскраве, переливчасте пір'я дуже цінують по всьому Тандер Блафу, прикрашаючи ним обрядові шати для пишних бенкетів і весільних святкувань.",sectionIndex=1}
c["subzone:windshear-crag"] = "a593bb"
P.scopedClips["subzone:windshear-crag"] = {scope="overview-body",sourceHash="47eb1d",hash="a593bb",name="Круча Вітрорізу",summary="Круча Вітрорізу — вщент сплюндрована долина в центрі Гір Кам'яного Кігтя, яку Венчурна Компанія позбавила прадавнього лісу. Колись тут шумів пишний ліс, а тепер це промислова пустка, де гудуть подрібнювачі, течуть каламутні стоки й лютують бригади лісорубів. У тіні машин місцеві кобольди риють руду, а гірські перевали з'єднують цей пошрамований край з Ашенвалем.",section="Ще недавно Круча Вітрорізу була густим пралісом на схилах Кам'яного Кігтя. Та спокійна дика місцина зникла, щойно сюди по наживу прийшла Венчурна Компанія. Тепер улоговина повна зрізаних пнів, їдкого смогу й брязкоту машин. Усім лісозаготівельним підприємством керує Ґерензо Ренчвісл — прокажений гном, чий інженерний геній створив Суперкосар 6000: механічне страхіття, здатне за мить перетворити величезні стовбури на тріски. З високого помосту над отруєним Озером Скельної Заводі Ґерензо керує цією неприборканою роботою, що оголює гору дочиста, і наживає собі ворогів і серед інженерів-суперників, і серед місцевих мешканців.",sectionIndex=1}
c["subzone:winterhoof-water-well"] = "425590"
P.scopedClips["subzone:winterhoof-water-well"] = {scope="overview-body",sourceHash="bfaa7e",hash="425590",name="Водяна Криниця Вінтергуфів",summary="Водяна Криниця Вінтергуфів — життєво важливе джерело прісної води на краю Хвилястих Рівнин у південному Малгорі. Вкрай потрібна місцевій живності й кочовим тауренським племенам, криниця нещодавно опинилася під загрозою з боку хижої Венчурної Компанії, що прагне отруїти й прибрати до рук водопостачання краю.",section="У посушливих просторах центрального Калімдору вода — це життя, і підземні криниці Малгору живлять і стада рівнин, і стійбища тауренів. Водяна Криниця Вінтергуфів, названа на честь одного з шанованих племен рівнин, сягає глибоких водоносних шарів під Хвилястими Рівнинами. На жаль, її стратегічна вага розпалила жадобу Венчурної Компанії. Замість ділити землю чи домовлятися безжальний гоблінський картель спробував отруїти воду, щоб здобути важіль тиску на довколишні землі.",sectionIndex=1}
c["subzone:xavian"] = "3f33a2"
P.scopedClips["subzone:xavian"] = {scope="overview-body",sourceHash="ee4477",hash="3f33a2",name="Ксавіан",summary="Ксавіан — давній зруйнований храмовий комплекс нічних ельфів на північному сході Ашенвалю, який захопили сатири. Це головний осередок влади сатирів у лісі: руїни просякнуті демонічною скверною, а тут правлять темні обряди, спрямовані проти лісу.",section="Ксавіан, що сховався серед північно-східних пагорбів Ашенвалю, на захід від Лісової Пісні й на північ від Сатирнаару, — найголовніший оплот сатирів у краї. Колись це був священний ельфійський храм, але його кам'яні арки й тераси осквернили прислужники Палаючого Легіону. Ватажки сатирів, серед них Принц Рейз і Ґелтарис, керують своїми родичами з цих руїн. Вони правлять по всій території осквернювальні ритуали і навіть використовують викрадену олію Бойової Пісні, щоб іще дужче отруїти священний ліс. Місцевість названа на честь Ксавіуса — радника Високородних, що став першим сатиром під час Війни Прадавніх, після того як підвів Саргераса.",sectionIndex=1}
c["subzone:yorgen-farmstead"] = "095578"
P.scopedClips["subzone:yorgen-farmstead"] = {scope="overview-body",sourceHash="364de6",hash="095578",name="Хутір Йорґенів",summary="Хутір Йорґенів — занедбана ферма на півдні Сутінколісся, що занепала разом із рештою неспокійного краю. Колись вона належала фермерові Свену Йорґену, а тепер її захопили розбійники Братства Дефіас.",section="Хутір Йорґенів, що лежить серед похмурих лісів південного Сутінколісся, колись був справним господарством Свена Йорґена. Як і багато відрізаних садиб краю, ферма не встояла перед небезпеками, що насувалися. Свен був змушений покинути свої землі й відійти на північ, до тимчасового табору на Темному Березі. За його відсутності покинуте обійстя захопили розбійники, що шукали опори подалі від очей влади Стормвінда.",sectionIndex=1}
c["subzone:zoram-gar-outpost"] = "77a098"
P.scopedClips["subzone:zoram-gar-outpost"] = {scope="overview-body",sourceHash="688b75",hash="77a098",name="Застава Зорам'гар",summary="Застава Зорам'гар — укріплений плацдарм Орди на західному краю Ашенвалю, на Зорамському Узмор'ї. Цей важливий прибережний табір дає Орді вихід до Прихованого Моря й пильнує загрози краю — наг, що наступають, і зловісні глибини неподалік.",section="Застава Зорам'гар, що стоїть на північно-західному краю Ашенвалю, де прадавній ліс обривається в море, — відокремлений прибережний плацдарм Орди на Зорамському Узмор'ї. Затиснутий між землями нічних ельфів у глибині суходолу й морськими небезпеками біля берега, табір слугує базою для розвідників, мисливців і шаманів, яким доручено стежити за місцевими загрозами. Життя на заставі — нескінченна варта: наги раз у раз нишпорять на мілинах, а з підземних печер, відомих як Чорноглибинні Печери, трохи далі вздовж берега, ширяться культисти й первісні жахи.",sectionIndex=1}
c["subzone:zoram-strand"] = "25d46f"
P.scopedClips["subzone:zoram-strand"] = {scope="overview-body",sourceHash="ef93f0",hash="25d46f",name="Зорамське Узмор'я",summary="Зорамське Узмор'я — продуване вітрами узбережжя на північно-західному краю Ашенвалю, над Прихованим Морем. Колись тут стояло давнє місто нічних ельфів, яке поглинув Великий Розкол, а нині берег заполонили наги Гнівохвості, уламки кораблів і викинуті на сушу морські велетні. Тут же — вхід до затопленого храмового комплексу Чорноглибинних Печер.",section="Десять тисяч років тому ці береги прикрашало величне місто нічних ельфів Зорам — доки Великий Розкол не роздер Калімдор і не скинув поселення в океанські глибини. Сьогодні приплив раз у раз викидає давні реліквії, уламки розбитих суден і туші величезних морських звірів. Наги Гнівохвості заполонили пляжі й припливні калюжі, люто стережучи затоплені руїни й давні артефакти від кожного, хто наважиться наблизитися.",sectionIndex=1}
c["topic:skyborne"] = "de0a2c"
P.scopedClips["topic:skyborne"] = {scope="overview-body",sourceHash="31ae63",hash="de0a2c",name="Небороджені",summary="Небороджені, або шен'дорей, — гілка високих ельфів, що походять від бунтівників, які втекли з Ельдре'Таласу, бо виступили проти демонічних угод Принца Тортельдріна. Уклавши відчайдушну угоду з духами вітру, їхні предки покинули Азерот і оселилися на летючому Острові Зефрас у Небесній Тверді. Сьогодні, коли їхні стихійні покровителі раптово зникли, летючий прихисток роздирають внутрішні чвари, і йому загрожує руйнування.",section="Після Розколу Шен'дралар з Ельдре'Таласу занепадали без Колодязя Вічності. Принц Тортельдрін задумав темний порятунок: викликати демона Іммол'тара й черпати його силу. Нажахані вельможі й городяни опиралися, боячись нового вторгнення Легіону. У відповідь Тортельдрін влаштував криваву розправу над десятками родів. З уцілілих тіней постав опір на чолі з постаттю в масці, відомою лише як Шал'нан («Завуальований»). Коли відчайдушний напад повстанців на ритуальне святилище Тортельдріна обернувся катастрофічною хаотичною магією, Шал'нан згуртував уцілілих і втік на захід до порту Ельдре'нарр, а звідти — у море, переслідуваний флотом принца.",sectionIndex=1}
c["topic:skyborne#faq1"] = "c2be1a"
P.scopedClips["topic:skyborne#faq1"] = {scope="answer-only",sourceHash="4c9009",hash="c2be1a",name="Небороджені",question="Хто такі Небороджені?",answer="Небороджені, або шен'дорей («прихований народ»), — високі ельфи, що походять від давніх нічних ельфів, які повстали проти Принца Тортельдріна в Ельдре'Таласі. Щоб утекти від його мстивого флоту, вони уклали угоду з духами вітру, і ті перенесли їхній острів, Острів Зефрас, до Царства Стихій Повітря."}
c["topic:skyborne#faq2"] = "1ecd86"
P.scopedClips["topic:skyborne#faq2"] = {scope="answer-only",sourceHash="4a7f82",hash="1ecd86",name="Небороджені",question="Чому в деяких Небороджених блакитна шкіра?",answer="Тисячоліття в Царстві Стихій Повітря непомітно змінили їхню природу. Нещодавнє явище, відоме як Благословення Небесного Дотику, призводить до того, що дедалі більша частка дітей — нині приблизно троє з десяти — народжуються з блакитною шкірою. Учені передрікають, що успадковані від нічних ельфів риси невдовзі зникнуть цілком."}
c["topic:skyborne#faq3"] = "4c2d75"
P.scopedClips["topic:skyborne#faq3"] = {scope="answer-only",sourceHash="a5f994",hash="4c2d75",name="Небороджені",question="Хто такий Шал'нан?",answer="Шал'нан, або «Завуальований», — ватажок у масці, що очолив опір проти виклику демона, який задумав Принц Тортельдрін в Ельдре'Таласі. Привівши вцілілих у безпеку до Небесної Тверді, він зрікся влади, щоб заснувати виборну раду, і служив своєму народові, доки кілька століть тому таємниче не зник разом з їхніми стихійними покровителями."}
c["topic:skyborne#faq4"] = "b4cf4e"
P.scopedClips["topic:skyborne#faq4"] = {scope="answer-only",sourceHash="7387cb",hash="b4cf4e",name="Небороджені",question="Що відбувається з Островом Зефрас?",answer="Острів Зефрас тримається в повітрі Небесної Тверді завдяки магічним пілонам, налаштованим на стихійну силу. Коли кілька століть тому раптово зникли духи вітру, які їх підтримували, пілони почали відмовляти. Частини суходолу відкололися й канули в порожнечу, лишивши вцілілих напризволяще, а ельфи, що втратили домівки, взялися до розбою."}
c["topic:skyborne#faq5"] = "6834f7"
P.scopedClips["topic:skyborne#faq5"] = {scope="answer-only",sourceHash="1959f3",hash="6834f7",name="Небороджені",question="Що таке Високий Орден і Вітротворці?",answer="Це дві головні культурні течії Небороджених. Високий Орден походить від магістрів-Високородних і прагне відбудувати своє суспільство, що розвалюється, через дисципліноване опанування таємної магії. Вітротворці ведуть родовід від звичайних городян із нічних ельфів і шанують стихійні й духовні звичаї, що склалися за час життя в Небесній Тверді."}
c["topic:skyborne#faq6"] = "aa344d"
P.scopedClips["topic:skyborne#faq6"] = {scope="answer-only",sourceHash="419c57",hash="aa344d",name="Небороджені",question="Хто такі Аль'Акет?",answer="Аль'Акет — відчайдушний культ Небороджених, що поклоняється Аль'Акірові, Володарю Вітрів. Стихійні покровителі їхніх предків боялися Аль'Акіра й уникали навіть згадувати його, але руйнування Острова Зефрас штовхнуло бездомних і знедолених біженців шукати порятунку й сили в цього володаря стихії."}
c["zone:alterac"] = "40848e"
P.scopedClips["zone:alterac"] = {scope="overview-body",sourceHash="6cd0ec",hash="40848e",name="Гори Альтерак",summary="Гори Альтерак — холодне, поруйноване високогір'я в центрі Лордерону. Колись тут лежали підступне людське королівство Альтерак і вчена магократія Даларан. Нині засніжені кручі заполонили огри Трощихребтів, аристократи-розбійники із Синдикату та рештки чародійських сил. Мандрівники вирушають сюди з поселень у передгір'ях і з Даларану, що постає з руїн.",section="Під час Другої війни Альтерак був одним із Семи Королівств людства, але король Ейден Перенольд зрадив Альянс Лордерону й перейшов на бік Старої Орди, сподіваючись уберегти свою державу. Його зраду викрили й придушили, а країна розпалася на спірні прикордонні землі. Після розпаду королівства й жахіть Третьої війни величну кам'яну столицю Альтераку обернули на руїни. Нині Руїни Альтераку займають жорстокі огри Трощихребтів на чолі з Муґ'толом, а вцілілі людські вельможі згуртувалися в Синдикат — люту злочинну спілку, що силою намагається повернути собі втрачені маєтки.",sectionIndex=1}
c["zone:arathi"] = "d2a5d0"
P.scopedClips["zone:arathi"] = {scope="overview-body",sourceHash="ab8970",hash="d2a5d0",name="Аратійське нагір'я",summary="Аратійське нагір'я — суворе плато на південному сході Лордерону, відоме як давня колиска Імперії Аратор. Нині королівство Стромґард лежить у руїнах, а скелястий край охопила війна на кількох фронтах: рештки Стромґарду, Орда, вельможі-злочинці із Синдикату й огри-загарбники б'ються тут усі проти всіх.",section="Тисячоліття тому король Торадін об'єднав розрізнені людські племена під стягом араті й звів на цих сухих, зручних для оборони рівнинах величну столицю Стром. Саме тут під час Тролячих воєн людство уклало легендарний союз із високими ельфами й опанувало таємну магію, щоб відкинути Амані. З часом шляхетні роди переселилися на північ, до Лордерону, і на південь, до Стормвінда, але імперська гвардія лишилася й заснувала войовниче королівство Стромґард. Віками Стромґард був оплотом стійких воїнів, які стримували лісових тролів.",sectionIndex=1}
c["zone:ashenvale"] = "e6646b"
P.scopedClips["zone:ashenvale"] = {scope="overview-body",sourceHash="dda087",hash="e6646b",name="Ашенваль",summary="Ашенваль — прадавній, щедро политий дощами ліс, батьківщина нічних ельфів, священний край під захистом Вартових і напівбога Кенарія. Він межує з Пустками на півдні й Темним Узбережжям на півночі і перетворився на арену запеклої війни, відколи Орда рубає тут ліс, щоб розбудувати свою молоду державу. Під одними кронами з прадавніми деревами й тихими місячними колодязями ховаються демонічні недобитки, ворожі звіролюди й гарячі точки вздовж спірного кордону.",section="Ашенваль, що розкинувся під Горою Гіджал, тисячоліттями перебуває під опікою калдореїв і дітей Кенарія. Велетенські дерева сплітаються в густе склепіння, яке перетворює щоденний дощ на легку мжичку й огортає лісову підстилку вічними сутінками. Крізь мох проступають давні руїни ельфійської цивілізації, які стережуть ходячі прадавні й дріади. Тисячі років нічні ельфи не будували тут справжніх міст: вони воліли полювати помірно й берегти дикий край у бездоганній рівновазі.",sectionIndex=1}
c["zone:azshara"] = "53be2a"
P.scopedClips["zone:azshara"] = {scope="overview-body",sourceHash="812577",hash="53be2a",name="Азшара",summary="Азшара — скелясте, обвітрене узбережжя на північному сході Калімдору, вбране в яскраве листя вічної осені. Колись тут була славетна столиця нічних ельфів, та Великий Розкол обрушив її в море. Нині це небезпечний дикий край, усіяний давніми руїнами, де чатують похмурі наги й живуть відлюдні чародії. І Орда, і Альянс тримають на його межах хиткі застави, остерігаючись неспокійних привидів і морських жахіть, що ховаються в глибині краю.",section="Десять тисяч років тому це узбережжя було живим серцем цивілізації калдореїв, що оточувало королівську столицю Зін-Азшарі. Коли королева Азшара та її двір Високородних закликали в Азерот Палаючий Легіон, спалахнула Війна Прадавніх, яка скінчилася катастрофічним обвалом Колодязя Вічності. Море ринуло на сушу й поглинуло більшу частину величного міста, лишивши по собі розколоті кручі, підступні коралові рифи й затоплені шпилі. Уцілілі назвали спустошений край на честь своєї загиблої володарки, затаврувавши його як проклятий пам'ятник гордині й страшній зраді.",sectionIndex=1}
c["zone:badlands"] = "ab5305"
P.scopedClips["zone:badlands"] = {scope="overview-body",sourceHash="0f4b4f",hash="ab5305",name="Пустища",summary="Пустища — посушливий, випалений сонцем край потрісканої землі, пилових бур і кам'янистих каньйонів між Лох Моданом і Палючою Ущелиною. Хоча вони лежать у самому серці дворфійського Каз Модану, це неспокійне прикордоння, де панують дворфи Темного Заліза, троги, огри Пилоригачів і чорні драконороди, що в'ють тут гнізда. Тут же стоять руїни титанів Ульдаман і твердиня Орди Карґат, тож Пустища мають чимале стратегічне значення.",section="На південь від зелених пагорбів Лох Модану земля швидко переходить у задушливу улоговину голих рівнин і крутих ярів. Щоб вижити тут, доводиться мати справу з безжальними койотами, пумами, грифами й лютими піщаними бурями, що затуляють обрій. Плато всіяні грубими таборами огрів Пилоригачів, а похмурий клан Темного Заліза укріпився у Фортеці Анґор і нападає на кожного, хто ступить на його землі.",sectionIndex=1}
c["zone:barrens"] = "c1c5fe"
P.scopedClips["zone:barrens"] = {scope="overview-body",sourceHash="f18b75",hash="c1c5fe",name="Пустки",summary="Пустки — безкрая, випалена сонцем савана, що стала географічним і постачальним серцем Орди в центральному Калімдорі. До Великого Розколу тут шумів зелений ліс, а тепер це посушлива рівнина з червоним пилом, витривалими чагарниками й мандрівними звірами. Довкола важливого вузла — Перехрестя — край не виходить із безупинної боротьби з племенами шипогривів, нападниками-кентаврами й повзучою скверною.",section="Незліченні покоління кочові таурени полювали на цих рівнинах на кодо й жевр, ведучи оборонну, нескінченну війну з розбійними кентаврами Колкарами. Коли під час Третьої війни Тралл привів орків на Калімдор, він допоміг Кайрнові Бладгуфу відбити кентаврів і перейти саваною до Малгору. Сьогодні Пустки з'єднують Дуротар, Малгор і Ашенваль. Застави на кшталт Перехрестя й Табору Тауражо захищають торгівлю на Золотому Шляху, а орківські садиби опираються посушливому кліматові, щоб збудувати тут тривку домівку.",sectionIndex=1}
c["zone:blackfathom"] = "4e3940"
P.scopedClips["zone:blackfathom"] = {scope="overview-body",sourceHash="30b598",hash="4e3940",name="Чорноглибинні Печери",summary="Чорноглибинні Печери — затоплений підземний храмовий комплекс на Зорамському Узмор'ї, на північному заході Ашенвалю. Колись це було святилище місячної богині нічних ельфів Елуни, але тепер затонулий храм захопили культ Молота Присмерку, підступні наги й сатири. Вони збираються в його темних водах, щоб шанувати й плекати Аку'май — первісну улюбленицю й провісницю Древніх Богів.",section="Задовго до того, як Великий Розкол зруйнував давній Калімдор, цей комплекс звався Латар'Лазал — розкішний храм, присвячений Елуні. Каменярі з Високородних звели мости, всипані самоцвітами, а королева Азшара повеліла довколишніми водами, розділивши солоні моря й гірські потоки довкола священного місячного колодязя. Коли десять тисяч років тому Розкол роздер світ, храм пішов на дно в прибережних глибинах Прихованого Моря. Тисячоліттями він непорушно лежав під хвилями — аж доки з підземної темряви не почав просочуватися мерзенний шепіт.",sectionIndex=1}
c["zone:blastedlands"] = "7e3310"
P.scopedClips["zone:blastedlands"] = {scope="overview-body",sourceHash="7c4df4",hash="7e3310",name="Спустошені Землі",summary="Спустошені Землі — безлюдний простір червоної глини й голого каміння на південно-східному краю Східних Королівств, понівечений хаотичною енергією Темного Порталу. Колись це була частина зеленої Чорної Трясовини, а тепер на розтрощеній землі ховаються недобитки Палаючого Легіону, жорстокі огри Дредмолів і витривалі звірі пустелі. Замок Незерґард пильно стереже цей мертвий край, захищаючи Азерот від жахіть, що можуть вирватися з приспаної брами.",section="До Першої війни цей край був продовженням густих боліт, відомих як Чорна Трясовина. Ті буйні болота знищили дощенту, коли чорнокнижник Ґул'дан і одержимий Медів розчахнули Темний Портал, щоб випустити орочу Орду. Хаотична енергія скверни просочилася крізь пролом між світами, висушила всю вологу й випекла землю на потріскану червону глину. Коли наприкінці Другої війни Темний Портал зруйнували, нищівні ударні хвилі ще дужче обпалили край і пофарбували тутешній камінь у неземний багряний колір.",sectionIndex=1}
c["zone:burningsteppes"] = "4792ae"
P.scopedClips["zone:burningsteppes"] = {scope="overview-body",sourceHash="3d9a9e",hash="4792ae",name="Палаючі Степи",summary="Палаючі Степи — випалена вулканічна пустка біля південного підніжжя Гори Блекрок. Цей підступний край постав століття тому внаслідок катастрофічного виклику Рагнароса, і саме ним пролягає головний суходільний шлях між Стормвіндом і Каз Моданом. Нині тут кишать орки-відщепенці клану Блекрок, огри Вогняного Черева, дворфи Темного Заліза й виводки чорного драконячого роду.",section="Колись ці передгір'я були просто північними відрогами Гір Редріджу. Під час Війни Трьох Молотів вигнаний клан Темного Заліза заснував тут своє королівство й звів столицю Тауріссан. Опинившись на межі повної поразки від кланів Бронзбірдів і Вайлдгаммерів, чародій-тан Тауріссан у відчаї спробував викликати сили стихій. Натомість він розколов землю й прикликав в Азерот Рагнароса, Володаря вогню. Нищівний вибух розтер на порох навколишні гори, розверз ріки лави й породив велетенський вулкан — Гору Блекрок, а степи назавжди лишилися обвугленими й безплідними.",sectionIndex=1}
c["zone:darkshore"] = "fba956"
P.scopedClips["zone:darkshore"] = {scope="overview-body",sourceHash="e2985e",hash="fba956",name="Темне Узбережжя",summary="Темне Узбережжя — холодна, оповита туманом смуга берега на північному заході Калімдору, всіяна давніми руїнами калдореїв і неспокійними звірами. Його опора — портове містечко Альянсу Обердайн, головна брама на континент для мандрівників із Тельдрассилу й Східних Королівств. За межами патрульованої дороги крихкій рівновазі краю загрожують демонічні культи, наги, що наступають, і повзуча скверна з нагір'я.",section="Темне Узбережжя, що простягається під західними тінями Гори Гіджал і Сквернолісся, — це соснові гаї, морський туман і кам'янисті пляжі, які б'ють холодні хвилі. Тисячоліття тому на цьому березі квітли міста-близнюки калдореїв — Амет'Аран і Башал'Аран. Зруйновані під час Великого Розколу, їхні оголені колони й мармурові арки тепер лежать напівзатоплені в прибої чи порослі корінням; там блукають неспокійні духи Високородних, а хазяйнують мурлоки-падальники й наги-загарбники.",sectionIndex=1}
c["zone:darnassus"] = "942f21"
P.scopedClips["zone:darnassus"] = {scope="overview-body",sourceHash="146c49",hash="942f21",name="Дарнасус",summary="Дарнасус — спокійна столиця нічних ельфів просто неба, збудована серед віт нещодавно висадженого Світового Дерева — Тельдрассила. Ним править Верховна Жриця Тіранда Віспервінд разом із друїдами Ценаріонського Анклаву, і він став тихим прихистком для давнього народу, що вчиться жити смертним. Дарнасус розкинувся просторими терасами довкола кришталевого озера — це серце суспільства нічних ельфів і їхній міст до Альянсу.",section="На відміну від щільної кам'яної забудови Стормвінда чи висічених у скелі тунелів Айронфорджа, Дарнасус просторий, тихий і відкритий дикій природі. Столиця постала у верхніх кронах Тельдрассила біля північного узбережжя Калімдору: її витончені дерев'яні споруди й звивисті стежки оточують спокійне озеро посередині. Елегантні мости з'єднують тераси торговців, ремісників, вартових і друїдів, і в місті панує рівновага між громадським ладом і глибокою шаною до природи.",sectionIndex=1}
c["zone:darnassus#faq1"] = "8b32f6"
P.scopedClips["zone:darnassus#faq1"] = {scope="answer-only",sourceHash="247242",hash="8b32f6",name="Дарнасус",question="Як дістатися до Дарнасуса з материка?",answer="Тельдрассил — відокремлений острів біля північно-західного узбережжя Калімдору, тож спершу треба дістатися кораблем або в польоті до Селища Рут'теран біля підніжжя дерева. Від пристані селища сяйливий чарівний портал переносить мандрівників просто вгору, до міських віт."}
c["zone:darnassus#faq2"] = "559118"
P.scopedClips["zone:darnassus#faq2"] = {scope="answer-only",sourceHash="464f4c",hash="559118",name="Дарнасус",question="Хто править Дарнасусом?",answer="Дарнасусом і калдореями править Верховна Жриця Тіранда Віспервінд із величного Храму Місяця. Архідруїд Фандрал Стаґгелм із Ценаріонського Анклаву очолює друїдів Кола Кенарія й фактично головує серед них, поки Малфуріон Стормрейдж загублений у Смарагдовому Сні."}
c["zone:darnassus#faq3"] = "a8f2a8"
P.scopedClips["zone:darnassus#faq3"] = {scope="answer-only",sourceHash="0e20e8",hash="a8f2a8",name="Дарнасус",question="Чому місто заснували так недавно?",answer="Дарнасус заснували невдовзі після Третьої війни. Коли нічні ельфи пожертвували безсмертям, щоб здолати Архімонда на Горі Гіджал, Фандрал Стаґгелм наполіг на тому, щоб виростити нове Світове Дерево — Тельдрассил — і повернути колишню силу. Дарнасус виплекали серед його віт як новий прихисток."}
c["zone:darnassus#faq4"] = "061946"
P.scopedClips["zone:darnassus#faq4"] = {scope="answer-only",sourceHash="df2032",hash="061946",name="Дарнасус",question="Де Архідруїд Малфуріон Стормрейдж?",answer="Малфуріон Стормрейдж зник: його дух ув'язнений у Смарагдовому Сні. Поки його немає, друїдами Тельдрассила керує Архідруїд Фандрал Стаґгелм, а Тіранда Віспервінд невпинно шукає способу пробудити й повернути свого коханого."}
c["zone:darnassus#faq5"] = "e9611a"
P.scopedClips["zone:darnassus#faq5"] = {scope="answer-only",sourceHash="aedb51",hash="e9611a",name="Дарнасус",question="Де знайти наставників професій і крамниці?",answer="Місто поділене на тераси з різним призначенням. На північній Терасі Ремісників — збиральні ремесла, кравецтво й корчма, а на південній Терасі Ремісників — торгові ятки й аукціонний дім. Наставники ковальства й бойового мистецтва працюють на Терасі Воїна, а міський банк розташований на центральному острові Храмових Садів."}
c["zone:darnassus#faq6"] = "bcd334"
P.scopedClips["zone:darnassus#faq6"] = {scope="answer-only",sourceHash="e3b6cd",hash="bcd334",name="Дарнасус",question="Чому нічні ельфи приєдналися до Альянсу?",answer="Після спустошень Третьої війни нічні ельфи опинилися під дедалі більшим тиском Орди — передусім через лісорубні походи орків в Ашенваль. Розуміючи, що проти цих вторгнень та інших загроз Калімдору потрібні союзники, Дарнасус налагодив дипломатичні зв'язки й вступив до Великого Альянсу."}
c["zone:deadmines"] = "28cfb0"
P.scopedClips["zone:deadmines"] = {scope="overview-body",sourceHash="65aca9",hash="28cfb0",name="Мертві Копальні",summary="Глибоко під запорошеним хліборобським містечком Мунбрук лежать Мертві Копальні — величезний підземний комплекс, що колись давав третину золотого запасу Стормвінда. Покинуті під час Першої війни й віддавна знані як прокляті, ці лабіринти тунелів таємно захопило Братство Дефіас і зробило своїм головним плацдармом. Тут Едвін Венкліф і його підневільні гобліни-інженери далеко від очей королівства будують знаряддя помсти.",section="До Першої війни Мертві Копальні славилися як найбільший осередок видобутку золота в людських землях, що забезпечував добробут Стормвінда. Коли Орда орків пронеслася королівством і зрівняла столицю з землею, копальні поспіхом покинули на поталу темряві. У ті буремні роки цими глибинами ходили легендарні постаті: сер Андуїн Лотар двадцять місяців пробув у полоні підземних огрів, добуваючи священний Фоліант Божественності, а бунтівна донька вождя Блекгенда, Ґризельда, утекла в нижні ходи разом з огром Туроком, де обоє й знайшли свою смерть. Глибини вважали проклятими, населеними лише шкандибаючою нежиттю та підземною наволоччю, і десятиліттями ніхто їх не торкався.",sectionIndex=1}
c["zone:deadwind"] = "3faafd"
P.scopedClips["zone:deadwind"] = {scope="overview-body",sourceHash="7f5cf2",hash="3faafd",name="Перевал Мертвого Вітру",summary="Перевал Мертвого Вітру — проклятий, зубчастий каньйон у центрі Азероту, що з'єднує Сутінколісся з Болотом Скорботи. Посеред нього здіймається білий, мов слонова кістка, шпиль Каражана — колишня оселя Охоронця Медіва, чия смерть розлила по краю згубну магію. Це мертвий прохід, де нишпорять огри, привиди й демонічні вітри і де немає ні притулку, ні людського житла.",section="Колись Перевал Мертвого Вітру вважали продовженням Гір Редріджу, але тепер це випотрошений шрам вибіленого каміння й скам'янілого дерева. Смердючий, невгамовний вітер продуває яри — від нього ущелина й дістала свою назву. Небо тут повсякчас сіре, мов склеп, і загрожує раптовими грозами, через які мандрувати з металевою зброєю небезпечно. Уздовж головної дороги на мертвих гілках висять тотемні опудала, що застерігають подорожніх не зупинятися. Тут немає ні родючої землі, ні рудних жил, ні містечок, ні майстрів польотів, які могли б допомогти.",sectionIndex=1}
c["zone:desolace"] = "bb692d"
P.scopedClips["zone:desolace"] = {scope="overview-body",sourceHash="5d0ba1",hash="bb692d",name="Пустограй",summary="Пустограй — похмура, вітряна пустеля на західному узбережжі Калімдору: потріскана сіра земля, вічно грозове небо й кістки загиблих звірів. Це прадавня колиска лютих кентаврів і спірна пустка, пошрамована давніми руїнами Високородних, культами демонопоклонників і запеклими війнами племен. І Орда, і Альянс тримають тут хиткі опорні пункти серед пилу, і кожна сторона прагне поширити свій вплив, водночас стримуючи скверну, що розповзається.",section="Пустограй не завжди був голою пусткою попелу й пожовклих калюж. Понад тисячу років тому тут лежав Машан'ше — буйний луговий край, який доглядали шамани-таурени. Той рай загинув, коли з-під землі пробудилася Принцеса Терадрас, елементаль землі, і почала висмоктувати життя з усього довкола, щоб відновити своє тіло. Лихо покликало сюди Заетара, сина Кенарія, але замість приборкати принцесу він узяв її собі за дружину. Від їхнього протиприродного союзу народилися перші кентаври. Сповнені сорому й кровожерного гніву, новонароджені кентаври вбили свого батька, заполонили зелені рівнини й прогнали тауренів, лишивши по собі той пошрамований пустир, який ми знаємо сьогодні.",sectionIndex=1}
c["zone:dunmorogh"] = "276c4a"
P.scopedClips["zone:dunmorogh"] = {scope="overview-body",sourceHash="831ca0",hash="276c4a",name="Дун Мороґ",summary="Дун Мороґ — засніжене гірське високогір'я в серці Каз Модану. Це прадавня стартова земля і спільна батьківщина дворфів Айронфорджа та гномів, що втратили Гномреґан. Хоч засніжений край захищають високі вершини й укріплені перевали, зсередини йому дедалі більше загрожують троги, тролі Морозогриви та опромінені прокажені гноми.",section="Дун Мороґ займає найвищі вершини Східних Королівств — альпійський простір, оточений зубчастими піками, що затуляють його від Палючої Ущелини на півдні та Багнокраю на півночі. Ці засніжені гори живлять річки, що течуть по всьому Каз Модану, і дають майже невичерпні жили міді й заліза. Доступ сюди суворо обмежений гірськими тунелями, як-от Перевал Північної Брами та Прохід Південної Брами, за якими пильно стежать дворфські горяни. У серці краю лежить Айронфордж — прадавнє підземне диво й столиця королівства Короля Маґні Бронзбірда, сполучена просто зі Стормвіндом дивовижним Глибинним трамваєм.",sectionIndex=1}
c["zone:dunmorogh#faq1"] = "1aedf8"
P.scopedClips["zone:dunmorogh#faq1"] = {scope="answer-only",sourceHash="8414f2",hash="1aedf8",name="Дун Мороґ",question="Які раси починають у Дун Мороґу?",answer="І дворфи, і гноми починають свій шлях тут, у Долині Холодного Хребта — захищеній улоговині на південному заході Дун Мороґу, — а потім виходять через Перевал Холодного Кряжа до Хараноса й решти зони."}
c["zone:dunmorogh#faq2"] = "e9cc01"
P.scopedClips["zone:dunmorogh#faq2"] = {scope="answer-only",sourceHash="7fe8bb",hash="e9cc01",name="Дун Мороґ",question="Що сталося з Гномреґаном?",answer="Під час Третьої війни підземна раса трогів заполонила Гномреґан. Намагаючись знищити загарбників, Великий Тінкер Ґелбін Меккаторк випустив у нижні рівні радіоактивний газ. План провалився з катастрофічними наслідками: загинули тисячі, багато гномів через опромінення перетворилися на божевільних прокажених гномів, а здорові вцілілі були змушені тікати до Айронфорджа."}
c["zone:dunmorogh#faq3"] = "d1af43"
P.scopedClips["zone:dunmorogh#faq3"] = {scope="answer-only",sourceHash="fd8191",hash="d1af43",name="Дун Мороґ",question="Як вийти з Дун Мороґу пішки?",answer="Дун Мороґ оточений високими гірськими хребтами. Щоб пішки потрапити на схід, до Лох Модану, ідіть дорогами до Перевалу Північної Брами або Проходу Південної Брами в північно-східних горах. Також можна дістатися просто до Стормвінда Глибинним трамваєм всередині Айронфорджа."}
c["zone:dunmorogh#faq4"] = "e9b257"
P.scopedClips["zone:dunmorogh#faq4"] = {scope="answer-only",sourceHash="fcce62",hash="e9b257",name="Дун Мороґ",question="Де в Дун Мороґу розпорядник польотів?",answer="Єдиний діючий розпорядник польотів Альянсу в зоні розташований усередині Великої Кузні Айронфорджа; він сполучає мандрівників із місцями по всьому Каз Модану, Стормвіндом і північними заставами Альянсу."}
c["zone:dunmorogh#faq5"] = "dc8838"
P.scopedClips["zone:dunmorogh#faq5"] = {scope="answer-only",sourceHash="252b3d",hash="dc8838",name="Дун Мороґ",question="Хто такі тролі Морозогриви?",answer="Морозогриви — плем'я крижаних тролів, яке правило Дун Мороґом задовго до того, як дворфи вийшли з Улдамана. Хоч багато поколінь тому їх розбили й загнали в скелі, вони лишаються запеклими ворогами Айронфорджа й раз у раз нападають на дворфські ферми та дороги зі своїх сховків на кшталт Твердині Морозогривів."}
c["zone:dunmorogh#faq6"] = "355b59"
P.scopedClips["zone:dunmorogh#faq6"] = {scope="answer-only",sourceHash="0ab561",hash="355b59",name="Дун Мороґ",question="Що таке Харанос?",answer="Харанос — головне дворфське поселення в центральному Дун Мороґу. Тут розташовані Ґуральня Тандербрю, наставники та припаси, тож це центральний осередок для молодих шукачів пригод і горян, які дають раду місцевим тролям і дикій звірині."}
c["zone:durotar"] = "d0063e"
P.scopedClips["zone:durotar"] = {scope="overview-body",sourceHash="5c6281",hash="d0063e",name="Дуротар",summary="Дуротар — посушлива батьківщина серед червоних скель, яку Вождь Тралл заснував після Третьої війни й назвав на честь свого батька Дуротана. Обмежений Річкою Південної Люті та Великим Морем, він є серцем Нової Орди й полігоном для молодих орків і тролів Темного Списа. У його суворих каньйонах лежать укріплені поселення на кшталт Гострого Пагорба, розлоге місто воїнів Оргріммар і ворожі оплоти, що окопалися тут, — від племен шипогривів до відрізаних військ Альянсу.",section="Коли Тралл повів свій народ через Велике Море на Калімдор, він свідомо шукав дике порубіжжя, де орки могли б вирвати собі чесне існування працею і завзяттям, а не завоюванням. Потріскана червона земля Дуротару, випалені балки й високі червоні скелясті шпилі глибоко нагадують оркам Дренор, яким той був до знищення. Хоч клімат нещадний і дає мало орної землі та скупу воду, Орда прийняла природний захист і сувору велич цього краю. Обмежений на заході, за Річкою Південної Люті, відкритими Пустками, а на півночі — зруйнованою глушиною Азшари, Дуротар стоїть живим доказом того, що орки викували власну долю.",sectionIndex=1}
c["zone:durotar#faq1"] = "c55ddc"
P.scopedClips["zone:durotar#faq1"] = {scope="answer-only",sourceHash="48858e",hash="c55ddc",name="Дуротар",question="Чому Тралл оселив Орду в такій безплідній пустелі?",answer="Тралл обрав цей нещадний край навмисне. Червона земля та суворі плоскогір'я нагадували оркам прадавній світ Дренор, а суворі умови слугували покутою та горнилом дисципліни. Тралл вважав, що його народ має заслужити виживання чесними злигоднями, а не захоплювати родючі землі війною, щоб не скотитися знову в кровожерливе самовдоволення."}
c["zone:durotar#faq2"] = "f00b92"
P.scopedClips["zone:durotar#faq2"] = {scope="answer-only",sourceHash="1a85b0",hash="f00b92",name="Дуротар",question="На чию честь названо Дуротар?",answer="Край названо на честь Дуротана — покійного батька Тралла й колишнього вождя клану Морозного Вовка. Дуротан виступав проти демонічного скверніння орківських кланів і був убитий за наказом чорнокнижника Ґул'дана."}
c["zone:durotar#faq3"] = "0236bc"
P.scopedClips["zone:durotar#faq3"] = {scope="answer-only",sourceHash="f35a92",hash="0236bc",name="Дуротар",question="Чому у Фортеці Тіраґард людські солдати?",answer="Солдати у Фортеці Тіраґард — уцілілі кул-тіраські морські піхотинці під проводом Лейтенанта Бенедикта, що лишилися від загарбницького флоту Великого Адмірала Дейліна Праудмура. Навіть після загибелі Праудмура ці війська відмовилися здатися чи відступити й утримують укріплену ворожу заставу просто на південному узбережжі Дуротару."}
c["zone:durotar#faq4"] = "6e61d1"
P.scopedClips["zone:durotar#faq4"] = {scope="answer-only",sourceHash="6e7c09",hash="6e61d1",name="Дуротар",question="Що за конфлікт на Островах Відлуння?",answer="Спершу тролі Темного Списа заснували свій калімдорський дім на Островах Відлуння. Та могутній знахар на ім'я Залазан піддався божевіллю й обернув темну магію проти братів, поневоливши їхній розум. Уцілілі втекли на материк і заснували Село Сен'джин, звідки роблять вилазки, щоб зламати його хватку."}
c["zone:durotar#faq5"] = "127dd5"
P.scopedClips["zone:durotar#faq5"] = {scope="answer-only",sourceHash="3ccdf5",hash="127dd5",name="Дуротар",question="Що Палаючий Клинок робить у Дуротарі?",answer="Палаючий Клинок — підривний демонічний культ, вірний Раді Тіней і Палаючому Легіону. Його агенти чаяться у відлюдних місцях на кшталт Череп-скелі та Ковену Палаючого Клинка, намагаючись підірвати провід Тралла й спокусити вразливих орків назад у демонічне рабство."}
c["zone:durotar#faq6"] = "5250d7"
P.scopedClips["zone:durotar#faq6"] = {scope="answer-only",sourceHash="d131fc",hash="5250d7",name="Дуротар",question="Що сполучає Дуротар з іншими краями?",answer="Міст через Річку Південної Люті веде на захід, у Пустки. За Оргріммаром вежа цепелінів забезпечує міжконтинентальні перельоти просто до Галявин Тірісфалю і Базового Базового Табору Ґром'ґол у Долині Стренглторну."}
c["zone:duskwood"] = "2c2605"
P.scopedClips["zone:duskwood"] = {scope="overview-body",sourceHash="5db036",hash="2c2605",name="Сутінколісся",summary="Колись осяяний сонцем край на півдні Елвінна, відомий як Брайтвуд, Сутінколісся нині — проклятий ліс, ув'язнений під неприродним вічним мороком. Покинуті владою Стормвінда, обложені люди тримаються за життя в Даркширі під пильним захистом місцевого ополчення — Нічної Варти. Темними гаями й примарними курганами никають гулі-трупоїди, велетенські отруйні павуки, огри-грабіжники й люті, загадкові воргени.",section="До того як упала темрява, цей край звався Брайтвудом — багатим хліборобським наділом Королівства Стормвінд із квітучими поселеннями на кшталт Великого Селища й Воронячого Пагорба. Трагедія почалася, коли під час Першої війни в Каражані впав Хранитель Медів, і хвилі спотвореної скверни перетворили мирний ліс на покручену, тінисту хащу. Павуки стали страхітливими хижаками, а вовки, рятуючись, ринули на північ, до Лісу Елвінн. З часом Велике Селище перейменували на Даркшир, а його наляканих мешканців майже полишили напризволяще, коли королівський гарнізон відступив боронити столицю.",sectionIndex=1}
c["zone:dustwallow"] = "c5752c"
P.scopedClips["zone:dustwallow"] = {scope="overview-body",sourceHash="23de26",hash="c5752c",name="Багно Пилоброду",summary="Багно Пилоброду — величезні задушливі болота в центрі Калімдору, затиснуті між посушливими рівнинами Пусток і Великим морем. Його підступні драговини, які живлять невичерпні підземні джерела, ховають небезпечних хижаків, таємні сутички фракцій і зловісну присутність чорного драконячого роду. На сході тут стоїть острівна фортеця Альянсу Терамор, а на північному заході — Село Папоротяної Стіни, де живуть огри Кам'яного Молота, союзники Орди.",section="До Великого Розколу на місці Багна Пилоброду лежала висока трав'яниста рівнина, де паслися численні стада. Катаклізм розколов долину: ґрунтові води піднялися й затопили землю нескінченними стоячими калюжами, мохуватими мілинами й в'язкою багнюкою. Підземні джерела не дають болоту висохнути: тут завжди волого, все вкрите густим туманом і кишить кроколісками, рапторами й павуками. Підступні мілини й мандрівні трясовини роблять подорож небезпечною для кожного, хто зійде з розвалених гребель.",sectionIndex=1}
c["zone:easternplaguelands"] = "de3cd3"
P.scopedClips["zone:easternplaguelands"] = {scope="overview-body",sourceHash="9c5496",hash="de3cd3",name="Східні Чумні землі",summary="Східні Чумні землі — спустошене серце загиблого королівства Лордерон, що задихається під заразою Погибелі, отруйними туманами й спотвореними грибами. На півночі височіє Стратгольм — оплот нежиті в цьому краї, а на сході окопався фанатичний Багряний Хрестовий Похід. Серед цього жахіття Каплиця Надії Світла стоїть непохитним нейтральним прихистком для кожного, кому стане відваги дати відсіч.",section="Колись цей край звався родючим Східноліссям і був житницею північного Лордерону. Його опорою слугували велике місто Стратгольм і заможні містечка на кшталт Дарроуширу й Перехрестя Коріна. Під час Третьої війни принц Артас вичистив Стратгольм, дізнавшись, що місцеве зерно отруєне Чумою Нежиття. Після загибелі королівства темна магія Погибелі запанувала безроздільно. Ґрунт став бурим і гнилим, звичайні рослини перетворилися на велетенські гриби, а долини огорнув моторошний помаранчевий туман.",sectionIndex=1}
c["zone:elwynn"] = "cb774a"
P.scopedClips["zone:elwynn"] = {scope="overview-body",sourceHash="efa666",hash="cb774a",name="Ліс Елвінн",summary="Ліс Елвінн — зелене серце королівства Стормвінд, що постачає столиці конче потрібні деревину, золото, рибу та збіжжя. Під покровом статечних листяних дерев він служить полігоном для новобранців з людей, що виходять з Абатства Нортшира. Та під ідилічним сільським склепінням ліс тяжко потерпає від погані, що насувається, зігнаної з місць звірини й повсюдного розбійництва.",section="Елвінн, що тягнеться на південь від брами Стормвінда до річки Назферіті, — родючий край, щедро обдарований дощами й густими листяними лісами. Такі громади, як Ґолдшир і Лісозаготівельний Табір Східної Долини, дають столиці вкрай потрібні збіжжя, худобу, деревину та сиру мідь. Край також славиться витривалими евендейлськими кіньми, яких полюбляють мандрівники й лицарі по всьому королівству.",sectionIndex=1}
c["zone:elwynn#faq1"] = "0af203"
P.scopedClips["zone:elwynn#faq1"] = {scope="answer-only",sourceHash="6a2a91",hash="0af203",name="Ліс Елвінн",question="Чому вартові Стормвінда майже не стежать за порядком у лісі?",answer="Збройні сили Стормвінда вкрай перенапружені. Королівство розгорнуло великі військові сили на півдні, у Долині Стренглторну, наробивши глибоких боргів і висотавши місцеві людські ресурси. Тому застави на кшталт Гарнізону Вестбрук і Ґолдшира покладаються на жменьку вартових і новобранців-добровольців, щоб відбиватися від розбійників, гнолів і мурлоків."}
c["zone:elwynn#faq2"] = "bd150c"
P.scopedClips["zone:elwynn#faq2"] = {scope="answer-only",sourceHash="4b39b6",hash="bd150c",name="Ліс Елвінн",question="Чому в усіх копальнях кобольди?",answer="Поки вартових бракувало, спритні кобольди заполонили Копальню Фарґодіп, Яшмову копальню та Шахту Ехо-Рідж у пошуках дорогоцінного золота й мінералів. Вони вигнали людей — шукачів і шахтарів — і люто боронять свої підземні володіння свічками, грубими кайлами та підібраним знаряддям."}
c["zone:elwynn#faq3"] = "6ff6ac"
P.scopedClips["zone:elwynn#faq3"] = {scope="answer-only",sourceHash="3c8826",hash="6ff6ac",name="Ліс Елвінн",question="Хто ці розбійники в червоних масках?",answer="Це члени Братства Дефіас на чолі з Едвіном Венкліфом. Багато з них спершу були ремісниками Гільдії Каменярів, яка відбудувала Стормвінд після Першої війни. Коли знать відмовилася виплатити обіцяну платню, спалахнули заворушення, що призвели до їхнього вигнання й скочування до організованого розбійництва."}
c["zone:elwynn#faq4"] = "131e37"
P.scopedClips["zone:elwynn#faq4"] = {scope="answer-only",sourceHash="44b388",hash="131e37",name="Ліс Елвінн",question="Куди веде дорога на південь?",answer="Перейшовши міст через річку Назферіті, ви потрапите до Сутінколісся, історично відомого як Світлолісся. Цей колись мирний край поринув у неприродну темряву й нині кишить нежиттю, жахливими павуками та ненажерливими звірами."}
c["zone:elwynn#faq5"] = "8b197f"
P.scopedClips["zone:elwynn#faq5"] = {scope="answer-only",sourceHash="3add43",hash="8b197f",name="Ліс Елвінн",question="Що за ворожнеча між Маклюрами та Стоунфілдами?",answer="Стоунфілди й Маклюри — сусідні фермерські родини на півдні Елвінну, що плекають гірку давню образу одна на одну. Попри нескінченні сварки й звинувачення, двоє їхніх молодших родичів — Мейбелл Маклур і Томмі Джо Стоунфілд — таємно покохали одне одного, ще дужче заплутавши суперництво."}
c["zone:elwynn#faq6"] = "a5a2f2"
P.scopedClips["zone:elwynn#faq6"] = {scope="answer-only",sourceHash="fab076",hash="a5a2f2",name="Ліс Елвінн",question="Що таке Вежа Азори?",answer="Вежа Азори — таємний шпиль при дорозі між Ґолдширом і Лісозаготівельним Табором Східної Долини. У ній живуть маги-відлюдники, зокрема Теокрітус, які спостерігають за лей-лініями краю й провадять магічні дослідження поза прямим наглядом Святилища Чародія в Стормвінді."}
c["zone:felwood"] = "2e4c67"
P.scopedClips["zone:felwood"] = {scope="overview-body",sourceHash="2ee678",hash="2e4c67",name="Сквернолісся",summary="Сквернолісся — сплюндрований ліс між Ашенвалем і Горою Гіджал, глибоко отруєний демонічною магією під час Третьої війни. Колись це був буйний рай лук і гаїв під опікою нічних ельфів, а тепер тут кишать демонічні сатири, скажені звірі й спотворені древні. Друїди Кола Кенарія разом із заставами Альянсу та Орди відчайдушно намагаються очистити землю й викорінити з її глибин Раду Тіней.",section="До Третьої війни ця долина була мирним прихистком співочих птахів, чистих струмків і тихих гаїв під охороною давніх захисників. Усе скінчилося, коли жахолорд Тіхондріус і Палаючий Легіон пустили в хід Череп Ґул'дана, щоб отруїти північ Калімдору перед наступом на Гору Гіджал. Мерзенні чари черепа перетворили лісову підстилку на почорніле трясовиння. Хоча Іллідан Стормрейдж зрештою вбив Тіхондріуса й поглинув силу артефакту, земля лишилася просякнутою скверною. Могутні деревні велетні й древні зогнили зсередини, річки обернулися на киплячу жовч, а лісові звірі в безумстві почали пожирати одне одного.",sectionIndex=1}
c["zone:feralas"] = "7f1f7c"
P.scopedClips["zone:feralas"] = {scope="overview-body",sourceHash="f6ee05",hash="7f1f7c",name="Фералас",summary="Фералас — величезний, оповитий туманом дощовий ліс між Пустограєм, Тисячею Голок і Прихованим Морем. Під захистом високих гірських стін тут зберігся прадавній світ, усіяний зарослими руїнами калдореїв і первісними звірами. Нині ці нетрі — спірна територія, за яку змагаються рештки давніх Високородних, огри Ґордунні, що вдерлися сюди, і суперницькі застави Альянсу та Орди.",section="Поки сусідні Пустограй і Тисяча Голок висохли на голі пустки й спраглі каньйони, Фералас і далі буяє зеленню. Гірські хребти замикають лісовий покрив, підтримуючи теплий клімат із густими туманами, давніми деревами й високими водоспадами. До Великого Розколу так виглядала більша частина Калімдору. За тисячоліття густі джунглі поглинули пам'ятки калдорейської цивілізації, що колись тут панувала, сховавши забуті храми й павільйони під задушливим мохом і густою папороттю.",sectionIndex=1}
c["zone:gnomeregan"] = "78a249"
P.scopedClips["zone:gnomeregan"] = {scope="overview-body",sourceHash="918b92",hash="78a249",name="Гномреґан",summary="Гномреґан, вирізаний у засніжених передгір'ях Дун Мороґу, колись був підземною столицею й найбільшим технічним дивом гномів. Сьогодні він лежить у руїнах і на карантині, отруєний радіоактивними викидами після відчайдушної оборони від підземної навали трогів. Уцілілі гноми живуть як біженці в сусідньому Айронфорджі, а опромінені зали заполонили мутовані троги, шалені гноми-прокажені й некеровані механічні вартові.",section="Задовго до трагічного падіння Гномреґан був свідченням вершин гномського генія, честолюбства й працьовитості. Збудований за допомоги сусідніх дворфів Айронфорджа, розлогий механічний комплекс живився велетенськими гуркітливими двигунами, вихором шестерень і складною мережею вентиляції, яку цілодобово обслуговували п'ятнадцять техніків — лише щоб підтримувати свіже повітря. Це був квітучий осередок винахідництва, змагань у ремеслі й політики, зосередженої в Дворі Майстрів, — горда столиця, звідки гноми під час Другої війни постачали Альянсові Лордерона безцінні облогові машини, літальні апарати й озброєння.",sectionIndex=1}
c["zone:hallofthanes"] = "aa0350"
P.scopedClips["zone:hallofthanes"] = {scope="overview-body",sourceHash="b8ab95",hash="aa0350",name="Зала Танів",summary="Глибоко під гамірним містом Айронфордж лежить Зала Танів — давній підземний комплекс, просякнутий історією дворфів. Це відлюдне підземелля для шукачів пригод з Альянсу на початку їхнього шляху: тут зберігаються реліквії минулого гірського королівства, яким нині загрожує небезпека. Щоб потрапити всередину, доведеться віднайти забуті шляхи крізь саму гору.",section="Поки Айронфордж гуде дзвоном молотів у Великій Кузні, забуті зали сягають значно глибше в камінь. Зала Танів — один із цих шанованих підземних куточків. Здавна пов'язана з родами предків-дворфів і реліквіями майстрів каменю, тепер вона потребує відважних героїв Альянсу, які зважаться спуститися в її темні склепіння й убезпечити глибини.",sectionIndex=1}
c["zone:hillsbrad"] = "b743dc"
P.scopedClips["zone:hillsbrad"] = {scope="overview-body",sourceHash="3aa0ff",hash="b743dc",name="Передгір'я Гілсбреда",summary="Передгір'я Гілсбреда — зелений, родючий край, останній пасторальний оплот занепалого королівства Лордерон. Хоч його здебільшого оминула чума Погибелі, землю роздирає жорстока відкрита війна між людьми Саутшора й Відступниками, що окопалися в Таррен Міллі. Це криваве перехрестя, де армії Альянсу й Орди сходяться без жалю.",section="Поки північний Лордерон гниє під пошестю Погибелі, Гілсбред лишається напрочуд зеленим. Його пологі пасовища, соснові гаї й діючі ферми дають мандрівникам рідкісну змогу побачити, яким було королівство до Третьої війни. Та цей мирний вигляд оманливий. Тихими полями й сільськими дорогами раз у раз прокочуються озброєні патрулі, найманці-ренегати й звірі-падальники. Те, що мало бути житницею Лордерона, стало натомість його найспірнішим прикордонням.",sectionIndex=1}
c["zone:hinterlands"] = "d1d9f8"
P.scopedClips["zone:hinterlands"] = {scope="overview-body",sourceHash="cdf42b",hash="d1d9f8",name="Пригір'я",summary="Пригір'я — суворий, густо зарослий лісом край на сході Лордерону, затиснутий між Чумними Землями й морем. Його обличчя визначають руїни давніх храмів тролів Амані, високі гнізда клану Вайлдгаммерів на Орлиному Піку й велетенське Велике Дерево, в якому ховається загадковий розлом у Смарагдовий Сон.",section="Задовго до того, як на півночі Лордерону ступили люди чи дворфи, Пригір'ям володіли лісові тролі Імперії Амані. Після поразки в давніх Тролячих війнах їхня імперія розпалася на розрізнені племена. Століттями пізніше, коли трагічна Війна Трьох Молотів вигнала дворфів-вайлдгаммерів із Ґрім Батолу, ті подалися на північ і оселилися на поверхні, на Орлиному Піку. Приручивши місцевих грифонів і прийнявши шаманські традиції, Вайлдгаммери звели величезну твердиню під самим небом. Тролі вважали цих дворфів, що жили на поверхні, непроханими зайдами на землях предків, і так спалахнула нескінченна ворожнеча сутичок і набігів.",sectionIndex=1}
c["zone:ironforge"] = "1b6e31"
P.scopedClips["zone:ironforge"] = {scope="overview-body",sourceHash="b36477",hash="1b6e31",name="Айронфордж",summary="Айронфордж, висічений у серці гори Айронфордж у засніженому Дун Мороґу, — родова столиця дворфів Бронзбірдів і неприступний бастіон Альянсу. Це розлоге підземне місто, у центрі якого пашить жаром Велика Кузня, — гамірний осередок торгівлі, ремесла й давніх дворфійських переказів. Під непохитною владою Короля Маґні Бронзбірда воно нині прихищає й гномів, вигнаних із сусіднього Гномреґана.",section="Айронфордж заснували дві з половиною тисячі років тому, коли перше покоління дворфів пробудилося в Ульдамані й вирушило на захід, до зубчастих вершин Дун Мороґу. Заглибившись у найвищу гору, вони звели величезну святиню на честь свого творця-титана Каз'ґорота, а поруч — колосальну Велику Кузню. Відтоді місто розросталося концентричними кільцями довкола цього вогняного осердя. На відміну від столиць на поверхні, Айронфордж повністю схований під кам'яними склепіннями; його зігрівають ревучі горнила й підземні ріки розплавленої магми. Укріплена брама й печерні глибини століттями війн доводили, що місто майже неприступне.",sectionIndex=1}
c["zone:ironforge#faq1"] = "b66719"
P.scopedClips["zone:ironforge#faq1"] = {scope="answer-only",sourceHash="92ad12",hash="b66719",name="Айронфордж",question="Хто править Айронфорджем?",answer="Айронфорджем і королівством Каз Модан править із Високого Престолу Король Маґні Бронзбірд. Вправний воїн і майстер-коваль, він провів свій народ крізь Другу й Третю війни й лишається відданою опорою Альянсу."}
c["zone:ironforge#faq2"] = "96fc50"
P.scopedClips["zone:ironforge#faq2"] = {scope="answer-only",sourceHash="c35195",hash="96fc50",name="Айронфордж",question="Чому в Айронфорджі так багато гномів?",answer="Коли сусідня гномська столиця Гномреґан упала через раптове вторгнення трогів і катастрофічну аварію з радіацією, уцілілі гноми втекли до Дун Мороґу. Король Маґні прийняв їх в Айронфорджі й віддав їм цілий квартал міста, відомий нині як Містечко Майстрів."}
c["zone:ironforge#faq3"] = "d0c70d"
P.scopedClips["zone:ironforge#faq3"] = {scope="answer-only",sourceHash="ce9e38",hash="d0c70d",name="Айронфордж",question="Що таке Велика Кузня?",answer="Велика Кузня — вогняне промислове серце міста, яке живлять підземні водоспади розплавленої магми. Вона оточує Велике Ковадло, на якому дворфійські зброярі кують легендарну зброю й обладунки. Сам Король Маґні викував на цьому ковадлі славетний святий клинок Ешбрінгер."}
c["zone:ironforge#faq4"] = "4bf391"
P.scopedClips["zone:ironforge#faq4"] = {scope="answer-only",sourceHash="9a784a",hash="4bf391",name="Айронфордж",question="Як дістатися з Айронфорджа до Стормвінда?",answer="Айронфордж сполучений зі Стормвіндом напряму Глибинним трамваєм — дивовижною підземною залізницею, яку створили гномські інженери. Вона пролягає просто крізь гірську основу Східних Королівств."}
c["zone:ironforge#faq5"] = "51801f"
P.scopedClips["zone:ironforge#faq5"] = {scope="answer-only",sourceHash="a1dbae",hash="51801f",name="Айронфордж",question="Чи захоплював Айронфордж колись ворог?",answer="Айронфордж ніколи не підкорявся жодному загарбникові ззовні. Під час Другої війни клан Кривавої Западини на чолі з Кілроґґом Дедаєм місяцями тримав його в облозі, а у Війні Трьох Молотів Темне Залізо пробилося до самого міста, але брама й захисники вистояли."}
c["zone:ironforge#faq6"] = "66e527"
P.scopedClips["zone:ironforge#faq6"] = {scope="answer-only",sourceHash="3a04ad",hash="66e527",name="Айронфордж",question="Куди поділися інші дворфійські клани?",answer="Після Війни Трьох Молотів переможений клан Вайлдгаммер перебрався на північ — у Багнокрай й Пригір'я, а ворожий клан Темного Заліза осів у краях Редріджу й Блекроку під владою Володаря вогню."}
c["zone:lochmodan"] = "6786fc"
P.scopedClips["zone:lochmodan"] = {scope="overview-body",sourceHash="bd85a0",hash="6786fc",name="Лох Модан",summary="Лох Модан — гірська долина з помірним кліматом на схід від Дун Мороґу, славетна своїм величезним альпійським озером, яке тримає монументальна Каменетесна Гребля. Край, серцем якого є дворфійське містечко Телсамар, потерпає від навали трогів, кобольдів у шахтах і агресивних огрів на північно-східному нагір'ї.",section="Лох Модан, що лежить у східному Каз Модані, — приємна протилежність замерзлим сніговим полям Дун Мороґу. Суворі гірські вершини оточують помірну долину з соснами й березами, що колише саме Озеро. Цю величезну прісну водойму тримає Каменетесна Гребля — архітектурний тріумф, що височіє на північному краю. Мирне поселення Телсамар — громадське серце краю: тут зупиняються мандрівні горяни, мисливці й рудокопи, що розробляють багаті жили міді й олова, розкидані по пагорбах.",sectionIndex=1}
c["zone:moonglade"] = "3275b1"
P.scopedClips["zone:moonglade"] = {scope="overview-body",sourceHash="4e816e",hash="3275b1",name="Місячний Гай",summary="Місячний Гай — давня відлюдна лісова долина високо на півночі Калімдору, шанована як священне серце друїдства й дім Кола Кенарія. Тут, під вічними сутінками, куди не дотягнулася скверна смертних, лежить нейтральний прихисток, де нічні ельфи й таурени пліч-о-пліч вивчають природу. Тим, хто не є друїдом, щоб дістатися цього гірського святилища, доводиться пройти небезпечним гірським тунелем Твердині Деревопащих.",section="Оточений стрімкими горами на північ від Сквернолісся й Вінтерспрінга, Місячний Гай живе у вічній тихій ночі під лагідним сяйвом місяця Елуне. У його серці лежить Озеро Елуне'ара — глибока спокійна водойма, священна від самого світанку калдорейської цивілізації. Палаючий Легіон не сплюндрував гаю ні під час обох давніх вторгнень, ні в недавній Третій війні: його захищали пильний напівбог Кенарій та його нащадки. Нині під опікою Хранителя Ремулоса долина лишається мирним прихистком, де рівновагу природи бережуть від суперечок фракцій.",sectionIndex=1}
c["zone:mulgore"] = "853321"
P.scopedClips["zone:mulgore"] = {scope="overview-body",sourceHash="2941b7",hash="853321",name="Малгор",summary="Малгор — прабатьківська домівка тауренів: пишна, захищена долина смарагдових пасовищ, високих плато й хвилястих рівнин під Горами Кам'яного Кігтя. Оточений високими природними гірськими стінами, край став безпечним після того, як Кайрн Бладгуф уклав союз із Ордою Тралла й вигнав кентаврів-мародерів. Сьогодні це духовне й територіальне серце об'єднаних тауренських племен, яким правлять із великого міста на плато — Тандер Блафа.",section="Поколіннями таурени жили кочовиками, яких ватаги агресивних кентаврів без упину гнали й витісняли центральними рівнинами. Їхня доля змінилася, коли Верховний Вождь Кайрн Бладгуф зустрів Тралла та його орків-вигнанців. Побачивши спільні ідеали честі, шаманізму й сили, таурени уклали союз із молодою Ордою. З допомогою орків Кайрн розірвав хватку кентаврів на краї й привів свій народ у Малгор. Тут вони вперше за століття звели постійні поселення, увінчавши найвищі північні плато своєю столицею — Тандер Блафом.",sectionIndex=1}
c["zone:mulgore#faq1"] = "d935e6"
P.scopedClips["zone:mulgore#faq1"] = {scope="answer-only",sourceHash="b40e24",hash="d935e6",name="Малгор",question="Чому таурени оселилися в Малгорі назавжди?",answer="Таурени здавна були кочовим народом, що мандрував Калімдором, рятуючись від кентаврів-мародерів. Об'єднавши сили з Ордою Тралла, Кайрн Бладгуф здобув військову міць, потрібну, щоб прогнати кентаврів і повернути прабатьківську долину Малгор. Вони звели постійні поселення, зокрема Село Бладгуф і Тандер Блаф, щоб створити єдину батьківщину, де всі тауренські племена могли б жити в мирі."}
c["zone:mulgore#faq2"] = "65ff4a"
P.scopedClips["zone:mulgore#faq2"] = {scope="answer-only",sourceHash="a0779d",hash="65ff4a",name="Малгор",question="Як вийти з Малгору пішки?",answer="Малгор повністю оточений непрохідними гірськими стінами, за винятком єдиного південно-східного проходу. Головна ґрунтова дорога, що веде на схід повз Село Бладгуф і пост Моріна Клаудсталкера, проходить цим гірським коридором просто в посушливі рівнини Пусток."}
c["zone:mulgore#faq3"] = "e98b32"
P.scopedClips["zone:mulgore#faq3"] = {scope="answer-only",sourceHash="0f6ed4",hash="e98b32",name="Малгор",question="Хто така Венчурна Компанія і чому вона тут?",answer="Венчурна Компанія — безсовісний торговий картель під орудою гоблінів, що полює на природні багатства Калімдору. У Малгорі вони ведуть видобуток у східних горах і захопили життєво важливі криниці — Тандергорнів, Вайлдмейнів і Вінтергуфів, — оскверняючи землю й загрожуючи водопостачанню краю."}
c["zone:mulgore#faq4"] = "ec3edb"
P.scopedClips["zone:mulgore#faq4"] = {scope="answer-only",sourceHash="99e8db",hash="ec3edb",name="Малгор",question="Чому дворфи копають на землях тауренів?",answer="Дворфи з експедиції Бель Модану заклали Розкопки Бел'дуну в західних передгір'ях Малгору. Спонукувані Лігою Дослідників відшукати реліквії своїх творців-титанів, вони розкопують тауренську землю без дозволу, нехтуючи протестами тауренів, що такі роботи ранять Земну Матір."}
c["zone:mulgore#faq5"] = "b9b99d"
P.scopedClips["zone:mulgore#faq5"] = {scope="answer-only",sourceHash="be8668",hash="b9b99d",name="Малгор",question="Що таке Обряди Земної Матері?",answer="Обряди Земної Матері — священна низка випробувань, які проходить кожен молодий таурен, досягнувши повноліття. Ці завдання перевіряють уміння полювати й вистежувати, спілкування через видіння та знання природної рівноваги, доводячи відданість молодого посвячуваного землі й прабатьківським традиціям свого народу."}
c["zone:mulgore#faq6"] = "697a9a"
P.scopedClips["zone:mulgore#faq6"] = {scope="answer-only",sourceHash="4eee3b",hash="697a9a",name="Малгор",question="Хто править Малгором?",answer="Верховний Вождь Кайрн Бладгуф править усіма землями тауренів зі столиці — Тандер Блафа на північних плато. Його син Бейн Бладгуф керує Селом Бладгуф і дбає про повсякденні справи нижніх рівнин, спираючись на мудрість Кайрна."}
c["zone:orgrimmar"] = "a07248"
P.scopedClips["zone:orgrimmar"] = {scope="overview-body",sourceHash="389ee6",hash="a07248",name="Оргріммар",summary="Оргріммар — столиця-фортеця орків і живе серце Нової Орди Тралла. Висічене просто у височенних червоних каньйонах північного Дуротару, укріплене місто стоїть пам'ятником орочій витривалості й непохитним прихистком і для тролів, і для тауренів, і для союзників-Відступників.",section="Після Третьої війни Вождь Тралл повів орків до посушливих берегів Калімдору, щоб збудувати батьківщину, вільну від демонічної скверни й людського ярма. Назвавши цей суворий край Дуротаром на честь свого батька, Тралл заснував Оргріммар на пам'ять про свого полеглого наставника Оргріма Думхаммера. Місто зводили кров'ю та потом: з допомогою тауренів, тролів Темного Списа, гоблінських інженерів і Поборника Рекссара Орда відтіснила кентаврів, гарпій і лютих громових ящерів, що насідали звідусіль, і закріпилася в цій твердині серед каньйону.",sectionIndex=1}
c["zone:orgrimmar#faq1"] = "7aae74"
P.scopedClips["zone:orgrimmar#faq1"] = {scope="answer-only",sourceHash="74e96b",hash="7aae74",name="Оргріммар",question="Хто править Оргріммаром?",answer="Містом править Вождь Тралл зі свого осідку у Фортеці Ґроммаш. Він веде Нову Орду, спираючись на честь, виживання й шаманську спадщину, а найближчу підтримку йому дають вождь Темного Списа Вол'джин і бувалий командувач Варок Саурфанг."}
c["zone:orgrimmar#faq2"] = "e8216a"
P.scopedClips["zone:orgrimmar#faq2"] = {scope="answer-only",sourceHash="39a621",hash="e8216a",name="Оргріммар",question="Чому місто назвали Оргріммаром?",answer="Тралл назвав місто на честь Оргріма Думхаммера — легендарного колишнього Вождя, що зламав владу Ради Тіней над Старою Ордою, а перед загибеллю в бою передав Траллові свої бойові лати й молот Думхаммер."}
c["zone:orgrimmar#faq3"] = "c89f98"
P.scopedClips["zone:orgrimmar#faq3"] = {scope="answer-only",sourceHash="60b752",hash="c89f98",name="Оргріммар",question="Хто, крім орків, живе в Оргріммарі?",answer="Місто заснували орки, але воно стало прихистком і для тролячого племені Темного Списа, що займає Долину Духів, а в Долині Мудрості гостюють посланці тауренів. Після нещодавнього вступу Відступників до Орди тут оселилася і їхня посольська делегація."}
c["zone:orgrimmar#faq4"] = "36facf"
P.scopedClips["zone:orgrimmar#faq4"] = {scope="answer-only",sourceHash="f1cecb",hash="36facf",name="Оргріммар",question="Що таке Тіньова Розколина?",answer="Тіньова Розколина — тьмяна печерна ущелина, що ховається під скелями каньйону біля Проходу. Тут розташовані міські гільдії розбійників і чорнокнижників: їхня сумнівна торгівля й небезпечні демонічні закляття лишаються осторонь від мирних кварталів."}
c["zone:orgrimmar#faq5"] = "88021d"
P.scopedClips["zone:orgrimmar#faq5"] = {scope="answer-only",sourceHash="948b08",hash="88021d",name="Оргріммар",question="Які загрози чигають у самому місті?",answer="Просто під Тіньовою Розколиною лежить Провалля Лютого Вогню — підступна мережа підземних вулканічних розломів, де кишать троги, палючі елементалі й зрадливі чорнокнижники, що прагнуть підірвати владу Тралла з глибин."}
c["zone:orgrimmar#faq6"] = "ae4379"
P.scopedClips["zone:orgrimmar#faq6"] = {scope="answer-only",sourceHash="38e22c",hash="ae4379",name="Оргріммар",question="Як дістатися з Оргріммара на інші континенти?",answer="За головною брамою на вежах причалюють цепеліни, збудовані гоблінськими інженерами. Вони регулярно перелітають Велике Море до Галявин Тірісфалю поблизу Андерсіті й на південь — до Базового Базового Табору Ґром'ґол у Долині Стренглторну."}
c["zone:ragefire"] = "04235d"
P.scopedClips["zone:ragefire"] = {scope="overview-body",sourceHash="8ad050",hash="04235d",name="Провалля Лютого Вогню",summary="Провалля Лютого Вогню — мережа звивистих вулканічних тунелів просто під орківською столицею Оргріммаром. Вхід до нього лежить у темних западинах Тіньової Розколини, а саме провалля заполонили дикі троги й демонічна секта культистів, відома як Пекучий Клинок. Якщо їх не зупинити, темні сили й підземні рої, що визрівають унизу, загрожують самим підвалинам молодої держави Орди.",section="Під пилом і червоним камінням Оргріммара лежить пекучий лабіринт вулканічних коридорів і лавових ям. Поки орківські будівничі зводили нагорі свою нову домівку, з глибин почали вириватися агресивні троги Лютого Вогню. Маґата Ґрімтотем від імені Тандер Блафа спробувала налагодити з ними дипломатичні стосунки, але її посланця Маура Ґрімтотема по-звірячому вбили, — і стало ясно, що троги поступаються лише силі.",sectionIndex=1}
c["zone:razorfenkraul"] = "f79765"
P.scopedClips["zone:razorfenkraul"] = {scope="overview-body",sourceHash="2a61b6",hash="f79765",name="Рейзорфен Краул",summary="Рейзорфен Краул, що сховався на далекому півдні Пусток, — прадавнє серце земель шипогривів Калімдору. Ці люті племена шанують густий лабіринт велетенських терновиків як священне місце спочинку свого праотця, полеглого напівбога Аґамаґґана. Сьогодні Краул став украй ворожим під тиранією матріархині шипогривів Чарлґи Рейзорфленк, чиї темні оборудки загрожують усьому краю.",section="Десять тисяч років тому, під час апокаліптичної Війни Прадавніх, велетенський дикий бог Аґамаґґан кинувся в бій проти Палаючого Легіону. Зрештою великий вепр загинув у битві, але його жертва зберегла життя на Азероті. Легенди кажуть, що там, де його кров просочилася в землю, вирвалися величезні колючі лози, утворивши густі оборонні лабіринти по всіх південних рівнинах. Шипогриви, що шанують Аґамаґґана як божественного предка, оголосили ці колосальні хащі своєю святою землею, а найбільшу з них назвали Рейзорфеном.",sectionIndex=1}
c["zone:redridge"] = "ea05a2"
P.scopedClips["zone:redridge"] = {scope="overview-body",sourceHash="5dd950",hash="ea05a2",name="Гори Редріджу",summary="На схід від Лісу Елвінн лежать Гори Редріджу — бурхливі річки, лісисті схили й безтурботна гладінь Озера Незрушного. Попри мальовничі висоти, край обложили ворожі гноли Тіньової Шкури й орки Блекрок із Темної Орди, що насуваються дедалі ближче. Військо королівства зв'язане внутрішніми чварами в Стормвінді, тож приозерне містечко Лейкшир мусить покладатися на мандрівних найманців, щоб утримати лінію.",section="Колись Редрідж був одним із наймирніших куточків королівства й постачав Стормвіндові деревину, прісноводну рибу й урожай. Нині те тихе життя розвіялося. Приозерне містечко Лейкшир повсякчас тримає оборону від агресивних вторгнень. На сході Фортеця Кам'яної Варти — колись гордий бастіон королівства — опинилася під владою орків-ренегатів Блекрок, що перерізали дороги й погрожують цілком захопити східні долини.",sectionIndex=1}
c["zone:riverglades"] = "e60a18"
P.scopedClips["zone:riverglades"] = {scope="overview-body",sourceHash="4e7594",hash="e60a18",name="Річкові Галявини",summary="Річкові Галявини — спірна річкова долина на схід від Палаючих Степів і Пустищ, яку здавна вважало своєю королівство Стормвінд. Під час Першої війни її захопила Стара Орда, а корона майже покинула край напризволяще, тож він досі лишається полем бою: місцеві люди, вірні короні, б'ються із заставами сучасної Орди й дикими звірами. На південному заході долина межує з Горами Редріджу, на півдні — з Болотом Скорботи, а за морем навпроти лежить Танаріс.",section="Колись Річкові Галявини належали королівству Стормвінд, але під час Першої війни, коли краєм прокотилася Стара Орда, вони занепали. Головне поселення, Сонячну Галявину, розграбували орки; вони вберегли лише вежу магів, щоб вивчати людське чаклунство, а вцілілих городян поневолили. Хоча воїни Стормвінда спробували визволити полонених і відбудувати край, зрештою королівство визнало всю долину втраченою й спрямувало сили на захист рідних земель. Роками край лишався майже без офіційної підтримки корони.",sectionIndex=1}
c["zone:ruinsoflordaeron"] = "910bde"
P.scopedClips["zone:ruinsoflordaeron"] = {scope="overview-body",sourceHash="68d8b5",hash="910bde",name="Руїни Лордерона",summary="Руїни Лордерона, що височіють просто над підземним Андерсіті, — порожні рештки колись могутнього північного людського королівства. Їх захопили Погибель і принц Артас під час Третьої війни, і тепер вулицями й потрісканими площами нагорі никають мандрівні потвори, мстиві примари й мерзенні експериментатори. І Альянс, і Орда посилають загони в цю сплюндровану цитадель, щоб повернути реліквії полеглого минулого чи винищити жахіття, що ховаються над столицею Відступників.",section="Місто Лордерон колись було перлиною Східних Королівств, осідком короля Теренаса Менетіла II і серцем людської цивілізації. Повернувшись із Нортренду, принц Артас убив свого батька в тронній залі й нацькував нежить на городян. Сьогодні, поки Відступники живуть у катакомбах Андерсіті внизу, руїни на поверхні лишаються покинутою сутінковою зоною. Розбиті арки й порослий бур'янами брук дають прихисток диким звірам на кшталт Візерфенга й божевільним рештам минулого.",sectionIndex=1}
c["zone:scarlet"] = "86796c"
P.scopedClips["zone:scarlet"] = {scope="overview-body",sourceHash="524cb6",hash="86796c",name="Багряний Монастир",summary="На північно-східних пагорбах Галявин Тірісфалю стоїть Багряний Монастир, колись мирний прихисток і осередок науки Церкви Святого Світла. Після падіння Лордерону його захопив і міцно укріпив Багряний Хрестовий Похід, зробивши своєю головною передовою базою на заході. Нині це розлога твердиня з чотирма крилами, де фанатики муштруються, катують полонених і ведуть безкомпромісну війну з усіма чужинцями.",section="До Третьої війни монастир був гордим осідком лордеронського священства й семінарією для молодих паладинів Срібної Длані, яку плекав сам архієпископ Алонсус Фаол. Після спустошення, якого завдала Погибель, уцілілі хрестоносці вичистили зали від нежиті й павуків, що там лишилися, і перетворили тихі архіви та двори на укріплений гарнізон. Гнані параноєю й горем, бійці Багряного Хрестового Походу почали вважати всіх чужинців — живих чи мертвих, людей чи ні — носіями чуми, яких треба очистити вогнем.",sectionIndex=1}
c["zone:searinggorge"] = "f15984"
P.scopedClips["zone:searinggorge"] = {scope="overview-body",sourceHash="b417b5",hash="f15984",name="Палюча Ущелина",summary="Палюча Ущелина — випалений, безлюдний каньйон на півдні Каз Модану, що на півдні межує з Горою Блекрок. Колись це був зелений край Гір Редріджу, але понад два століття тому його спустошив апокаліптичний виклик Рагнароса, Володаря вогню. Нині в ущелині невтомно працює клан Темного Заліза, а за його розлогими рабськими копальнями в Казані пильно стежить Братство Торію, що відкололося від клану.",section="До Війни Трьох Молотів край, де нині лежить Палюча Ущелина, був зеленим горбистим нагір'ям, що продовжувало хребет Редрідж. Той буйний край зник понад двісті тридцять років тому, коли чародій-тан Тауріссан, у відчаї намагаючись переломити хід програної війни, викликав Рагнароса з надр під світом. Катастрофічна поява Володаря вогню розірвала землю, підняла Гору Блекрок, обернула велике місто Темного Заліза Тауріссан на димні руїни й випалила північну долину на потріскану пустку попелу, сірки й вулканічного скла.",sectionIndex=1}
c["zone:shadowfang"] = "6e49c5"
P.scopedClips["zone:shadowfang"] = {scope="overview-body",sourceHash="718b33",hash="6e49c5",name="Фортеця Шадовфенг",summary="Фортеця Шадовфенг, що стоїть на суворих кручах над Селом Пайрвуд, — похмура твердиня чарівника-ренегата з Кірін-Тору, Архімага Аруґала. Колись родовий маєток Барона Сільверлейна, нині цей оплот кишить дикими звірами-воргенами й змученими привидами вбитих захисників. Для шукачів пригод, що мандрують південним Срібноліссям, фортеця — темний осередок звірячої пошесті, що поглинає край.",section="До того як фортецю огорнуло жахіття, Шадовфенг звався Фортецею Сільверлейн — шляхетським осідком, вірним ґілнеаським володарям, де стояв гарнізон під проводом побожного Командира Спрінґвейла. Коли під час Третьої війни Погибель прокотилася Лордероном, чарівники Даларана гинули сотнями. Прагнучи будь-що стримати мерців, що повставали, Архімаг Аруґал знехтував проводом Кірін-Тору, заглибився в дослідження чарівника Ура й викликав воргенів з іншого виміру, щоб переломити хід війни. Викликані звірі шматували нежить, але швидко вийшли з-під будь-якого контролю смертних, вдерлися в південне Срібнолісся й штурмом узяли твердиню. Барона Сільверлейна й увесь його двір було вирізано, і тепер вони приречені блукати кам'яними залами поряд із дикими потворами, що захопили їхню домівку.",sectionIndex=1}
c["zone:shendralas"] = "032ad5"
P.scopedClips["zone:shendralas"] = {scope="overview-body",sourceHash="e90889",hash="032ad5",name="Шен'дралас",summary="Шен'дралас — суворий, спірний дикий край між Фераласом, Малгором і південно-східною частиною Пустограю. Тут панують рештки давніх нічних ельфів і неспокійні кордони, а сам край — бурхливе перехрестя, де стикаються кентаври-загарбники, вигнанці без даху над головою й наїжачені шипогриви.",section="Захований у висотах на південний схід від Пустограю, між Малгором і Фераласом, Шен'дралас — дике прикордоння, далеке від великих столиць фракцій. Його скелясті перевали й приховані закутки дають притулок людям у відчаї, які виборюють собі існування на краю дикого Калімдору. Від відлюдних оглядових місць на кшталт Скелі Вечірньої Тіні до беззаконних сховищ на зразок Схованки Вигнанців — цей край належить тим, хто хоче стежити непоміченим або лишитися забутим.",sectionIndex=1}
c["zone:silithus"] = "3995cf"
P.scopedClips["zone:silithus"] = {scope="overview-body",sourceHash="fb383a",hash="3995cf",name="Силітус",summary="Силітус — безлюдна пустеля, яку шмагають вітри, на далекому південному заході Калімдору. Під її сухими пісками лежать величезні колонії комахоподібних силітидів і давні руїни Ан'Кіража, запечатані тисячу років тому за грізною Стіною Скарабея. Нині друїди Кола Кенарія несуть тяжку варту проти роїв, що підкрадаються, і культистів, які пророкують кінець світу.",section="Щоб дістатися Силітусу, треба пройти первісними джунглями Кратера Ун'Ґоро й піднятися широким кам'янистим перевалом у його північно-західному куті. Перехід разючий: буйна первісна зелень раптом зникає, поступаючись безмежжю рухомих дюн, зубчастого каміння й неприродно високих вуликів. Води тут майже немає, а вітер несе дзижчання крил і шепіт пісків. Посеред пустелі Коло Кенарія утримує Цитадель Кенаріуса — єдиний оплот цивілізації й прихисток для мандрівників, дослідників і воїнів, що наважуються вирушити в ці ворожі пустки.",sectionIndex=1}
c["zone:silverpine"] = "01fbb2"
P.scopedClips["zone:silverpine"] = {scope="overview-body",sourceHash="300fae",hash="01fbb2",name="Срібнолісся",summary="Срібнолісся — моторошний, оповитий туманом ліс уздовж західного узбережжя Лордерона між Галявинами Тірісфалю й замкненою Стіною Ґреймейна. Досі пошрамований чумою Погибелі, він став спірним південним прикордонням Відступників. Мандрівників тут чекають дикі воргени, що никають у тінях, хворі гноли й ворожі людські анклави.",section="Колись Срібнолісся славилося як пишне диво Лордерона, яким шляхетні мандрівники подорожували до Міста Лордерон, але під подихом Третьої війни воно зів'яло. Примарні тумани в'ються між сосен зі срібною корою, що всихають, а зруйновані хутори покинуті напризволяще дикій природі. На півночі лежать Галявини Тірісфалю, а східний берег межує з Озером Лордамер. На півдні стоїть грізна й замкнена Стіна Ґреймейна, що відгороджує відокремлене королівство Ґілнеас від хаосу довкола. Відступники тримають свою головну заставу в Гробниці, намагаючись убезпечити ліс від ворогів з усіх боків.",sectionIndex=1}
c["zone:stockade"] = "b81bf5"
P.scopedClips["zone:stockade"] = {scope="overview-body",sourceHash="ae92d5",hash="b81bf5",name="В'язниця",summary="В'язниця — тюремний комплекс суворого режиму в Стормвінді, захований під міським кварталом каналів біля Кварталу магів. Збудована, щоб тримати найнебезпечніших головорізів королівства, політичних бунтарів і полонених ворогів держави, нещодавно вона поринула в жорстоку анархію. Наглядача Телвотера відтіснили до самого входу, і він відчайдушно наймає вправних шукачів пригод, щоб придушити бунт зсередини, доки той не вихлюпнувся на вулиці столиці.",section="Під тихими каналами Стормвінда В'язниця перетворилася на поле бою. Коли регулярна армія вирушила воювати на далекі фронти, в'язниця, якій бракувало людей, покладалася на недосвідчену молодь — аж до чотирнадцятирічних новобранців. Цього виявилося замало. В'язні підняли кривавий злагоджений бунт: порвали вовняні ковдри на пов'язки для своїх банд і вирізали решту вартових. Наглядач Телвотер ледве втримав вхід, а камери, коридори й блоки опинилися в безжальних руках каторжників.",sectionIndex=1}
c["zone:stonetalon"] = "12b329"
P.scopedClips["zone:stonetalon"] = {scope="overview-body",sourceHash="ef8236",hash="12b329",name="Гори Кам'яного Кігтя",summary="Гори Кам'яного Кігтя — суворий, обточений вітрами ланцюг скелястих вершин на межі з Ашенвалем, Пустками та Пустограєм. І нічні ельфи, і таурени шанують цей край як священний притулок, і його святі висоти разюче контрастують із димом і машинами, що душать нижні каньйони. Сьогодні гори роздирають вирубки, руйнівна стихія елементалів і прикордонна ворожнеча, що ледь жевріє.",section="Хребет Кам'яного Кігтя, що круто здіймається з центрального Калімдору, перехоплює вологу із західних морів — звідси раптові зливи й підступні, слизькі від дощу пісковикові стежки. Нижні долини найбільше відомі невщухаючим вітром, що шмагає все довкола, — його звуть Лихими Вітрами: він може засліпити мандрівника піском або скинути необачного з прямовисної кручі. Вище вічнозелені ліси вкривають гребені довкола Піка Кам'яного Кігтя, де нічні ельфи доглядають підземні обителі й галявини предків, оберігаючи священні гнізда віверн і гіпогрифів на берегах Озера Міркфаллон.",sectionIndex=1}
c["zone:stormwind"] = "a59eff"
P.scopedClips["zone:stormwind"] = {scope="overview-body",sourceHash="18bb68",hash="a59eff",name="Стормвінд",summary="Стормвінд — гамірна столиця королівства Стормвінд і найбільший оплот людей у світі після падіння Лордерона. Відбудовані з попелу Гільдією Каменярів після руйнування в Першій війні, його величні квартали з білого каменю нині вміщують серце Великого Альянсу. Та під розкішними каналами й соборами місто потерпає від раптового зникнення короля Варіана Рінна і дедалі гострішої політичної інтриги.",section="Заснований понад тисячу років тому нащадками араті, Стормвінд поколіннями був квітучим, самодостатнім королівством. Ця золота доба скінчилася, коли Орда орків ринула крізь Темний Портал, спустошила південний континент і зрівняла столицю з землею в Першій війні. Уцілілі на чолі з сером Андуїном Лотаром утекли на північ, за Велике Море, до Лордерона. Після поразки Орди в Другій війні король Теренас Менетіл II та Альянс профінансували повну відбудову. Гільдія Каменярів ретельно відродила столицю як Новий Стормвінд — сяйливу цитадель із полірованого білого каменю й кварталів, порізаних каналами.",sectionIndex=1}
c["zone:stormwind#faq1"] = "5c1a60"
P.scopedClips["zone:stormwind#faq1"] = {scope="answer-only",sourceHash="9e3455",hash="5c1a60",name="Стормвінд",question="Хто зараз править Стормвіндом?",answer="Корону носить десятирічний принц Андуїн Рінн, але насправді королівством керує Верховний Лорд Болвар Фордрагон — регент Стормвінда й верховний командувач його війська. Поки король Варіан Рінн вважається зниклим, Болвар значною мірою покладається на поради королівської радниці Леді Катрани Престор."}
c["zone:stormwind#faq2"] = "d149b0"
P.scopedClips["zone:stormwind#faq2"] = {scope="answer-only",sourceHash="fea00a",hash="d149b0",name="Стормвінд",question="Що сталося з королем Варіаном Рінном?",answer="Король Варіан за підозрілих обставин зник дорогою на дипломатичні перемовини в Тераморі, куди плив кораблем. Щоб зберегти лад, про його зникнення мовчать, але чутки вже ширяться вулицями міста й селами."}
c["zone:stormwind#faq3"] = "933b25"
P.scopedClips["zone:stormwind#faq3"] = {scope="answer-only",sourceHash="fa3d92",hash="933b25",name="Стормвінд",question="Чому місто відбудовували і хто це зробив?",answer="Перше місто Орда орків спалила дотла в Першій війні. Після Другої війни Гільдія Каменярів на чолі з майстром Едвіном Венкліфом ретельно відбудувала столицю з сяйливого білого каменю, а гроші на це дав Альянс Лордерону."}
c["zone:stormwind#faq4"] = "e7bb38"
P.scopedClips["zone:stormwind#faq4"] = {scope="answer-only",sourceHash="ac0d49",hash="e7bb38",name="Стормвінд",question="Чому каменярі повстали проти корони?",answer="Дім Вельмож загнав королівство в борги, нарощуючи військо Стормвінда, і відмовився заплатити Гільдії Каменярів обіцяну платню. Коли Едвін Венкліф зажадав розрахунку, вельможі розпустили гільдію. Робітники збунтувалися, королеву Тіффін Рінн убив кинутий камінь, а вигнані каменярі заснували Братство Дефіас."}
c["zone:stormwind#faq5"] = "6f2c8e"
P.scopedClips["zone:stormwind#faq5"] = {scope="answer-only",sourceHash="e332f2",hash="6f2c8e",name="Стормвінд",question="Кому стоять велетенські статуї в Долині Героїв?",answer="Статуї вшановують Синів Лотара: генерала Туральйона, капітана рейнджерів Аллерію Віндраннер, архімага Хадґара, Курдрана Вайлдгаммера й Даната Троллбейна. Їх звели на честь героїв, що пішли крізь Темний Портал на Дренор, аби закрити розлом і вберегти Азерот."}
c["zone:stormwind#faq6"] = "91e33d"
P.scopedClips["zone:stormwind#faq6"] = {scope="answer-only",sourceHash="25b13e",hash="91e33d",name="Стормвінд",question="Як Стормвінд сполучений з Айронфорджем?",answer="Стормвінд сполучає з Айронфорджем Глибинний трамвай — підземна залізниця, яку збудував Великий Тінкер Ґелбін Меккаторк на замовлення короля Маґні Бронзбірда, щоб між двома столицями швидко йшла торгівля й так само швидко прибувало підкріплення."}
c["zone:stormwind#faq7"] = "0b89ac"
P.scopedClips["zone:stormwind#faq7"] = {scope="answer-only",sourceHash="602579",hash="0b89ac",name="Стормвінд",question="Чому Стормвінд не посилає війська на допомогу Вестфолу й Редріджу?",answer="Королівський двір, де головне слово має Леді Катрана Престор, твердить, що місто не може зняти солдатів зі своїх мурів і найближчих кордонів. Скарбниця виснажена, Дім Вельмож паралізують чвари, тож віддалені містечка покинуто напризволяще: вони мусять покладатися на місцеве ополчення."}
c["zone:stranglethorn"] = "00bc12"
P.scopedClips["zone:stranglethorn"] = {scope="overview-body",sourceHash="ce52e9",hash="00bc12",name="Долина Стренглторну",summary="Долина Стренглторну — неприборкані густі джунглі на південному краю Східних Королівств, на південь від Сутінколісся. Колись тут був осідок великої Імперії Ґурубаші, а нині дощовий ліс усіяний руїнами тролячих споруд, кишить лютими звірами й таборами гоблінів, піратів і солдатів, що змагаються між собою. За владу над краєм запекло борються місцеві племена тролів, Венчурна Компанія й суперницькі фракції, що виборюють собі плацдарми в цій спеці.",section="Тисячоліттями долиною правила могутня Імперія Ґурубаші зі своєї столиці Зул'Ґуруб. Її владі настав край, коли жерці-радикали викликали Гаккара Душолупа й кинули край у катастрофічну громадянську війну. Хоча зандаларі втрутилися й придушили повстання кривавого бога, імперія безповоротно розкололася. Нині джунглі заполонили ворожі між собою племена-спадкоємці — передусім Кривавого Скальпа на північному заході й Череполоми на сході, — і обидва ревно вирізають чужинців, щоб повернути собі землю предків.",sectionIndex=1}
c["zone:swampofsorrows"] = "3f9011"
P.scopedClips["zone:swampofsorrows"] = {scope="overview-body",sourceHash="2b78da",hash="3f9011",name="Болото Скорботи",summary="Болото Скорботи — каламутні солонуваті мочарі між Перевалом Мертвого Вітру й посушливими Спустошеними Землями. Колись це була північна частина давньої Чорної Трясовини, а нині на її вкритих сольовою кіркою драговинах живуть небезпечні звірі й зелені драконороди, а на дні Ставка Сліз лежать руїни затонулого Храму Атал'Гаккара. Орда утримує тут укріплений гарнізон Стонард, а Альянс не має в трясовині безпечного прихистку, тож край лишається здебільшого диким.",section="Задовго до приходу орочої Орди ці мочарі становили північну половину величезних боліт, відомих як Чорна Трясовина. Після розпаду Імперії Ґурубаші фанатичні тролі атал'аї втекли в трясовину й звели Храм Атал'Гаккара, щоб викликати свого кровожерного лоа — Гаккара Душолупа. Відчувши наближення катастрофи, Аспект Ізера вивільнила свою силу й затопила прокляту піраміду у водах Ставка Сліз. Охоронці із зеленого драконячого роду на чолі з Ераникусом залишилися тут пильно стерегти затоплену споруду. Коли ж згодом катаклізм Темного Порталу випалив південну частину трясовини на Спустошені Землі, це північне болото дістало свою нинішню скорботну назву.",sectionIndex=1}
c["zone:tanaris"] = "344920"
P.scopedClips["zone:tanaris"] = {scope="overview-body",sourceHash="a86d8e",hash="344920",name="Танаріс",summary="Танаріс — безмежна спекотна пустеля на півдні Калімдору, край хвилястих піщаних дюн і пекучої спеки. У її серці лежить Ґаджетзан — нейтральне торговельне поселення, яким керують гобліни картелю Стімвідл. За межами гамірних поселень дюни ховають ворожих піщаних тролів, небезпечні вулики силітидів і потаємні володіння бронзового драконячого роду.",section="До того як Великий Розкол розтрощив світ, тут росли буйні джунглі, де жили перші таурени й на які зазіхала Імперія Ґурубаші. Катаклізм позбавив землю лісів, лишивши голу, випалену сонцем пустку. Відрізані зміненою географією, місцеві тролі пристосувалися й загартувалися, ставши племенем Піщаної Люті, і збудували свою відокремлену імперію в обнесеному мурами місті Зул'Фаррак. Нині поверхнею пустелі владарюють гієни, василіски й скорпіди, а під розпеченою землею звиваються підземні тунелі.",sectionIndex=1}
c["zone:teldrassil"] = "3cfda0"
P.scopedClips["zone:teldrassil"] = {scope="overview-body",sourceHash="dd8ee1",hash="3cfda0",name="Тельдрассил",summary="Тельдрассил, що означає «Корона Землі», — велетенське нове Світове Дерево, вирощене біля північно-західного узбережжя Калімдору. Виплекане друїдами після Третьої війни, його могутнє гілля тримає на собі цілу сутінкову дику природу й столицю нічних ельфів — Дарнасус. Та під його тихою, залитою місячним світлом кроною почала ворушитися скверна.",section="Тельдрассил — не просто дерево; це піднесена над водами Прихованого Моря жива система. Його велетенські гілки тримають хвилясті пагорби, річки, живлені вранішньою росою, імлисті озера й густі прадавні гаї. На західному краю лежить Дарнасус — велична столиця калдореїв. Біля підніжжя монументального стовбура — Селище Рут'теран, з'єднане з кроною містичною брамою; це головна гавань острова.",sectionIndex=1}
c["zone:teldrassil#faq1"] = "f14f70"
P.scopedClips["zone:teldrassil#faq1"] = {scope="answer-only",sourceHash="58a722",hash="f14f70",name="Тельдрассил",question="Навіщо виростили Тельдрассил?",answer="Коли Нордрассил було спустошено наприкінці Третьої війни, нічні ельфи втратили безсмертя. Архідруїд Фандрал Стаґгелм схилив Коло Древніх і друїдів Кола Кенарія посадити в морі нове Світове Дерево, щоб повернути втрачене їхнім народом."}
c["zone:teldrassil#faq2"] = "2a5e18"
P.scopedClips["zone:teldrassil#faq2"] = {scope="answer-only",sourceHash="9079c7",hash="2a5e18",name="Тельдрассил",question="Чому Тельдрассил не повернув нічним ельфам безсмертя?",answer="Нордрассил дарував безсмертя, бо його благословив Ноздорму, Позачасний. Коли виростили Тельдрассил, Ноздорму визнав бажання нічних ельфів зухвалим і відмовився дарувати новому дереву своє благословення."}
c["zone:teldrassil#faq3"] = "401ed1"
P.scopedClips["zone:teldrassil#faq3"] = {scope="answer-only",sourceHash="f1f507",hash="401ed1",name="Тельдрассил",question="Як вийти з Тельдрассила?",answer="Мандрівникам треба пройти через Дарнасус до рожевого порталу в Храмових Садах, який переносить униз, до Селища Рут'теран біля підніжжя стовбура. З Рут'терана корабель пливе через море до Обердайна на материку, на Темному Узбережжі; є й маршрути гіпогрифів."}
c["zone:teldrassil#faq4"] = "a07ee6"
P.scopedClips["zone:teldrassil#faq4"] = {scope="answer-only",sourceHash="f64da7",hash="a07ee6",name="Тельдрассил",question="Чому в Тельдрассилі немає рудних жил?",answer="Уся зона лежить на живих гілках і деревині велетенського Світового Дерева, а не на природній материковій породі. Оскільки тут немає кам'яних підземних шарів, не утворюються ні жили металу, ні поклади руди, зате трави ростуть у великому достатку."}
c["zone:teldrassil#faq5"] = "587091"
P.scopedClips["zone:teldrassil#faq5"] = {scope="answer-only",sourceHash="b6c593",hash="587091",name="Тельдрассил",question="Чому фурболги й звірі божеволіють?",answer="Лиховісна присутність почала просочуватися в неблагословенне коріння Тельдрассила. Хвороба зіпсувала місцеву воду й рослинність, штовхнувши мирних деревляників і плем'я фурболгів-Вузлошкірів у шалену агресію, а рештки сатирів свідомо плекають цю заразу."}
c["zone:teldrassil#faq6"] = "27fb66"
P.scopedClips["zone:teldrassil#faq6"] = {scope="answer-only",sourceHash="a55b8e",hash="27fb66",name="Тельдрассил",question="Що таке Тінедол?",answer="Тінедол — захищена відлюдна долина на східному гіллі Тельдрассила довкола великого дерева Алдрассил. Це мирне святилище, де молоді нічні ельфи починають навчання, перш ніж вирушити в широкий світ."}
c["zone:thousandneedles"] = "a2a1a6"
P.scopedClips["zone:thousandneedles"] = {scope="overview-body",sourceHash="c1fa7f",hash="a2a1a6",name="Тисяча Голок",summary="Тисяча Голок — розлогий каньйон із прямовисних пісковикових стовпів і випалених сонцем солончаків на півдні Калімдору. Таурени чіпляються за поселення на вершинах височенних столових гір, ховаючись від агресивних зграй кентаврів, а гноми й гобліни-винахідники ганяють ракетні автомобілі висохлим морським дном Мерехтливих Низин.",section="До того як Великий Розкол розтрощив прадавній Калімдор, тут був пишний річковий каньйон, який живили внутрішні водні шляхи, що текли до моря. Катаклізм розірвав континент, виштовхнув річище вище від ґрунтових вод і змінив русло річки, тож лишилися тільки сухий камінь і пісковикові шпилі. Нині з дна каньйону здіймаються десятки тонких стовпоподібних колон, наче скам'янілий ліс. Таурени оселилися на вершинах і натягли між ними хиткі мотузяні мости, щоб облаштувати селища поза досяжністю ворожих кентаврів-грабіжників, які никають затіненим дном каньйону внизу.",sectionIndex=1}
c["zone:thunderbluff"] = "b419ff"
P.scopedClips["zone:thunderbluff"] = {scope="overview-body",sourceHash="794fc3",hash="b419ff",name="Тандер Блаф",summary="Тандер Блаф — велична столиця тауренів на вітряних червоних столових горах, що здіймаються над травами Малгору. Її заснував Верховний Вождь Кайрн Бладгуф, коли з допомогою Нової Орди об'єднав кочові племена, і нині місто — культурне, духовне й торговельне серце його народу. З'єднане хиткими мотузяними мостами й дерев'яними підйомниками, воно захищає від набігів кентаврів і дарує мирний прихисток мандрівникам з усього Калімдору.",section="Незліченні покоління таурени кочували Калімдором, ведучи жорстоку боротьбу за виживання з ненажерливими племенами кентаврів. Ця відчайдушна доба скінчилася в Третій війні, коли Кайрн Бладгуф об'єднав сили з Вождем Траллом. Разом орки й таурени зламали натиск кентаврів і відвоювали соковиті пасовища Малгору. Щоб уберегти своє майбутнє, Кайрн повів союзні племена під захист цих природних кам'яних бастіонів і заснував Тандер Блаф — перший за багато століть спільний, постійний дім тауренів.",sectionIndex=1}
c["zone:thunderbluff#faq1"] = "16233a"
P.scopedClips["zone:thunderbluff#faq1"] = {scope="answer-only",sourceHash="ecaec0",hash="16233a",name="Тандер Блаф",question="Хто править Тандер Блафом?",answer="Тандер Блафом править і веде об'єднані тауренські племена Верховний Вождь Кайрн Бладгуф. Шанований за мудрість, терпіння й величезну силу, Кайрн заснував місто, коли уклав союз з Ордою Тралла й вигнав кентаврів із Малгору."}
c["zone:thunderbluff#faq2"] = "949174"
P.scopedClips["zone:thunderbluff#faq2"] = {scope="answer-only",sourceHash="993cbd",hash="949174",name="Тандер Блаф",question="Як піднятися до Тандер Блафа?",answer="Ті, хто прибуває пішки чи верхи на кодо, мають скористатися величезними дерев'яними підйомниками на південно-західному й північно-східному боках центральної гори. Крім того, у місті є гніздовище вітрокрилів із маршрутами польотів по всьому Калімдору."}
c["zone:thunderbluff#faq3"] = "e4e605"
P.scopedClips["zone:thunderbluff#faq3"] = {scope="answer-only",sourceHash="7ff942",hash="e4e605",name="Тандер Блаф",question="Чому таурени будували на високих горах, а не на землі?",answer="Століття кочового життя минули під безупинними наскоками войовничих кланів кентаврів. Прямовисні скелі Малгору дають природний захист: вони вберігають оселі, кузні й священних старійшин тауренів від засідок із землі й дають змогу нарешті осісти в мирі."}
c["zone:thunderbluff#faq4"] = "e38a63"
P.scopedClips["zone:thunderbluff#faq4"] = {scope="answer-only",sourceHash="076cb0",hash="e38a63",name="Тандер Блаф",question="Які є узвишшя в місті?",answer="Місто займає центральну гору (поділену на нижній, середній і верхній яруси) та три зовнішні гори довкола неї. Узвишшя Мисливців віддане воїнам, мисливцям і слідопитам. На Узвишші Старійшин живуть друїди, мудреці й плем'я Ґрімтотем. На Узвишші Духів — святині Земної Матері, наставники шаманів, жерців і магів та печерні Ставки Видінь."}
c["zone:thunderbluff#faq5"] = "0052de"
P.scopedClips["zone:thunderbluff#faq5"] = {scope="answer-only",sourceHash="e6689b",hash="0052de",name="Тандер Блаф",question="Що таке Ставки Видінь?",answer="Ставки Видінь — священні підземні печери під Узвишшям Духів. Тауренські провидці, духоходи й знавці чародійства збираються біля цих тихих, оповитих туманом вод, щоб єднатися зі стихіями й тлумачити знамення про майбутнє свого народу."}
c["zone:thunderbluff#faq6"] = "96d5bd"
P.scopedClips["zone:thunderbluff#faq6"] = {scope="answer-only",sourceHash="43e66a",hash="96d5bd",name="Тандер Блаф",question="Хто така Маґата Ґрімтотем?",answer="Маґата Ґрімтотем — матріарх і Стара Відьма грізного клану Ґрімтотем. Вона живе на Узвишші Старійшин і прилюдно бере участь у раді Кайрна, але лишається затятою прихильницею старих звичаїв: не довіряє чужинцям і потай опирається поступливості племені Бладгуф щодо Орди."}
c["zone:tirisfal"] = "9e2a57"
P.scopedClips["zone:tirisfal"] = {scope="overview-body",sourceHash="9b65de",hash="9e2a57",name="Галявини Тірісфалю",summary="Галявини Тірісфалю — моторошний північний край Лордерона, нині серце володінь Леді Сильвани Віндраннер і Відступників. Під ураженим чумою небом і гнилим гіллям лежать занепалі маєтки, принишклі склепи й величезна підземна столиця — Андерсіті. Оточений безтямною Погибеллю й ревними багряними хрестоносцями, це небезпечний край, де вільна нежить виборює своє виживання.",section="Колись родюча колиска людства, Галявини Тірісфалю всохли під прокляттям чуми, яку наслав Король-Ліч. Сонце рідко пробивається крізь каламутний морок, кидаючи вічну хворобливу блідість на вмирущі ліси, занедбані гарбузові грядки й холодні прибережні пагорби. Рештки старих хуторів, як-от Млини Аґаманда й Хутір Балнірів, досі стоять, та їхніх колишніх господарів здебільшого змели в братські могили або підняли неспокійними мерцями. Попри спустошення, край просякнутий темною стійкістю, опертою на такі містечка, як Брілл, і замкнене святилище Похоронного Подзвону, де щойно пробуджені Відступники вчаться витримувати своє друге життя.",sectionIndex=1}
c["zone:tirisfal#faq1"] = "3fd1cb"
P.scopedClips["zone:tirisfal#faq1"] = {scope="answer-only",sourceHash="5de39d",hash="3fd1cb",name="Галявини Тірісфалю",question="Чому небо зелене, а земля гниє?",answer="Під час Третьої війни принц Артас і Погибель випустили Чуму Нежиті на Королівство Лордерон. Магічна пошесть отруїла не лише населення, а й ґрунт, дерева та саму воду, лишивши галявини у вічному стані моторошного, хворобливого тління."}
c["zone:tirisfal#faq2"] = "ac4baf"
P.scopedClips["zone:tirisfal#faq2"] = {scope="answer-only",sourceHash="a3df50",hash="ac4baf",name="Галявини Тірісфалю",question="Яка тут різниця між Відступниками й Погибеллю?",answer="Відступники — нежить, що вирвалася з-під телепатичного панування Короля-Ліча після битви біля Гори Гіджал і з власної волі пішла за Леді Сильваною Віндраннер. Погибель, що блукає хуторами й руїнами, лишається безтямними рабами, прив'язаними до наказів Короля-Ліча."}
c["zone:tirisfal#faq3"] = "2afbe2"
P.scopedClips["zone:tirisfal#faq3"] = {scope="answer-only",sourceHash="2d96f6",hash="2afbe2",name="Галявини Тірісфалю",question="Хто ці вояки в червоних обладунках, що нападають на подорожніх?",answer="Вони належать до Багряного Хрестового Походу — безкомпромісного ордену, що відколовся від колишніх паладинів Срібної Длані й уцілілих. Переконані, що вся нежить — невиправна гидота, яку треба очистити мечем і вогнем, вони з фанатичною ненавистю страчують і безтямних рабів, і вільних Відступників."}
c["zone:tirisfal#faq4"] = "e2417a"
P.scopedClips["zone:tirisfal#faq4"] = {scope="answer-only",sourceHash="8eca13",hash="e2417a",name="Галявини Тірісфалю",question="Звідки походить назва Тірісфаль?",answer="Край названо на честь титана-хранителя Тіра. За легендою, Тір упав у битві з потойбічними жахіттями в цій галявині. Прадавньою мовою врайкулів «Падіння Тіра» перетворилося на назву «Тірісфаль», а срібна рука хранителя стала символом, глибоко вплетеним у ранню міфологію людей."}
c["zone:tirisfal#faq5"] = "053a43"
P.scopedClips["zone:tirisfal#faq5"] = {scope="answer-only",sourceHash="c19c54",hash="053a43",name="Галявини Тірісфалю",question="Де щойно пробуджені Відступники починають свою путь?",answer="Щойно пробуджені Відступники виходять зі склепів Тіньової Могили в Похоронному Подзвоні — замкненому містечку в південно-західному Тірісфалі. Там управителі й екзекутори оцінюють, чи мають воскреслі мерці здоровий глузд і вірність, потрібні для служби Темній Леді."}
c["zone:tirisfal#faq6"] = "f8347b"
P.scopedClips["zone:tirisfal#faq6"] = {scope="answer-only",sourceHash="fa36e0",hash="f8347b",name="Галявини Тірісфалю",question="Як мандрівники залишають Тірісфаль, щоб дістатися інших континентів?",answer="Велика гоблінська вежа цепелінів стоїть на схилі пагорба на південь від Брілла, одразу за Руїнами Лордерона. Ці повітряні кораблі регулярно й напряму перевозять через моря до Оргріммара в Калімдорі та Базового Базового Табору Ґром'ґол у Долині Стренглторну."}
c["zone:undercity"] = "4ed982"
P.scopedClips["zone:undercity"] = {scope="overview-body",sourceHash="d409ac",hash="4ed982",name="Андерсіті",summary="Глибоко під розтрощеними руїнами Столиці Лордерона лежить Андерсіті — темна твердиня Відступників. Спершу Погибель висікла її з давніх королівських склепів і темниць, але Леді Сильвана Віндраннер захопила місто й перетворила на неприступне підземне святилище. Нині це осідок влади Відступників і важливий оплот Орди на півночі Східних Королівств.",section="Задовго до того, як чума прокотилася Лордероном, катакомби, темниці й каналізацію під палацом разом називали Андерсіті. Тут були гробниці знаті, найглибші в'язниці королівства — де колись тримали колишнього Вождя Оргріма Думхаммера, поки він не втік, — і найбідніші мешканці держави. Коли 20 року після відкриття Темного Порталу Артас Менетіл убив короля Теренаса й спустошив столицю, принц наказав своїм слугам-нежиті розкопати й розширити підземні ходи, перетворивши їх на укріплений осідок влади Погибелі.",sectionIndex=1}
c["zone:undercity#faq1"] = "4c6e90"
P.scopedClips["zone:undercity#faq1"] = {scope="answer-only",sourceHash="77e2ec",hash="4c6e90",name="Андерсіті",question="Чим було Андерсіті до того, як його захопила нежить?",answer="Під палацом Лордерона лежали давні склепи людських королів, а також міські темниці й величезна мережа каналізації. Тут тримали воєнних полонених, зокрема Оргріма Думхаммера, а в підземних тінях жили злиденні городяни. Сплюндрувавши столицю, принц Артас почав перетворювати ці катакомби на фортецю Погибелі, але Сильвана їх захопила."}
c["zone:undercity#faq2"] = "64f277"
P.scopedClips["zone:undercity#faq2"] = {scope="answer-only",sourceHash="4bd10f",hash="64f277",name="Андерсіті",question="Чому місто збудоване під землею, а не на поверхні?",answer="Наземне місто Лордерон у Третій війні було вщент зруйноване, і його було важко боронити від Багряного Хрестового Походу, сил Погибелі й уцілілих людей з Альянсу. Підземні тунелі давали природні укріплення, вузькі проходи й потаємність, тож Відступники змогли завершити розпочате Погибеллю будівництво й непомітно процвітати."}
c["zone:undercity#faq3"] = "cca845"
P.scopedClips["zone:undercity#faq3"] = {scope="answer-only",sourceHash="397cef",hash="cca845",name="Андерсіті",question="Хто править Андерсіті?",answer="Містом править Леді Сильвана Віндраннер — Королева Баньші й королева Відступників. Вона править із Королівського Кварталу під охороною королівських вартових-Відступників і свого підкореного поплічника, жахолорда Варіматраса."}
c["zone:undercity#faq4"] = "702735"
P.scopedClips["zone:undercity#faq4"] = {scope="answer-only",sourceHash="48abd3",hash="702735",name="Андерсіті",question="Що за пам'ятник королю Теренасу в руїнах нагорі?",answer="Над головними підйомниками міста стоїть кам'яний пам'ятник убитому королю Теренасу Менетілу Другому. Його тіла там немає: труп короля спалили, а попіл розвіяли під час воскресіння Кел'Тузада. Уцілілі люди Альянсу відважно вирізьбили цей пам'ятник серед руїн, щоб пам'ять про останнього справжнього короля Лордерона жила далі."}
c["zone:undercity#faq5"] = "60b097"
P.scopedClips["zone:undercity#faq5"] = {scope="answer-only",sourceHash="641f89",hash="60b097",name="Андерсіті",question="Що за дивні звуки в тронній залі Лордерона?",answer="У зруйнованій тронній залі над підйомниками Андерсіті досі живуть примарні відлуння минулого. Хто стане посередині, почує ледь чутні привидні звуки: святкові дзвони й шелест пелюсток троянд на честь повернення Артаса, застережливі слова пророка Медіва й останню розмову короля Теренаса з сином-батьковбивцею."}
c["zone:undercity#faq6"] = "2a80a9"
P.scopedClips["zone:undercity#faq6"] = {scope="answer-only",sourceHash="15aa1f",hash="2a80a9",name="Андерсіті",question="Чому Відступники пускають сюди інших членів Орди?",answer="Відступники уклали союз із розрахунку з Ордою Вождя Тралла, щоб вижити, адже довкола них — ворожі фанатики Багряного Хрестового Походу й легіони Погибелі. Живим расам Орди отруйні випари й алхімічні ріки не дають дихати, та посланцям і мандрівникам дозволяють сюди приходити, щоб зміцнювати дипломатичні й військові зв'язки."}
c["zone:ungoro"] = "8b1683"
P.scopedClips["zone:ungoro"] = {scope="overview-body",sourceHash="0f6e4e",hash="8b1683",name="Кратер Ун'Ґоро",summary="Кратер Ун'Ґоро — первісні джунглі в глибокій западині між посушливими пустками Танарісу й Силітусу. Тут панують дикі динозаври, живі елементалі й вулкан у самому центрі, а пишна кальдера сповнена давніх реліквій Титанів і кристалів сили, чиє походження досі лишається глибокою таємницею.",section="Затиснутий між пустелями, Кратер Ун'Ґоро кидає виклик географії південного Калімдору. Давні записи нічних ельфів про Війну Рухомих Пісків свідчать, що комахоподібних кіраджі спинили на краю кратера: вони не змогли проникнути в місце, яке їхньою мовою звалося «Землями Богів». Учені припускають, що кальдера була полігоном чи давньою оселею Титанів, коли ті творили Калімдор. Уздовж хребтів здіймаються кам'яні пілони, що гудуть від енергії, а крізь первісну землю проростають сині, червоні, зелені й жовті кристали.",sectionIndex=1}
c["zone:westernplaguelands"] = "6ca14b"
P.scopedClips["zone:westernplaguelands"] = {scope="overview-body",sourceHash="bf2f1a",hash="6ca14b",name="Західні Чумні Землі",summary="Колись родюча житниця північного Лордерону, Західні Чумні Землі нині задихаються під отруйним туманом і легіонами нежиті. Хоча казани Кел'Тузада занапастили тутешні ферми й містечка, ґрунт і досі вперто тримається за життя. Срібний Світанок, Альянс, Відступники й Багряний Хрестовий Похід ведуть на цих сплюндрованих полях відчайдушну боротьбу.",section="До Третьої війни цей край був зеленим поясом ферм, що тягнувся на схід від Галявин Тірісфалю до Озера Дарроумер. Гартглен правив північчю з Фортеці Марденгольд, а розлоге місто Андоргал порядкувало зберіганням і вивезенням зерна по всьому королівству. Саме через цю важливу роль житниці край став головною ціллю Кел'Тузада. Підмішавши Чуму Нежиття просто в зерно, яке відвантажували з Андоргала, Культ Проклятих обернув хліб Лордерону на його погибель.",sectionIndex=1}
c["zone:westfall"] = "28852f"
P.scopedClips["zone:westfall"] = {scope="overview-body",sourceHash="666f58",hash="28852f",name="Вестфол",summary="Колись Вестфол був родючою житницею Королівства Стормвінд, а тепер це вітряний, занедбаний край, захоплений розбійниками. Без підтримки Корони й без військових гарнізонів уцілілі хуторяни чіпляються за свої ферми, а Братство Дефіас дедалі міцніше стискає хватку з покинутого гірницького містечка Мунбрук.",section="Поколіннями Вестфол годував Королівство Стормвінд. Його пологі пасовища й пшеничні лани квітнули, аж поки наслідки Другої війни не принесли фінансового виснаження та політичної байдужості. Королівство спрямовувало ресурси деінде й не утримувало гарнізонів, і край занепав. Нині безплідні пасовища, виття морських вітрів, збунтовані големи жнив та набіги гнолів Річколапів роблять кожен день випробуванням для тих небагатьох упертих, хто відмовляється покинути свої хутори.",sectionIndex=1}
c["zone:wetlands"] = "7a82b4"
P.scopedClips["zone:wetlands"] = {scope="overview-body",sourceHash="5c21d0",hash="7a82b4",name="Багнокрай",summary="Багнокрай — величезне, оповите туманом болото між горами Каз Модану та берегами Затоки Барадін. Споконвіку терзаний війнами дворфів і навалами орків, він править за суворий буферний край між Айронфорджем і північними землями Лордерону. Укріплений порт Гавань Менетіл — головна рятівна нитка Альянсу в цій розмоклій глушині, яку заполонили орки Драконячої Пащі, мурлоки й гноли.",section="Багнокрай, що простягається під височенним урвищем Каменетесної Греблі, — холодний, підтоплений простір, оповитий вічним туманом під одноманітним сірим небом. Колись тут квітли дворфійські поселення, а тепер болота всіяні затонулими кам'яними руїнами, розмоклими трясовинами й підступними драговинами. Шукачам пригод доводиться пробиратися вузькими проходами: або рухатися на північ з Лох Модану крізь забарикадовану ущелину Дун Алґаз, або перейти височенні арки Мосту Тандол з Аратійського нагір'я.",sectionIndex=1}
c["zone:winterspring"] = "a10036"
P.scopedClips["zone:winterspring"] = {scope="overview-body",sourceHash="7fe637",hash="a10036",name="Вінтерспрінг",summary="Вінтерспрінг — величезна засніжена долина високо на північно-східних схилах Гори Гіджал, просто над зачарованими лісами Місячного Гаю й Сквернолісся. Цей край, відомий лютими морозами, давніми руїнами Високородних і мандрівними грізними хижаками, тримається довкола нейтральної гоблінської застави Евірлук. Це земля суворих природних небезпек: тут знаходять прихисток рештки синього драконячого роду, а на південних висотах доводиться протистояти демонічній скверні.",section="Вінтерспрінг лежить на тисячі футів вище за довколишні нетрі, під свіжим гірським повітрям і невпинними хуртовинами. Величезні оголені корені Світового Дерева, Нордрассіла, прорізають замети, наче височенні дерев'яні арки, вигнуті й покручені у вирішальних битвах Третьої війни. Хоча більшу частину північного Калімдору вкривають густі ліси й там тепліше, Вінтерспрінг — тихий край негустих гірських лісів, скелястих урвищ і замерзлих озер, де живуть грізні морозні шаблезуби, химери, єті й зимові ведмеді з густим хутром.",sectionIndex=1}
c["zone:zephras"] = "febdea"
P.scopedClips["zone:zephras"] = {scope="overview-body",sourceHash="202a23",hash="febdea",name="Острів Зефрас",summary="Острів Зефрас — летючий острів, що ширяє в Небесній Тверді, Царстві Стихій повітря. Це прадавня домівка небороджених і місце, де починається їхній шлях. Нині їхнє суспільство постало перед загрозою зникнення: магія, що тримає острів, поступово вивітрюється. Зв'язок із сусідніми небесними краями обірвався, і мешканці острова борються з розпадом стихій і напливом біженців.",section="Острів Зефрас — відокремлений клаптик суходолу, що дрейфує в безкраїх вітрах Небесної Тверді. Поколіннями небороджені жили тут пліч-о-пліч із місцевими повітряними елементалями, які допомагали підтримувати магічні течії, що тримали острів у повітрі. Та кілька століть тому ці стихійні охоронці зникли без сліду. Без їхньої присутності й опіки приховані чари, що тримають землю, поволі почали слабнути, і Зефрас помалу тріщить і втрачає рівновагу.",sectionIndex=1}
c["zone:zephras#faq1"] = "30ef3d"
P.scopedClips["zone:zephras#faq1"] = {scope="answer-only",sourceHash="0baca9",hash="30ef3d",name="Острів Зефрас",question="Де розташований Острів Зефрас?",answer="Острів Зефрас лежить не на поверхні Азерота, а в Небесній Тверді — Царстві Стихій повітря. Він ширяє серед вічних хмар і вітряних течій цих ефірних володінь."}
c["zone:zephras#faq2"] = "c9a0d2"
P.scopedClips["zone:zephras#faq2"] = {scope="answer-only",sourceHash="c3d449",hash="c9a0d2",name="Острів Зефрас",question="Чому Острів Зефрас розвалюється?",answer="Острів тримався завдяки місцевим повітряним елементалям, які колись жили пліч-о-пліч із небородженими. Кілька століть тому ці елементалі зникли, і магічні основи, що тримають і бережуть летючу землю, з часом почали поволі слабнути й руйнуватися."}
c["zone:zephras#faq3"] = "34f587"
P.scopedClips["zone:zephras#faq3"] = {scope="answer-only",sourceHash="149c1b",hash="34f587",name="Острів Зефрас",question="Що таке Анвілас і Сіроккас?",answer="Це сусідні летючі острови в Небесній Тверді, де теж живуть небороджені. Коли елементалі зникли, Острів Зефрас утратив зв'язок з обома, а біженці, що звідти тікають, розповідають, що і Анвілас, і Сіроккас розсипаються в небуття."}
c["zone:zephras#faq4"] = "450f5e"
P.scopedClips["zone:zephras#faq4"] = {scope="answer-only",sourceHash="a5d00a",hash="450f5e",name="Острів Зефрас",question="Як дістатися з Острова Зефрас до Азерота й назад?",answer="Небороджені тримають небесні доки в поселенні Валанаар. Звідти повітряні кораблі перетинають межу царств і приземляються в Азероті — біля Даларану в Горах Альтерак і на Плато Небоглядів у Малгорі."}
c["zone:zephras#faq5"] = "fb7bef"
P.scopedClips["zone:zephras#faq5"] = {scope="answer-only",sourceHash="488194",hash="fb7bef",name="Острів Зефрас",question="Хто такі небороджені?",answer="Небороджені — мешканці Острова Зефрас і його небесних островів-побратимів. Вони поколіннями жили в Небесній Тверді, а тепер бачать, як їхня летюча батьківщина поволі руйнується, бо магія, що тримає її вкупі, згасає."}
c["zone:zephras#faq6"] = "294ce3"
P.scopedClips["zone:zephras#faq6"] = {scope="answer-only",sourceHash="f8b813",hash="294ce3",name="Острів Зефрас",question="Хто ще живе на Острові Зефрас, окрім небороджених?",answer="Окрім мирних сіл і біженців, острів потерпає від місцевих розбійників, нічнокігтів, що живуть у печерах, і звірів, які населяють такі місця, як Лігво Верескунів і Печера Нічнокігтів."}
